int main() {
    const int SIZE = 5;
    int array[SIZE];

    cout << "Enter 5 numbers: ";

    for (int i = 0; i < SIZE; i++) {
        cin >> array[i];
    }

    for (int i = 0; i < SIZE / 2; i++) {
        int temp = array[i];
        array[i] = array[SIZE - 1 - i];
        array[SIZE - 1 - i] = temp;
    }

