#include <iostream>
#include <string>
using namespace std;

int main() {
    string word;
    bool palindrome = true;

    cout << "Enter word: ";
    cin >> word;

    int left = 0;
    int right = word.length() - 1;

    while (left < right) {
        if (word[left] != word[right]) {
            palindrome = false;
            break;
        }
        left++;
        right--;
    }

    if (palindrome)
        cout << "Palindrome";
    else
        cout << "Not Palindrome";

    return 0;
}

