#include <iostream>

using namespace std;

int power(int a, int b) {

        int ans=1;
        for(int i=1;i<=b;i++){
            ans=ans*a;
        }
        return ans;

}

int main()
{
    int a,b;
    cout<<"enter any two numbers: "<<endl;
    cin>>a>>b;
    int answer=power(a,b);
    cout<<"the power of "<<a<<" is "<<b<<" and the answer is  "<<answer<<endl;
    return 0;
}

#include <iostream>

using namespace std;

int power(int a, int b){

    if(b==0)
        return 1;
    if(b==1)
        return a;
    int ans=power(a,b/2);

    if(b%2==0)
        return ans*ans;
    else
        return a*ans*ans;

}


int main()
{
    int a,b;
    cin>>a>>b;
    cout<<endl;
    int ans=power(a,b);
    cout<<"Answer is "<<ans<<endl;
    return 0;
}

