    reverse(name,l);
    return 0;
}

#include <iostream>
using namespace std;

void sort01(int arr[], int n) {
    int left = 0, right = n - 1;

    while (left < right) {
        // пропускаем уже правильные 0
        while (arr[left] == 0 && left < right)
            left++;

        // пропускаем уже правильные 1
        while (arr[right] == 1 && left < right)
            right--;

        // меняем местами
        if (left < right) {
            swap(arr[left], arr[right]);
            left++;
            right--;
        }
    }
}

int main() {
    int arr[] = {1, 0, 1, 0, 1, 0};
    int n = 6;

    sort01(arr, n);

    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

class Stack {
    Node* top;

public:
    Stack() {
        top = NULL;
    }

    void push(int x) {
        Node* temp = new Node;
        temp->data = x;
        temp->next = top;
        top = temp;
    }

    void pop() {
        if (top == NULL) {
            cout << "Empty\n";
            return;
        }
        Node* temp = top;
        top = top->next;
        delete temp;
    }

    int peek() {
        if (top == NULL) return -1;
        return top->data;
    }
};

