namespace bit_manipulation {
namespace count_of_trailing_ciphers_in_factorial_n {

uint64_t numberOfCiphersInFactorialN(uint64_t n) {
    uint64_t count = 0;

    for (uint64_t i = 5; n / i >= 1; i *= 5) {
        count += static_cast<uint64_t>(n) / i;
    }

    return count;
}
}
}

