static void test() {
    uint256_t a("4451685225093714772084598273548424"),
        b("2061118396808653202902996166388514"),
        mod("4451685225093714772084598273548427");

    ciphers::elliptic_curve_key_exchange::Point ptr = {
        uint256_t("188281465057972534892223778713752"),
        uint256_t("3419875491033170827167861896082688")};

    cout << "For alice:\n";
    uint256_t alice_private_key("164330438812053169644452143505618");
    ciphers::elliptic_curve_key_exchange::Point alice_public_key =
        ciphers::elliptic_curve_key_exchange::multiply(ptr, a, alice_private_key, mod);
    cout << "\tPrivate key: " << alice_private_key << "\n";
    cout << "\tPublic Key: " << alice_public_key << endl;

    cout << "For Bob:\n";
    uint256_t bob_private_key("1959473333748537081510525763478373");
    ciphers::elliptic_curve_key_exchange::Point bob_public_key =
        ciphers::elliptic_curve_key_exchange::multiply(ptr, a, bob_private_key, mod);
    cout << "\tPrivate key: " << bob_private_key << "\n";
    cout << "\tPublic Key: " << bob_public_key << endl;

    ciphers::elliptic_curve_key_exchange::Point alice_shared_key = 
        ciphers::elliptic_curve_key_exchange::multiply(bob_public_key, a, alice_private_key, mod);
    ciphers::elliptic_curve_key_exchange::Point bob_shared_key = 
        ciphers::elliptic_curve_key_exchange::multiply(alice_public_key, a, bob_private_key, mod);

    cout << "Shared keys:\n";
    cout << alice_shared_key << endl;
    cout << bob_shared_key << endl;

    assert(alice_shared_key == bob_shared_key);
}

int main() {
    uint128_t_tests();
    uint256_t_tests();
    test();
    return 0;
}

#include <iostream>
