string xorCipher(string text, char key) {
    string result = text;

    for (int i = 0; i < text.length(); i++) {
        result[i] = text[i] ^ key;
    }

    return result;
}

int main() {
    string text = "HELLO";
    char key = 'K';

    string encrypted = xorCipher(text, key);
    string decrypted = xorCipher(encrypted, key);

    cout << "Encrypted: " << encrypted << endl;
    cout << "Decrypted: " << decrypted << endl;
}

#include <iostream>
using namespace std;

string xorCipher(string text, string key) {
    string result = text;

    for (int i = 0; i < text.length(); i++) {
        result[i] = text[i] ^ key[i % key.length()];
    }

    return result;
}

int main() {
    string text = "HELLO WORLD";
    string key = "KEY";

    string encrypted = xorCipher(text, key);
    string decrypted = xorCipher(encrypted, key);

    cout << "Encrypted: " << encrypted << endl;
    cout << "Decrypted: " << decrypted << endl;
}

#include <cassert>
#include <functional>
#include <initializer_list>
#include <string>
#include <vector>
#include <iostream>

using namespace std;

namespace data_structures {

class Bitset {
 private:
    vector<size_t> data;
    static const size_t blockSize = sizeof(size_t);

 public:
    explicit Bitset(size_t);
    size_t size();
    void add(size_t);
    bool contains(size_t);
};

size_t Bitset::size() { return data.size(); }

Bitset::Bitset(size_t initSize) : data(initSize) {}

void Bitset::add(size_t x) {
    size_t blockIndex = x / blockSize;
    if (blockIndex >= data.size()) {
        data.resize(blockIndex + 1);
    }
    data[blockIndex] |= 1 << (x % blockSize);
}

bool Bitset::contains(size_t x) {
    size_t blockIndex = x / blockSize;
    if (blockIndex >= data.size()) {
        return false;
    }
    return data[blockIndex] & (1 << (x % blockSize));
}

template <typename T>
class BloomFilter {
 private:
    Bitset set;
    vector<function<size_t(T)>> hashFunks;

 public:
    BloomFilter(size_t,
                initializer_list<function<size_t(T)>>);
    void add(T);
    bool contains(T);
};

template <typename T>
BloomFilter<T>::BloomFilter(
    size_t size,
    initializer_list<function<size_t(T)>> funks)
    : set(size), hashFunks(funks) {}

template <typename T>
void BloomFilter<T>::add(T x) {
    for (size_t i = 0; i < hashFunks.size(); i++) {
        set.add(hashFunks[i](x) % (sizeof(size_t) * set.size()));
    }
}

template <typename T>
bool BloomFilter<T>::contains(T x) {
    for (size_t i = 0; i < hashFunks.size(); i++) {
        if (set.contains(hashFunks[i](x) %
                         (sizeof(size_t) * set.size())) == false) {
            return false;
        }
    }
    return true;
}

static size_t hashDJB2(string const& s) {
    size_t hash = 5381;
    for (char c : s) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

static size_t hashStr(string const& s) {
    size_t hash = 37;
    size_t primeNum1 = 54059;
    size_t primeNum2 = 76963;
    for (char c : s) {
        hash = (hash * primeNum1) ^ (c * primeNum2);
    }
    return hash;
}

size_t hashInt_1(int x) {
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = (x >> 16) ^ x;
    return x;
}

size_t hashInt_2(int x) {
    auto y = static_cast<size_t>(x);
    y = (y ^ (y >> 30)) * static_cast<size_t>(0xbf58476d1ce4e5b9);
    y = (y ^ (y >> 27)) * static_cast<size_t>(0x94d049bb133111eb);
    y = y ^ (y >> 31);
    return y;
}

} 

static void test_bloom_filter_string() {
    data_structures::BloomFilter<string> filter(
        10, {data_structures::hashDJB2, data_structures::hashStr});

    vector<string> toCheck{"hello", "world", "!"};
    vector<string> toFalse{"false", "world2", "!!!"};

    for (const auto& x : toCheck) {
        filter.add(x);
    }

    for (const auto& x : toFalse) {
        assert(filter.contains(x) == false);
    }

    for (const auto& x : toCheck) {
        assert(filter.contains(x));
    }
}

static void test_bloom_filter_int() {
    data_structures::BloomFilter<int> filter(
        20, {data_structures::hashInt_1, data_structures::hashInt_2});

    vector<int> toCheck{100, 200, 300, 50};
    vector<int> toFalse{1, 2, 3, 4, 5, 6, 7, 8};

    for (int x : toCheck) {
        filter.add(x);
    }

    for (int x : toFalse) {
        assert(filter.contains(x) == false);
    }

    for (int x : toCheck) {
        assert(filter.contains(x));
    }
}

static void test_bitset() {
    data_structures::Bitset set(2);

    vector<size_t> toCheck{0, 1, 5, 8, 63, 64, 67, 127};

    for (auto x : toCheck) {
        set.add(x);
        assert(set.contains(x));
    }

    assert(set.contains(128) == false);
    assert(set.contains(256) == false);
}

int main() {
    test_bitset();
    test_bloom_filter_string();
    test_bloom_filter_int();

    cout << "All tests have successfully passed!\n";
    return 0;
}

#include <iostream>

struct node {
    int data;
    struct node* next;
};
class Queue {
    node* front = nullptr;
    node* rear = nullptr;

    Queue(const Queue&) = delete;
    Queue& operator=(const Queue&) = delete;

 public:
    Queue() = default;
    ~Queue() {
        while (front) {
            dequeue();
        }
    }

 private:
    void createNode(int val) {
        auto* nn = new node;
        nn->data = val;
        nn->next = nullptr;
        front = nn;
        rear = nn;
    }

 public:
    void enqueue(int val) {
        if (front == nullptr || rear == nullptr) {
            createNode(val);
        } else {
            node* nn = new node;
            nn->data = val;
            rear->next = nn;
            nn->next = front;
            rear = nn;
        }
    }
    void dequeue() {
        if (front == nullptr) {
            return;
        }
        const node* const n = front;
        if (front == rear) {
            front = nullptr;
            rear = nullptr;
        } else {
            front = front->next;
            rear->next = front;
        }
        delete n;
    }
    void traverse() {
        if (front == nullptr) {
            return;
        }
        const node* ptr = front;
        do {
            std::cout << ptr->data << ' ';
            ptr = ptr->next;
        } while (ptr != front);
        std::cout << '\n';
    }
};
int main(void) {
    Queue q;
    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);
    q.enqueue(40);
    q.enqueue(50);
    q.enqueue(60);
    q.enqueue(70);
    q.traverse();
    q.dequeue();
    q.traverse();
    return 0;
}

#include <cstdio>
#include <cstdlib>
#include <iostream>

using namespace std;

struct node {
    int val;
    node *prev;
    node *next;
} *start;

class double_linked_list {
 public:
    double_linked_list() { start = NULL; }
    void insert(int x);
    void remove(int x);
    void search(int x);
    void show();
    void reverseShow();
};

void double_linked_list::insert(int x) {
    node *t = start;
    if (start != NULL) {
        while (t->next != NULL) {
            t = t->next;
        }
        node *n = new node;
        t->next = n;
        n->prev = t;
        n->val = x;
        n->next = NULL;
    } else {
        node *n = new node;
        n->val = x;
        n->prev = NULL;
        n->next = NULL;
        start = n;
    }
}

void double_linked_list::remove(int x) {
    node *t = start;
    while (t != NULL && t->val != x) {
        t = t->next;
    }
    if (t == NULL) {
        return;
    }
    if (t->prev == NULL) {
        if (t->next == NULL) {
            start = NULL;
        } else {
            start = t->next;
            start->prev = NULL;
        }
    } else if (t->next == NULL) {
        t->prev->next = NULL;
    } else {
        t->prev->next = t->next;
        t->next->prev = t->prev;
    }
    delete t;
}

void double_linked_list::search(int x) {
    node *t = start;
    int found = 0;
    while (t != NULL) {
        if (t->val == x) {
            cout << "\nFound";
            found = 1;
            break;
        }
        t = t->next;
    }
    if (found == 0) {
        cout << "\nNot Found";
    }
}

void double_linked_list::show() {
    node *t = start;
    while (t != NULL) {
        cout << t->val << "\t";
        t = t->next;
    }
}

void double_linked_list::reverseShow() {
    node *t = start;
    while (t != NULL && t->next != NULL) {
        t = t->next;
    }
    while (t != NULL) {
        cout << t->val << "\t";
        t = t->prev;
    }
}

int main() {
    int choice, x;
    double_linked_list ob;

    do {
        cout << "\n1. Insert";
        cout << "\n2. Delete";
        cout << "\n3. Search";
        cout << "\n4. Forward print";
        cout << "\n5. Reverse print";
        cout << "\n\nEnter you choice : ";
        cin >> choice;

        switch (choice) {
        case 1:
            cout << "\nEnter the element to be inserted : ";
            cin >> x;
            ob.insert(x);
            break;
        case 2:
            cout << "\nEnter the element to be removed : ";
            cin >> x;
            ob.remove(x);
            break;
        case 3:
            cout << "\nEnter the element to be searched : ";
            cin >> x;
            ob.search(x);
            break;
        case 4:
            ob.show();
            break;
        case 5:
            ob.reverseShow();
            break;
        }
    } while (choice != 0);

    return 0;
}

#include <iostream>
using namespace std;

class DSU {
    int parent[100];
    int rank[100];

public:
    DSU(int n) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    // find с path compression
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);

        return parent[x];
    }

    // union by rank
    void unite(int x, int y) {
        int px = find(x);
        int py = find(y);

        if (px == py) return;

        if (rank[px] < rank[py]) {
            parent[px] = py;
        }
        else if (rank[px] > rank[py]) {
            parent[py] = px;
        }
        else {
            parent[py] = px;
            rank[px]++;
        }
    }

    void print(int n) {
        for (int i = 0; i < n; i++)
            cout << parent[i] << " ";
        cout << endl;
    }
};

int main() {
    DSU dsu(6);

    dsu.unite(0, 1);
    dsu.unite(2, 3);
    dsu.unite(4, 5);

    dsu.unite(1, 3);
    dsu.unite(3, 5);

    dsu.print(6);

    return 0;
}

#include <iostream>

using namespace std;

struct Node {
    int data;
    int next;
};

Node AvailArray[100];

int head = -1;
int avail = 0;

void initialise_list() {
    for (int i = 0; i <= 98; i++) {
        AvailArray[i].next = i + 1;
    }
    AvailArray[99].next = -1;
}

int getnode() {
    int NodeIndexToBeReturned = avail;
    avail = AvailArray[avail].next;
    return NodeIndexToBeReturned;
}

void freeNode(int nodeToBeDeleted) {
    AvailArray[nodeToBeDeleted].next = avail;
    avail = nodeToBeDeleted;
}

void insertAtTheBeginning(int data) {
    int newNode = getnode();
    AvailArray[newNode].data = data;
    AvailArray[newNode].next = head;
    head = newNode;
}

void insertAtTheEnd(int data) {
    int newNode = getnode();

    if (head == -1) {
        AvailArray[newNode].data = data;
        AvailArray[newNode].next = -1;
        head = newNode;
        return;
    }

    int temp = head;
    while (AvailArray[temp].next != -1) {
        temp = AvailArray[temp].next;
    }

    AvailArray[newNode].data = data;
    AvailArray[newNode].next = -1;
    AvailArray[temp].next = newNode;
}

void display() {
    int temp = head;
    while (temp != -1) {
        cout << AvailArray[temp].data << "->";
        temp = AvailArray[temp].next;
    }
    cout << "-1" << endl;
}

int main() {
    initialise_list();

    int x, y, z;

    while (true) {
        cout << "1. Insert At The Beginning" << endl;
        cout << "2. Insert At The End" << endl;
        cout << "3. Display" << endl;
        cout << "4.Exit" << endl;
        cout << "Enter Your choice" << endl;

        cin >> z;

        switch (z) {
        case 1:
            cout << "Enter the number you want to enter" << endl;
            cin >> x;
            insertAtTheBeginning(x);
            break;

        case 2:
            cout << "Enter the number you want to enter" << endl;
            cin >> y;
            insertAtTheEnd(y);
            break;

        case 3:
            cout << "The linked list contains the following element in order" << endl;
            display();
            break;

        case 4:
            return 0;

        default:
            cout << "The entered choice is not correct" << endl;
        }
    }

    return 0;
}

#ifndef DATA_STRUCTURES_QUEUE_HPP_
#define DATA_STRUCTURES_QUEUE_HPP_

#include <iostream>
#include <vector>
#include <memory>
#include <stdexcept>

using namespace std;

template <class ValueType>
struct Node {
    ValueType data;
    shared_ptr<Node<ValueType>> next;
};

template <class ValueType>
class queue {
    using node_type = Node<ValueType>;

 public:
    using value_type = ValueType;

    void display() const {
        cout << "Front --> ";
        auto temp = queueFront;
        while (temp != nullptr) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << '\n';
        cout << "Size of queue: " << size << '\n';
    }

    vector<value_type> toVector() const {
        vector<value_type> result;
        auto temp = queueFront;
        while (temp != nullptr) {
            result.push_back(temp->data);
            temp = temp->next;
        }
        return result;
    }

 private:
    void ensureNotEmpty() const {
        if (isEmptyQueue()) {
            throw invalid_argument("Queue is empty.");
        }
    }

 public:
    bool isEmptyQueue() const {
        return (queueFront == nullptr);
    }

    void enQueue(const value_type& item) {
        auto newNode = make_shared<node_type>();
        newNode->data = item;
        newNode->next = nullptr;

        if (isEmptyQueue()) {
            queueFront = newNode;
            queueRear = newNode;
        } else {
            queueRear->next = newNode;
            queueRear = queueRear->next;
        }
        ++size;
    }

    value_type front() const {
        ensureNotEmpty();
        return queueFront->data;
    }

    void deQueue() {
        ensureNotEmpty();
        queueFront = queueFront->next;
        --size;
    }

    void clear() {
        queueFront = nullptr;
        queueRear = nullptr;
        size = 0;
    }

 private:
    shared_ptr<node_type> queueFront = {};
    shared_ptr<node_type> queueRear = {};
    size_t size = 0;
};

#endif

#include <iostream>
#include <queue>
using namespace std;

class Stack {
private:
    queue<int> q;

public:
    // PUSH
    void push(int x) {
        int size = q.size();
        q.push(x);

        // вращаем очередь
        for (int i = 0; i < size; i++) {
            q.push(q.front());
            q.pop();
        }
    }

    // POP
    void pop() {
        if (q.empty()) {
            cout << "Stack is empty\n";
            return;
        }
        q.pop();
    }

    // PEEK
    int top() {
        if (q.empty()) return -1;
        return q.front();
    }

    bool isEmpty() {
        return q.empty();
    }
};

int main() {
    Stack s;

    s.push(10);
    s.push(20);
    s.push(30);

    cout << "Top: " << s.top() << endl; // 30

    s.pop();
    cout << "Top after pop: " << s.top() << endl; // 20

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

class Stack {
private:
    Node* top;

public:
    Stack() {
        top = nullptr;
    }

    bool isEmpty() {
        return top == nullptr;
    }

    void push(int x) {
        Node* temp = new Node;
        temp->data = x;
        temp->next = top;
        top = temp;
    }

    void pop() {
        if (isEmpty()) {
            cout << "Underflow\n";
            return;
        }
        Node* temp = top;
        top = top->next;
        delete temp;
    }

    int peek() {
        if (isEmpty()) return -1;
        return top->data;
    }

    void display() {
        Node* temp = top;
        while (temp != nullptr) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }
};

int main() {
    Stack s;
    int choice, x;

    do {
        cin >> choice;

        switch (choice) {
        case 1:
            cin >> x;
            s.push(x);
            break;
        case 2:
            s.pop();
            break;
        case 3:
            cout << s.peek() << endl;
            break;
        case 4:
            s.display();
            break;
        }

    } while (choice != 0);

    return 0;
}

#include <iostream>
#include <list>

using namespace std;

struct node {
    int val;
    node *left;
    node *right;
};

void CreateTree(node *curr, node *n, int x, char pos) {
    if (n != NULL) {
        char ch;
        cout << "\nLeft or Right of " << n->val << " : ";
        cin >> ch;

        if (ch == 'l')
            CreateTree(n, n->left, x, ch);
        else if (ch == 'r')
            CreateTree(n, n->right, x, ch);
    } else {
        node *t = new node;
        t->val = x;
        t->left = NULL;
        t->right = NULL;

        if (pos == 'l')
            curr->left = t;
        else if (pos == 'r')
            curr->right = t;
    }
}

void BFT(node *n) {
    list<node *> queue;
    queue.push_back(n);

    while (!queue.empty()) {
        n = queue.front();
        cout << n->val << "  ";
        queue.pop_front();

        if (n->left != NULL)
            queue.push_back(n->left);
        if (n->right != NULL)
            queue.push_back(n->right);
    }
}

void Pre(node *n) {
    if (n != NULL) {
        cout << n->val << "  ";
        Pre(n->left);
        Pre(n->right);
    }
}

void In(node *n) {
    if (n != NULL) {
        In(n->left);
        cout << n->val << "  ";
        In(n->right);
    }
}

void Post(node *n) {
    if (n != NULL) {
        Post(n->left);
        Post(n->right);
        cout << n->val << "  ";
    }
}

int main() {
    int value, ch;
    node *root = new node;

    cout << "\nEnter the value of root node : ";
    cin >> value;

    root->val = value;
    root->left = NULL;
    root->right = NULL;

    do {
        cout << "\n1. Insert";
        cout << "\n2. Breadth First";
        cout << "\n3. Preorder";
        cout << "\n4. Inorder";
        cout << "\n5. Postorder";
        cout << "\nEnter Your Choice : ";

        cin >> ch;

        switch (ch) {
        case 1: {
            int x;
            char pos;

            cout << "\nEnter the value to be Inserted : ";
            cin >> x;

            cout << "\nLeft or Right of Root : ";
            cin >> pos;

            if (pos == 'l')
                CreateTree(root, root->left, x, pos);
            else if (pos == 'r')
                CreateTree(root, root->right, x, pos);

            break;
        }

        case 2:
            BFT(root);
            break;

        case 3:
            Pre(root);
            break;

        case 4:
            In(root);
            break;

        case 5:
            Post(root);
            break;
        }

    } while (ch != 0);

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
};

Node* create(int x) {
    Node* n = new Node;
    n->data = x;
    n->left = n->right = nullptr;
    return n;
}

Node* insert(Node* root, int x) {
    if (!root) return create(x);
    if (x < root->data)
        root->left = insert(root->left, x);
    else
        root->right = insert(root->right, x);
    return root;
}

bool search(Node* root, int x) {
    if (!root) return false;
    if (root->data == x) return true;
    if (x < root->data) return search(root->left, x);
    return search(root->right, x);
}

Node* findMin(Node* root) {
    while (root && root->left) root = root->left;
    return root;
}

Node* deleteNode(Node* root, int x) {
    if (!root) return root;

    if (x < root->data)
        root->left = deleteNode(root->left, x);
    else if (x > root->data)
        root->right = deleteNode(root->right, x);
    else {
        if (!root->left) {
            Node* temp = root->right;
            delete root;
            return temp;
        }
        else if (!root->right) {
            Node* temp = root->left;
            delete root;
            return temp;
        }

        Node* temp = findMin(root->right);
        root->data = temp->data;
        root->right = deleteNode(root->right, temp->data);
    }
    return root;
}

void inorder(Node* root) {
    if (root) {
        inorder(root->left);
        cout << root->data << " ";
        inorder(root->right);
    }
}

void preorder(Node* root) {
    if (root) {
        cout << root->data << " ";
        preorder(root->left);
        preorder(root->right);
    }
}

void postorder(Node* root) {
    if (root) {
        postorder(root->left);
        postorder(root->right);
        cout << root->data << " ";
    }
}

int main() {
    Node* root = nullptr;

    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 70);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 60);
    root = insert(root, 80);

    inorder(root);
    cout << endl;

    preorder(root);
    cout << endl;

    postorder(root);
    cout << endl;

    cout << search(root, 60) << endl;

    root = deleteNode(root, 50);

    inorder(root);
    cout << endl;

    return 0;
}

#include <cassert>
#include <iostream>
#include <memory>
#include <stack>
#include <unordered_map>
#include <vector>

using namespace std;

namespace data_structures {
namespace trie_using_hashmap {

class Trie {
 private:
    struct Node {
        unordered_map<char16_t, shared_ptr<Node>> children;
        bool word_end = false;
    };

    shared_ptr<Node> root_node = make_shared<Node>();

 public:
    Trie() = default;

    void insert(const string& word) {
        shared_ptr<Node> curr = root_node;
        for (char ch : word) {
            if (curr->children.find(ch) == curr->children.end()) {
                curr->children[ch] = make_shared<Node>();
            }
            curr = curr->children[ch];
        }
        if (!curr->word_end && curr != root_node) {
            curr->word_end = true;
        }
    }

    bool search(const string& word) {
        shared_ptr<Node> curr = root_node;
        for (char ch : word) {
            if (curr->children.find(ch) == curr->children.end()) {
                return false;
            }
            curr = curr->children[ch];
            if (!curr) return false;
        }
        return curr->word_end;
    }

    bool startwith(const string& prefix) {
        shared_ptr<Node> curr = root_node;
        for (char ch : prefix) {
            if (curr->children.find(ch) == curr->children.end()) {
                return false;
            }
            curr = curr->children[ch];
        }
        return true;
    }

    void delete_word(string word) {
        shared_ptr<Node> curr = root_node;
        stack<shared_ptr<Node>> nodes;

        for (char ch : word) {
            if (curr->children.find(ch) == curr->children.end()) return;
            nodes.push(curr->children[ch]);
            curr = curr->children[ch];
        }

        if (nodes.top()->word_end) {
            nodes.top()->word_end = false;
        }

        while (!nodes.empty() &&
               !nodes.top()->word_end &&
               nodes.top()->children.empty()) {

            nodes.pop();
            if (!nodes.empty()) {
                nodes.top()->children.erase(word.back());
                word.pop_back();
            }
        }
    }

    vector<string> get_all_words(vector<string> results,
                                const shared_ptr<Node>& element,
                                string prefix) {
        if (element->word_end) results.push_back(prefix);

        for (auto const& x : element->children) {
            prefix.push_back(static_cast<char>(x.first));
            results = get_all_words(results, x.second, prefix);
            prefix.pop_back();
        }

        return results;
    }

    vector<string> predict_words(const string& prefix) {
        vector<string> result;
        shared_ptr<Node> curr = root_node;

        for (char ch : prefix) {
            if (curr->children.find(ch) == curr->children.end()) {
                return result;
            }
            curr = curr->children[ch];
        }

        if (curr->word_end && curr->children.empty()) {
            result.push_back(prefix);
            return result;
        }

        return get_all_words(result, curr, prefix);
    }
};

}  
}

static void test() {
    data_structures::trie_using_hashmap::Trie obj;

    obj.insert("app");
    obj.insert("abscond");
    obj.insert("about");
    obj.insert("apps");
    obj.insert("apen");
    obj.insert("apples");
    obj.insert("apple");
    obj.insert("approach");
    obj.insert("bus");
    obj.insert("buses");
    obj.insert("Apple");
    obj.insert("Bounce");

    assert(!obj.search("appy"));
    cout << "appy is not a word in trie\n";

    assert(!obj.search("car"));
    cout << "car is not a word in trie\n";

    assert(obj.search("app"));
    assert(obj.search("apple"));

    cout << "All words exist\n";

    vector<string> pred = obj.predict_words("app");

    for (auto& s : pred) {
        cout << s << endl;
    }

    obj.delete_word("app");
    assert(!obj.search("app"));

    cout << "delete works\n";
}

int main() {
    test();
    return 0;
}

/**
 * @file
 * @brief [Eight Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle)
 * puzzle, printing all solutions
 *
 * @author [Himani Negi](https://github.com/Himani2000)
 * @author [David Leal](https://github.com/Panquesito7)
 *
 */
#include <array>     /// for std::array
#include <iostream>  /// for IO operations

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace n_queens_all_solutions
 * @brief Functions for the [Eight
 * Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle) puzzle with all
 * solutions.
 */
namespace n_queens_all_solutions {
/**
 * @brief Utility function to print matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 */
template <size_t n>
void PrintSol(const std::array<std::array<int, n>, n>& board) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << board[i][j] << " ";
        }
        std::cout << std::endl;
    }
    std::cout << std::endl;
}

/**
 * @brief Check if a queen can be placed on the matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param row current index in rows
 * @param col current index in columns
 * @returns `true` if queen can be placed on matrix
 * @returns `false` if queen can't be placed on matrix
 */
template <size_t n>
bool CanIMove(const std::array<std::array<int, n>, n>& board, int row,
              int col) {
    /// check in the row
    for (int i = 0; i < col; i++) {
        if (board[row][i] == 1) {
            return false;
        }
    }
    /// check the first diagonal
    for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }
    /// check the second diagonal
    for (int i = row, j = col; i <= n - 1 && j >= 0; i++, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }
    return true;
}

/**
 * @brief Main function to solve the N Queens problem
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param col current index in columns
 */
template <size_t n>
void NQueenSol(std::array<std::array<int, n>, n> board, int col) {
    if (col >= n) {
        PrintSol(board);
        return;
    }
    for (int i = 0; i < n; i++) {
        if (CanIMove(board, i, col)) {
            board[i][col] = 1;
            NQueenSol(board, col + 1);
            board[i][col] = 0;
        }
    }
}
}  // namespace n_queens_all_solutions
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    const int n = 4;
    std::array<std::array<int, n>, n> board{0};

    backtracking::n_queens_all_solutions::NQueenSol(board, 0);
}

/**
 * Enumerates and prints every distinct arrangement of N non-attacking queens
 * on an N x N board, using plain (unoptimized) column-by-column backtracking.
 */

#include <array>
#include <iostream>

namespace backtracking {
namespace queens_enum {

// Prints the full board, one row per line.
template <size_t dim>
void dumpBoard(const std::array<std::array<int, dim>, dim> &grid) {
    for (size_t row = 0; row < dim; ++row) {
        for (size_t col = 0; col < dim; ++col) {
            std::cout << grid[row][col] << ' ';
        }
        std::cout << '\n';
    }
    std::cout << '\n';
}

// Verifies no existing queen threatens the (row, col) cell via row,
// or either diagonal.
template <size_t dim>
bool placementAllowed(const std::array<std::array<int, dim>, dim> &grid,
                      int row, int col) {
    for (int c = 0; c < col; ++c) {
        if (grid[row][c] == 1) return false;
    }

    int r = row, c = col;
    while (r >= 0 && c >= 0) {
        if (grid[r][c] == 1) return false;
        --r;
        --c;
    }

    r = row;
    c = col;
    while (r <= static_cast<int>(dim) - 1 && c >= 0) {
        if (grid[r][c] == 1) return false;
        ++r;
        --c;
    }

    return true;
}

// Backtracking driver: try every row for the current column, recurse, undo.
template <size_t dim>
void fillColumn(std::array<std::array<int, dim>, dim> grid, int col) {
    if (col >= static_cast<int>(dim)) {
        dumpBoard(grid);
        return;
    }

    for (size_t row = 0; row < dim; ++row) {
        if (placementAllowed(grid, static_cast<int>(row), col)) {
            grid[row][col] = 1;
            fillColumn(grid, col + 1);
            grid[row][col] = 0;
        }
    }
}

}  // namespace queens_enum
}  // namespace backtracking

int main() {
    constexpr int boardSize = 4;
    std::array<std::array<int, boardSize>, boardSize> grid{};
    for (auto &row : grid) row.fill(0);

    backtracking::queens_enum::fillColumn(grid, 0);
    return 0;
}

/**
 * @file
 * @brief [Subset-sum](https://en.wikipedia.org/wiki/Subset_sum_problem) (only
 * continuous subsets) problem
 * @details We are given an array and a sum value. The algorithms find all
 * the subarrays of that array with sum equal to the given sum and return such
 * subarrays count. This approach will have \f$O(n)\f$ time complexity and
 * \f$O(n)\f$ space complexity. NOTE: In this problem, we are only referring to
 * the continuous subsets as subarrays everywhere. Subarrays can be created
 * using deletion operation at the end of the front of an array only. The parent
 * array is also counted in subarrays having 0 number of deletion operations.
 *
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <cassert>        /// for assert
#include <cstdint>
#include <iostream>       /// for IO operations
#include <unordered_map>  /// for unordered_map
#include <vector>         /// for std::vector

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace subarray_sum
 * @brief Functions for the [Subset
 * sum](https://en.wikipedia.org/wiki/Subset_sum_problem) implementation
 */
namespace subarray_sum {
/**
 * @brief The main function that implements the count of the subarrays
 * @param sum is the required sum of any subarrays
 * @param in_arr is the input array
 * @returns count of the number of subsets with required sum
 */
uint64_t subarray_sum(int64_t sum, const std::vector<int64_t> &in_arr) {
    int64_t nelement = in_arr.size();
    int64_t count_of_subset = 0;
    int64_t current_sum = 0;
    std::unordered_map<int64_t, int64_t>
        sumarray;  // to store the subarrays count
                   // frequency having some sum value

    for (int64_t i = 0; i < nelement; i++) {
        current_sum += in_arr[i];

        if (current_sum == sum) {
            count_of_subset++;
        }
        // If in case current_sum is greater than the required sum
        if (sumarray.find(current_sum - sum) != sumarray.end()) {
            count_of_subset += (sumarray[current_sum - sum]);
        }
        sumarray[current_sum]++;
    }
    return count_of_subset;
}
}  // namespace subarray_sum
}  // namespace backtracking

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::cout << "1st test ";
    std::vector<int64_t> array1 = {-7, -3, -2, 5, 8};  // input array
    assert(
