/**
 * Counts contiguous slices (subarrays) of an integer array whose elements
 * add up to a target value, in linear time using a running-sum frequency
 * map (a prefix-sum / hash-map technique rather than brute force).
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <unordered_map>
#include <vector>

namespace backtracking {
namespace contiguous_sum {

// Walks the array once, tracking how many times each prefix sum has been
// seen so far, to count how many contiguous ranges hit `target`.
uint64_t countRanges(int64_t target, const std::vector<int64_t> &values) {
    int64_t size = static_cast<int64_t>(values.size());
    int64_t matches = 0;
    int64_t runningTotal = 0;

    std::unordered_map<int64_t, int64_t> seenTotals;

    int64_t idx = 0;
    while (idx < size) {
        runningTotal += values[idx];

        if (runningTotal == target) {
            ++matches;
        }

        auto it = seenTotals.find(runningTotal - target);
        if (it != seenTotals.end()) {
            matches += it->second;
        }

        seenTotals[runningTotal]++;
        ++idx;
    }

    return static_cast<uint64_t>(matches);
}

}  // namespace contiguous_sum
}  // namespace backtracking

static void runSelfCheck() {
    std::cout << "case A ";
    std::vector<int64_t> dataA = {-7, -3, -2, 5, 8};
    assert(backtracking::contiguous_sum::countRanges(0, dataA) == 1);
    std::cout << "ok" << std::endl;

    std::cout << "case B ";
    std::vector<int64_t> dataB = {1, 2, 3, 3};
    assert(backtracking::contiguous_sum::countRanges(6, dataB) == 2);
    std::cout << "ok" << std::endl;

    std::cout << "case C ";
    std::vector<int64_t> dataC = {1, 1, 1, 1};
    assert(backtracking::contiguous_sum::countRanges(1, dataC) == 4);
    std::cout << "ok" << std::endl;

    std::cout << "case D ";
    std::vector<int64_t> dataD = {3, 3, 3, 3};
    assert(backtracking::contiguous_sum::countRanges(6, dataD) == 3);
    std::cout << "ok" << std::endl;

    std::cout << "case E ";
    std::vector<int64_t> dataE = {};
    assert(backtracking::contiguous_sum::countRanges(6, dataE) == 0);
    std::cout << "ok" << std::endl;
}

int main() {
    runSelfCheck();
    return 0;
}

/**
 * @file
 * @brief Implementation of the [Subset
 * Sum](https://en.wikipedia.org/wiki/Subset_sum_problem) problem.
 * @details
 * We are given an array and a sum value. The algorithm finds all
 * the subsets of that array with sum equal to the given sum and return such
 * subsets count. This approach will have exponential time complexity.
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace Subsets
 * @brief Functions for the [Subset
 * Sum](https://en.wikipedia.org/wiki/Subset_sum_problem) problem.
 */
namespace subset_sum {
/**
 * @brief The main function implements count of subsets
 * @param sum is the required sum of any subset
 * @param in_arr is the input array
 * @returns count of the number of subsets with required sum
 */
uint64_t number_of_subsets(int32_t sum, const std::vector<int32_t> &in_arr) {
    int32_t nelement = in_arr.size();
    uint64_t count_of_subset = 0;

    for (int32_t i = 0; i < (1 << (nelement)); i++) {
        int32_t check = 0;
        for (int32_t j = 0; j < nelement; j++) {
            if (i & (1 << j)) {
                check += (in_arr[j]);
            }
        }
        if (check == sum) {
            count_of_subset++;
        }
    }
    return count_of_subset;
}
}  // namespace subset_sum
}  // namespace backtracking

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::cout << "1st test ";
    std::vector<int32_t> array1 = {-7, -3, -2, 5, 8};  // input array
    assert(backtracking::subset_sum::number_of_subsets(0, array1) ==
           2);  // first argument in subset_sum function is the required sum and
                // second is the input array
    std::cout << "passed" << std::endl;

    // 2nd test
    std::cout << "2nd test ";
    std::vector<int32_t> array2 = {1, 2, 3, 3};
    assert(backtracking::subset_sum::number_of_subsets(6, array2) ==
           3);  // here we are expecting 3 subsets which sum up to 6 i.e.
                // {(1,2,3),(1,2,3),(3,3)}
    std::cout << "passed" << std::endl;

    // 3rd test
    std::cout << "3rd test ";
    std::vector<int32_t> array3 = {1, 1, 1, 1};
    assert(backtracking::subset_sum::number_of_subsets(1, array3) ==
           4);  // here we are expecting 4 subsets which sum up to 1 i.e.
                // {(1),(1),(1),(1)}
    std::cout << "passed" << std::endl;

    // 4th test
    std::cout << "4th test ";
    std::vector<int32_t> array4 = {3, 3, 3, 3};
    assert(backtracking::subset_sum::number_of_subsets(6, array4) ==
