/**
 * @file hill_cipher.cpp
 * @brief Alternate implementation of the Hill cipher
 * (https://en.wikipedia.org/wiki/Hill_cipher) block cipher algorithm.
 *
 * The Hill cipher encrypts fixed-size blocks of text by treating each block
 * as a vector and multiplying it by a square key matrix modulo the size of
 * the character alphabet. Decryption uses the modular inverse of that
 * matrix. For the matrix to be usable it must be invertible modulo the
 * alphabet size, i.e. its determinant must be coprime with that size.
 *
 * This variant restructures the original HillCipher class into a set of
 * free functions grouped in a namespace, but preserves the same overall
 * algorithm: random key generation, modular matrix inversion via
 * Gauss-Jordan elimination, and block encode/decode.
 *
 * \note Relies on determinant_lu from lu_decomposition.h, same as original.
 */

#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <ctime>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <string>
#ifdef _OPENMP
#include <omp.h>
#endif

#include "../numerical_methods/lu_decomposition.h"

/// Pretty-prints a matrix for debugging/output purposes.
template <typename T>
static std::ostream &operator<<(std::ostream &out, matrix<T> const &m) {
    constexpr int kColumnWidth = 15;
    constexpr char kFill = ' ';
    for (size_t r = 0; r < m.size(); r++) {
        for (size_t c = 0; c < m[r].size(); c++) {
            out << std::left << std::setw(kColumnWidth) << std::setfill(kFill)
                << m[r][c];
        }
        out << std::endl;
    }
    return out;
}

namespace ciphers {

/// The alphabet of characters the cipher can encode/decode.
static const char *kAlphabet =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789~!@#$%^&"
    "*()_+`-=[]{}|;':\",./<>?\\\r\n \0";

namespace hill_detail {

/// Generates a uniform random value scaled into [lo, hi).
template <typename TIn, typename TOut>
TOut uniform_random(TIn lo, TIn hi) {
    long double unit = static_cast<long double>(std::rand()) / RAND_MAX;
    return static_cast<TOut>(unit * (hi - lo) + lo);
}

/// Fills a matrix with random integers in [lo, hi) and returns its
/// determinant.
template <typename TIn, typename TVal>
double fill_random_matrix(matrix<TVal> *target, TIn lo, TIn hi) {
    for (size_t r = 0; r < target->size(); r++) {
        for (size_t c = 0; c < target[0][0].size(); c++) {
            target[0][r][c] = uniform_random<TIn, TVal>(lo, hi);
        }
    }
    return determinant_lu(*target);
}

/// Euclidean algorithm for greatest common divisor.
template <typename T>
T gcd_of(T x, T y) {
    if (y > x) std::swap(x, y);
    while (y != 0) {
        T rem = x % y;
        x = y;
        y = rem;
    }
    return x;
}

/// Applies the key matrix to a block vector, reducing modulo the alphabet
/// size.
std::valarray<uint8_t> apply_matrix(const std::valarray<uint8_t> &block,
                                    const matrix<int> &key) {
    std::valarray<uint8_t> transformed(block);
    size_t alphabet_len = std::strlen(kAlphabet);

    for (size_t row = 0; row < key.size(); row++) {
        int acc = 0;
        for (size_t col = 0; col < block.size(); col++) {
            acc += key[row][col] * block[col];
        }
        transformed[row] = static_cast<uint8_t>(acc % alphabet_len);
    }
    return transformed;
}

/// Looks up the character stored at a given alphabet index.
inline char char_at(uint8_t index) { return kAlphabet[index]; }

/// Finds the alphabet index of a character (linear scan).
inline uint8_t index_of_char(char ch) {
    size_t alphabet_len = std::strlen(kAlphabet);
    for (size_t i = 0; i <= alphabet_len; i++) {
        if (kAlphabet[i] == ch) return static_cast<uint8_t>(i);
    }
    std::cerr << __func__ << ":" << __LINE__ << ": (" << ch
              << ") Should not reach here!\n";
    return 0;
}

/// Shared routine for block-based encode/decode: chunks `text` into blocks
/// matching the key's dimension and multiplies each block by `key`.
std::string apply_block_cipher(const std::string &text, const matrix<int> &key) {
    size_t text_len = text.length();
    size_t block_size = key.size();

    size_t padded_len = (text_len % block_size == 0)
                            ? text_len
                            : text_len + block_size - (text_len % block_size);
    std::string out(padded_len, '\0');

    int i;
#ifdef _OPENMP
#pragma parallel omp for private(i)
#endif
    for (i = 0; i < static_cast<int>(padded_len) - static_cast<int>(block_size) + 1;
         i += static_cast<int>(block_size)) {
        std::valarray<uint8_t> block(block_size);
        for (size_t j = 0; j < block_size; j++) {
            block[j] = index_of_char(text[i + j]);
        }

        block = apply_matrix(block, key);

        for (size_t j = 0; j < block_size; j++) {
            out[i + j] = kAlphabet[block[j]];
        }
    }

    return out;
}

/// Computes the matrix inverse via Gauss-Jordan row reduction (no modular
/// arithmetic here -- that's applied afterwards).
template <typename T>
matrix<double> gauss_jordan_inverse(matrix<T> const &input) {
    size_t n = input.size();

    matrix<double> inverse(n, std::valarray<double>(n));
    for (size_t r = 0; r < n; r++) {
        for (size_t c = 0; c < n; c++) {
            inverse[r][c] = (r == c) ? 1.0 : 0.0;
        }
    }

    if (input.size() != input[0].size()) {
        std::cerr << "Input must be a square matrix!" << std::endl;
        return inverse;
    }

    matrix<double> work(n, std::valarray<double>(n));
    for (size_t r = 0; r < n; r++) {
        for (size_t c = 0; c < n; c++) {
            work[r][c] = static_cast<double>(input[r][c]);
        }
    }

    for (size_t pivot_row = 0; pivot_row < n; pivot_row++) {
        for (size_t alt_row = pivot_row; alt_row < n && work[pivot_row][pivot_row] == 0;
             alt_row++) {
            work[pivot_row] = work[pivot_row] + work[alt_row];
            inverse[pivot_row] = inverse[pivot_row] + inverse[alt_row];
        }

        for (size_t alt_col = pivot_row;
             alt_col < n && work[pivot_row][pivot_row] == 0; alt_col++) {
            for (size_t r2 = 0; r2 < n; r2++) {
                work[r2][pivot_row] = work[r2][pivot_row] + work[r2][alt_col];
                inverse[r2][pivot_row] =
                    inverse[r2][pivot_row] + inverse[r2][alt_col];
            }
        }

        if (work[pivot_row][pivot_row] == 0) {
            std::cerr << "Low-rank matrix, no inverse!" << std::endl;
            return inverse;
        }

        double pivot_value = work[pivot_row][pivot_row];
        work[pivot_row] = work[pivot_row] / pivot_value;
        inverse[pivot_row] = inverse[pivot_row] / pivot_value;

        for (size_t r2 = 0; r2 < n; r2++) {
            if (r2 == pivot_row) continue;
            double factor = work[r2][pivot_row];
            work[r2] = work[r2] - factor * work[pivot_row];
            inverse[r2] = inverse[r2] - factor * inverse[pivot_row];
        }
    }

    return inverse;
}

/// Modulo that always returns a non-negative remainder.
inline int positive_mod(int a, int m) {
    int r = a % m;
    return r < 0 ? r + m : r;
}

}  // namespace hill_detail

/**
 * @brief Random key generation, modular inversion, and block
 * encode/decode for the Hill cipher.
 */
namespace hill_cipher {

/**
 * @brief Generates a random square encryption key matrix that is invertible
 * modulo the alphabet length.
 */
matrix<int> make_encryption_key(size_t dimension, int lo = 0, int hi = 10) {
    matrix<int> key(dimension, std::valarray<int>(dimension));
    int alphabet_len = static_cast<int>(std::strlen(kAlphabet));

    double det;
    int det_int;
    do {
        det = hill_detail::fill_random_matrix(&key, lo, hi);
        det_int = static_cast<int>(det);
        if (det_int < 0) det_int %= alphabet_len;
    } while (std::abs(det) > 1e3 || det < 0.1 || !std::isfinite(det) ||
             hill_detail::gcd_of(det_int, alphabet_len) != 1);

    return key;
}

/**
 * @brief Derives the decryption key (modular inverse of the encryption key)
 * from a given encryption key.
 */
matrix<int> make_decryption_key(matrix<int> const &encryption_key) {
    size_t dimension = encryption_key.size();
    int alphabet_len = static_cast<int>(std::strlen(kAlphabet));

    matrix<int> decryption_key(dimension, std::valarray<int>(dimension));
    int det = static_cast<int>(determinant_lu(encryption_key));
    int det_mod = det < 0 ? det % alphabet_len : det;

    matrix<double> raw_inverse = hill_detail::gauss_jordan_inverse(encryption_key);

    int det_inverse = -1;
    for (int candidate = 0; candidate < alphabet_len; candidate++) {
        if (hill_detail::positive_mod(det_mod * candidate, alphabet_len) == 1) {
            det_inverse = candidate;
            break;
        }
    }

    if (det_inverse == -1) {
        std::cerr << "Could not find a co-prime for inversion\n";
        std::exit(EXIT_FAILURE);
    }

    int scale = det_inverse * det;

    int i;
#ifdef _OPENMP
#pragma parallel omp for private(i)
#endif
    for (i = 0; i < static_cast<int>(dimension); i++) {
        for (int j = 0; j < static_cast<int>(dimension); j++) {
            int rounded = static_cast<int>(std::round(raw_inverse[i][j] * scale));
            decryption_key[i][j] = hill_detail::positive_mod(rounded, alphabet_len);
        }
    }
    return decryption_key;
}

/**
 * @brief Generates a matching encryption/decryption key pair, retrying
 * generation until the decryption key is also well conditioned.
 */
std::pair<matrix<int>, matrix<int>> make_key_pair(size_t dimension, int lo = 0,
                                                  int hi = 10) {
    matrix<int> enc_key = make_encryption_key(dimension);
    matrix<int> dec_key = make_decryption_key(enc_key);
    double dec_det = determinant_lu(dec_key);

    while (std::abs(dec_det) < 0.1 || std::abs(dec_det) > 1e3) {
        enc_key = make_encryption_key(dimension, lo, hi);
        dec_key = make_decryption_key(enc_key);
        dec_det = determinant_lu(dec_key);
    }
    return std::make_pair(enc_key, dec_key);
}

/// Encrypts `plaintext` using `key`.
std::string encrypt(const std::string &plaintext, const matrix<int> &key) {
    return hill_detail::apply_block_cipher(plaintext, key);
}

/// Decrypts `ciphertext` using `key`.
std::string decrypt(const std::string &ciphertext, const matrix<int> &key) {
    return hill_detail::apply_block_cipher(ciphertext, key);
}

}  // namespace hill_cipher
}  // namespace ciphers

namespace {

/// Demo run using a randomly generated 3x3 key.
void demo_small_key(const std::string &text) {
    std::cout << "=== Demo: 3x3 key ===\nplaintext:\n\t" << text << std::endl;

    auto keys = ciphers::hill_cipher::make_key_pair(3, 0, 100);
    matrix<int> enc_key = keys.first;
    matrix<int> dec_key = keys.second;

    std::string ciphertext = ciphers::hill_cipher::encrypt(text, enc_key);
    std::cout << "ciphertext:\n\t" << ciphertext << std::endl;

    std::string roundtrip = ciphers::hill_cipher::decrypt(ciphertext, dec_key);
    std::cout << "roundtrip:\n\t" << roundtrip << std::endl;

    std::ofstream log_file("hill_cipher_test1.txt");
    log_file << "Block size: " << enc_key.size() << "\n";
    log_file << "Encryption Key:\n" << enc_key;
    log_file << "\nDecryption Key:\n" << dec_key;
    log_file.close();

    assert(roundtrip == text);
    std::cout << "3x3 demo: OK\n";
}

/// Demo run using a randomly generated 8x8 key.
void demo_large_key(const std::string &text) {
    std::cout << "=== Demo: 8x8 key ===\nplaintext:\n\t" << text << std::endl;

    auto keys = ciphers::hill_cipher::make_key_pair(8, 0, 3);
    matrix<int> enc_key = keys.first;
    matrix<int> dec_key = keys.second;

    std::string ciphertext = ciphers::hill_cipher::encrypt(text, enc_key);
    std::cout << "ciphertext:\n\t" << ciphertext << std::endl;

    std::string roundtrip = ciphers::hill_cipher::decrypt(ciphertext, dec_key);
    std::cout << "roundtrip:\n\t" << roundtrip << std::endl;

    std::ofstream log_file("hill_cipher_test2.txt");
    log_file << "Block size: " << enc_key.size() << "\n";
    log_file << "Encryption Key:\n" << enc_key;
    log_file << "\nDecryption Key:\n" << dec_key;
    log_file.close();

    assert(roundtrip.compare(0, text.size(), text) == 0);
    std::cout << "8x8 demo: OK\n";
}

}  // namespace

int main() {
    std::srand(static_cast<unsigned int>(std::time(nullptr)));
    std::cout << "Alphabet size: (" << std::strlen(ciphers::kAlphabet) << ")\n\t"
              << ciphers::kAlphabet << "\n";

    std::string sample_text = "This is a simple text with numb3r5 and exclamat!0n.";

    demo_small_key(sample_text);
    demo_large_key(sample_text);

    return 0;
}

/**
 * @file
 * @brief A generic [binary search tree](https://en.wikipedia.org/wiki/Binary_search_tree) implementation.
 * Here you can find more information about the algorithm: [Scaler - Binary Search tree](https://www.scaler.com/topics/data-structures/binary-search-tree/).
 * @see binary_search_tree.cpp
 */

#include <cassert>
#include <functional>
#include <iostream>
#include <memory>
#include <vector>

/**
 * @brief The Binary Search Tree class.
 *
 * @tparam T The type of the binary search tree key.
 */
template <class T>
class binary_search_tree {
 private:
    /**
    * @brief A struct to represent a node in the Binary Search Tree.
    */
    struct bst_node {
        T value; /**< The value/key of the node. */
        std::unique_ptr<bst_node> left; /**< Pointer to left subtree. */
        std::unique_ptr<bst_node> right; /**< Pointer to right subtree. */

        /**
        * Constructor for bst_node, used to simplify node construction and
        * smart pointer construction.
        * @param _value The value of the constructed node.
        */
        explicit bst_node(T _value) {
            value = _value;
            left = nullptr;
            right = nullptr;
        }
    };

    std::unique_ptr<bst_node> root_; /**< Pointer to the root of the BST. */
    std::size_t size_ = 0; /**< Number of elements/nodes in the BST. */

    /**
     * @brief Recursive function to find the maximum value in the BST.
     *
     * @param node The node to search from.
     * @param ret_value Variable to hold the maximum value.
     * @return true If the maximum value was successfully found.
     * @return false Otherwise.
     */
    bool find_max(std::unique_ptr<bst_node>& node, T& ret_value) {
        if (!node) {
            return false;
        } else if (!node->right) {
            ret_value = node->value;
            return true;
        }
        return find_max(node->right, ret_value);
    }

    /**
     * @brief Recursive function to find the minimum value in the BST.
     *
     * @param node The node to search from.
     * @param ret_value Variable to hold the minimum value.
     * @return true If the minimum value was successfully found.
     * @return false Otherwise.
     */
    bool find_min(std::unique_ptr<bst_node>& node, T& ret_value) {
        if (!node) {
            return false;
        } else if (!node->left) {
            ret_value = node->value;
            return true;
        }

        return find_min(node->left, ret_value);
    }

    /**
     * @brief Recursive function to insert a value into the BST.
     *
     * @param node The node to search from.
     * @param new_value The value to insert.
     * @return true If the insert operation was successful.
     * @return false Otherwise.
     */
    bool insert(std::unique_ptr<bst_node>& node, T new_value) {
        if (root_ == node && !root_) {
            root_ = std::unique_ptr<bst_node>(new bst_node(new_value));
            return true;
        }

        if (new_value < node->value) {
            if (!node->left) {
                node->left = std::unique_ptr<bst_node>(new bst_node(new_value));
                return true;
            } else {
                return insert(node->left, new_value);
            }
        } else if (new_value > node->value) {
            if (!node->right) {
                node->right =
                    std::unique_ptr<bst_node>(new bst_node(new_value));
                return true;
            } else {
                return insert(node->right, new_value);
            }
        } else {
            return false;
        }
    }

    /**
     * @brief Recursive function to remove a value from the BST.
     *
     * @param parent The parent node of node.
     * @param node The node to search from.
     * @param rm_value The value to remove.
     * @return true If the removal operation was successful.
     * @return false Otherwise.
     */
    bool remove(std::unique_ptr<bst_node>& parent,
                std::unique_ptr<bst_node>& node, T rm_value) {
        if (!node) {
            return false;
        }

        if (node->value == rm_value) {
            if (node->left && node->right) {
                T successor_node_value{};
                find_max(node->left, successor_node_value);
                remove(root_, root_, successor_node_value);
                node->value = successor_node_value;
                return true;
            } else if (node->left || node->right) {
                std::unique_ptr<bst_node>& non_null =
                    (node->left ? node->left : node->right);

                if (node == root_) {
                    root_ = std::move(non_null);
                } else if (rm_value < parent->value) {
                    parent->left = std::move(non_null);
                } else {
                    parent->right = std::move(non_null);
                }

                return true;
            } else {
                if (node == root_) {
                    root_.reset(nullptr);
                } else if (rm_value < parent->value) {
                    parent->left.reset(nullptr);
                } else {
                    parent->right.reset(nullptr);
                }

                return true;
            }
        } else if (rm_value < node->value) {
            return remove(node, node->left, rm_value);
        } else {
            return remove(node, node->right, rm_value);
        }
    }

    /**
     * @brief Recursive function to check if a value is in the BST.
     *
     * @param node The node to search from.
     * @param value The value to find.
     * @return true If the value was found in the BST.
     * @return false Otherwise.
     */
    bool contains(std::unique_ptr<bst_node>& node, T value) {
        if (!node) {
            return false;
        }

        if (value < node->value) {
            return contains(node->left, value);
        } else if (value > node->value) {
            return contains(node->right, value);
        } else {
            return true;
        }
    }

    /**
     * @brief Recursive function to traverse the tree in in-order order.
     *
     * @param callback Function that is called when a value needs to processed.
     * @param node The node to traverse from.
     */
    void traverse_inorder(std::function<void(T)> callback,
                          std::unique_ptr<bst_node>& node) {
        if (!node) {
            return;
        }

        traverse_inorder(callback, node->left);
        callback(node->value);
        traverse_inorder(callback, node->right);
    }

    /**
     * @brief Recursive function to traverse the tree in pre-order order.
     *
     * @param callback Function that is called when a value needs to processed.
     * @param node The node to traverse from.
     */
    void traverse_preorder(std::function<void(T)> callback,
                           std::unique_ptr<bst_node>& node) {
        if (!node) {
            return;
        }

        callback(node->value);
        traverse_preorder(callback, node->left);
        traverse_preorder(callback, node->right);
    }

    /**
     * @brief Recursive function to traverse the tree in post-order order.
     *
     * @param callback Function that is called when a value needs to processed.
     * @param node The node to traverse from.
     */
    void traverse_postorder(std::function<void(T)> callback,
                            std::unique_ptr<bst_node>& node) {
        if (!node) {
            return;
        }

        traverse_postorder(callback, node->left);
        traverse_postorder(callback, node->right);
        callback(node->value);
    }

 public:
    /**
     * @brief Construct a new Binary Search Tree object.
     *
     */
    binary_search_tree() {
        root_ = nullptr;
        size_ = 0;
    }

    /**
     * @brief Insert a new value into the BST.
     *
     * @param new_value The value to insert into the BST.
     * @return true If the insertion was successful.
     * @return false Otherwise.
     */
    bool insert(T new_value) {
        bool result = insert(root_, new_value);
        if (result) {
            size_++;
        }
        return result;
    }

    /**
     * @brief Remove a specified value from the BST.
     *
     * @param rm_value The value to remove.
     * @return true If the removal was successful.
     * @return false Otherwise.
     */
    bool remove(T rm_value) {
        bool result = remove(root_, root_, rm_value);
        if (result) {
            size_--;
        }
        return result;
    }

    /**
     * @brief Check if a value is in the BST.
     *
     * @param value The value to find.
     * @return true If value is in the BST.
     * @return false Otherwise.
     */
    bool contains(T value) { return contains(root_, value); }

    /**
     * @brief Find the smallest value in the BST.
     *
     * @param ret_value Variable to hold the minimum value.
     * @return true If minimum value was successfully found.
     * @return false Otherwise.
     */
    bool find_min(T& ret_value) { return find_min(root_, ret_value); }

    /**
     * @brief Find the largest value in the BST.
     *
     * @param ret_value Variable to hold the maximum value.
     * @return true If maximum value was successfully found.
     * @return false Otherwise.
     */
    bool find_max(T& ret_value) { return find_max(root_, ret_value); }

    /**
     * @brief Get the number of values in the BST.
     *
     * @return std::size_t Number of values in the BST.
     */
    std::size_t size() { return size_; }

    /**
     * @brief Get all values of the BST in in-order order.
     *
     * @return std::vector<T> List of values, sorted in in-order order.
     */
    std::vector<T> get_elements_inorder() {
        std::vector<T> result;
        traverse_inorder([&](T node_value) { result.push_back(node_value); },
                         root_);
        return result;
    }

    /**
     * @brief Get all values of the BST in pre-order order.
     *
     * @return std::vector<T> List of values, sorted in pre-order order.
     */
    std::vector<T> get_elements_preorder() {
        std::vector<T> result;
        traverse_preorder([&](T node_value) { result.push_back(node_value); },
                          root_);
        return result;
    }

    /**
     * @brief Get all values of the BST in post-order order.
     *
     * @return std::vector<T> List of values, sorted in post-order order.
     */
    std::vector<T> get_elements_postorder() {
        std::vector<T> result;
        traverse_postorder([&](T node_value) { result.push_back(node_value); },
                           root_);
        return result;
    }
};

/**
 * @brief Function for testing insert().
 * 
 * @returns `void`
 */
static void test_insert() {
    std::cout << "Testing BST insert...";

    binary_search_tree<int> tree;
    bool res = tree.insert(5);
    int min = -1, max = -1;
    assert(res);
    assert(tree.find_max(max));
    assert(tree.find_min(min));
    assert(max == 5);
    assert(min == 5);
    assert(tree.size() == 1);

    tree.insert(4);
    tree.insert(3);
    tree.insert(6);
    assert(tree.find_max(max));
    assert(tree.find_min(min));
    assert(max == 6);
    assert(min == 3);
    assert(tree.size() == 4);

    bool fail_res = tree.insert(4);
    assert(!fail_res);
    assert(tree.size() == 4);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing remove().
 * 
 * @returns `void`
 */
static void test_remove() {
    std::cout << "Testing BST remove...";

    binary_search_tree<int> tree;
    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    bool res = tree.remove(5);
    int min = -1, max = -1;
    assert(res);
    assert(tree.find_max(max));
    assert(tree.find_min(min));
    assert(max == 6);
    assert(min == 3);
    assert(tree.size() == 3);
    assert(tree.contains(5) == false);

    tree.remove(4);
    tree.remove(3);
    tree.remove(6);
    assert(tree.size() == 0);
    assert(tree.contains(6) == false);

    bool fail_res = tree.remove(5);
    assert(!fail_res);
    assert(tree.size() == 0);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing contains().
 * 
 * @returns `void`
 */
static void test_contains() {
    std::cout << "Testing BST contains...";

    binary_search_tree<int> tree;
    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    assert(tree.contains(5));
    assert(tree.contains(4));
    assert(tree.contains(3));
    assert(tree.contains(6));
    assert(!tree.contains(999));

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing find_min().
 * 
 * @returns `void`
 */
static void test_find_min() {
    std::cout << "Testing BST find_min...";

    int min = 0;
    binary_search_tree<int> tree;
    assert(!tree.find_min(min));

    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

