/**
 * @file
 * @brief An alternate take on a templated binary search tree container.
 * Implements the classic ordered-tree operations (insert, erase, lookup,
 * traversals) using owning smart pointers for automatic cleanup.
 */

#include <cassert>
#include <functional>
#include <iostream>
#include <memory>
#include <vector>

/**
 * @brief Ordered binary search tree keyed on type Key.
 *
 * @tparam Key Comparable key/value type stored in the tree.
 */
template <class Key>
class OrderedTree {
 private:
    struct TreeNode {
        Key key;
        std::unique_ptr<TreeNode> leftChild;
        std::unique_ptr<TreeNode> rightChild;

        explicit TreeNode(Key k) : key(std::move(k)), leftChild(nullptr), rightChild(nullptr) {}
    };

    std::unique_ptr<TreeNode> top_;
    std::size_t count_ = 0;

    bool locateLargest(std::unique_ptr<TreeNode>& cursor, Key& out) {
        if (!cursor) {
            return false;
        }
        if (!cursor->rightChild) {
            out = cursor->key;
            return true;
        }
        return locateLargest(cursor->rightChild, out);
    }

    bool locateSmallest(std::unique_ptr<TreeNode>& cursor, Key& out) {
        if (!cursor) {
            return false;
        }
        if (!cursor->leftChild) {
            out = cursor->key;
            return true;
        }
        return locateSmallest(cursor->leftChild, out);
    }

    bool place(std::unique_ptr<TreeNode>& cursor, Key incoming) {
        if (top_ == cursor && !top_) {
            top_ = std::make_unique<TreeNode>(incoming);
            return true;
        }

        if (incoming < cursor->key) {
            if (!cursor->leftChild) {
                cursor->leftChild = std::make_unique<TreeNode>(incoming);
                return true;
            }
            return place(cursor->leftChild, incoming);
        } else if (incoming > cursor->key) {
            if (!cursor->rightChild) {
                cursor->rightChild = std::make_unique<TreeNode>(incoming);
                return true;
            }
            return place(cursor->rightChild, incoming);
        }
        return false;
    }

    bool erase(std::unique_ptr<TreeNode>& parent, std::unique_ptr<TreeNode>& cursor, Key target) {
        if (!cursor) {
            return false;
        }

        if (cursor->key == target) {
            if (cursor->leftChild && cursor->rightChild) {
                Key replacement{};
                locateLargest(cursor->leftChild, replacement);
                erase(top_, top_, replacement);
                cursor->key = replacement;
                return true;
            } else if (cursor->leftChild || cursor->rightChild) {
                std::unique_ptr<TreeNode>& survivor =
                    (cursor->leftChild ? cursor->leftChild : cursor->rightChild);

                if (cursor == top_) {
                    top_ = std::move(survivor);
                } else if (target < parent->key) {
                    parent->leftChild = std::move(survivor);
                } else {
                    parent->rightChild = std::move(survivor);
                }
                return true;
            } else {
                if (cursor == top_) {
                    top_.reset(nullptr);
                } else if (target < parent->key) {
                    parent->leftChild.reset(nullptr);
                } else {
                    parent->rightChild.reset(nullptr);
                }
                return true;
            }
        } else if (target < cursor->key) {
            return erase(cursor, cursor->leftChild, target);
        } else {
            return erase(cursor, cursor->rightChild, target);
        }
    }

    bool lookup(std::unique_ptr<TreeNode>& cursor, Key target) {
        if (!cursor) {
            return false;
        }
        if (target < cursor->key) {
            return lookup(cursor->leftChild, target);
        } else if (target > cursor->key) {
            return lookup(cursor->rightChild, target);
        }
        return true;
    }

    void walkInOrder(const std::function<void(Key)>& visit, std::unique_ptr<TreeNode>& cursor) {
        if (!cursor) {
            return;
        }
        walkInOrder(visit, cursor->leftChild);
        visit(cursor->key);
        walkInOrder(visit, cursor->rightChild);
    }

    void walkPreOrder(const std::function<void(Key)>& visit, std::unique_ptr<TreeNode>& cursor) {
        if (!cursor) {
            return;
        }
        visit(cursor->key);
        walkPreOrder(visit, cursor->leftChild);
        walkPreOrder(visit, cursor->rightChild);
    }

    void walkPostOrder(const std::function<void(Key)>& visit, std::unique_ptr<TreeNode>& cursor) {
        if (!cursor) {
            return;
        }
        walkPostOrder(visit, cursor->leftChild);
        walkPostOrder(visit, cursor->rightChild);
        visit(cursor->key);
    }

 public:
    OrderedTree() : top_(nullptr), count_(0) {}

    bool insertKey(Key incoming) {
        bool ok = place(top_, incoming);
        if (ok) {
            ++count_;
        }
        return ok;
    }

    bool eraseKey(Key target) {
        bool ok = erase(top_, top_, target);
        if (ok) {
            --count_;
        }
        return ok;
    }

    bool hasKey(Key target) { return lookup(top_, target); }

    bool smallest(Key& out) { return locateSmallest(top_, out); }

    bool largest(Key& out) { return locateLargest(top_, out); }

    std::size_t length() { return count_; }

    std::vector<Key> collectInOrder() {
        std::vector<Key> out;
        walkInOrder([&](Key k) { out.push_back(k); }, top_);
        return out;
    }

    std::vector<Key> collectPreOrder() {
        std::vector<Key> out;
        walkPreOrder([&](Key k) { out.push_back(k); }, top_);
        return out;
    }

    std::vector<Key> collectPostOrder() {
        std::vector<Key> out;
        walkPostOrder([&](Key k) { out.push_back(k); }, top_);
        return out;
    }
};

/** Checks that inserting keys grows the tree and tracks min/max correctly. */
static void checkInsertBehavior() {
    std::cout << "Checking insertion behavior...";

    OrderedTree<int> tree;
    bool ok = tree.insertKey(5);
    int lo = -1, hi = -1;
    assert(ok);
    assert(tree.largest(hi));
    assert(tree.smallest(lo));
    assert(hi == 5);
    assert(lo == 5);
    assert(tree.length() == 1);

    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);
    assert(tree.largest(hi));
    assert(tree.smallest(lo));
    assert(hi == 6);
    assert(lo == 3);
    assert(tree.length() == 4);

    bool dup = tree.insertKey(4);
    assert(!dup);
    assert(tree.length() == 4);

    std::cout << "passed" << std::endl;
}

/** Checks that removal shrinks the tree and updates bounds correctly. */
static void checkEraseBehavior() {
    std::cout << "Checking erase behavior...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    bool ok = tree.eraseKey(5);
    int lo = -1, hi = -1;
    assert(ok);
    assert(tree.largest(hi));
    assert(tree.smallest(lo));
    assert(hi == 6);
    assert(lo == 3);
    assert(tree.length() == 3);
    assert(tree.hasKey(5) == false);

    tree.eraseKey(4);
    tree.eraseKey(3);
    tree.eraseKey(6);
    assert(tree.length() == 0);
    assert(tree.hasKey(6) == false);

    bool missing = tree.eraseKey(5);
    assert(!missing);
    assert(tree.length() == 0);

    std::cout << "passed" << std::endl;
}

/** Checks membership lookups. */
static void checkContainsBehavior() {
    std::cout << "Checking membership lookups...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    assert(tree.hasKey(5));
    assert(tree.hasKey(4));
    assert(tree.hasKey(3));
    assert(tree.hasKey(6));
    assert(!tree.hasKey(999));

    std::cout << "passed" << std::endl;
}

/** Checks minimum lookup on empty and populated trees. */
static void checkSmallestBehavior() {
    std::cout << "Checking smallest-key lookup...";

    int lo = 0;
    OrderedTree<int> tree;
    assert(!tree.smallest(lo));

    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    assert(tree.smallest(lo));
    assert(lo == 3);

    std::cout << "passed" << std::endl;
}

/** Checks maximum lookup on empty and populated trees. */
static void checkLargestBehavior() {
    std::cout << "Checking largest-key lookup...";

    int hi = 0;
    OrderedTree<int> tree;
    assert(!tree.largest(hi));

    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    assert(tree.largest(hi));
    assert(hi == 6);

    std::cout << "passed" << std::endl;
}

/** Checks the in-order traversal output. */
static void checkInOrderBehavior() {
    std::cout << "Checking in-order traversal...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    std::vector<int> expect = {3, 4, 5, 6};
    std::vector<int> got = tree.collectInOrder();
    assert(got == expect);

    std::cout << "passed" << std::endl;
}

/** Checks the pre-order traversal output. */
static void checkPreOrderBehavior() {
    std::cout << "Checking pre-order traversal...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    std::vector<int> expect = {5, 4, 3, 6};
    std::vector<int> got = tree.collectPreOrder();
    assert(got == expect);

    std::cout << "passed" << std::endl;
}

/** Checks the post-order traversal output. */
static void checkPostOrderBehavior() {
    std::cout << "Checking post-order traversal...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    std::vector<int> expect = {3, 4, 6, 5};
    std::vector<int> got = tree.collectPostOrder();
    assert(got == expect);

    std::cout << "passed" << std::endl;
}

int main() {
    checkInsertBehavior();
    checkEraseBehavior();
    checkContainsBehavior();
    checkLargestBehavior();
    checkSmallestBehavior();
    checkInOrderBehavior();
    checkPreOrderBehavior();
    checkPostOrderBehavior();
}

/**
 * \file
 * \brief A C++ program to demonstrate common Binary Heap Operations
 */
#include <climits>
#include <iostream>
#include <utility>

/** A class for Min Heap */
class MinHeap {
    int *harr;      ///< pointer to array of elements in heap
    int capacity;   ///< maximum possible size of min heap
    int heap_size;  ///< Current number of elements in min heap

 public:
    /** Constructor: Builds a heap from a given array a[] of given size
     * \param[in] capacity initial heap capacity
     */
    explicit MinHeap(int cap) {
        heap_size = 0;
        capacity = cap;
        harr = new int[cap];
    }

    /** to heapify a subtree with the root at given index */
    void MinHeapify(int);

    int parent(int i) { return (i - 1) / 2; }

    /** to get index of left child of node at index i */
    int left(int i) { return (2 * i + 1); }

    /** to get index of right child of node at index i */
    int right(int i) { return (2 * i + 2); }

    /** to extract the root which is the minimum element */
    int extractMin();

    /** Decreases key value of key at index i to new_val */
    void decreaseKey(int i, int new_val);

    /** Returns the minimum key (key at root) from min heap */
    int getMin() { return harr[0]; }

    /** Deletes a key stored at index i */
    void deleteKey(int i);

    /** Inserts a new key 'k' */
    void insertKey(int k);

    ~MinHeap() { delete[] harr; }
};

// Inserts a new key 'k'
void MinHeap::insertKey(int k) {
    if (heap_size == capacity) {
        std::cout << "\nOverflow: Could not insertKey\n";
        return;
    }

    // First insert the new key at the end
    heap_size++;
    int i = heap_size - 1;
    harr[i] = k;

    // Fix the min heap property if it is violated
    while (i != 0 && harr[parent(i)] > harr[i]) {
        std::swap(harr[i], harr[parent(i)]);
        i = parent(i);
    }
}

/** Decreases value of key at index 'i' to new_val.  It is assumed that new_val
 * is smaller than harr[i].
 */
void MinHeap::decreaseKey(int i, int new_val) {
    harr[i] = new_val;
    while (i != 0 && harr[parent(i)] > harr[i]) {
        std::swap(harr[i], harr[parent(i)]);
        i = parent(i);
    }
}

// Method to remove minimum element (or root) from min heap
int MinHeap::extractMin() {
    if (heap_size <= 0)
        return INT_MAX;
    if (heap_size == 1) {
        heap_size--;
        return harr[0];
    }

    // Store the minimum value, and remove it from heap
    int root = harr[0];
    harr[0] = harr[heap_size - 1];
    heap_size--;
    MinHeapify(0);

    return root;
}

/** This function deletes key at index i. It first reduced value to minus
 * infinite, then calls extractMin()
 */
void MinHeap::deleteKey(int i) {
    decreaseKey(i, INT_MIN);
    extractMin();
}

/** A recursive method to heapify a subtree with the root at given index
 *  This method assumes that the subtrees are already heapified
 */
void MinHeap::MinHeapify(int i) {
    int l = left(i);
    int r = right(i);
    int smallest = i;
    if (l < heap_size && harr[l] < harr[i])
        smallest = l;
    if (r < heap_size && harr[r] < harr[smallest])
        smallest = r;
    if (smallest != i) {
        std::swap(harr[i], harr[smallest]);
        MinHeapify(smallest);
    }
}

// Driver program to test above functions
int main() {
    MinHeap h(11);
    h.insertKey(3);
    h.insertKey(2);
    h.deleteKey(1);
    h.insertKey(15);
    h.insertKey(5);
    h.insertKey(4);
    h.insertKey(45);
    std::cout << h.extractMin() << " ";
    std::cout << h.getMin() << " ";
    h.decreaseKey(2, 1);
    std::cout << h.getMin();
    return 0;
}

/**
 * \file
 * \brief A restyled walkthrough of the classic array-backed binary min-heap
 * operations.
 */
#include <climits>
#include <iostream>
#include <utility>

/// Array-backed binary min-heap supporting insert, decrease-key, delete, and
/// extract-min.
class MinBinaryHeap {
 public:
    /**
     * @brief Allocates storage for up to @p maxElements entries.
     */
    explicit MinBinaryHeap(int maxElements)
        : store_(new int[maxElements]), capacity_(maxElements), count_(0) {}

    ~MinBinaryHeap() { delete[] store_; }

    /// Index of the parent of the node at position @p idx.
    static int parentOf(int idx) { return (idx - 1) / 2; }

    /// Index of the left child of the node at position @p idx.
    static int leftChildOf(int idx) { return 2 * idx + 1; }

    /// Index of the right child of the node at position @p idx.
    static int rightChildOf(int idx) { return 2 * idx + 2; }

    /// Returns the smallest element currently stored (the root).
    int peekMin() const { return store_[0]; }

    /// Inserts a new value, bubbling it up until heap order is restored.
    void push(int value) {
        if (count_ == capacity_) {
            std::cout << "\nOverflow: Could not insert new key\n";
            return;
        }

        count_++;
        int slot = count_ - 1;
        store_[slot] = value;

        while (slot != 0 && store_[parentOf(slot)] > store_[slot]) {
            std::swap(store_[slot], store_[parentOf(slot)]);
            slot = parentOf(slot);
        }
    }

    /**
     * @brief Lowers the value stored at index @p idx to @p smallerValue and
     * restores heap order by bubbling up. Caller must guarantee
     * smallerValue <= current value at idx.
     */
    void lowerValueAt(int idx, int smallerValue) {
        store_[idx] = smallerValue;
        while (idx != 0 && store_[parentOf(idx)] > store_[idx]) {
            std::swap(store_[idx], store_[parentOf(idx)]);
            idx = parentOf(idx);
        }
    }

    /// Removes and returns the minimum element, or INT_MAX if empty.
    int popMin() {
        if (count_ <= 0) {
            return INT_MAX;
        }
        if (count_ == 1) {
            count_--;
            return store_[0];
        }

        int minVal = store_[0];
        store_[0] = store_[count_ - 1];
        count_--;
        restoreHeapDown(0);
        return minVal;
    }

    /// Removes the element stored at index @p idx entirely.
    void removeAt(int idx) {
        lowerValueAt(idx, INT_MIN);
        popMin();
    }

 private:
    /// Sift-down pass ensuring the min-heap property holds beneath @p idx.
    void restoreHeapDown(int idx) {
        int left = leftChildOf(idx);
        int right = rightChildOf(idx);
        int smallest = idx;

        if (left < count_ && store_[left] < store_[smallest]) {
            smallest = left;
        }
        if (right < count_ && store_[right] < store_[smallest]) {
            smallest = right;
        }
        if (smallest != idx) {
            std::swap(store_[idx], store_[smallest]);
            restoreHeapDown(smallest);
        }
    }

    int *store_;
    int capacity_;
    int count_;
};

/// Demonstrates the heap operations with a short scripted sequence.
int main() {
    MinBinaryHeap heap(11);

    heap.push(3);
    heap.push(2);
    heap.removeAt(1);
    heap.push(15);
    heap.push(5);
    heap.push(4);
    heap.push(45);

    std::cout << heap.popMin() << " ";
    std::cout << heap.peekMin() << " ";
    heap.lowerValueAt(2, 1);
    std::cout << heap.peekMin();

    return 0;
}

/**
 * @file
 * @brief [DSU (Disjoint
 * sets)](https://en.wikipedia.org/wiki/Disjoint-set-data_structure)
 * @details
 * dsu : It is a very powerful data structure which keeps track of different
 * clusters(sets) of elements, these sets are disjoint(doesnot have a common
 * element). Disjoint sets uses cases : for finding connected components in a
 * graph, used in Kruskal's algorithm for finding Minimum Spanning tree.
 * Operations that can be performed:
 * 1) UnionSet(i,j): add(element i and j to the set)
 * 2) findSet(i): returns the representative of the set to which i belogngs to.
 * 3) getParents(i): prints the parent of i and so on and so forth.
 * Below is the class-based approach which uses the heuristic of union-ranks.
 * Using union-rank in findSet(i),we are able to get to the representative of i
 * in slightly delayed O(logN) time but it allows us to keep tracks of the
 * parent of i.
 * @author [AayushVyasKIIT](https://github.com/AayushVyasKIIT)
 * @see dsu_path_compression.cpp
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

using std::cout;
using std::endl;
using std::vector;

/**
 * @brief Disjoint sets union data structure, class based representation.
 * @param n number of elements
 */
class dsu {
 private:
    vector<uint64_t> p;        ///< keeps track of the parent of ith element
    vector<uint64_t> depth;    ///< tracks the depth(rank) of i in the tree
    vector<uint64_t> setSize;  ///< size of each chunk(set)
 public:
    /**
     * @brief constructor for initialising all data members
     * @param n number of elements
     */
    explicit dsu(uint64_t n) {
        p.assign(n, 0);
        /// initially all of them are their own parents
        depth.assign(n, 0);
        setSize.assign(n, 0);
        for (uint64_t i = 0; i < n; i++) {
            p[i] = i;
            depth[i] = 0;
            setSize[i] = 1;
        }
    }
    /**
     * @brief Method to find the representative of the set to which i belongs
     * to, T(n) = O(logN)
     * @param i element of some set
     * @returns representative of the set to which i belongs to
     */
    uint64_t findSet(uint64_t i) {
        /// using union-rank
        while (i != p[i]) {
            i = p[i];
        }
        return i;
    }
    /**
     * @brief Method that combines two disjoint sets to which i and j belongs to
     * and make a single set having a common representative.
     * @param i element of some set
     * @param j element of some set
     * @returns void
     */
    void unionSet(uint64_t i, uint64_t j) {
        /// checks if both belongs to same set or not
        if (isSame(i, j)) {
            return;
        }
        /// we find representative of the i and j
        uint64_t x = findSet(i);
        uint64_t y = findSet(j);

        /// always keeping the min as x
        /// in order to create a shallow tree
        if (depth[x] > depth[y]) {
            std::swap(x, y);
        }
        /// making the shallower tree, root parent of the deeper root
        p[x] = y;

        /// if same depth, then increase one's depth
        if (depth[x] == depth[y]) {
            depth[y]++;
        }
        /// total size of the resultant set
        setSize[y] += setSize[x];
    }
    /**
     * @brief A utility function which check whether i and j belongs to same set
     * or not
     * @param i element of some set
     * @param j element of some set
     * @returns `true` if element i and j are in same set
     * @returns `false` if element i and j are not in same set
     */
    bool isSame(uint64_t i, uint64_t j) {
        if (findSet(i) == findSet(j)) {
            return true;
        }
        return false;
    }
    /**
     * @brief Method to print all the parents of i, or the path from i to
     * representative.
     * @param i element of some set
     * @returns void
     */
    vector<uint64_t> getParents(uint64_t i) {
        vector<uint64_t> ans;
        while (p[i] != i) {
            ans.push_back(i);
            i = p[i];
        }
        ans.push_back(i);
        return ans;
    }
};
/**
 * @brief Self-implementations, 1st test
 * @returns void
 */
static void test1() {
    /* checks the parents in the resultant structures */
    uint64_t n = 10;   ///< number of elements
    dsu d(n + 1);      ///< object of class disjoint sets
    d.unionSet(2, 1);  ///< performs union operation on 1 and 2
    d.unionSet(1, 4);
    d.unionSet(8, 1);
    d.unionSet(3, 5);
    d.unionSet(5, 6);
    d.unionSet(5, 7);
    d.unionSet(9, 10);
    d.unionSet(2, 10);
    // keeping track of the changes using parent pointers
    vector<uint64_t> ans = {7, 5};
    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.getParents(7).at(i) ==
               ans[i]);  // makes sure algorithm works fine
    }
    cout << "1st test passed!" << endl;
}
/**
 * @brief Self-implementations, 2nd test
 * @returns void
 */
static void test2() {
    // checks the parents in the resultant structures
    uint64_t n = 10;   ///< number of elements
    dsu d(n + 1);      ///< object of class disjoint sets
    d.unionSet(2, 1);  /// performs union operation on 1 and 2
    d.unionSet(1, 4);
    d.unionSet(8, 1);
    d.unionSet(3, 5);
    d.unionSet(5, 6);
    d.unionSet(5, 7);
    d.unionSet(9, 10);
    d.unionSet(2, 10);

    /// keeping track of the changes using parent pointers
    vector<uint64_t> ans = {2, 1, 10};
    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.getParents(2).at(i) ==
               ans[i]);  /// makes sure algorithm works fine
    }
    cout << "2nd test passed!" << endl;
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test1();  // run 1st test case
    test2();  // run 2nd test case

    return 0;
}

/**
 * @file
 * @brief Union-Find (Disjoint Set) using the union-by-rank heuristic.
 * @details
 * Maintains disjoint groups over a fixed universe, merging via rank
 * comparison rather than path compression. find() walks parent links
 * iteratively without rewriting them, so the parent chain can still be
 * inspected afterward (see chain_to_root below).
 * @see dsu_path_compression.cpp
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

using std::cout;
using std::endl;
using std::vector;

/**
 * @brief Disjoint-set forest that merges by rank without path compression.
 */
class RankedUnionFind {
 public:
    explicit RankedUnionFind(uint64_t count) {
        link_.resize(count);
        tier_.resize(count);
        tally_.resize(count);
        for (uint64_t idx = 0; idx < count; idx++) {
            link_[idx] = idx;
            tier_[idx] = 0;
            tally_[idx] = 1;
        }
    }

    /** @brief Walk parent links up to the root, without compressing. */
    uint64_t root_of(uint64_t elem) {
        while (elem != link_[elem]) {
            elem = link_[elem];
        }
        return elem;
    }

    /** @brief True if `a` and `b` currently live in the same group. */
    bool shares_group(uint64_t a, uint64_t b) { return root_of(a) == root_of(b); }

    /** @brief Merge groups by attaching the shallower root under the deeper one. */
    void join(uint64_t a, uint64_t b) {
        if (shares_group(a, b)) {
            return;
        }
        uint64_t root_a = root_of(a);
        uint64_t root_b = root_of(b);

        if (tier_[root_a] > tier_[root_b]) {
            std::swap(root_a, root_b);
        }
        link_[root_a] = root_b;

        if (tier_[root_a] == tier_[root_b]) {
            tier_[root_b]++;
        }
        tally_[root_b] += tally_[root_a];
    }

    /** @brief Path from `elem` up to its root, inclusive of the root. */
    vector<uint64_t> chain_to_root(uint64_t elem) {
        vector<uint64_t> path;
        while (link_[elem] != elem) {
            path.push_back(elem);
            elem = link_[elem];
        }
        path.push_back(elem);
        return path;
    }

 private:
    vector<uint64_t> link_;   ///< parent pointer per element
    vector<uint64_t> tier_;   ///< approximate rank per root
    vector<uint64_t> tally_;  ///< group size per root
};

/** @brief Build the standard test forest of 11 elements (index 0..10). */
static RankedUnionFind build_sample_forest() {
    uint64_t total = 10;
    RankedUnionFind forest(total + 1);
    forest.join(2, 1);
    forest.join(1, 4);
    forest.join(8, 1);
    forest.join(3, 5);
    forest.join(5, 6);
    forest.join(5, 7);
    forest.join(9, 10);
    forest.join(2, 10);
    return forest;
}

/** @brief First scenario: verify the parent chain starting at element 7. */
static void scenario_chain_from_seven() {
    RankedUnionFind forest = build_sample_forest();
    vector<uint64_t> expected = {7, 5};
    vector<uint64_t> actual = forest.chain_to_root(7);
    for (uint64_t idx = 0; idx < expected.size(); idx++) {
        assert(actual.at(idx) == expected[idx]);
    }
    cout << "1st test passed!" << endl;
}

/** @brief Second scenario: verify the parent chain starting at element 2. */
static void scenario_chain_from_two() {
    RankedUnionFind forest = build_sample_forest();
    vector<uint64_t> expected = {2, 1, 10};
    vector<uint64_t> actual = forest.chain_to_root(2);
    for (uint64_t idx = 0; idx < expected.size(); idx++) {
        assert(actual.at(idx) == expected[idx]);
    }
    cout << "2nd test passed!" << endl;
}

int main() {
    scenario_chain_from_seven();
    scenario_chain_from_two();
    return 0;
}

/**
 * @file
 * @brief Implementation of singly linked list algorithm.
 * @details
 * The linked list is a data structure used for holding a sequence of
 * values, which can be added, removed and displayed.
 * ### Algorithm
 * Values can be added by iterating to the end of a list(by following
 * the pointers) starting from the first link. Whichever link points to null
 * is considered the last link and is pointed to the new value.
 *
 * Values can be removed by also iterating through the list. When the node
 * containing the value is found, the node pointing to the current node is made
 * to point to the node that the current node is pointing to, and then returning
 * the current node to heap store.
 */
#include <iostream>
#include <memory>
#include <string>

/**
 * @namespace data_structures
 * @brief Data Structures algorithms
 */
namespace data_structures {

/**
 * @namespace linked_list
 * @brief Functions for singly linked list algorithm
 */
namespace linked_list {

/**
 * This function checks if the string passed consists
 * of only digits.
 * @param s To be checked if s contains only integers
 * @returns true if there are only digits present in the string
 * @returns false if any other character is found
 */
bool isDigit(const std::string& s) {
    // function statements here
    for (char i : s) {
        if (!isdigit(i)) {
            return false;
        }
    }
    return true;
}

/**
 * A link class containing a value and pointer to another link
 */
class link {
 private:
    int pvalue;                   ///< value of the current link
    std::shared_ptr<link> psucc;  ///< pointer to the next value on the list

 public:
    /**
     * function returns the integer value stored in the link.
     * @returns the integer value stored in the link.
     */
    int val() { return pvalue; }

    /**
     * function returns the pointer to next link
     * @returns the pointer to the next link
     * */
    std::shared_ptr<link>& succ() { return psucc; }

    /**
     * Creates link with provided value and pointer to next link
     * @param value is the integer stored in the link
     */
    explicit link(int value = 0) : pvalue(value), psucc(nullptr) {}
};

/**
 * A list class containing a sequence of links
 */
class list {
 private:
    std::shared_ptr<link> first;  ///< link before the actual first element
    std::shared_ptr<link> last;   ///< last link on the list
 public:
    /**
     * List constructor. Initializes the first and last link.
     */
    list() {
        // Initialize the first link
        first = std::make_shared<link>();
        // Initialize the last link with the first link
        last = nullptr;
    }

    bool isEmpty();

    void push_back(int new_elem);
    void push_front(int new_elem);
    void erase(int old_elem);
    void display();
    std::shared_ptr<link> search(int find_elem);
    void reverse();
};

/**
 * function checks if list is empty
 * @returns true if list is empty
 * @returns false if list is not empty
 */
bool list::isEmpty() {
    if (last == nullptr) {
        return true;
    } else {
        return false;
    }
}

/**
 * function adds new element to the end of the list
 * @param new_elem to be added to the end of the list
 */
void list::push_back(int new_elem) {
    if (isEmpty()) {
        first->succ() = std::make_shared<link>(new_elem);
        last = first->succ();
    } else {
        last->succ() = std::make_shared<link>(new_elem);
        last = last->succ();
    }
}

/**
 * function adds new element to the beginning of the list
 * @param new_elem to be added to front of the list
 */
void list::push_front(int new_elem) {
    if (isEmpty()) {
        first->succ() = std::make_shared<link>(new_elem);
        last = first->succ();
    } else {
        std::shared_ptr<link> t = std::make_shared<link>(new_elem);
        t->succ() = first->succ();
        first->succ() = t;
    }
}

/**
 * function erases old element from the list
 * @param old_elem to be erased from the list
 */
void list::erase(int old_elem) {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return;
    }
    std::shared_ptr<link> t = first;
    std::shared_ptr<link> to_be_removed = nullptr;
    while (t != last && t->succ()->val() != old_elem) {
        t = t->succ();
    }
    if (t == last) {
        std::cout << "Element not found\n";
        return;
    }
    to_be_removed = t->succ();
    t->succ() = t->succ()->succ();
    to_be_removed.reset();
    if (t->succ() == nullptr) {
        last = t;
    }
    if (first == last){
        last = nullptr;
    }
}

/**
 * function displays all the elements in the list
 * @returns 'void'
 */
void list::display() {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return;
    }
    std::shared_ptr<link> t = first;
    while (t->succ() != nullptr) {
        std::cout << t->succ()->val() << "\t";
        t = t->succ();
    }
}

/**
 * function searchs for @param find_elem in the list
 * @param find_elem to be searched for in the list
 */
std::shared_ptr<link> list::search(int find_elem) {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return nullptr;
    }
    std::shared_ptr<link> t = first;
    while (t != last && t->succ()->val() != find_elem) {
        t = t->succ();
    }
    if (t == last) {
        std::cout << "Element not found\n";
        return nullptr;
    }
    std::cout << "Element was found\n";
    return t->succ();
}
}  // namespace linked_list
}  // namespace data_structures

/**
 * Main function:
 * Allows the user add and delete values from the list.
 * Also allows user to search for and display values in the list.
 * @returns 0 on exit
 */
int main() {
    data_structures::linked_list::list l;
    int choice = 0;
    int x = 0;
    std::string s;
    do {
        std::cout << "\n1. Insert";
        std::cout << "\n2. Delete";
        std::cout << "\n3. Search";
        std::cout << "\n4. Print";
        std::cout << "\n0. Exit";
        std::cout << "\n\nEnter you choice : ";
        std::cin >> choice;
        switch (choice) {
            case 0:
                std::cout << "\nQuitting the program...\n";
                break;
            case 1:
                std::cout << "\nEnter the element to be inserted : ";
                std::cin >> s;

                if (data_structures::linked_list::isDigit(s)) {
                    x = std::stoi(s);
                    l.push_back(x);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 2:
                std::cout << "\nEnter the element to be removed : ";
                std::cin >> s;
                if (data_structures::linked_list::isDigit(s)) {
                    x = std::stoi(s);
                    l.erase(x);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 3:
                std::cout << "\nEnter the element to be searched : ";
                std::cin >> s;
                if (data_structures::linked_list::isDigit(s)) {
                    x = std::stoi(s);
                    std::shared_ptr<data_structures::linked_list::link> found =
                        l.search(x);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 4:
                l.display();
                std::cout << "\n";
                break;
            default:
                std::cout << "Invalid Input\n" << std::endl;
                break;
        }
    } while (choice != 0);
    return 0;
}

/**
 * @file
 * @brief Singly linked list demo built around a lightweight node wrapper.
 * @details
 * Stores an ordered sequence of integers in nodes chained by shared
 * pointers. Supports appending, prepending, erasing by value, searching,
 * and printing. Traversal always starts from a sentinel-style "before
 * head" node to keep insert/erase logic uniform at both ends.
 */
#include <iostream>
#include <memory>
#include <string>

/**
 * @namespace data_structures
 * @brief Data Structures algorithms
 */
namespace data_structures {

/**
 * @namespace linked_list
 * @brief Functions for singly linked list algorithm
 */
namespace linked_list {

/**
 * @brief Tests whether every character in `text` is a decimal digit.
 * @param text candidate string
 * @returns true when non-empty and all-digit, false otherwise
 */
bool isDigit(const std::string& text) {
    for (char ch : text) {
        if (!isdigit(ch)) {
            return false;
        }
    }
    return true;
}

/**
 * @brief A single node holding an integer payload and a link to the next node.
 */
class Cell {
 public:
    explicit Cell(int payload = 0) : payload_(payload), next_(nullptr) {}

    int value() const { return payload_; }
    std::shared_ptr<Cell>& next() { return next_; }

 private:
    int payload_;
    std::shared_ptr<Cell> next_;
};

/**
 * @brief Singly linked chain of Cell nodes with a sentinel head.
 */
class Chain {
 public:
    Chain() : sentinel_(std::make_shared<Cell>()), tail_(nullptr) {}

    bool isEmpty();
    void push_back(int new_elem);
    void push_front(int new_elem);
    void erase(int old_elem);
    void display();
    std::shared_ptr<Cell> search(int find_elem);

 private:
    std::shared_ptr<Cell> sentinel_;  ///< dummy node preceding the real head
    std::shared_ptr<Cell> tail_;      ///< last real node, or null if empty
};

/** @brief True when the chain currently holds no elements. */
bool Chain::isEmpty() { return tail_ == nullptr; }

/** @brief Append a value after the current tail. */
void Chain::push_back(int new_elem) {
    auto fresh = std::make_shared<Cell>(new_elem);
    if (isEmpty()) {
        sentinel_->next() = fresh;
    } else {
        tail_->next() = fresh;
    }
    tail_ = fresh;
}

/** @brief Insert a value directly after the sentinel, becoming the new head. */
void Chain::push_front(int new_elem) {
    auto fresh = std::make_shared<Cell>(new_elem);
    if (isEmpty()) {
        sentinel_->next() = fresh;
        tail_ = fresh;
    } else {
        fresh->next() = sentinel_->next();
        sentinel_->next() = fresh;
    }
}

/** @brief Remove the first node matching `old_elem`, if any. */
void Chain::erase(int old_elem) {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return;
    }

    std::shared_ptr<Cell> walker = sentinel_;
    while (walker != tail_ && walker->next()->value() != old_elem) {
        walker = walker->next();
    }

    if (walker == tail_) {
        std::cout << "Element not found\n";
        return;
    }

    std::shared_ptr<Cell> doomed = walker->next();
    walker->next() = doomed->next();
    doomed.reset();

    if (walker->next() == nullptr) {
        tail_ = walker;
    }
    if (sentinel_ == tail_) {
        tail_ = nullptr;
    }
}

/** @brief Print every stored value, tab separated. */
void Chain::display() {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return;
    }
    std::shared_ptr<Cell> walker = sentinel_;
    while (walker->next() != nullptr) {
        std::cout << walker->next()->value() << "\t";
        walker = walker->next();
    }
}

/** @brief Find the node holding `find_elem`, reporting the outcome. */
std::shared_ptr<Cell> Chain::search(int find_elem) {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return nullptr;
    }
    std::shared_ptr<Cell> walker = sentinel_;
    while (walker != tail_ && walker->next()->value() != find_elem) {
        walker = walker->next();
    }
    if (walker == tail_) {
        std::cout << "Element not found\n";
        return nullptr;
    }
    std::cout << "Element was found\n";
    return walker->next();
}

}  // namespace linked_list
}  // namespace data_structures

/**
 * @brief Interactive demo driver for the Chain data structure.
 * @returns 0 on exit
 */
int main() {
    data_structures::linked_list::Chain chain;
    int menu_choice = 0;
    int parsed_value = 0;
    std::string raw_input;

    while (true) {
