        std::cout << "\n\nEnter you choice : ";
        std::cin >> menu_choice;

        if (menu_choice == 0) {
            std::cout << "\nQuitting the program...\n";
            break;
        }

        switch (menu_choice) {
            case 1:
                std::cout << "\nEnter the element to be inserted : ";
                std::cin >> raw_input;
                if (data_structures::linked_list::isDigit(raw_input)) {
                    parsed_value = std::stoi(raw_input);
                    chain.push_back(parsed_value);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 2:
                std::cout << "\nEnter the element to be removed : ";
                std::cin >> raw_input;
                if (data_structures::linked_list::isDigit(raw_input)) {
                    parsed_value = std::stoi(raw_input);
                    chain.erase(parsed_value);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 3:
                std::cout << "\nEnter the element to be searched : ";
                std::cin >> raw_input;
                if (data_structures::linked_list::isDigit(raw_input)) {
                    parsed_value = std::stoi(raw_input);
                    std::shared_ptr<data_structures::linked_list::Cell> hit =
                        chain.search(parsed_value);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 4:
                chain.display();
                std::cout << "\n";
                break;
            default:
                std::cout << "Invalid Input\n" << std::endl;
                break;
        }
    }
    return 0;
}

/**
 * @author [shoniavika](https://github.com/shoniavika)
 * @file
 *
 * Implementation of a Queue using two Stacks.
 */

#include <cassert>
#include <iostream>
#include <stack>

namespace {
/**
 * @brief Queue data structure. Stores elements in FIFO
 * (first-in-first-out) manner.
 * @tparam T datatype to store in the queue
 */
template <typename T>
class MyQueue {
 private:
    std::stack<T> s1, s2;

 public:
    /**
     * Constructor for queue.
     */
    MyQueue() = default;

    /**
     * Pushes x to the back of queue.
     */
    void push(T x);

    /**
     * Removes an element from the front of the queue.
     */
    const T& pop();

    /**
     * Returns first element, without removing it.
     */
    const T& peek() const;

    /**
     * Returns whether the queue is empty.
     */
    bool empty() const;
};

/**
 * Appends element to the end of the queue
 */
template <typename T>
void MyQueue<T>::push(T x) {
    while (!s2.empty()) {
        s1.push(s2.top());
        s2.pop();
    }
    s2.push(x);
    while (!s1.empty()) {
        s2.push(s1.top());
        s1.pop();
    }
}

/**
 * Removes element from the front of the queue
 */
template <typename T>
const T& MyQueue<T>::pop() {
    const T& temp = MyQueue::peek();
    s2.pop();
    return temp;
}

/**
 * Returns element in the front.
 * Does not remove it.
 */
template <typename T>
const T& MyQueue<T>::peek() const {
    if (!empty()) {
        return s2.top();
    }
    std::cerr << "Queue is empty" << std::endl;
    exit(0);
}

/**
 * Checks whether a queue is empty
 */
template <typename T>
bool MyQueue<T>::empty() const {
    return s2.empty() && s1.empty();
}
}  // namespace

/**
 * Testing function
 */
void queue_test() {
    MyQueue<int> que;
    std::cout << "Test #1\n";
    que.push(2);
    que.push(5);
    que.push(0);
    assert(que.peek() == 2);
    assert(que.pop() == 2);
    assert(que.peek() == 5);
    assert(que.pop() == 5);
    assert(que.peek() == 0);
    assert(que.pop() == 0);
    assert(que.empty() == true);
    std::cout << "PASSED\n";

    std::cout << "Test #2\n";
    que.push(-1);
    assert(que.empty() == false);
    assert(que.peek() == -1);
    assert(que.pop() == -1);
    std::cout << "PASSED\n";

    MyQueue<double> que2;
    std::cout << "Test #3\n";
    que2.push(2.31223);
    que2.push(3.1415926);
    que2.push(2.92);

    assert(que2.peek() == 2.31223);
    assert(que2.pop() == 2.31223);
    assert(que2.peek() == 3.1415926);
    assert(que2.pop() == 3.1415926);
    assert(que2.peek() == 2.92);
    assert(que2.pop() == 2.92);
    std::cout << "PASSED\n";
}

/**
 * Main function, calls testing function
 */
int main() {
    queue_test();
    return 0;
}

/**
 * @file
 *
 * Queue built entirely out of two std::stack instances (amortized O(1)
 * push/pop by shuffling elements between the two stacks).
 */

#include <cassert>
#include <iostream>
#include <stack>

namespace {
/**
 * @brief FIFO queue implemented using a pair of LIFO stacks.
 * @tparam ValueType datatype to store in the queue
 */
template <typename ValueType>
class DualStackQueue {
 private:
    std::stack<ValueType> inbox, outbox;

 public:
    DualStackQueue() = default;

    /// Adds an element to the back of the queue.
    void push(ValueType item);

    /// Removes and returns the element at the front of the queue.
    const ValueType& pop();

    /// Returns the front element without removing it.
    const ValueType& peek() const;

    /// Reports whether the queue currently holds no elements.
    bool empty() const;
};

/**
 * @brief Inserts item so that it ends up at the bottom of `outbox`,
 * preserving FIFO order for subsequent pops.
 */
template <typename ValueType>
void DualStackQueue<ValueType>::push(ValueType item) {
    // Drain outbox into inbox so outbox is empty...
    while (!outbox.empty()) {
        inbox.push(outbox.top());
        outbox.pop();
    }
    // ...place the new item at the bottom of outbox...
    outbox.push(item);
    // ...then pour everything back so oldest items end up on top.
    while (!inbox.empty()) {
        outbox.push(inbox.top());
        inbox.pop();
    }
}

/**
 * @brief Removes the front element and returns its value.
 */
template <typename ValueType>
const ValueType& DualStackQueue<ValueType>::pop() {
    const ValueType& frontValue = DualStackQueue::peek();
    outbox.pop();
    return frontValue;
}

/**
 * @brief Returns the front element without popping it.
 */
template <typename ValueType>
const ValueType& DualStackQueue<ValueType>::peek() const {
    if (!empty()) {
        return outbox.top();
    }
    std::cerr << "Queue is empty" << std::endl;
    exit(0);
}

/**
 * @brief True only when both underlying stacks are empty.
 */
template <typename ValueType>
bool DualStackQueue<ValueType>::empty() const {
    return outbox.empty() && inbox.empty();
}
}  // namespace

/**
 * @brief Exercises DualStackQueue with a handful of scripted scenarios.
 */
void runQueueChecks() {
    DualStackQueue<int> intQueue;
    std::cout << "Test #1\n";
    intQueue.push(2);
    intQueue.push(5);
    intQueue.push(0);
    assert(intQueue.peek() == 2);
    assert(intQueue.pop() == 2);
    assert(intQueue.peek() == 5);
    assert(intQueue.pop() == 5);
    assert(intQueue.peek() == 0);
    assert(intQueue.pop() == 0);
    assert(intQueue.empty() == true);
    std::cout << "PASSED\n";

    std::cout << "Test #2\n";
    intQueue.push(-1);
    assert(intQueue.empty() == false);
    assert(intQueue.peek() == -1);
    assert(intQueue.pop() == -1);
    std::cout << "PASSED\n";

    DualStackQueue<double> doubleQueue;
    std::cout << "Test #3\n";
    doubleQueue.push(2.31223);
    doubleQueue.push(3.1415926);
    doubleQueue.push(2.92);

    assert(doubleQueue.peek() == 2.31223);
    assert(doubleQueue.pop() == 2.31223);
    assert(doubleQueue.peek() == 3.1415926);
    assert(doubleQueue.pop() == 3.1415926);
    assert(doubleQueue.peek() == 2.92);
    assert(doubleQueue.pop() == 2.92);
    std::cout << "PASSED\n";
}

/**
 * @brief Entry point; runs the scripted checks above.
 */
int main() {
    runQueueChecks();
    return 0;
}

#include <cassert>    /// For std::assert
#include <iostream>   /// For std::cout
#include <memory>     /// For std::unique_ptr
#include <stdexcept>  /// For std::out_of_range

/**
 * @namespace
 * @brief data_structures
 */
namespace data_structures {
/**
 * @brief Class representation of a stack
 * @tparam T The type of the elements in the stack
 */
template <typename T>
class Stack {
 private:
    std::unique_ptr<T[]> stack;  ///< Smart pointer to the stack array
    int stackSize;               ///< Maximum size of the stack
    int stackIndex;  ///< Index pointing to the top element of the stack

 public:
    /**
     * @brief Constructs a new Stack object
     *
     * @param size Maximum size of the stack
     */
    Stack(int size) : stack(new T[size]), stackSize(size), stackIndex(-1) {}

    /**
     * @brief Checks if the stack is full
     *
     * @return true if the stack is full, false otherwise
     */
    bool full() const { return stackIndex == stackSize - 1; }

    /**
     * @brief Checks if the stack is empty
     * @return true if the stack is empty, false otherwise
     */
    bool empty() const { return stackIndex == -1; }

    /**
     * @brief Pushes an element onto the stack
     *
     * @param element Element to push onto the stack
     */
    void push(T element) {
        if (full()) {
            throw std::out_of_range("Stack overflow");
        } else {
            stack[++stackIndex] = element;
        }
    }

    /**
     * @brief Pops an element from the stack
     *
     * @return The popped element
     * @throws std::out_of_range if the stack is empty
     */
    T pop() {
        if (empty()) {
            throw std::out_of_range("Stack underflow");
        }
        return stack[stackIndex--];
    }

    /**
     * @brief Displays all elements in the stack
     */
    void show() const {
        for (int i = 0; i <= stackIndex; i++) {
            std::cout << stack[i] << "\n";
        }
    }

    /**
     * @brief Displays the topmost element of the stack
     *
     * @return The topmost element of the stack
     * @throws std::out_of_range if the stack is empty
     */
    T topmost() const {
        if (empty()) {
            throw std::out_of_range("Stack underflow");
        }
        return stack[stackIndex];
    }

    /**
     * @brief Displays the bottom element of the stack
     *
     * @return The bottom element of the stack
     * @throws std::out_of_range if the stack is empty
     */
    T bottom() const {
        if (empty()) {
            throw std::out_of_range("Stack underflow");
        }
        return stack[0];
    }
};
}  // namespace data_structures

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    data_structures::Stack<int> stack(5);

    // Test empty and full operations
    assert(stack.empty());
    assert(!stack.full());

    // Test pushing elements and checking topmost
    stack.push(10);
    assert(stack.topmost() == 10);

    stack.push(20);
    assert(stack.topmost() == 20);

    stack.push(30);
    stack.push(40);
    stack.push(50);
    assert(stack.full());

    // Test stack overflow
    try {
        stack.push(60);
    } catch (const std::out_of_range& e) {
        assert(std::string(e.what()) == "Stack overflow");
    }

    // Test popping elements
    assert(stack.pop() == 50);
    assert(stack.pop() == 40);
    assert(stack.pop() == 30);

    // Check topmost and bottom elements
    assert(stack.topmost() == 20);
    assert(stack.bottom() == 10);

    assert(stack.pop() == 20);
    assert(stack.pop() == 10);

    assert(stack.empty());
    assert(!stack.full());

    // Test stack underflow
    try {
        stack.pop();
    } catch (const std::out_of_range& e) {
        assert(std::string(e.what()) == "Stack underflow");
    }

    try {
        stack.topmost();
    } catch (const std::out_of_range& e) {
        assert(std::string(e.what()) == "Stack underflow");
    }

    try {
        stack.bottom();
    } catch (const std::out_of_range& e) {
        assert(std::string(e.what()) == "Stack underflow");
    }
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    std::cout << "All tests passed!" << std::endl;
    return 0;
}

#include <cassert>
#include <iostream>
#include <memory>
#include <stdexcept>

/**
 * @namespace data_structures
 * @brief Container implementations used throughout this collection.
 */
namespace data_structures {

/**
 * @brief A fixed-capacity LIFO container backed by a dynamically
 * allocated buffer.
 * @tparam ElemT type of the values stored
 */
template <typename ElemT>
class FixedCapacityStack {
 public:
    /**
     * @brief Builds an empty stack able to hold up to `capacity` items.
     */
    explicit FixedCapacityStack(int capacity)
        : buffer_(new ElemT[capacity]), capacity_(capacity), topPos_(-1) {}

    /// True once the number of stored elements reaches capacity.
    bool full() const { return topPos_ + 1 == capacity_; }

    /// True when no elements have been pushed (or all have been popped).
    bool empty() const { return topPos_ < 0; }

    /**
     * @brief Places a new value on top of the stack.
     * @throws std::out_of_range when the stack has no remaining room.
     */
    void push(ElemT value) {
        if (full()) {
            throw std::out_of_range("Stack overflow");
        }
        buffer_[++topPos_] = value;
    }

    /**
     * @brief Removes and returns the value currently on top.
     * @throws std::out_of_range when there is nothing to remove.
     */
    ElemT pop() {
        if (empty()) {
            throw std::out_of_range("Stack underflow");
        }
        ElemT value = buffer_[topPos_];
        --topPos_;
        return value;
    }

    /// Prints every stored element from bottom to top.
    void show() const {
        for (int idx = 0; idx <= topPos_; ++idx) {
            std::cout << buffer_[idx] << "\n";
        }
    }

    /**
     * @brief Peeks at the topmost element without removing it.
     * @throws std::out_of_range when the stack is empty.
     */
    ElemT topmost() const {
        if (empty()) {
            throw std::out_of_range("Stack underflow");
        }
        return buffer_[topPos_];
    }

    /**
     * @brief Peeks at the oldest (bottom-most) element without removing it.
     * @throws std::out_of_range when the stack is empty.
     */
    ElemT bottom() const {
        if (empty()) {
            throw std::out_of_range("Stack underflow");
        }
        return buffer_[0];
    }

 private:
    std::unique_ptr<ElemT[]> buffer_;
    int capacity_;
    int topPos_;
};

}  // namespace data_structures

/**
 * @brief Runs a battery of assertions covering normal operation as well
 * as overflow/underflow edge cases.
 */
static void runSelfChecks() {
    data_structures::FixedCapacityStack<int> myStack(5);

    assert(myStack.empty());
    assert(!myStack.full());

    myStack.push(10);
    assert(myStack.topmost() == 10);

    myStack.push(20);
    assert(myStack.topmost() == 20);

    myStack.push(30);
    myStack.push(40);
    myStack.push(50);
    assert(myStack.full());

    bool overflowCaught = false;
    try {
        myStack.push(60);
    } catch (const std::out_of_range& err) {
        overflowCaught = (std::string(err.what()) == "Stack overflow");
    }
    assert(overflowCaught);

    assert(myStack.pop() == 50);
    assert(myStack.pop() == 40);
    assert(myStack.pop() == 30);

    assert(myStack.topmost() == 20);
    assert(myStack.bottom() == 10);

    assert(myStack.pop() == 20);
    assert(myStack.pop() == 10);

    assert(myStack.empty());
    assert(!myStack.full());

    bool underflowCaught = false;
    try {
        myStack.pop();
    } catch (const std::out_of_range& err) {
        underflowCaught = (std::string(err.what()) == "Stack underflow");
    }
    assert(underflowCaught);

    bool topmostThrew = false;
    try {
        myStack.topmost();
    } catch (const std::out_of_range& err) {
        topmostThrew = (std::string(err.what()) == "Stack underflow");
    }
    assert(topmostThrew);

    bool bottomThrew = false;
    try {
        myStack.bottom();
    } catch (const std::out_of_range& err) {
        bottomThrew = (std::string(err.what()) == "Stack underflow");
    }
    assert(bottomThrew);
}

int main() {
    runSelfChecks();
    std::cout << "All tests passed!" << std::endl;
    return 0;
}

/**
 * @brief Stack Data Structure Using the Queue Data Structure
 * @details
 * Using 2 Queues inside the Stack class, we can easily implement Stack
 * data structure with heavy computation in push function.
 *
 * References used:
 * [StudyTonight](https://www.studytonight.com/data-structures/stack-using-queue)
 * @author [tushar2407](https://github.com/tushar2407)
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <queue>     /// for queue data structure

/**
 * @namespace data_structures
 * @brief Data structures algorithms
 */
namespace data_structures {
/**
 * @namespace stack_using_queue
 * @brief Functions for the [Stack Using
 * Queue](https://www.studytonight.com/data-structures/stack-using-queue)
 * implementation
 */
namespace stack_using_queue {
/**
 * @brief Stack Class implementation for basic methods of Stack Data Structure.
 */
struct Stack {
    std::queue<int64_t> main_q;       ///< stores the current state of the stack
    std::queue<int64_t> auxiliary_q;  ///< used to carry out intermediate
                                      ///< operations to implement stack
    uint32_t current_size = 0;        ///< stores the current size of the stack

    /**
     * Returns the top most element of the stack
     * @returns top element of the queue
     */
    int top() { return main_q.front(); }

    /**
     * @brief Inserts an element to the top of the stack.
     * @param val the element that will be inserted into the stack
     * @returns void
     */
    void push(int val) {
        auxiliary_q.push(val);
        while (!main_q.empty()) {
            auxiliary_q.push(main_q.front());
            main_q.pop();
        }
        swap(main_q, auxiliary_q);
        current_size++;
    }

    /**
     * @brief Removes the topmost element from the stack
     * @returns void
     */
    void pop() {
        if (main_q.empty()) {
            return;
        }
        main_q.pop();
        current_size--;
    }

    /**
     * @brief Utility function to return the current size of the stack
     * @returns current size of stack
     */
    int size() { return current_size; }
};
}  // namespace stack_using_queue
}  // namespace data_structures

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    data_structures::stack_using_queue::Stack s;
    s.push(1);  /// insert an element into the stack
    s.push(2);  /// insert an element into the stack
    s.push(3);  /// insert an element into the stack

    assert(s.size() == 3);  /// size should be 3

    assert(s.top() == 3);  /// topmost element in the stack should be 3

    s.pop();               /// remove the topmost element from the stack
    assert(s.top() == 2);  /// topmost element in the stack should now be 2

    s.pop();  /// remove the topmost element from the stack
    assert(s.top() == 1);

    s.push(5);             /// insert an element into the stack
    assert(s.top() == 5);  /// topmost element in the stack should now be 5

    s.pop();               /// remove the topmost element from the stack
    assert(s.top() == 1);  /// topmost element in the stack should now be 1

    assert(s.size() == 1);  /// size should be 1
}

/**
 * @brief Main function
 * Creates a stack and pushed some value into it.
 * Through a series of push and pop functions on stack,
 * it demostrates the functionality of the custom stack
 * declared above.
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @brief Alternate take on building a Stack (LIFO) on top of two Queue
 * (FIFO) containers.
 * @details
 * The trick is to make `push` the expensive operation: whenever a new
 * value arrives, it is enqueued into a scratch queue first, and then every
 * item already present in the main queue is drained into that same scratch
 * queue behind it. Swapping the two queues afterwards leaves the newest
 * value sitting at the front, which is exactly where "top of stack" needs
 * to be. `pop` and `top` then become trivial calls to the underlying
 * queue's front/pop.
 */
#include <cassert>
#include <cstdint>
#include <iostream>
#include <queue>

namespace data_structures {

namespace stack_using_queue {

/**
 * @brief LIFO adapter built from a pair of std::queue instances.
 */
struct Stack {
    std::queue<int64_t> primaryQueue;
    std::queue<int64_t> scratchQueue;
    uint32_t elementCount = 0;

    /// Returns the element currently considered "top of stack".
    int top() { return primaryQueue.front(); }

    /**
     * @brief Adds `value` so that it becomes the new top of the stack.
     */
    void push(int value) {
        scratchQueue.push(value);
        while (!primaryQueue.empty()) {
            scratchQueue.push(primaryQueue.front());
            primaryQueue.pop();
        }
        swap(primaryQueue, scratchQueue);
        ++elementCount;
    }

    /**
     * @brief Discards the current top element, if any.
     */
    void pop() {
        if (primaryQueue.empty()) {
            return;
        }
        primaryQueue.pop();
        --elementCount;
    }

    /// Number of elements currently held.
    int size() { return elementCount; }
};

}  // namespace stack_using_queue
}  // namespace data_structures

/**
 * @brief Exercises push/pop/top/size against expected sequences.
 */
static void runSelfChecks() {
    data_structures::stack_using_queue::Stack myStack;
    myStack.push(1);
    myStack.push(2);
    myStack.push(3);

    assert(myStack.size() == 3);
    assert(myStack.top() == 3);

    myStack.pop();
    assert(myStack.top() == 2);

    myStack.pop();
    assert(myStack.top() == 1);

    myStack.push(5);
    assert(myStack.top() == 5);

    myStack.pop();
    assert(myStack.top() == 1);

    assert(myStack.size() == 1);
}

int main() {
    runSelfChecks();
    return 0;
}

#include <cassert>    /// for assert
#include <iostream>   /// for std::cout
#include <stdexcept>  /// std::invalid_argument
#include <vector>     /// for std::vector

#include "./stack.hpp"

template <typename T>
void testConstructedStackIsEmpty() {
    const stack<T> curStack;
    assert(curStack.isEmptyStack());
}

void testPush() {
    using valueType = int;
    stack<valueType> curStack;
    curStack.push(10);
    curStack.push(20);
    curStack.push(30);
    curStack.push(40);
    const auto expectedData = std::vector<valueType>({40, 30, 20, 10});
    assert(curStack.toVector() == expectedData);
}

void testTop() {
    using valueType = unsigned;
    stack<valueType> curStack;
    curStack.push(1);
    curStack.push(2);
    curStack.push(3);
    curStack.push(4);
    assert(curStack.top() == static_cast<valueType>(4));
}

void testPop() {
    using valueType = int;
    stack<valueType> curStack;
    curStack.push(100);
    curStack.push(200);
    curStack.push(300);

    assert(curStack.top() == static_cast<valueType>(300));
    curStack.pop();
    assert(curStack.top() == static_cast<valueType>(200));
    curStack.pop();
    assert(curStack.top() == static_cast<valueType>(100));
    curStack.pop();
    assert(curStack.isEmptyStack());
}

void testClear() {
    stack<int> curStack;
    curStack.push(1000);
    curStack.push(2000);
    curStack.clear();
    assert(curStack.isEmptyStack());
}

void testCopyOfStackHasSameData() {
    stack<int> stackA;
    stackA.push(10);
    stackA.push(200);
    stackA.push(3000);
    const auto stackB(stackA);
    assert(stackA.toVector() == stackB.toVector());
}

void testPushingToCopyDoesNotChangeOriginal() {
    using valueType = int;
    stack<valueType> stackA;
    stackA.push(10);
    stackA.push(20);
    stackA.push(30);
    auto stackB(stackA);
    stackB.push(40);

    const auto expectedDataA = std::vector<valueType>({30, 20, 10});
    const auto expectedDataB = std::vector<valueType>({40, 30, 20, 10});

    assert(stackA.toVector() == expectedDataA);
    assert(stackB.toVector() == expectedDataB);
}

void testPoppingFromCopyDoesNotChangeOriginal() {
    using valueType = int;
    stack<valueType> stackA;
    stackA.push(10);
    stackA.push(20);
    stackA.push(30);
    auto stackB(stackA);
    stackB.pop();

    const auto expectedDataA = std::vector<valueType>({30, 20, 10});
    const auto expectedDataB = std::vector<valueType>({20, 10});

    assert(stackA.toVector() == expectedDataA);
    assert(stackB.toVector() == expectedDataB);
}

void testPushingToOrginalDoesNotChangeCopy() {
    using valueType = int;
    stack<valueType> stackA;
    stackA.push(10);
    stackA.push(20);
    stackA.push(30);
    const auto stackB(stackA);
    stackA.push(40);

    const auto expectedDataA = std::vector<valueType>({40, 30, 20, 10});
    const auto expectedDataB = std::vector<valueType>({30, 20, 10});

    assert(stackA.toVector() == expectedDataA);
    assert(stackB.toVector() == expectedDataB);
}

void testPoppingFromOrginalDoesNotChangeCopy() {
    using valueType = int;
    stack<valueType> stackA;
    stackA.push(10);
    stackA.push(20);
    stackA.push(30);
    const auto stackB(stackA);
    stackA.pop();

    const auto expectedDataA = std::vector<valueType>({20, 10});
    const auto expectedDataB = std::vector<valueType>({30, 20, 10});

    assert(stackA.toVector() == expectedDataA);
    assert(stackB.toVector() == expectedDataB);
}

void testAssign() {
    using valueType = int;
    stack<valueType> stackA;
    stackA.push(10);
    stackA.push(20);
    stackA.push(30);
    stack<valueType> stackB = stackA;
    stackA.pop();
    stackB.push(40);

    const auto expectedDataA = std::vector<valueType>({20, 10});
    const auto expectedDataB = std::vector<valueType>({40, 30, 20, 10});

    assert(stackA.toVector() == expectedDataA);
    assert(stackB.toVector() == expectedDataB);

    stackB = stackA;
    stackA.pop();
    stackB.push(5);
    stackB.push(6);

    const auto otherExpectedDataA = std::vector<valueType>({10});
    const auto otherExpectedDataB = std::vector<valueType>({6, 5, 20, 10});

    assert(stackA.toVector() == otherExpectedDataA);
    assert(stackB.toVector() == otherExpectedDataB);
}

void testTopThrowsAnInvalidArgumentWhenStackEmpty() {
    const stack<long double> curStack;
    bool wasException = false;
    try {
        curStack.top();
    } catch (const std::invalid_argument&) {
        wasException = true;
    }
    assert(wasException);
}

void testPopThrowsAnInvalidArgumentWhenStackEmpty() {
    stack<bool> curStack;
    bool wasException = false;
    try {
        curStack.pop();
    } catch (const std::invalid_argument&) {
        wasException = true;
    }
    assert(wasException);
}

int main() {
    testConstructedStackIsEmpty<int>();
    testConstructedStackIsEmpty<char>();

    testPush();
    testPop();
    testClear();

    testCopyOfStackHasSameData();
    testPushingToCopyDoesNotChangeOriginal();
    testPoppingFromCopyDoesNotChangeOriginal();
    testPushingToOrginalDoesNotChangeCopy();
    testPoppingFromOrginalDoesNotChangeCopy();

    testAssign();

    testTopThrowsAnInvalidArgumentWhenStackEmpty();
    testPopThrowsAnInvalidArgumentWhenStackEmpty();

    std::cout << "All tests pass!\n";
    return 0;
}

#include <cassert>
#include <iostream>
#include <stdexcept>
#include <vector>

#include "./stack.hpp"

// A default-constructed stack, of any element type, should start empty.
template <typename ElemT>
void checkFreshStackIsEmpty() {
    const stack<ElemT> s;
    assert(s.isEmptyStack());
}

// Pushed values should come back out in LIFO order via toVector().
void checkPushOrdering() {
    using Val = int;
    stack<Val> s;
    s.push(10);
    s.push(20);
    s.push(30);
    s.push(40);
    const auto expected = std::vector<Val>({40, 30, 20, 10});
    assert(s.toVector() == expected);
}

// top() should always reflect the most recently pushed value.
void checkTopReflectsLatestPush() {
    using Val = unsigned;
    stack<Val> s;
    s.push(1);
    s.push(2);
    s.push(3);
    s.push(4);
    assert(s.top() == static_cast<Val>(4));
}

// pop() should remove values in reverse insertion order, ending empty.
void checkPopRemovesInReverseOrder() {
    using Val = int;
    stack<Val> s;
    s.push(100);
    s.push(200);
    s.push(300);

    assert(s.top() == static_cast<Val>(300));
    s.pop();
    assert(s.top() == static_cast<Val>(200));
    s.pop();
    assert(s.top() == static_cast<Val>(100));
    s.pop();
    assert(s.isEmptyStack());
}

// clear() should drop all elements immediately.
void checkClearDropsEverything() {
    stack<int> s;
    s.push(1000);
    s.push(2000);
    s.clear();
    assert(s.isEmptyStack());
}

// Copy-constructing a stack should produce identical contents.
void checkCopyMatchesOriginal() {
    stack<int> original;
    original.push(10);
    original.push(200);
    original.push(3000);
    const auto duplicate(original);
    assert(original.toVector() == duplicate.toVector());
}

// Mutating a copy via push must not affect the source stack.
void checkPushOnCopyLeavesOriginalUntouched() {
    using Val = int;
    stack<Val> original;
    original.push(10);
    original.push(20);
    original.push(30);
    auto duplicate(original);
    duplicate.push(40);

    const auto expectedOriginal = std::vector<Val>({30, 20, 10});
    const auto expectedDuplicate = std::vector<Val>({40, 30, 20, 10});

    assert(original.toVector() == expectedOriginal);
    assert(duplicate.toVector() == expectedDuplicate);
}

// Popping from a copy must not affect the source stack.
void checkPopOnCopyLeavesOriginalUntouched() {
    using Val = int;
    stack<Val> original;
    original.push(10);
    original.push(20);
    original.push(30);
    auto duplicate(original);
    duplicate.pop();

    const auto expectedOriginal = std::vector<Val>({30, 20, 10});
    const auto expectedDuplicate = std::vector<Val>({20, 10});

    assert(original.toVector() == expectedOriginal);
    assert(duplicate.toVector() == expectedDuplicate);
}

// Pushing onto the original after copying must not affect the copy.
void checkPushOnOriginalLeavesCopyUntouched() {
    using Val = int;
    stack<Val> original;
    original.push(10);
    original.push(20);
    original.push(30);
    const auto duplicate(original);
    original.push(40);

    const auto expectedOriginal = std::vector<Val>({40, 30, 20, 10});
    const auto expectedDuplicate = std::vector<Val>({30, 20, 10});

    assert(original.toVector() == expectedOriginal);
    assert(duplicate.toVector() == expectedDuplicate);
}

// Popping from the original after copying must not affect the copy.
void checkPopOnOriginalLeavesCopyUntouched() {
    using Val = int;
    stack<Val> original;
    original.push(10);
    original.push(20);
    original.push(30);
    const auto duplicate(original);
    original.pop();

    const auto expectedOriginal = std::vector<Val>({20, 10});
    const auto expectedDuplicate = std::vector<Val>({30, 20, 10});

    assert(original.toVector() == expectedOriginal);
    assert(duplicate.toVector() == expectedDuplicate);
}

// Assignment (both construction-style and operator=) should behave like an
// independent deep copy, in both directions.
void checkAssignmentIsIndependent() {
    using Val = int;
    stack<Val> a;
    a.push(10);
    a.push(20);
    a.push(30);
    stack<Val> b = a;
    a.pop();
    b.push(40);

    const auto expectedA = std::vector<Val>({20, 10});
    const auto expectedB = std::vector<Val>({40, 30, 20, 10});

    assert(a.toVector() == expectedA);
    assert(b.toVector() == expectedB);

    b = a;
    a.pop();
    b.push(5);
    b.push(6);

    const auto expectedA2 = std::vector<Val>({10});
    const auto expectedB2 = std::vector<Val>({6, 5, 20, 10});

    assert(a.toVector() == expectedA2);
    assert(b.toVector() == expectedB2);
}

// top() on an empty stack must raise std::invalid_argument.
void checkTopThrowsWhenEmpty() {
    const stack<long double> s;
    bool threw = false;
    try {
        s.top();
    } catch (const std::invalid_argument&) {
        threw = true;
    }
    assert(threw);
}

// pop() on an empty stack must raise std::invalid_argument.
void checkPopThrowsWhenEmpty() {
    stack<bool> s;
    bool threw = false;
    try {
        s.pop();
    } catch (const std::invalid_argument&) {
        threw = true;
    }
    assert(threw);
}

int main() {
    checkFreshStackIsEmpty<int>();
    checkFreshStackIsEmpty<char>();

    checkPushOrdering();
    checkPopRemovesInReverseOrder();
    checkClearDropsEverything();

    checkCopyMatchesOriginal();
    checkPushOnCopyLeavesOriginalUntouched();
    checkPopOnCopyLeavesOriginalUntouched();
    checkPushOnOriginalLeavesCopyUntouched();
    checkPopOnOriginalLeavesCopyUntouched();

    checkAssignmentIsIndependent();

    checkTopThrowsWhenEmpty();
    checkPopThrowsWhenEmpty();

    std::cout << "All tests pass!\n";
    return 0;
}

/**
 * @file
 * @author [@Arctic2333](https://github.com/Arctic2333)
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Implementation of [Trie](https://en.wikipedia.org/wiki/Trie) data
 * structure for English alphabets in small characters.
 * @note the function ::data_structure::trie::deleteString might be erroneous
 * @see trie_modern.cpp
 */
#include <array>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <memory>
#include <string>

/** \namespace data_structures
 * \brief Data-structure algorithms
 */
namespace data_structures {
/**
 * @brief [Trie](https://en.wikipedia.org/wiki/Trie) implementation for
 * small-case English alphabets `a-z`
 */
class trie {
 private:
    static constexpr uint8_t NUM_CHARS = 26;  ///< Number of alphabets
    /** @brief Recursive tree nodes as an array of shared-pointers */
    std::array<std::shared_ptr<trie>, NUM_CHARS << 1> arr;
    bool isEndofWord = false;  ///< identifier if a node is terminal node

    /**
     * @brief Convert a character to integer for indexing
     *
     * @param ch character to index
     * @return unsigned integer index
     */
    uint8_t char_to_int(const char& ch) const {
        if (ch >= 'A' && ch <= 'Z') {
            return ch - 'A';
        } else if (ch >= 'a' && ch <= 'z') {
            return ch - 'a' + NUM_CHARS;
        }

        std::cerr << "Invalid character present. Exiting...";
        std::exit(EXIT_FAILURE);
        return 0;
    }

    /** search a string exists inside a given root trie
     * @param str string to search for
     * @param index start index to search from
     * @returns `true` if found
     * @returns `false` if not found
     */
    bool search(const std::shared_ptr<trie>& root, const std::string& str,
                int index) {
        if (index == str.length()) {
            if (!root->isEndofWord) {
                return false;
            }
            return true;
        }
        int j = char_to_int(str[index]);
        if (!root->arr[j]) {
            return false;
        }
        return search(root->arr[j], str, index + 1);
    }

 public:
    trie() = default;  ///< Class default constructor

    /** insert string into the trie
     * @param str String to insert in the tree
     */
    void insert(const std::string& str) {
        std::shared_ptr<trie> root(nullptr);

        for (const char& ch : str) {
            int j = char_to_int(ch);
            if (root) {
                if (root->arr[j]) {
                    root = root->arr[j];
                } else {
                    std::shared_ptr<trie> temp(new trie());
                    root->arr[j] = temp;
                    root = temp;
                }
            } else if (arr[j]) {
                root = arr[j];
            } else {
                std::shared_ptr<trie> temp(new trie());
                arr[j] = temp;
                root = temp;
            }
        }
        root->isEndofWord = true;
    }

    /** search a string exists inside the trie
     * @param str string to search for
     * @param index start index to search from
     * @returns `true` if found
     * @returns `false` if not found
     */
    bool search(const std::string& str, int index) {
        if (index == str.length()) {
            if (!isEndofWord) {
                return false;
            }
            return true;
        }
        int j = char_to_int(str[index]);
        if (!arr[j]) {
            return false;
        }
        return search(arr[j], str, index + 1);
    }

    /**
     * removes the string if it is not a prefix of any  other
     * string, if it is then just sets the ::data_structure::trie::isEndofWord
     * to false, else removes the given string
     * @note the function ::data_structure::trie::deleteString might be
     * erroneous
     * @todo review the function ::data_structure::trie::deleteString and the
     * commented lines
     * @param str string to remove
     * @param index index to remove from
     * @returns `true` if successful
     * @returns `false` if unsuccessful
     */
    bool deleteString(const std::string& str, int index) {
        if (index == str.length()) {
            if (!isEndofWord) {
                return false;
            }
            isEndofWord = false;
            // following lines - possible source of error?
            // for (int i = 0; i < NUM_CHARS; i++)
            //     if (!arr[i])
            //         return false;
            return true;
        }
        int j = char_to_int(str[index]);
        if (!arr[j]) {
            return false;
        }
        bool var = deleteString(str, index + 1);
        if (var) {
            arr[j].reset();
            if (isEndofWord) {
                return false;
            } else {
                int i = 0;
                for (i = 0; i < NUM_CHARS; i++) {
                    if (arr[i]) {
                        return false;
                    }
                }
                return true;
            }
        }

        /* should not return here */
        std::cout << __func__ << ":" << __LINE__
                  << "Should not reach this line\n";
        return false;
    }
};
}  // namespace data_structures

/**
 * @brief Testing function
 * @returns void
 */
static void test() {
    data_structures::trie root;
    root.insert("Hello");
    root.insert("World");

    assert(!root.search("hello", 0));
    std::cout << "hello - " << root.search("hello", 0) << "\n";

    assert(root.search("Hello", 0));
    std::cout << "Hello - " << root.search("Hello", 0) << "\n";

    assert(!root.search("Word", 0));
    std::cout << "Word - " << root.search("Word", 0) << "\n";

    assert(root.search("World", 0));
    std::cout << "World - " << root.search("World", 0) << "\n";

    // Following lines of code give erroneous output
    // root.deleteString("hello", 0);
    // assert(!root.search("hello", 0));
    // std::cout << "hello - " << root.search("world", 0) << "\n";
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    test();

    return 0;
}

/**
 * @file
 * @brief Alternate-cased [Trie](https://en.wikipedia.org/wiki/Trie)
 * implementation supporting both upper- and lower-case English letters.
 * @note the deletion routine here mirrors a known-tricky case from the
 * reference implementation; treat it with the same suspicion.
 */
#include <array>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <memory>
#include <string>

/** \namespace ds
 * \brief Container/data-structure implementations
 */
namespace ds {
/**
 * @brief Prefix tree supporting both `A-Z` and `a-z`, distinguished via a
 * doubled index range.
 */
class PrefixTree {
 private:
    static constexpr uint8_t kLetterCount = 26;  ///< letters per case
    /** @brief Children slots: lower half for uppercase, upper half for lowercase */
    std::array<std::shared_ptr<PrefixTree>, kLetterCount << 1> kids;
    bool wordEnd = false;  ///< marks a node as the end of some inserted word

    /**
     * @brief Maps a character to its slot index within `kids`.
     *
     * @param c character to convert
     * @return slot index for that character
     */
    uint8_t slotFor(const char& c) const {
        if (c >= 'A' && c <= 'Z') {
            return c - 'A';
        } else if (c >= 'a' && c <= 'z') {
            return c - 'a' + kLetterCount;
        }

        std::cerr << "Invalid character present. Exiting...";
        std::exit(EXIT_FAILURE);
        return 0;
    }

    /** Looks for `str` starting under an arbitrary subtree.
     * @param sub subtree root to search from
     * @param str target string
     * @param pos position within `str` currently being matched
     * @returns true when the full string terminates a word
     * @returns false otherwise
     */
    bool locate(const std::shared_ptr<PrefixTree>& sub, const std::string& str,
                int pos) {
        if (pos == str.length()) {
            if (!sub->wordEnd) {
                return false;
            }
            return true;
        }
        int slot = slotFor(str[pos]);
        if (!sub->kids[slot]) {
            return false;
        }
        return locate(sub->kids[slot], str, pos + 1);
    }

 public:
    PrefixTree() = default;  ///< Default-constructs an empty node

    /** Inserts `str` into the tree, allocating nodes along the way as
     * needed.
     * @param str string to insert
     */
    void insert(const std::string& str) {
        std::shared_ptr<PrefixTree> cursor(nullptr);

        for (const char& c : str) {
            int slot = slotFor(c);
            if (cursor) {
                if (cursor->kids[slot]) {
                    cursor = cursor->kids[slot];
                } else {
                    std::shared_ptr<PrefixTree> fresh(new PrefixTree());
                    cursor->kids[slot] = fresh;
                    cursor = fresh;
                }
            } else if (kids[slot]) {
                cursor = kids[slot];
            } else {
                std::shared_ptr<PrefixTree> fresh(new PrefixTree());
                kids[slot] = fresh;
                cursor = fresh;
            }
        }
        cursor->wordEnd = true;
    }

    /** Checks whether `str` exists in the tree starting from this node.
     * @param str target string
     * @param pos current match position within `str`
     * @returns true if found
     * @returns false if not found
     */
    bool search(const std::string& str, int pos) {
        if (pos == str.length()) {
            if (!wordEnd) {
                return false;
            }
            return true;
        }
        int slot = slotFor(str[pos]);
        if (!kids[slot]) {
            return false;
        }
        return locate(kids[slot], str, pos + 1);
    }

    /**
     * Attempts to erase `str` from the tree. If the string is a prefix of
     * another stored word, only its word-end flag is cleared; otherwise
     * the now-unused nodes are released.
     * @note ported over a known-flaky deletion case; double check before
     * relying on it
     * @param str string to erase
     * @param pos current index being processed
     * @returns true on success
     * @returns false on failure
     */
    bool eraseString(const std::string& str, int pos) {
        if (pos == str.length()) {
            if (!wordEnd) {
                return false;
            }
            wordEnd = false;
            // Possible extra check here (left out on purpose, matching the
            // original's commented-out verification block):
            // for (int i = 0; i < kLetterCount; i++)
            //     if (!kids[i])
            //         return false;
            return true;
        }
        int slot = slotFor(str[pos]);
        if (!kids[slot]) {
            return false;
        }
        bool childCleared = eraseString(str, pos + 1);
        if (childCleared) {
            kids[slot].reset();
            if (wordEnd) {
                return false;
            } else {
                for (int i = 0; i < kLetterCount; i++) {
                    if (kids[i]) {
                        return false;
                    }
                }
                return true;
            }
        }

        /* control flow should never arrive here */
        std::cout << __func__ << ":" << __LINE__
                  << "Should not reach this line\n";
        return false;
    }
};
}  // namespace ds

/**
 * @brief Runs a handful of sanity checks against PrefixTree.
