#include <iostream>
using namespace std;
int fib(int n) {
    int res[3];
    res[0] = 0;
    res[1] = 1;
    for (int i = 2; i <= n; i++) {
        res[2] = res[1] + res[0];
        res[0] = res[1];
        res[1] = res[2];
    }
    return res[1];
}
int main() {
    int n;
    cout << "Enter n: ";
    cin >> n;
    cout << "Fibonacci number is ";
    cout << fib(n) << endl;
    return 0;
}

#include <iostream>

// Iteratively builds up the Fibonacci sequence using only two rolling
// values instead of storing the whole sequence.
int fibonacciAt(int position) {
    int previous = 0;
    int current = 1;

    for (int step = 2; step <= position; ++step) {
        int next = previous + current;
        previous = current;
        current = next;
    }

    return current;
}

int main() {
    int position;
    std::cout << "Enter n: ";
    std::cin >> position;
    std::cout << "Fibonacci number is ";
    std::cout << fibonacciAt(position) << std::endl;
    return 0;
}

// Longest common subsequence - Dynamic Programming
#include <iostream>
#include <vector>
using namespace std;

void Print(int trace[20][20], int m, int n, string a) {
    if (m == 0 || n == 0) {
        return;
    }
    if (trace[m][n] == 1) {
        Print(trace, m - 1, n - 1, a);
        cout << a[m - 1];
    } else if (trace[m][n] == 2) {
        Print(trace, m - 1, n, a);
    } else if (trace[m][n] == 3) {
        Print(trace, m, n - 1, a);
    }
}

int lcs(string a, string b) {
    int m = a.length(), n = b.length();
    std::vector<std::vector<int> > res(m + 1, std::vector<int>(n + 1));
    int trace[20][20];

    // fills up the arrays with zeros.
    for (int i = 0; i < m + 1; i++) {
        for (int j = 0; j < n + 1; j++) {
            res[i][j] = 0;
            trace[i][j] = 0;
        }
    }

    for (int i = 0; i < m + 1; ++i) {
        for (int j = 0; j < n + 1; ++j) {
            if (i == 0 || j == 0) {
                res[i][j] = 0;
                trace[i][j] = 0;
            }

            else if (a[i - 1] == b[j - 1]) {
                res[i][j] = 1 + res[i - 1][j - 1];
                trace[i][j] = 1;  // 1 means trace the matrix in upper left
                                  // diagonal direction.
            } else {
                if (res[i - 1][j] > res[i][j - 1]) {
                    res[i][j] = res[i - 1][j];
                    trace[i][j] =
                        2;  // 2 means trace the matrix in upwards direction.
                } else {
                    res[i][j] = res[i][j - 1];
                    trace[i][j] =
                        3;  //  means trace the matrix in left direction.
                }
            }
        }
    }
    Print(trace, m, n, a);
    return res[m][n];
}

int main() {
    string a, b;
    cin >> a >> b;
    cout << lcs(a, b);
    return 0;
}

// Longest Common Subsequence, solved with a bottom-up DP table plus
// backtracking to reconstruct the actual subsequence text.
#include <iostream>
#include <vector>
using namespace std;

// Directions used while walking back through the DP table to rebuild the
// subsequence: DIAG means both characters matched, UP means we came from the
// row above, LEFT means we came from the column to the left.
enum TraceDir { NONE = 0, DIAG = 1, UP = 2, LEFT = 3 };

// Walks the trace table backwards from (row, col) and prints the characters
// belonging to the reconstructed common subsequence in order.
void emitSubsequence(const vector<vector<int>>& trace, int row, int col,
                     const string& source) {
    if (row == 0 || col == 0) {
        return;
    }
    if (trace[row][col] == DIAG) {
        emitSubsequence(trace, row - 1, col - 1, source);
        cout << source[row - 1];
    } else if (trace[row][col] == UP) {
        emitSubsequence(trace, row - 1, col, source);
    } else if (trace[row][col] == LEFT) {
        emitSubsequence(trace, row, col - 1, source);
    }
}

// Computes the length of the LCS between first and second, printing the
// reconstructed subsequence as a side effect before returning the length.
int longestCommonSubsequence(const string& first, const string& second) {
    const int rows = static_cast<int>(first.length());
    const int cols = static_cast<int>(second.length());

    vector<vector<int>> lengths(rows + 1, vector<int>(cols + 1, 0));
    vector<vector<int>> trace(rows + 1, vector<int>(cols + 1, NONE));

    for (int i = 0; i <= rows; ++i) {
        for (int j = 0; j <= cols; ++j) {
            if (i == 0 || j == 0) {
                lengths[i][j] = 0;
                trace[i][j] = NONE;
                continue;
            }

            if (first[i - 1] == second[j - 1]) {
                lengths[i][j] = 1 + lengths[i - 1][j - 1];
                trace[i][j] = DIAG;
            } else if (lengths[i - 1][j] > lengths[i][j - 1]) {
                lengths[i][j] = lengths[i - 1][j];
                trace[i][j] = UP;
            } else {
                lengths[i][j] = lengths[i][j - 1];
                trace[i][j] = LEFT;
            }
        }
    }

    emitSubsequence(trace, rows, cols, first);
    return lengths[rows][cols];
}

int main() {
    string first, second;
    cin >> first >> second;
    cout << longestCommonSubsequence(first, second);
    return 0;
}

// Program to calculate length of longest increasing subsequence in an array
// in O(n log n)
// tested on : https://cses.fi/problemset/task/1145/

#include <iostream>
#include <set>
#include <vector>

using namespace std;
int LIS(const std::vector<int>& arr, int n) {
    set<int> active;  // The current built LIS.
    active.insert(arr[0]);
    // Loop through every element.
    for (int i = 1; i < n; ++i) {
        auto get = active.lower_bound(arr[i]);
        if (get == active.end()) {
            active.insert(arr[i]);
        }  // current element is the greatest so LIS increases by 1.
        else {
            int val = *get;  // we find the position where arr[i] will be in the
                             // LIS. If it is in the LIS already we do nothing
            if (val > arr[i]) {
                // else we remove the bigger element and add a smaller element
                // (which is arr[i]) and continue;
                active.erase(get);
                active.insert(arr[i]);
            }
        }
    }
    return active.size();  // size of the LIS.
}
int main() {
    int n;
    cout << "Enter size of array: ";
    cin >> n;
    std::vector<int> a(n);
    cout << "Enter array elements: ";
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    cout << LIS(a, n) << endl;
    return 0;
}

// Computes the length of the longest increasing subsequence of an array in
// O(n log n) time by maintaining the smallest possible "tail" value for every
// achievable subsequence length.
// verified against: https://cses.fi/problemset/task/1145/

#include <iostream>
#include <set>
#include <vector>

using namespace std;

int longestIncreasingSubsequenceLength(const std::vector<int>& sequence,
                                        int count) {
    set<int> tails;  // tails[k] roughly tracks the best (smallest) end value
                     // for an increasing run of length k+1
    tails.insert(sequence[0]);

    int idx = 1;
    while (idx < count) {
        const auto slot = tails.lower_bound(sequence[idx]);
        if (slot == tails.end()) {
            // sequence[idx] is larger than everything seen, so it extends
            // the longest run found so far by one.
            tails.insert(sequence[idx]);
        } else if (*slot > sequence[idx]) {
            // sequence[idx] can replace an existing tail with a smaller
            // value, keeping future extensions easier without changing the
            // run length.
            tails.erase(slot);
            tails.insert(sequence[idx]);
        }
        // if *slot == sequence[idx] there's nothing to do, the value is
        // already represented.
        ++idx;
    }

    return static_cast<int>(tails.size());
}

int main() {
    int count;
    cout << "Enter size of array: ";
    cin >> count;

    std::vector<int> sequence(count);
    cout << "Enter array elements: ";
    for (int idx = 0; idx < count; ++idx) {
        cin >> sequence[idx];
    }

    cout << longestIncreasingSubsequenceLength(sequence, count) << endl;
    return 0;
}

#include <climits>
#include <iostream>
using namespace std;

#define MAX 10

// dp table to store the solution for already computed sub problems
int dp[MAX][MAX];

// Function to find the most efficient way to multiply the given sequence of
// matrices
int MatrixChainMultiplication(int dim[], int i, int j) {
    // base case: one matrix
    if (j <= i + 1)
        return 0;

    // stores minimum number of scalar multiplications (i.e., cost)
    // needed to compute the matrix M[i+1]...M[j] = M[i..j]
    int min = INT_MAX;

    // if dp[i][j] is not calculated (calculate it!!)

    if (dp[i][j] == 0) {
        // take the minimum over each possible position at which the
        // sequence of matrices can be split

        for (int k = i + 1; k <= j - 1; k++) {
            // recur for M[i+1]..M[k] to get a i x k matrix
            int cost = MatrixChainMultiplication(dim, i, k);

            // recur for M[k+1]..M[j] to get a k x j matrix
            cost += MatrixChainMultiplication(dim, k, j);

            // cost to multiply two (i x k) and (k x j) matrix
            cost += dim[i] * dim[k] * dim[j];

            if (cost < min)
                min = cost;  // store the minimum cost
        }
        dp[i][j] = min;
    }

    // return min cost to multiply M[j+1]..M[j]
    return dp[i][j];
}

// main function
int main() {
    // Matrix i has Dimensions dim[i-1] & dim[i] for i=1..n
    // input is 10 x 30 matrix, 30 x 5 matrix, 5 x 60 matrix
    int dim[] = {10, 30, 5, 60};
    int n = sizeof(dim) / sizeof(dim[0]);

    // Function Calling: MatrixChainMultiplications(dimensions_array, starting,
    // ending);

    cout << "Minimum cost is " << MatrixChainMultiplication(dim, 0, n - 1)
         << "\n";

    return 0;
}

#include <climits>
#include <iostream>
using namespace std;

#define MAX_MATRICES 10

// Memo table holding already-solved subproblem costs, indexed by the
// (start, end) split boundaries used below.
int memo[MAX_MATRICES][MAX_MATRICES];

// Recursively determines the cheapest way (fewest scalar multiplications) to
// multiply the chain of matrices whose boundary dimensions live in
// dims[start..end].
int cheapestChainCost(int dims[], int start, int end) {
    // Base case: a single matrix requires no multiplication.
    if (end <= start + 1) {
        return 0;
    }

    // Only do the work if this subproblem hasn't been solved before.
    if (memo[start][end] == 0) {
        int bestCost = INT_MAX;

        // Try every valid split point and keep whichever is cheapest.
        for (int split = start + 1; split <= end - 1; split++) {
            // Cost of multiplying the left half of the split...
            int cost = cheapestChainCost(dims, start, split);

            // ...plus the cost of multiplying the right half...
            cost += cheapestChainCost(dims, split, end);

            // ...plus the cost of combining the two resulting matrices.
            cost += dims[start] * dims[split] * dims[end];

            if (cost < bestCost) {
                bestCost = cost;
            }
        }
        memo[start][end] = bestCost;
    }

    return memo[start][end];
}

int main() {
    // dims[i-1] and dims[i] give the dimensions of matrix i, for i = 1..n.
    // Here: a 10x30 matrix, followed by 30x5, followed by 5x60.
    int dims[] = {10, 30, 5, 60};
    int matrixCount = sizeof(dims) / sizeof(dims[0]);

    cout << "Minimum cost is " << cheapestChainCost(dims, 0, matrixCount - 1)
         << "\n";

    return 0;
}

/**
* @file
* @brief C++ program for maximum contiguous circular sum problem using [Kadane's Algorithm](https://en.wikipedia.org/wiki/Maximum_subarray_problem)
* @details
* The idea is to modify Kadane’s algorithm to find a minimum contiguous subarray sum and the maximum contiguous subarray sum,
* then check for the maximum value between the max_value and the value left after subtracting min_value from the total sum.
* For more information, check [Geeks For Geeks](https://www.geeksforgeeks.org/maximum-contiguous-circular-sum/) explanation page.
*/

#include <cassert>     /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector


/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {
/**
 * @brief returns the maximum contiguous circular sum of an array
 * 
 * @param arr is the array/vector
 * @return int which is the maximum sum
 */
int maxCircularSum(std::vector<int>& arr)
{
    // Edge Case
    if (arr.size() == 1)
        return arr[0];

    // Sum variable which stores total sum of the array.
    int sum = 0;
    for (int i = 0; i < arr.size(); i++) {
        sum += arr[i];
    }

    // Every variable stores first value of the array.
    int current_max = arr[0], max_so_far = arr[0], current_min = arr[0], min_so_far = arr[0];

    // Concept of Kadane's Algorithm
    for (int i = 1; i < arr.size(); i++) {
        // Kadane's Algorithm to find Maximum subarray sum.
        current_max = std::max(current_max + arr[i], arr[i]);
        max_so_far = std::max(max_so_far, current_max);

        // Kadane's Algorithm to find Minimum subarray sum.
        current_min = std::min(current_min + arr[i], arr[i]);
        min_so_far = std::min(min_so_far, current_min);
    }

    if (min_so_far == sum)
        return max_so_far;

    // Return the maximum value
    return std::max(max_so_far, sum - min_so_far);
}
}  // namespace dynamic_programming

/**
 * @brief Self-test implementation
 * @returns void
 */
static void test() {
    // Description of the test
    // Input: arr[] = {8, -8, 9, -9, 10, -11, 12}
    // Output: 22 
    // Explanation: Subarray 12, 8, -8, 9, -9, 10 gives the maximum sum, that is 22.

    std::vector<int> arr = {8, -8, 9, -9, 10, -11, 12}; 
    assert(dynamic_programming::maxCircularSum(arr) == 22); // this ensures that the algorithm works as expected

    arr = {8, -8, 10, -9, 10, -11, 12};
    assert(dynamic_programming::maxCircularSum(arr) == 23);

    std::cout << "All tests have successfully passed!\n";
}


/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
     test();  // run self-test implementations
     return 0;
}

/**
* @file
* @brief Alternative implementation of the maximum contiguous circular
* subarray sum problem, built on top of [Kadane's
* Algorithm](https://en.wikipedia.org/wiki/Maximum_subarray_problem).
* @details
* We run Kadane's algorithm twice: once to obtain the best ordinary
* (non-wrapping) subarray sum, and once (with min/max swapped) to obtain the
* worst subarray sum. Subtracting the worst subarray from the array's total
* yields the best possible *wrapping* subarray sum. The final answer is the
* larger of the two, unless every element is negative, in which case the
* non-wrapping result must be used since a "wrap everything" answer would be
* an empty subarray.
* See also: https://www.geeksforgeeks.org/maximum-contiguous-circular-sum/
*/

#include <cassert>    /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {

/**
 * @brief Finds the maximum possible sum of a contiguous subarray, allowing
 * the subarray to wrap around from the end of the array back to the start.
 * @param values the array/vector to inspect
 * @return the largest achievable circular subarray sum
 */
int maxCircularSum(std::vector<int>& values) {
    const std::size_t count = values.size();

    // With a single element, that element is the only possible subarray.
    if (count == 1) {
        return values[0];
    }

    // Total of every element, needed to derive the wrap-around sum later.
    int total = 0;
    for (std::size_t idx = 0; idx < count; idx++) {
        total += values[idx];
    }

    // Track the best/worst running subarray sums simultaneously.
    int runningMax = values[0];
    int bestNonWrap = values[0];
    int runningMin = values[0];
    int worstSubarray = values[0];

    for (std::size_t idx = 1; idx < count; idx++) {
        // Standard Kadane step for the maximum subarray.
        runningMax = std::max(runningMax + values[idx], values[idx]);
        bestNonWrap = std::max(bestNonWrap, runningMax);

        // Mirror-image Kadane step for the minimum subarray.
        runningMin = std::min(runningMin + values[idx], values[idx]);
        worstSubarray = std::min(worstSubarray, runningMin);
    }

    // If the "worst" subarray is actually the whole array, wrapping around
    // would leave nothing behind, so only the plain answer is valid.
    if (worstSubarray == total) {
        return bestNonWrap;
    }

    return std::max(bestNonWrap, total - worstSubarray);
}

}  // namespace dynamic_programming

/**
 * @brief Exercises maxCircularSum against a couple of known-answer cases
 * @returns void
 */
static void runChecks() {
    // Case 1: wrapping around the end beats any non-wrapping run.
    // arr = {8, -8, 9, -9, 10, -11, 12} -> best is 12,8,-8,9,-9,10 = 22
    std::vector<int> caseOne = {8, -8, 9, -9, 10, -11, 12};
    assert(dynamic_programming::maxCircularSum(caseOne) == 22);

    // Case 2: a slight tweak to the values raises the best wrap-around sum.
    std::vector<int> caseTwo = {8, -8, 10, -9, 10, -11, 12};
    assert(dynamic_programming::maxCircularSum(caseTwo) == 23);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Program entry point
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief A simple [Memory Game](https://en.wikipedia.org/wiki/Matching_game)
 * with **3 different sizes** and multiple letters.
 * @details
 * The game consists on finding **the pair** of all the given letters depending
 * on the table size. Once all of the instances are all found, the game will end
 * and will ask you if you'd like to play again or not.
 *
 * It provides **3 different sizes** available that the user can choose (4x2,
 * 5x2, 7x2). 7x2 being the biggest table size and hardest mode. The bigger the
 * size, **the more letters are available**.
 *
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <algorithm>  /// for std::shuffle()
#include <cstdlib>    /// for std::srand()
#include <ctime>      /// for std::time()
#include <iostream>   /// for IO operations
#include <random>     /// for std::mt19937
#include <vector>     /// for std::vector

// `Sleep` is only available in Windows in milliseconds.
// However, on Unix/Linux systems it is `sleep`, in seconds.
#ifdef _WIN32
#include <Windows.h>  /// for Sleep()
template <typename T>
constexpr typename std::enable_if<std::is_integral<T>::value, void>::type SLEEP(
    T milliseconds) {
    Sleep(milliseconds * 1000);
}
#else
#include <unistd.h>  /// for sleep()
template <typename T>
constexpr T SLEEP(T seconds) {
    return sleep(seconds);
}
#endif

/**
 * @namespace
 * @brief (Mini)game implementations.
 */
namespace games {
/**
 * @namespace
 * @brief Functions for the [Memory
 * Game](https://en.wikipedia.org/wiki/Matching_game) implementation
 */
namespace memory_game {
/**
 * @brief Utility function to verify if the given input is a number or not.
 * This is very useful to prevent the program being stuck in a loop.
 * @tparam T The type of the input
 * @param input The input to check.
 * @returns false if the input IS empty or if it contains a non-digit character
 * @returns true if the input is NOT empty and if it contains only digit
 * characters
 */
template <typename T>
bool is_number(const T &input) {
    if (std::cin.fail()) {
        std::cin.clear();
        std::cin.ignore(256, '\n');

        return false;
    }

    return true;
}

/**
 * @brief Initializes the table with the letters.
 * @tparam T The type of the table.
 * @param table The table to initialize.
 * @returns void
 */
template <typename T>
void init(std::vector<T> *table) {
    std::vector<char> letters(7);

    // Decrease / increase the number of letters depending on the size.
    if ((*table).size() == 10) {  // 5x2
        letters = {'A', 'E', 'Z', 'P', 'D'};
    } else if ((*table).size() == 8) {  // 4x2
        letters = {'A', 'E', 'Z', 'D'};
    } else if ((*table).size() == 14) {  // 7x2
        letters = {'A', 'E', 'Z', 'P', 'D', 'B', 'M'};
    }

    std::vector<char> pairs;
    for (char letter : letters) {
        pairs.push_back(letter);
        pairs.push_back(letter);
    }

    std::shuffle(pairs.begin(), pairs.end(),
                 std::mt19937(std::random_device()()));

    for (int i = 0; i < (*table).size(); i++) {
        (*table)[i] = pairs[i];
    }

    std::cout << "All available types are: ";

    for (int i = 0; i < letters.size(); i++) {
        if (i == letters.size() - 1) {
            std::cout << "and " << letters[i] << ".\n\n";
        } else {
            std::cout << letters[i] << ", ";
        }
    }
}

/**
 * @brief Utility function to print the table.
 * @tparam T The type of the table.
 * @param table The table to print.
 * @returns void
 */
template <typename T>
void print_table(const std::vector<T> &table) {
    std::cout << "| ";
    std::vector<T> table_print(table.size());

    for (int i = 0; i < table.size(); i++) {
        table_print[i] = ' ';

        if (table[i] != 0) {
            table_print[i] = table[i];
        }
    }

    for (int i = 0; i < table.size(); i++) {
        if (i % 5 == 0 && i != 0) {
            std::cout << "\n| ";
        }

        std::cout << table_print[i] << " | ";
    }
}

// Prototype function. This is needed as `ask_data` calls `reset_data`, and
// `reset_data` calls `ask_data`.
template <typename T>
void reset_data(const std::vector<T> &, int *, int *, int *);

/**
 * @brief Function that asks the user for their
 * input in the table they previously chose.
 * @tparam T The type of the table.
 * @param table The table that's used to get the user's input and data.
 * @param answer The user's answer.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns void
 */
template <typename T>
void ask_data(const std::vector<T> &table, int *answer, int *old_answer,
              int *memory_count) {
    (*old_answer) = (*answer);
    print_table(table);

    std::cout << "\n\nType your response here (number index):\n";
    std::cin >> (*answer);

    if (!is_number((*answer))) {
        std::cout << "\nYou must enter a valid number.\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }

    // Increase the memory count, which will be later on used for checking if
    // the user has already answered two values.
    (*memory_count)++;

    if (((*answer) > table.size()) || ((*answer) < 1)) {
        std::cout << "\nYou can't check a value that doesn't exist (or an "
                     "invalid number).\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }

    if ((*old_answer) == (*answer)) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }

    // If two matches are answered already, but the user checkes a non-answered
    // and an answered value, the program will mark it as no match, however, we
    // must not allow the user to check the same value twice.
    if ((table[(*answer) - 1] != 0) &&
        ((table[(*old_answer)] == 0) || (table[(*old_answer)] != 0))) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }
}

/**
 * @brief Utility function that resets the data if the user enters an invalid
 * value.
 * @tparam T The type of the table.
 * @param table The table that will be used to call `ask_data()`.
 * @param answer The user's answer.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns void
 */
template <typename T>
void reset_data(const std::vector<T> &table, int *answer, int *old_answer,
                int *memory_count) {
    (*answer) = (*old_answer);
    (*memory_count)--;

    ask_data(table, answer, old_answer, memory_count);
}

/**
 * @brief Checks if the two values given by the user match.
 * @tparam T The type of the table.
 * @param table_empty The table with no values, slowly assigned from `table`
 * depending on the user's input.
 * @param table The table with the original values.
 * @param answer The user's answer.
 * @param first_time A boolean to check if the user has already answered a
 * value.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns true IF the values given by the user match
 * @returns false if the values given by the user do NOT match
 */
template <typename T>
bool match(const std::vector<T> &table, std::vector<T> *table_empty,
           const int &answer, bool *first_time, int *old_answer,
           int *memory_count) {
    if ((*first_time) == true) {
        return true;
    }

    // Search across the whole table and if the two values match, keep results,
    // otherwise, hide 'em up.
    for (int i = 0; i < table.size() + 1; i++) {
        if (i == answer) {
            if (table[i - 1] == table[(*old_answer) - 1]) {
                (*first_time) = true;
                (*memory_count) = 0;

                (*old_answer) = 0;
                return true;
            } else {
                std::cout << "\nNo match (value was " << table[i - 1]
                          << ", index is " << i << ").\n\n";

                (*table_empty)[(*old_answer) - 1] = 0;
                (*table_empty)[answer - 1] = 0;

                (*first_time) = true;
                (*memory_count) = 0;

                (*old_answer) = 0;
                return false;
            }
        }
    }

    return false;
}

/**
 * @brief Function to assign the results to the table.
 *
 * Also checkes if the user has answered all the values already, as well as
 * verify if the user made a match or not.
 * @tparam T The type of the tables.
 * @param table_empty The table with no values, slowly assigned from `table`
 * depending on the user's input.
 * @param table The table with the original values.
 * @param answer The user's answer.
 * @param first_time A boolean to check if the user has already answered a
 * value.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns void
 */
template <typename T>
void assign_results(std::vector<T> *table_empty, std::vector<T> *table,
                    int *answer, bool *first_time, int *old_answer,
                    int *memory_count) {
    // Search through the entire table and if the answer matches the index, show
    // the value. If it doesn't match, hide both the values. Don't forget to
    // keep older values already answered.
    for (int i = 0; i < (*table).size() + 1; i++) {
        if (i == (*answer)) {
            if (match((*table), table_empty, (*answer), first_time, old_answer,
                      memory_count) == true) {
                (*table_empty)[i - 1] = (*table)[i - 1];
                (*first_time) = true;
            }
        }
    }

    if ((*memory_count) == 1) {
        (*first_time) = false;
        (*memory_count) = 0;
    }

    char try_again = 'n';

    // Has the user finished the game? Use a `for` loop, and if the table is
    // full, ask the user if he wants to play again.
    for (int i = 0; i < (*table).size() + 1; i++) {
        if ((*table_empty)[i] == 0) {
            break;
        } else if (i == (*table).size() - 1) {
            print_table((*table));

            std::cout << "\n\nYou won. Congratulations! Do you want to play "
                         "again? (y/n)\n";
            std::cout
                << "Size " << (*table).size()
                << " will be used. This can be changed by re-running the game.";
            std::cin >> try_again;
            if (try_again == 'y') {
                // This is needed when checking if the user has two matches
                // already.
                for (int i = 0; i < (*table_empty).size(); i++) {
                    (*table_empty)[i] = 0;
                }

                init(table);
            } else if (try_again == 'n') {
                std::cout << "\nThanks for playing the game!\n";
                SLEEP(3);

                exit(0);
            } else {
                std::cout << "\nInvalid input (exitting...).\n";
                SLEEP(3);

                exit(0);
            }
        }
    }

    // Ask data again.
    ask_data((*table_empty), answer, old_answer, memory_count);
    assign_results(table_empty, table, answer, first_time, old_answer,
                   memory_count);
}
}  // namespace memory_game
}  // namespace games

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // Start randomizer. This changes the values every time.
    std::srand(std::time(nullptr));

    int size = 0;       ///< Size of the table.
    int selection = 0;  ///< Selection of the size (4x2, 5x2, 7x2).

    int response = 0;    ///< The answer (number index) that the user chose.
    int old_answer = 0;  ///< Previous answer (number index).

    int memory_count =
        0;  ///< Counter to check if the user has already answered two values.
    bool first_time = true;  ///< Whether the user has answered 1 value or not
                             ///< (previous answered values do not count).

    std::cout << "\tMEMORY GAME\n";

    do {
        std::cout << "\n1. 4x2 (1)";
        std::cout << "\n2. 5x2 (2)";
        std::cout << "\n3. 7x2 (3)\n";

        std::cout << "\nChoose table size: ";
        std::cin >> selection;
    } while ((selection < 1 || selection > 3) &&
             (!games::memory_game::is_number(selection)));

    switch (selection) {
        case 1:
            size = 8;
            break;
        case 2:
            size = 10;
            break;
        case 3:
            size = 14;
            break;
        default:
            size = 10;
            break;
    }

    std::vector<char> table(size);
    std::vector<char> table_empty(size);

    std::cout << "\n";

    games::memory_game::init(&table);
    games::memory_game::ask_data(table_empty, &response, &old_answer,
                                 &memory_count);
    games::memory_game::assign_results(&table_empty, &table, &response,
                                       &first_time, &old_answer, &memory_count);

    return 0;
}

/**
 * @file
 * @brief A console-based tile-matching memory puzzle offering three board
 * sizes and a rotating set of letter tiles.
 * @details
 * Two hidden copies of each letter are scattered across a grid. The player
 * repeatedly reveals two cells; matching letters stay uncovered, mismatches
 * flip back down. The round ends once every tile has been paired, after
 * which the player may start a fresh round or quit.
 *
 * Board options: 4x2 (8 cells), 5x2 (10 cells), 7x2 (14 cells). Larger
 * boards draw from a bigger alphabet pool.
 *
 * @author Rewritten variant for educational similarity-detection dataset.
 */

#include <algorithm>  /// for std::shuffle()
#include <cstdlib>    /// for std::srand(), exit()
#include <ctime>      /// for std::time()
#include <iostream>   /// for IO operations
#include <random>     /// for std::mt19937
#include <vector>     /// for std::vector

// Cross-platform pause helper: Windows measures Sleep() in milliseconds,
// POSIX systems measure sleep() in whole seconds.
#ifdef _WIN32
#include <Windows.h>
template <typename DurationT>
constexpr typename std::enable_if<std::is_integral<DurationT>::value,
                                   void>::type
pause_execution(DurationT seconds) {
    Sleep(seconds * 1000);
}
#else
#include <unistd.h>
template <typename DurationT>
constexpr DurationT pause_execution(DurationT seconds) {
    return sleep(seconds);
}
#endif

/**
 * @namespace arcade
 * @brief Collection of small terminal-based games.
 */
namespace arcade {
/**
 * @namespace tile_match
 * @brief Core logic for the letter-matching memory puzzle.
 */
namespace tile_match {

/**
 * @brief Confirms that the last extraction from std::cin actually produced
 * a usable numeric value, clearing the stream on failure.
 * @tparam ValueT type of the value being validated
 * @param value the just-read value (unused directly, kept for symmetry)
 * @returns false when the stream is in a failed state, true otherwise.
 */
template <typename ValueT>
bool looks_numeric(const ValueT &value) {
    if (std::cin.fail()) {
        std::cin.clear();
        std::cin.ignore(256, '\n');
        return false;
    }
    return true;
}

/**
 * @brief Populates the board with shuffled letter pairs matching its size.
 * @tparam CellT cell value type stored in the board
 * @param board pointer to the vector representing the game board
 */
template <typename CellT>
void seed_board(std::vector<CellT> *board) {
    std::vector<char> alphabet(7);

    switch (board->size()) {
        case 8:
            alphabet = {'A', 'E', 'Z', 'D'};
            break;
        case 10:
            alphabet = {'A', 'E', 'Z', 'P', 'D'};
            break;
        case 14:
            alphabet = {'A', 'E', 'Z', 'P', 'D', 'B', 'M'};
            break;
        default:
            break;
    }

    std::vector<char> tiles;
    for (char symbol : alphabet) {
        tiles.push_back(symbol);
        tiles.push_back(symbol);
    }

    std::mt19937 rng(std::random_device{}());
    std::shuffle(tiles.begin(), tiles.end(), rng);

    for (std::size_t idx = 0; idx < board->size(); ++idx) {
        (*board)[idx] = tiles[idx];
    }

    std::cout << "All available types are: ";
    for (std::size_t idx = 0; idx < alphabet.size(); ++idx) {
        std::cout << alphabet[idx];
        if (idx + 1 == alphabet.size()) {
            std::cout << " -- that's the full set.\n\n";
        } else {
            std::cout << ", ";
        }
    }
}

/**
 * @brief Renders the current state of the board, five cells per row.
 * @tparam CellT cell value type stored in the board
 * @param board board to render
 */
template <typename CellT>
void render_board(const std::vector<CellT> &board) {
    const int columns_per_row = 5;
    std::cout << "| ";

    std::vector<CellT> visible(board.size());
    for (std::size_t idx = 0; idx < board.size(); ++idx) {
        visible[idx] = (board[idx] != 0) ? board[idx] : ' ';
    }

    for (std::size_t idx = 0; idx < visible.size(); ++idx) {
        if (idx != 0 && idx % columns_per_row == 0) {
            std::cout << "\n| ";
        }
        std::cout << visible[idx] << " | ";
    }
}

// Forward declaration: prompt_choice() and retry_prompt() are mutually
// recursive.
template <typename CellT>
void retry_prompt(const std::vector<CellT> &, int *, int *, int *);

/**
 * @brief Prompts the player for a one-based index into the board and
 * validates the response, retrying on any malformed or repeated input.
 * @tparam CellT cell value type stored in the board
 * @param board board used to display state and validate bounds
 * @param choice output: the player's latest choice
 * @param previous_choice output: the player's prior choice
 * @param picks_made counter tracking how many picks were made this turn
 */
template <typename CellT>
void prompt_choice(const std::vector<CellT> &board, int *choice,
                    int *previous_choice, int *picks_made) {
    *previous_choice = *choice;
    render_board(board);

    std::cout << "\n\nType your response here (number index):\n";
    std::cin >> *choice;

    if (!looks_numeric(*choice)) {
        std::cout << "\nYou must enter a valid number.\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }

    ++(*picks_made);

    if (*choice > static_cast<int>(board.size()) || *choice < 1) {
        std::cout << "\nYou can't check a value that doesn't exist (or an "
                     "invalid number).\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }

    if (*previous_choice == *choice) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }

    if (board[*choice - 1] != 0 &&
        (board[*previous_choice] == 0 || board[*previous_choice] != 0)) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }
}

/**
 * @brief Rewinds the pick counter and re-issues the prompt after an
 * invalid entry.
 * @tparam CellT cell value type stored in the board
 * @param board board forwarded to prompt_choice()
 * @param choice output: the player's latest choice
 * @param previous_choice output: the player's prior choice
 * @param picks_made counter tracking how many picks were made this turn
 */
template <typename CellT>
void retry_prompt(const std::vector<CellT> &board, int *choice,
                   int *previous_choice, int *picks_made) {
    *choice = *previous_choice;
    --(*picks_made);
    prompt_choice(board, choice, previous_choice, picks_made);
}

/**
 * @brief Determines whether the two most recently picked tiles are equal.
 * @tparam CellT cell value type stored in the board
 * @param solved_board board holding the true (hidden) values
 * @param visible_board board tracking what's currently shown to the player
 * @param choice the newest pick
 * @param awaiting_first_pick whether this is the first pick of the turn
 * @param previous_choice the earlier pick this turn
 * @param picks_made counter of picks made so far this turn
 * @returns true when the two picks reveal identical letters (or when this
 * is only the first pick of the turn), false on a mismatch.
 */
template <typename CellT>
bool tiles_match(const std::vector<CellT> &solved_board,
                  std::vector<CellT> *visible_board, const int &choice,
                  bool *awaiting_first_pick, int *previous_choice,
                  int *picks_made) {
    if (*awaiting_first_pick) {
        return true;
    }

    for (std::size_t idx = 0; idx < solved_board.size() + 1; ++idx) {
        if (static_cast<int>(idx) != choice) {
            continue;
        }

        bool same = solved_board[idx - 1] == solved_board[*previous_choice - 1];
        *awaiting_first_pick = true;
        *picks_made = 0;
        *previous_choice = 0;

        if (same) {
            return true;
        }

        std::cout << "\nNo match (value was " << solved_board[idx - 1]
                   << ", index is " << idx << ").\n\n";
        (*visible_board)[*previous_choice - 1] = 0;
        (*visible_board)[choice - 1] = 0;
        return false;
    }

    return false;
}

/**
 * @brief Applies the outcome of the latest pick to the visible board,
 * checks for a completed round, and loops back for the next pick.
 * @tparam CellT cell value type stored in the board
 * @param visible_board board tracking what's currently shown to the player
 * @param solved_board board holding the true (hidden) values
 * @param choice the newest pick
 * @param awaiting_first_pick whether the next pick starts a fresh turn
 * @param previous_choice the earlier pick this turn
 * @param picks_made counter of picks made so far this turn
 */
template <typename CellT>
void apply_turn(std::vector<CellT> *visible_board,
                 std::vector<CellT> *solved_board, int *choice,
                 bool *awaiting_first_pick, int *previous_choice,
                 int *picks_made) {
    for (std::size_t idx = 0; idx < solved_board->size() + 1; ++idx) {
        if (static_cast<int>(idx) == *choice) {
            if (tiles_match(*solved_board, visible_board, *choice,
                            awaiting_first_pick, previous_choice, picks_made)) {
                (*visible_board)[idx - 1] = (*solved_board)[idx - 1];
                *awaiting_first_pick = true;
            }
        }
    }

    if (*picks_made == 1) {
        *awaiting_first_pick = false;
        *picks_made = 0;
    }

    bool round_complete = true;
    for (std::size_t idx = 0; idx < visible_board->size(); ++idx) {
        if ((*visible_board)[idx] == 0) {
            round_complete = false;
            break;
        }
    }

    if (round_complete) {
        render_board(*solved_board);
        std::cout << "\n\nYou won. Congratulations! Do you want to play "
                     "again? (y/n)\n";
        std::cout << "Size " << solved_board->size()
                   << " will be used. This can be changed by re-running the "
                      "game.";

        char play_again = 'n';
        std::cin >> play_again;

        if (play_again == 'y') {
            std::fill(visible_board->begin(), visible_board->end(), 0);
            seed_board(solved_board);
        } else if (play_again == 'n') {
            std::cout << "\nThanks for playing the game!\n";
            pause_execution(3);
            exit(0);
        } else {
            std::cout << "\nInvalid input (exitting...).\n";
            pause_execution(3);
            exit(0);
        }
    }

    prompt_choice(*visible_board, choice, previous_choice, picks_made);
    apply_turn(visible_board, solved_board, choice, awaiting_first_pick,
               previous_choice, picks_made);
}

}  // namespace tile_match
}  // namespace arcade

/**
 * @brief Entry point: gathers the board-size selection then hands off to
 * the game loop.
 * @returns 0 on exit
 */
int main() {
    std::srand(static_cast<unsigned int>(std::time(nullptr)));

    int board_cells = 0;
    int size_choice = 0;

    int player_pick = 0;
    int prior_pick = 0;

    int picks_this_turn = 0;
    bool awaiting_first_pick = true;

    std::cout << "\tMEMORY GAME\n";

    do {
        std::cout << "\n1. 4x2 (1)";
        std::cout << "\n2. 5x2 (2)";
        std::cout << "\n3. 7x2 (3)\n";
        std::cout << "\nChoose table size: ";
        std::cin >> size_choice;
    } while ((size_choice < 1 || size_choice > 3) &&
             !arcade::tile_match::looks_numeric(size_choice));

    switch (size_choice) {
        case 1:
            board_cells = 8;
            break;
        case 2:
            board_cells = 10;
            break;
        case 3:
            board_cells = 14;
            break;
        default:
            board_cells = 10;
            break;
    }

    std::vector<char> solved_board(board_cells);
    std::vector<char> visible_board(board_cells);

    std::cout << "\n";

    arcade::tile_match::seed_board(&solved_board);
    arcade::tile_match::prompt_choice(visible_board, &player_pick, &prior_pick,
                                       &picks_this_turn);
    arcade::tile_match::apply_turn(&visible_board, &solved_board, &player_pick,
                                    &awaiting_first_pick, &prior_pick,
                                    &picks_this_turn);

    return 0;
}

/* Implementation of Kosaraju's Algorithm to find out the strongly connected
   components (SCCs) in a graph. Author:Anirban166
*/

#include <iostream>
#include <stack>
#include <vector>

/**
 * Iterative function/method to print graph:
 * @param a adjacency list representation of the graph
 * @param V number of vertices
 * @return void
 **/
void print(const std::vector<std::vector<int> > &a, int V) {
    for (int i = 0; i < V; i++) {
        if (!a[i].empty()) {
            std::cout << "i=" << i << "-->";
        }
        for (int j : a[i]) {
            std::cout << j << " ";
        }
        if (!a[i].empty()) {
            std::cout << std::endl;
        }
    }
}

/**
 * //Recursive function/method to push vertices into stack passed as parameter:
 * @param v vertices
 * @param st stack passed by reference
 * @param vis array to keep track of visited nodes (boolean type)
 * @param adj adjacency list representation of the graph
 * @return void
 **/
void push_vertex(int v, std::stack<int> *st, std::vector<bool> *vis,
                 const std::vector<std::vector<int> > &adj) {
    (*vis)[v] = true;
    for (auto i = adj[v].begin(); i != adj[v].end(); i++) {
        if ((*vis)[*i] == false) {
            push_vertex(*i, st, vis, adj);
        }
    }
    st->push(v);
}

/**
 * //Recursive function/method to implement depth first traversal(dfs):
 * @param v vertices
 * @param vis array to keep track of visited nodes (boolean type)
 * @param grev graph with reversed edges
 * @return void
 **/
void dfs(int v, std::vector<bool> *vis,
         const std::vector<std::vector<int> > &grev) {
    (*vis)[v] = true;
    // cout<<v<<" ";
    for (auto i = grev[v].begin(); i != grev[v].end(); i++) {
        if ((*vis)[*i] == false) {
            dfs(*i, vis, grev);
        }
    }
}

// function/method to implement Kosaraju's Algorithm:
/**
* Info about the method
* @param V vertices in graph
* @param adj array of vectors that represent a graph (adjacency list/array)
* @return int ( 0, 1, 2..and so on, only unsigned values as either there can be
no SCCs i.e. none(0) or there will be x no. of SCCs (x>0)) i.e. it returns the
count of (number of) strongly connected components (SCCs) in the graph.
(variable 'count_scc' within function)
**/
int kosaraju(int V, const std::vector<std::vector<int> > &adj) {
    std::vector<bool> vis(V, false);
    std::stack<int> st;
    for (int v = 0; v < V; v++) {
        if (vis[v] == false) {
            push_vertex(v, &st, &vis, adj);
        }
    }
    // making new graph (grev) with reverse edges as in adj[]:
    std::vector<std::vector<int> > grev(V);
    for (int i = 0; i < V + 1; i++) {
        for (auto j = adj[i].begin(); j != adj[i].end(); j++) {
            grev[*j].push_back(i);
        }
    }
    // cout<<"grev="<<endl; ->debug statement
    // print(grev,V);       ->debug statement
    // reinitialise visited to 0
    for (int i = 0; i < V; i++) vis[i] = false;
    int count_scc = 0;
    while (!st.empty()) {
        int t = st.top();
        st.pop();
        if (vis[t] == false) {
            dfs(t, &vis, grev);
            count_scc++;
        }
    }
    // cout<<"count_scc="<<count_scc<<endl; //in case you want to print here
    // itself, uncomment & change return type of function to void.
    return count_scc;
}

// All critical/corner cases have been taken care of.
