int main() {
    int t = 0;
    std::cin >> t;
    while (t--) {
        int a = 0, b = 0;  // a->number of nodes, b->directed edges.
        std::cin >> a >> b;
        int m = 0, n = 0;
        std::vector<std::vector<int> > adj(a + 1);
        for (int i = 0; i < b; i++)  // take total b inputs of 2 vertices each
                                     // required to form an edge.
        {
            std::cin >> m >> n;  // take input m,n denoting edge from m->n.
            adj[m].push_back(n);
        }
        // pass number of nodes and adjacency array as parameters to function:
        std::cout << kosaraju(a, adj) << std::endl;
    }
    return 0;
}

/* Alternate implementation of Kosaraju's algorithm for counting strongly
   connected components (SCCs) in a directed graph. Rewritten variant for
   a classroom similarity-detection exercise. */

#include <iostream>
#include <stack>
#include <vector>

using AdjacencyList = std::vector<std::vector<int>>;

/**
 * Debug helper that dumps an adjacency list to stdout, one source vertex
 * per line, only for vertices that actually have outgoing edges.
 */
void dump_adjacency(const AdjacencyList &graph, int vertexCount) {
    for (int src = 0; src < vertexCount; ++src) {
        if (graph[src].empty()) {
            continue;
        }
        std::cout << "node " << src << " -> ";
        for (int dst : graph[src]) {
            std::cout << dst << " ";
        }
        std::cout << std::endl;
    }
}

/**
 * Post-order DFS: visits every reachable vertex from `at`, then pushes `at`
 * onto the finishing-order stack. Used in the first pass of Kosaraju's
 * algorithm to establish an ordering by finish time.
 */
void record_finish_order(int at, std::stack<int> *finishOrder,
                          std::vector<bool> *seen,
                          const AdjacencyList &graph) {
    (*seen)[at] = true;
    for (int next : graph[at]) {
        if (!(*seen)[next]) {
            record_finish_order(next, finishOrder, seen, graph);
        }
    }
    finishOrder->push(at);
}

/**
 * Plain DFS over the transposed graph, marking every vertex reachable from
 * `at` as visited. One call floods exactly one SCC.
 */
void flood_component(int at, std::vector<bool> *seen,
                      const AdjacencyList &transposed) {
    (*seen)[at] = true;
    for (int next : transposed[at]) {
        if (!(*seen)[next]) {
            flood_component(next, seen, transposed);
        }
    }
}

/**
 * Runs Kosaraju's algorithm and returns how many strongly connected
 * components the graph decomposes into.
 * @param vertexCount total number of vertices, indexed 0..vertexCount-1 (with
 * an extra slot up to vertexCount used by the caller's input format)
 * @param graph adjacency list of the original directed graph
 */
int count_strongly_connected_components(int vertexCount,
                                         const AdjacencyList &graph) {
    std::vector<bool> seen(vertexCount, false);
    std::stack<int> finishOrder;

    for (int v = 0; v < vertexCount; ++v) {
        if (!seen[v]) {
            record_finish_order(v, &finishOrder, &seen, graph);
        }
    }

    // Build the transposed graph (reverse every directed edge).
    AdjacencyList transposed(vertexCount);
    for (int src = 0; src < vertexCount + 1; ++src) {
        for (int dst : graph[src]) {
            transposed[dst].push_back(src);
        }
    }

    std::fill(seen.begin(), seen.end(), false);

    int sccCount = 0;
    while (!finishOrder.empty()) {
        int candidate = finishOrder.top();
        finishOrder.pop();
        if (!seen[candidate]) {
            flood_component(candidate, &seen, transposed);
            ++sccCount;
        }
    }
    return sccCount;
}

int main() {
    int testCases = 0;
    std::cin >> testCases;

    while (testCases--) {
        int vertexCount = 0;
        int edgeCount = 0;
        std::cin >> vertexCount >> edgeCount;

        AdjacencyList graph(vertexCount + 1);
        for (int i = 0; i < edgeCount; ++i) {
            int from = 0;
            int to = 0;
            std::cin >> from >> to;
            graph[from].push_back(to);
        }

        std::cout << count_strongly_connected_components(vertexCount, graph)
                  << std::endl;
    }
    return 0;
}

#include <algorithm>
#include <array>
#include <iostream>
#include <vector>
//#include <boost/multiprecision/cpp_int.hpp>
// using namespace boost::multiprecision;
const int mx = 1e6 + 5;
using ll = int64_t;

std::array<ll, mx> parent;
ll node, edge;
std::vector<std::pair<ll, std::pair<ll, ll>>> edges;
void initial() {
    for (int i = 0; i < node + edge; ++i) {
        parent[i] = i;
    }
}

int root(int i) {
    while (parent[i] != i) {
        parent[i] = parent[parent[i]];
        i = parent[i];
    }
    return i;
}

void join(int x, int y) {
    int root_x = root(x);  // Disjoint set union by rank
    int root_y = root(y);
    parent[root_x] = root_y;
}

ll kruskal() {
    ll mincost = 0;
    for (int i = 0; i < edge; ++i) {
        ll x = edges[i].second.first;
        ll y = edges[i].second.second;
        if (root(x) != root(y)) {
            mincost += edges[i].first;
            join(x, y);
        }
    }
    return mincost;
}

int main() {
    while (true) {
        int from = 0, to = 0, cost = 0, totalcost = 0;
        std::cin >> node >> edge;  // Enter the nodes and edges
        if (node == 0 && edge == 0) {
            break;  // Enter 0 0 to break out
        }
        initial();  // Initialise the parent array
        for (int i = 0; i < edge; ++i) {
            std::cin >> from >> to >> cost;
            edges.emplace_back(make_pair(cost, std::make_pair(from, to)));
            totalcost += cost;
        }
        sort(edges.begin(), edges.end());
        std::cout << kruskal() << std::endl;
        edges.clear();
    }
    return 0;
}

#include <algorithm>
#include <array>
#include <iostream>
#include <vector>
// Alternate rewrite of Kruskal's minimum spanning tree cost computation
// using a disjoint-set (union-find) forest with path compression.

const int kMaxNodes = 1e6 + 5;
using Long = int64_t;

std::array<Long, kMaxNodes> uf;
Long numVertices, numEdges;
std::vector<std::pair<Long, std::pair<Long, Long>>> edgeList;

void resetForest() {
    for (int i = 0; i < numVertices + numEdges; ++i) {
        uf[i] = i;
    }
}

int findSet(int v) {
    while (uf[v] != v) {
        uf[v] = uf[uf[v]];
        v = uf[v];
    }
    return v;
}

void unionSets(int a, int b) {
    int setA = findSet(a);  // union by attaching one root under another
    int setB = findSet(b);
    uf[setA] = setB;
}

Long computeMstCost() {
    Long total = 0;
    for (int i = 0; i < numEdges; ++i) {
        Long u = edgeList[i].second.first;
        Long v = edgeList[i].second.second;
        if (findSet(u) != findSet(v)) {
            total += edgeList[i].first;
            unionSets(u, v);
        }
    }
    return total;
}

int main() {
    while (true) {
        int u = 0, v = 0, weight = 0, sumWeights = 0;
        std::cin >> numVertices >> numEdges;  // read vertex/edge counts
        if (numVertices == 0 && numEdges == 0) {
            break;  // sentinel "0 0" terminates input
        }
        resetForest();
        for (int i = 0; i < numEdges; ++i) {
            std::cin >> u >> v >> weight;
            edgeList.emplace_back(std::make_pair(weight, std::make_pair(u, v)));
            sumWeights += weight;
        }
        std::sort(edgeList.begin(), edgeList.end());
        std::cout << computeMstCost() << std::endl;
        edgeList.clear();
    }
    return 0;
}

/**
 *
 * \file
 *
 * \brief Data structure for finding the lowest common ancestor
 * of two vertices in a rooted tree using binary lifting.
 *
 * \details
 * Algorithm: https://cp-algorithms.com/graph/lca_binary_lifting.html
 *
 * Complexity:
 *   - Precomputation: \f$O(N \log N)\f$ where \f$N\f$ is the number of vertices
 * in the tree
 *   - Query: \f$O(\log N)\f$
 *   - Space: \f$O(N \log N)\f$
 *
 * Example:
 * <br/>  Tree:
 * <pre>
 *             _  3  _
 *          /     |     \
 *        1       6       4
 *      / |     /   \       \
 *    7   5   2       8       0
 *            |
 *            9
 * </pre>
 *
 * <br/>  lowest_common_ancestor(7, 4) = 3
 * <br/>  lowest_common_ancestor(9, 6) = 6
 * <br/>  lowest_common_ancestor(0, 0) = 0
 * <br/>  lowest_common_ancestor(8, 2) = 6
 *
 *   The query is symmetrical, therefore
 *     lowest_common_ancestor(x, y) = lowest_common_ancestor(y, x)
 */

#include <cassert>
#include <iostream>
#include <queue>
#include <utility>
#include <vector>

/**
 * \namespace graph
 * \brief Graph algorithms
 */
namespace graph {
/**
 * Class for representing a graph as an adjacency list.
 * Its vertices are indexed 0, 1, ..., N - 1.
 */
class Graph {
 public:
    /**
     * \brief Populate the adjacency list for each vertex in the graph.
     * Assumes that evey edge is a pair of valid vertex indices.
     *
     * @param N number of vertices in the graph
     * @param undirected_edges list of graph's undirected edges
     */
    Graph(size_t N, const std::vector<std::pair<int, int> > &undirected_edges) {
        neighbors.resize(N);
        for (auto &edge : undirected_edges) {
            neighbors[edge.first].push_back(edge.second);
            neighbors[edge.second].push_back(edge.first);
        }
    }

    /**
     * Function to get the number of vertices in the graph
     * @return the number of vertices in the graph.
     */
    int number_of_vertices() const { return neighbors.size(); }

    /** \brief for each vertex it stores a list indicies of its neighbors */
    std::vector<std::vector<int> > neighbors;
};

/**
 * Representation of a rooted tree. For every vertex its parent is
 * precalculated.
 */
class RootedTree : public Graph {
 public:
    /**
     * \brief Constructs the tree by calculating parent for every vertex.
     * Assumes a valid description of a tree is provided.
     *
     * @param undirected_edges list of graph's undirected edges
     * @param root_ index of the root vertex
     */
    RootedTree(const std::vector<std::pair<int, int> > &undirected_edges,
               int root_)
        : Graph(undirected_edges.size() + 1, undirected_edges), root(root_) {
        populate_parents();
    }

    /**
     * \brief Stores parent of every vertex and for root its own index.
     * The root is technically not its own parent, but it's very practical
     * for the lowest common ancestor algorithm.
     */
    std::vector<int> parent;
    /** \brief Stores the distance from the root. */
    std::vector<int> level;
    /** \brief Index of the root vertex. */
    int root;

 protected:
    /**
     * \brief Calculate the parents for all the vertices in the tree.
     * Implements the breadth first search algorithm starting from the root
     * vertex searching the entire tree and labeling parents for all vertices.
     * @returns none
     */
    void populate_parents() {
        // Initialize the vector with -1 which indicates the vertex
        // wasn't yet visited.
        parent = std::vector<int>(number_of_vertices(), -1);
        level = std::vector<int>(number_of_vertices());
        parent[root] = root;
        level[root] = 0;
        std::queue<int> queue_of_vertices;
        queue_of_vertices.push(root);
        while (!queue_of_vertices.empty()) {
            int vertex = queue_of_vertices.front();
            queue_of_vertices.pop();
            for (int neighbor : neighbors[vertex]) {
                // As long as the vertex was not yet visited.
                if (parent[neighbor] == -1) {
                    parent[neighbor] = vertex;
                    level[neighbor] = level[vertex] + 1;
                    queue_of_vertices.push(neighbor);
                }
            }
        }
    }
};

/**
 * A structure that holds a rooted tree and allow for effecient
 * queries of the lowest common ancestor of two given vertices in the tree.
 */
class LowestCommonAncestor {
 public:
    /**
     * \brief Stores the tree and precomputs "up lifts".
     * @param tree_ rooted tree.
     */
    explicit LowestCommonAncestor(const RootedTree &tree_) : tree(tree_) {
        populate_up();
    }

    /**
     * \brief Query the structure to find the lowest common ancestor.
     * Assumes that the provided numbers are valid indices of vertices.
     * Iterativelly modifies ("lifts") u an v until it finnds their lowest
     * common ancestor.
     * @param u index of one of the queried vertex
     * @param v index of the other queried vertex
     * @return index of the vertex which is the lowet common ancestor of u and v
     */
    int lowest_common_ancestor(int u, int v) const {
        // Ensure u is the deeper (higher level) of the two vertices
        if (tree.level[v] > tree.level[u]) {
            std::swap(u, v);
        }

        // "Lift" u to the same level as v.
        int level_diff = tree.level[u] - tree.level[v];
        for (int i = 0; (1 << i) <= level_diff; ++i) {
            if (level_diff & (1 << i)) {
                u = up[u][i];
            }
        }
        assert(tree.level[u] == tree.level[v]);

        if (u == v) {
            return u;
        }

        // "Lift" u and v to their 2^i th ancestor if they are different
        for (int i = static_cast<int>(up[u].size()) - 1; i >= 0; --i) {
            if (up[u][i] != up[v][i]) {
                u = up[u][i];
                v = up[v][i];
            }
        }

        // As we regressed u an v such that they cannot further be lifted so
        // that their ancestor would be different, the only logical
        // consequence is that their parent is the sought answer.
        assert(up[u][0] == up[v][0]);
        return up[u][0];
    }

    /* \brief reference to the rooted tree this structure allows to query */
    const RootedTree &tree;
    /**
     * \brief for every vertex stores a list of its ancestors by powers of two
     * For each vertex, the first element of the corresponding list contains
     * the index of its parent. The i-th element of the list is an index of
     * the (2^i)-th ancestor of the vertex.
     */
    std::vector<std::vector<int> > up;

 protected:
    /**
     * Populate the "up" structure. See above.
     */
    void populate_up() {
        up.resize(tree.number_of_vertices());
        for (int vertex = 0; vertex < tree.number_of_vertices(); ++vertex) {
            up[vertex].push_back(tree.parent[vertex]);
        }
        for (int level = 0; (1 << level) < tree.number_of_vertices(); ++level) {
            for (int vertex = 0; vertex < tree.number_of_vertices(); ++vertex) {
                // up[vertex][level + 1] = 2^(level + 1) th ancestor of vertex =
                // = 2^level th ancestor of 2^level th ancestor of vertex =
                // = 2^level th ancestor of up[vertex][level]
                up[vertex].push_back(up[up[vertex][level]][level]);
            }
        }
    }
};

}  // namespace graph

/**
 * Unit tests
 * @returns none
 */
static void tests() {
    /**
     *             _  3  _
     *          /     |     \
     *        1       6       4
     *      / |     /   \       \
     *    7   5   2       8       0
     *            |
     *            9
     */
    std::vector<std::pair<int, int> > edges = {
        {7, 1}, {1, 5}, {1, 3}, {3, 6}, {6, 2}, {2, 9}, {6, 8}, {4, 3}, {0, 4}};
    graph::RootedTree t(edges, 3);
    graph::LowestCommonAncestor lca(t);
    assert(lca.lowest_common_ancestor(7, 4) == 3);
    assert(lca.lowest_common_ancestor(9, 6) == 6);
    assert(lca.lowest_common_ancestor(0, 0) == 0);
    assert(lca.lowest_common_ancestor(8, 2) == 6);
}

/** Main function */
int main() {
    tests();
    return 0;
}

/**
 *
 * \file
 *
 * \brief Alternative implementation of lowest-common-ancestor queries on a
 * rooted tree using the binary lifting (sparse ancestor table) technique.
 *
 * \details
 * Reference: https://cp-algorithms.com/graph/lca_binary_lifting.html
 *
 * Complexity:
 *   - Build: O(N log N) for N vertices
 *   - Query: O(log N)
 *   - Space: O(N log N)
 *
 * Sample tree:
 * <pre>
 *             _  3  _
 *          /     |     \
 *        1       6       4
 *      / |     /   \       \
 *    7   5   2       8       0
 *            |
 *            9
 * </pre>
 *
 * lca(7, 4) = 3, lca(9, 6) = 6, lca(0, 0) = 0, lca(8, 2) = 6.
 * The relation is symmetric: lca(x, y) == lca(y, x).
 */

#include <cassert>
#include <iostream>
#include <queue>
#include <utility>
#include <vector>

/**
 * \namespace graph
 * \brief Graph-related algorithms.
 */
namespace graph {

/**
 * Adjacency-list representation of an undirected graph with vertices
 * indexed 0..N-1.
 */
class AdjacencyGraph {
 public:
    /**
     * Builds neighbor lists from a collection of undirected edges.
     * @param vertexCount total vertex count
     * @param edgeList undirected edges as (u, v) pairs
     */
    AdjacencyGraph(size_t vertexCount, const std::vector<std::pair<int, int> > &edgeList) {
        adj.resize(vertexCount);
        for (auto &e : edgeList) {
            adj[e.first].push_back(e.second);
            adj[e.second].push_back(e.first);
        }
    }

    /** @return total number of vertices in the graph. */
    int vertexCount() const { return adj.size(); }

    /** neighbor list per vertex */
    std::vector<std::vector<int> > adj;
};

/**
 * A tree rooted at a chosen vertex, with parent/depth arrays precomputed
 * via BFS.
 */
class RootedTree : public AdjacencyGraph {
 public:
    /**
     * Builds the tree and computes parent/depth for every vertex.
     * @param edgeList undirected tree edges
     * @param rootVertex the vertex to root the tree at
     */
    RootedTree(const std::vector<std::pair<int, int> > &edgeList, int rootVertex)
        : AdjacencyGraph(edgeList.size() + 1, edgeList), rootVertex(rootVertex) {
        buildParents();
    }

    /** parent of each vertex; root is its own parent by convention */
    std::vector<int> parentOf;
    /** depth (distance from root) of each vertex */
    std::vector<int> depthOf;
    /** index of the tree root */
    int rootVertex;

 protected:
    /**
     * BFS from the root, recording parent and depth for every reachable
     * vertex.
     */
    void buildParents() {
        parentOf = std::vector<int>(vertexCount(), -1);
        depthOf = std::vector<int>(vertexCount());
        parentOf[rootVertex] = rootVertex;
        depthOf[rootVertex] = 0;

        std::queue<int> frontier;
        frontier.push(rootVertex);
        while (!frontier.empty()) {
            int cur = frontier.front();
            frontier.pop();
            for (int nxt : adj[cur]) {
                if (parentOf[nxt] == -1) {
                    parentOf[nxt] = cur;
                    depthOf[nxt] = depthOf[cur] + 1;
                    frontier.push(nxt);
                }
            }
        }
    }
};

/**
 * Answers lowest-common-ancestor queries on a rooted tree in O(log N) time
 * after an O(N log N) preprocessing step (binary lifting table).
 */
class AncestorFinder {
 public:
    /**
     * @param sourceTree the rooted tree to query against.
     */
    explicit AncestorFinder(const RootedTree &sourceTree) : sourceTree(sourceTree) {
        buildLiftTable();
    }

    /**
     * Finds the lowest common ancestor of vertices a and b by first
     * equalizing their depths, then binary-lifting both together until
     * they meet.
     * @param a first vertex
     * @param b second vertex
     * @return the lowest common ancestor of a and b
     */
    int query(int a, int b) const {
        if (sourceTree.depthOf[b] > sourceTree.depthOf[a]) {
            std::swap(a, b);
        }

        int gap = sourceTree.depthOf[a] - sourceTree.depthOf[b];
        for (int bit = 0; (1 << bit) <= gap; ++bit) {
            if (gap & (1 << bit)) {
                a = liftTable[a][bit];
            }
        }
        assert(sourceTree.depthOf[a] == sourceTree.depthOf[b]);

        if (a == b) {
            return a;
        }

        for (int bit = static_cast<int>(liftTable[a].size()) - 1; bit >= 0; --bit) {
            if (liftTable[a][bit] != liftTable[b][bit]) {
                a = liftTable[a][bit];
                b = liftTable[b][bit];
            }
        }

        assert(liftTable[a][0] == liftTable[b][0]);
        return liftTable[a][0];
    }

    const RootedTree &sourceTree;
    /**
     * liftTable[v][k] holds the (2^k)-th ancestor of vertex v.
     */
    std::vector<std::vector<int> > liftTable;

 protected:
    /** Fills liftTable using doubling over the direct-parent column. */
    void buildLiftTable() {
        liftTable.resize(sourceTree.vertexCount());
        for (int v = 0; v < sourceTree.vertexCount(); ++v) {
            liftTable[v].push_back(sourceTree.parentOf[v]);
        }
        for (int k = 0; (1 << k) < sourceTree.vertexCount(); ++k) {
            for (int v = 0; v < sourceTree.vertexCount(); ++v) {
                // 2^(k+1)-th ancestor = 2^k-th ancestor of the 2^k-th ancestor
                liftTable[v].push_back(liftTable[liftTable[v][k]][k]);
            }
        }
    }
};

}  // namespace graph

/**
 * Sanity checks against the sample tree from the header comment.
 */
static void runChecks() {
    std::vector<std::pair<int, int> > edges = {
        {7, 1}, {1, 5}, {1, 3}, {3, 6}, {6, 2}, {2, 9}, {6, 8}, {4, 3}, {0, 4}};
    graph::RootedTree tree(edges, 3);
    graph::AncestorFinder finder(tree);
    assert(finder.query(7, 4) == 3);
    assert(finder.query(9, 6) == 6);
    assert(finder.query(0, 0) == 0);
    assert(finder.query(8, 2) == 6);
}

int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Implementation of
 * [Spirograph](https://en.wikipedia.org/wiki/Spirograph)
 *
 * @details
 * Implementation of the program is based on the geometry shown in the figure
 * below:
 *
 * <a
 * href="https://commons.wikimedia.org/wiki/File:Resonance_Cascade.svg"><img
 * src="https://upload.wikimedia.org/wikipedia/commons/3/39/Resonance_Cascade.svg"
 * alt="Spirograph geometry from Wikipedia" style="width: 250px"/></a>
 */
#ifdef USE_GLUT
#ifdef __APPLE__
#include <GLUT/glut.h>  // include path on Macs is different
#else
#include <GL/glut.h>
#endif  // __APPLE__
#endif
#define _USE_MATH_DEFINES /**< required for MSVC compiler */
#include <array>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#ifdef _OPENMP
#include <omp.h>
#endif

/**
 * @namespace spirograph Functions related to spirograph.cpp
 */
namespace spirograph {
/** Generate spirograph curve into arrays `x` and `y` such that the i^th point
 * in 2D is represented by `(x[i],y[i])`. The generating function is given by:
 * \f{eqnarray*}{
 * x &=& R\left[ (1-k) \cos (t) + l\cdot k\cdot\cos \left(\frac{1-k}{k}t\right)
 * \right]\\
 * y &=& R\left[ (1-k) \sin (t) - l\cdot k\cdot\sin \left(\frac{1-k}{k}t\right)
 * \right] \f}
 * where
 * * \f$R\f$ is the scaling parameter that we will consider \f$=1\f$
 * * \f$l=\frac{\rho}{r}\f$ is the relative distance of marker from the centre
 * of inner circle and \f$0\le l\le1\f$
 * * \f$\rho\f$ is physical distance of marker from centre of inner circle
 * * \f$r\f$ is the radius of inner circle
 * * \f$k=\frac{r}{R}\f$ is the ratio of radius of inner circle to outer circle
 * and \f$0<k<1\f$
 * * \f$R\f$ is the radius of outer circle
 * * \f$t\f$ is the angle of rotation of the point i.e., represents the time
 * parameter
 *
 * Since we are considering ratios, the actual values of \f$r\f$ and
 * \f$R\f$ are immaterial.
 *
 * @tparam N number of points = size of array
 * @param [out] points Array of 2D points represented as std::pair
 * @param l the relative distance of marker from the centre of
 * inner circle and \f$0\le l\le1\f$
 * @param k the ratio of radius of inner circle to outer circle and \f$0<k<1\f$
 * @param rot the number of rotations to perform (can be fractional value)
 */
template <std::size_t N>
void spirograph(std::array<std::pair<double, double>, N> *points, double l,
                double k, double rot) {
    double dt = rot * 2.f * M_PI / N;
    double R = 1.f;
    const double k1 = 1.f - k;
    int32_t step = 0;

#ifdef _OPENMP
#pragma omp for
#endif
    for (step = 0; step < N; step++) {
        double t = dt * step;
        double first = R * (k1 * std::cos(t) + l * k * std::cos(k1 * t / k));
        double second = R * (k1 * std::sin(t) - l * k * std::sin(k1 * t / k));
        points[0][step].first = first;
        points[0][step].second = second;
    }
}

/**
 * @brief Test function to save resulting points to a CSV file.
 *
 */
void test() {
    const size_t N = 500;
    double l = 0.3, k = 0.75, rot = 10.;
    std::stringstream fname;
    fname << std::setw(3) << "spirograph_" << l << "_" << k << "_" << rot
          << ".csv";
    std::ofstream fp(fname.str());
    if (!fp.is_open()) {
        perror(fname.str().c_str());
        exit(EXIT_FAILURE);
    }

    std::array<std::pair<double, double>, N> points;

    spirograph(&points, l, k, rot);

    for (size_t i = 0; i < N; i++) {
        fp << points[i].first << "," << points[i].first;
        if (i < N - 1) {
            fp << '\n';
        }
    }

    fp.close();
}

#ifdef USE_GLUT
static bool paused = 0; /**< flag to set pause/unpause animation */
static const int animation_speed = 25; /**< animation delate in ms */

static const double step = 0.01;   /**< animation step size */
static double l_ratio = step * 10; /**< the l-ratio defined in docs */
static double k_ratio = step;      /**< the k-ratio defined in docs */
static const double num_rot = 20.; /**< number of rotations to simulate */

/** A wrapper that is not available in all GLUT implementations.
 */
static inline void glutBitmapString(void *font, char *message) {
    for (char *ch = message; *ch != '\0'; ch++) glutBitmapCharacter(font, *ch);
}

/**
 * @brief Function to graph (x,y) points on the OpenGL graphics window.
 *
 * @tparam N number of points = size of array
 * @param [in] points Array of 2D points represented as std::pair
 * @param l the relative distance of marker from the centre of
 * inner circle and \f$0\le l\le1\f$ to display info
 * @param k the ratio of radius of inner circle to outer circle and \f$0<k<1\f$
 * to display info
 */
template <size_t N>
void display_graph(const std::array<std::pair<double, double>, N> &points,
                   double l, double k) {
    glClearColor(1.0f, 1.0f, 1.0f,
                 0.0f);            // Set background color to white and opaque
    glClear(GL_COLOR_BUFFER_BIT);  // Clear the color buffer (background)

    glBegin(GL_LINES);         // draw line segments
    glColor3f(0.f, 0.f, 1.f);  // blue
    glPointSize(2.f);          // point size in pixels

    for (size_t i = 1; i < N; i++) {
        glVertex2f(points[i - 1].first, points[i - 1].second);  // line from
        glVertex2f(points[i].first, points[i].second);          // line to
    }
    glEnd();

    glColor3f(0.f, 0.f, 0.f);
    std::stringstream buffer;
    buffer << std::setw(3) << "l = " << l;
    glRasterPos2f(-.85, .85);
    glutBitmapString(GLUT_BITMAP_TIMES_ROMAN_24,
                     const_cast<char *>(buffer.str().c_str()));
    buffer.str("");
    buffer.clear();
    buffer << std::setw(3) << "k = " << k;
    glRasterPos2f(-.85, .70);
    glutBitmapString(GLUT_BITMAP_TIMES_ROMAN_24,
                     const_cast<char *>(buffer.str().c_str()));

    glutSwapBuffers();
}

/**
 * @brief Test function with animation
 *
 */
void test2() {
    const size_t N = 5000;  // number of samples

    static bool direction1 = true;  // increment if true, otherwise decrement
    static bool direction2 = true;  // increment if true, otherwise decrement

    std::array<std::pair<double, double>, N> points;

    spirograph(&points, l_ratio, k_ratio, num_rot);
    display_graph(points, l_ratio, k_ratio);

    if (paused)
        // if paused, do not update l_ratio and k_ratio
        return;

    if (direction1) {                 // increment k_ratio
        if (k_ratio >= (1.f - step))  // maximum limit
            direction1 = false;       // reverse direction of k_ratio
        else
            k_ratio += step;
    } else {                    // decrement k_ratio
        if (k_ratio <= step) {  // minimum limit
            direction1 = true;  // reverse direction of k_ratio

            if (direction2) {                 // increment l_ratio
                if (l_ratio >= (1.f - step))  // max limit of l_ratio
                    direction2 = false;       // reverse direction of l_ratio
                else
                    l_ratio += step;
            } else {                    // decrement l_ratio
                if (l_ratio <= step)    // minimum limit of l_ratio
                    direction2 = true;  // reverse direction of l_ratio
                else
                    l_ratio -= step;
            }
        } else {  // no min limit of k_ratio
            k_ratio -= step;
        }
    }
}

/**
 * @brief GLUT timer callback function to add animation delay.
 */
void timer_cb(int t) {
    glutTimerFunc(animation_speed, timer_cb, 0);
    glutPostRedisplay();
}

/**
 * @brief Keypress event call back function.
 *
 * @param key ID of the key pressed
 * @param x mouse pointer position at event
 * @param y mouse pointer position at event
 */
void keyboard_cb(unsigned char key, int x, int y) {
    switch (key) {
        case ' ':              // spacebar toggles pause
            paused = !paused;  // toggle
            break;
        case GLUT_KEY_UP:
        case '+':  // up arrow key
            k_ratio += step;
            break;
        case GLUT_KEY_DOWN:
        case '_':  // down arrow key
            k_ratio -= step;
            break;
        case GLUT_KEY_RIGHT:
        case '=':  // left arrow key
            l_ratio += step;
            break;
        case GLUT_KEY_LEFT:
        case '-':  // right arrow key
            l_ratio -= step;
            break;
        case 0x1B:  // escape key exits
            exit(EXIT_SUCCESS);
        default:
            return;
    }
}
#endif
}  // namespace spirograph

/** Main function */
int main(int argc, char **argv) {
    spirograph::test();

#ifdef USE_GLUT
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_RGB | GLUT_DOUBLE);
    glutCreateWindow("Spirograph");
    glutInitWindowSize(400, 400);
    // glutIdleFunc(glutPostRedisplay);
    glutTimerFunc(spirograph::animation_speed, spirograph::timer_cb, 0);
    glutKeyboardFunc(spirograph::keyboard_cb);
    glutDisplayFunc(spirograph::test2);
    glutMainLoop();
#endif

    return 0;
}

/**
 * @file
 * @brief Draws a hypotrochoid-style [Spirograph]
 * (https://en.wikipedia.org/wiki/Spirograph) curve
 *
 * @details
 * A spirograph curve traces the path of a marker fixed to a small circle
 * rolling inside a larger, stationary one. Given the marker offset ratio,
 * the circle-radius ratio, and how many full rotations to simulate, this
 * file samples the parametric curve into a fixed-size point buffer and can
 * optionally render/animate it live with GLUT if compiled with USE_GLUT.
 */
#ifdef USE_GLUT
#ifdef __APPLE__
#include <GLUT/glut.h>
#else
#include <GL/glut.h>
#endif
#endif
#define _USE_MATH_DEFINES
#include <array>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#ifdef _OPENMP
#include <omp.h>
#endif

/**
 * @namespace hypotrochoid
 * @brief Curve-sampling and (optional) rendering routines for spirographs
 */
namespace hypotrochoid {

/**
 * Samples N points of the hypotrochoid described by:
 *   x(t) = (1-k)*cos(t) + l*k*cos((1-k)/k * t)
 *   y(t) = (1-k)*sin(t) - l*k*sin((1-k)/k * t)
 * with the outer radius normalized to 1.
 *
 * @tparam N number of samples to generate
 * @param buffer output array of (x, y) samples
 * @param marker_ratio l, the marker's relative distance from the inner
 * circle's centre, in [0, 1]
 * @param radius_ratio k, ratio of inner to outer circle radius, in (0, 1)
 * @param revolutions how many times to go around (may be fractional)
 */
template <std::size_t N>
void sample_curve(std::array<std::pair<double, double>, N> *buffer,
                  double marker_ratio, double radius_ratio,
                  double revolutions) {
    const double outer_radius = 1.0;
    const double complement = 1.0 - radius_ratio;
    const double angle_step = revolutions * 2.0 * M_PI / static_cast<double>(N);

    int32_t idx = 0;
#ifdef _OPENMP
#pragma omp for
#endif
    for (idx = 0; idx < static_cast<int32_t>(N); ++idx) {
        double t = angle_step * idx;
        double inner_angle = complement * t / radius_ratio;

        double x = outer_radius * (complement * std::cos(t) +
                                   marker_ratio * radius_ratio * std::cos(inner_angle));
        double y = outer_radius * (complement * std::sin(t) -
                                   marker_ratio * radius_ratio * std::sin(inner_angle));

        (*buffer)[idx] = std::make_pair(x, y);
    }
}

/**
 * @brief Generates one curve and dumps the sampled points to a CSV file.
 */
void export_curve_to_csv() {
    constexpr std::size_t sample_count = 500;
    const double marker_ratio = 0.3, radius_ratio = 0.75, revolutions = 10.0;

    std::stringstream file_name;
    file_name << std::setw(3) << "spirograph_" << marker_ratio << "_"
             << radius_ratio << "_" << revolutions << ".csv";

    std::ofstream output(file_name.str());
    if (!output.is_open()) {
        perror(file_name.str().c_str());
        exit(EXIT_FAILURE);
    }

    std::array<std::pair<double, double>, sample_count> curve;
    sample_curve(&curve, marker_ratio, radius_ratio, revolutions);

    for (std::size_t i = 0; i < sample_count; ++i) {
        output << curve[i].first << "," << curve[i].first;
        if (i + 1 < sample_count) {
            output << '\n';
        }
    }

    output.close();
}

#ifdef USE_GLUT
static bool animation_paused = false;
static const int frame_delay_ms = 25;

static const double increment = 0.01;
static double marker_ratio_live = increment * 10;
static double radius_ratio_live = increment;
static const double revolutions_live = 20.0;

static inline void draw_bitmap_text(void *font, char *text) {
    for (char *c = text; *c != '\0'; ++c) {
        glutBitmapCharacter(font, *c);
    }
}

/**
 * @brief Draws the sampled curve as connected line segments and overlays
 * the current l/k parameters as text.
 */
template <std::size_t N>
void render_curve(const std::array<std::pair<double, double>, N> &curve,
                  double marker_ratio, double radius_ratio) {
    glClearColor(1.0f, 1.0f, 1.0f, 0.0f);
    glClear(GL_COLOR_BUFFER_BIT);

    glBegin(GL_LINES);
    glColor3f(0.f, 0.f, 1.f);
    glPointSize(2.f);
    for (std::size_t i = 1; i < N; ++i) {
        glVertex2f(curve[i - 1].first, curve[i - 1].second);
        glVertex2f(curve[i].first, curve[i].second);
    }
    glEnd();

    glColor3f(0.f, 0.f, 0.f);
    std::stringstream label;
    label << std::setw(3) << "l = " << marker_ratio;
    glRasterPos2f(-.85, .85);
    draw_bitmap_text(GLUT_BITMAP_TIMES_ROMAN_24, const_cast<char *>(label.str().c_str()));

    label.str("");
    label.clear();
    label << std::setw(3) << "k = " << radius_ratio;
    glRasterPos2f(-.85, .70);
    draw_bitmap_text(GLUT_BITMAP_TIMES_ROMAN_24, const_cast<char *>(label.str().c_str()));

    glutSwapBuffers();
}

/**
 * @brief Redraws one animation frame and advances the l/k parameters,
 * bouncing them back and forth between their limits.
 */
void animate_frame() {
    constexpr std::size_t sample_count = 5000;
    static bool radius_growing = true;
    static bool marker_growing = true;

    std::array<std::pair<double, double>, sample_count> curve;
    sample_curve(&curve, marker_ratio_live, radius_ratio_live, revolutions_live);
    render_curve(curve, marker_ratio_live, radius_ratio_live);

    if (animation_paused) {
        return;
    }

    if (radius_growing) {
        if (radius_ratio_live >= (1.0 - increment)) {
            radius_growing = false;
        } else {
            radius_ratio_live += increment;
        }
    } else {
        if (radius_ratio_live <= increment) {
            radius_growing = true;
            if (marker_growing) {
                if (marker_ratio_live >= (1.0 - increment)) {
                    marker_growing = false;
                } else {
                    marker_ratio_live += increment;
                }
            } else {
                if (marker_ratio_live <= increment) {
                    marker_growing = true;
                } else {
                    marker_ratio_live -= increment;
                }
            }
        } else {
            radius_ratio_live -= increment;
        }
    }
}

void on_timer_tick(int) {
    glutTimerFunc(frame_delay_ms, on_timer_tick, 0);
    glutPostRedisplay();
}

void on_key_press(unsigned char key, int, int) {
    switch (key) {
        case ' ':
            animation_paused = !animation_paused;
            break;
        case GLUT_KEY_UP:
        case '+':
            radius_ratio_live += increment;
            break;
        case GLUT_KEY_DOWN:
        case '_':
            radius_ratio_live -= increment;
            break;
        case GLUT_KEY_RIGHT:
        case '=':
            marker_ratio_live += increment;
            break;
        case GLUT_KEY_LEFT:
        case '-':
            marker_ratio_live -= increment;
            break;
        case 0x1B:
            exit(EXIT_SUCCESS);
        default:
            return;
    }
}
#endif
}  // namespace hypotrochoid

int main(int argc, char **argv) {
    hypotrochoid::export_curve_to_csv();

#ifdef USE_GLUT
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_RGB | GLUT_DOUBLE);
    glutCreateWindow("Spirograph");
    glutInitWindowSize(400, 400);
    glutTimerFunc(hypotrochoid::frame_delay_ms, hypotrochoid::on_timer_tick, 0);
    glutKeyboardFunc(hypotrochoid::on_key_press);
    glutDisplayFunc(hypotrochoid::animate_frame);
    glutMainLoop();
#endif

    return 0;
}

﻿/**
 * @author [Jason Nardoni](https://github.com/JNardoni)
 * @file
 *
 * @brief
 * [Borůvkas Algorithm](https://en.wikipedia.org/wiki/Borůvka's_algorithm) to
 *find the Minimum Spanning Tree
 *
 *
 * @details
 * Boruvka's algorithm is a greepy algorithm to find the MST by starting with
 *small trees, and combining them to build bigger ones.
 *	1. Creates a group for every vertex.
 *	2. looks through each edge of every vertex for the smallest weight. Keeps
 *track of the smallest edge for each of the current groups.
 *  3. Combine each group with the group it shares its smallest edge, adding the
 *smallest edge to the MST.
 *  4. Repeat step 2-3 until all vertices are combined into a single group.
 *
 * It assumes that the graph is connected. Non-connected edges can be
 *represented using 0 or INT_MAX
 *
 */

#include <cassert>   /// for assert
#include <climits>   /// for INT_MAX
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace greedy_algorithms
 * @brief Greedy Algorithms
 */
namespace greedy_algorithms {
/**
 * @namespace boruvkas_minimum_spanning_tree
 * @brief Functions for the [Borůvkas
 * Algorithm](https://en.wikipedia.org/wiki/Borůvka's_algorithm) implementation
 */
namespace boruvkas_minimum_spanning_tree {
/**
 * @brief Recursively returns the vertex's parent at the root of the tree
 * @param parent the array that will be checked
 * @param v vertex to find parent of
 * @returns the parent of the vertex
 */
int findParent(std::vector<std::pair<int, int>> parent, const int v) {
    if (parent[v].first != v) {
        parent[v].first = findParent(parent, parent[v].first);
    }

    return parent[v].first;
}

/**
 * @brief the implementation of boruvka's algorithm
 * @param adj a graph adjancency matrix stored as 2d vectors.
 * @returns the MST as 2d vectors
 */
std::vector<std::vector<int>> boruvkas(std::vector<std::vector<int>> adj) {
    size_t size = adj.size();
    size_t total_groups = size;

    if (size <= 1) {
        return adj;
    }

    // Stores the current Minimum Spanning Tree. As groups are combined, they
    // are added to the MST
    std::vector<std::vector<int>> MST(size, std::vector<int>(size, INT_MAX));
    for (int i = 0; i < size; i++) {
        MST[i][i] = 0;
    }

    // Step 1: Create a group for each vertex

    // Stores the parent of the vertex and its current depth, both initialized
    // to 0
    std::vector<std::pair<int, int>> parent(size, std::make_pair(0, 0));

    for (int i = 0; i < size; i++) {
        parent[i].first =
            i;  // Sets parent of each vertex to itself, depth remains 0
    }

    // Repeat until all are in a single group
    while (total_groups > 1) {
        std::vector<std::pair<int, int>> smallest_edge(
            size, std::make_pair(-1, -1));  // Pairing: start node, end node

        // Step 2: Look throught each vertex for its smallest edge, only using
        // the right half of the adj matrix
        for (int i = 0; i < size; i++) {
            for (int j = i + 1; j < size; j++) {
                if (adj[i][j] == INT_MAX || adj[i][j] == 0) {  // No connection
                    continue;
                }

                // Finds the parents of the start and end points to make sure
                // they arent in the same group
                int parentA = findParent(parent, i);
                int parentB = findParent(parent, j);

                if (parentA != parentB) {
                    // Grabs the start and end points for the first groups
                    // current smallest edge
                    int start = smallest_edge[parentA].first;
                    int end = smallest_edge[parentA].second;

                    // If there is no current smallest edge, or the new edge is
                    // smaller, records the new smallest
                    if (start == -1 || adj[i][j] < adj[start][end]) {
                        smallest_edge[parentA].first = i;
                        smallest_edge[parentA].second = j;
                    }

                    // Does the same for the second group
                    start = smallest_edge[parentB].first;
                    end = smallest_edge[parentB].second;

                    if (start == -1 || adj[j][i] < adj[start][end]) {
                        smallest_edge[parentB].first = j;
                        smallest_edge[parentB].second = i;
                    }
                }
            }
        }

        // Step 3: Combine the groups based off their smallest edge

        for (int i = 0; i < size; i++) {
            // Makes sure the smallest edge exists
            if (smallest_edge[i].first != -1) {
                // Start and end points for the groups smallest edge
                int start = smallest_edge[i].first;
                int end = smallest_edge[i].second;

                // Parents of the two groups - A is always itself
                int parentA = i;
                int parentB = findParent(parent, end);

                // Makes sure the two nodes dont share the same parent. Would
                // happen if the two groups have been
                // merged previously through a common shortest edge
                if (parentA == parentB) {
                    continue;
                }

                // Tries to balance the trees as much as possible as they are
                // merged. The parent of the shallower
                // tree will be pointed to the parent of the deeper tree.
                if (parent[parentA].second < parent[parentB].second) {
                    parent[parentB].first = parentA;  // New parent
                    parent[parentB].second++;         // Increase depth
                } else {
                    parent[parentA].first = parentB;
                    parent[parentA].second++;
                }
                // Add the connection to the MST, using both halves of the adj
                // matrix
                MST[start][end] = adj[start][end];
                MST[end][start] = adj[end][start];
                total_groups--;  // one fewer group
            }
        }
    }
    return MST;
}

/**
 * @brief counts the sum of edges in the given tree
 * @param adj 2D vector adjacency matrix
 * @returns the int size of the tree
 */
int test_findGraphSum(std::vector<std::vector<int>> adj) {
    size_t size = adj.size();
    int sum = 0;

    // Moves through one side of the adj matrix, counting the sums of each edge
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (adj[i][j] < INT_MAX) {
                sum += adj[i][j];
            }
        }
    }
    return sum;
}
}  // namespace boruvkas_minimum_spanning_tree
}  // namespace greedy_algorithms

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    std::cout << "Starting tests...\n\n";
    std::vector<std::vector<int>> graph = {
        {0, 5, INT_MAX, 3, INT_MAX}, {5, 0, 2, INT_MAX, 5},
        {INT_MAX, 2, 0, INT_MAX, 3}, {3, INT_MAX, INT_MAX, 0, INT_MAX},
        {INT_MAX, 5, 3, INT_MAX, 0},
    };
    std::vector<std::vector<int>> MST =
        greedy_algorithms::boruvkas_minimum_spanning_tree::boruvkas(graph);
    assert(greedy_algorithms::boruvkas_minimum_spanning_tree::test_findGraphSum(
               MST) == 13);
    std::cout << "1st test passed!" << std::endl;

    graph = {{0, 2, 0, 6, 0},
             {2, 0, 3, 8, 5},
             {0, 3, 0, 0, 7},
             {6, 8, 0, 0, 9},
             {0, 5, 7, 9, 0}};
    MST = greedy_algorithms::boruvkas_minimum_spanning_tree::boruvkas(graph);
    assert(greedy_algorithms::boruvkas_minimum_spanning_tree::test_findGraphSum(
               MST) == 16);
    std::cout << "2nd test passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief [Boruvka's Algorithm]
 * (https://en.wikipedia.org/wiki/Bor%C5%AFvka%27s_algorithm) for building a
 * Minimum Spanning Tree
 *
 * @details
 * Boruvka's approach grows a forest of components in rounds: each round,
 * every component finds the cheapest edge leaving it toward some other
 * component, and all such edges are contracted simultaneously (using a
 * union-find structure to avoid double-merging components that pick the
 * same edge). Because every round at least halves the number of remaining
 * components, the process finishes in O(log V) rounds.
 *
 * The input graph is assumed connected; absent edges are marked with
 * INT_MAX (or 0, which is also treated as "no edge").
 */

#include <cassert>
#include <climits>
#include <iostream>
#include <vector>

namespace greedy_algorithms {

namespace boruvka_mst {

/**
 * @brief Union-find "find" with path compression, storing (root, rank)
 * pairs per node.
 * @param roots the union-find table (root, rank) to search within
 * @param node vertex whose representative we want
 * @returns the representative vertex of node's component
 */
int representative_of(std::vector<std::pair<int, int>> roots, const int node) {
    if (roots[node].first != node) {
        roots[node].first = representative_of(roots, roots[node].first);
    }
    return roots[node].first;
}

/**
 * @brief Builds a Minimum Spanning Tree from a dense adjacency matrix using
 * Boruvka's component-merging approach.
 * @param weights adjacency matrix (INT_MAX or 0 means "no edge")
 * @returns adjacency matrix containing only MST edges
 */
std::vector<std::vector<int>> build_mst(std::vector<std::vector<int>> weights) {
    const size_t vertex_count = weights.size();
    size_t components_left = vertex_count;

    if (vertex_count <= 1) {
        return weights;
    }

    std::vector<std::vector<int>> mst(vertex_count, std::vector<int>(vertex_count, INT_MAX));
    for (size_t v = 0; v < vertex_count; ++v) {
        mst[v][v] = 0;
    }

    // Union-find bookkeeping: each vertex starts as its own singleton
    // component at depth zero.
    std::vector<std::pair<int, int>> uf(vertex_count, std::make_pair(0, 0));
    for (size_t v = 0; v < vertex_count; ++v) {
        uf[v].first = static_cast<int>(v);
    }

    while (components_left > 1) {
        // best_edge[c] holds the cheapest (u, v) edge leaving component c
        std::vector<std::pair<int, int>> best_edge(vertex_count, std::make_pair(-1, -1));

        for (size_t u = 0; u < vertex_count; ++u) {
            for (size_t v = u + 1; v < vertex_count; ++v) {
                if (weights[u][v] == INT_MAX || weights[u][v] == 0) {
                    continue;
                }

                int comp_u = representative_of(uf, static_cast<int>(u));
                int comp_v = representative_of(uf, static_cast<int>(v));
                if (comp_u == comp_v) {
                    continue;
                }

                // Update component u's best known outgoing edge, if beaten
                int cur_u = best_edge[comp_u].first;
                int cur_v = best_edge[comp_u].second;
                if (cur_u == -1 || weights[u][v] < weights[cur_u][cur_v]) {
                    best_edge[comp_u] = std::make_pair(static_cast<int>(u), static_cast<int>(v));
                }

                // Same bookkeeping from component v's perspective
                cur_u = best_edge[comp_v].first;
                cur_v = best_edge[comp_v].second;
                if (cur_u == -1 || weights[v][u] < weights[cur_u][cur_v]) {
                    best_edge[comp_v] = std::make_pair(static_cast<int>(v), static_cast<int>(u));
                }
            }
        }

        for (size_t comp = 0; comp < vertex_count; ++comp) {
            if (best_edge[comp].first == -1) {
                continue;
            }

            int from = best_edge[comp].first;
            int to = best_edge[comp].second;

            int root_from = static_cast<int>(comp);
            int root_to = representative_of(uf, to);

            if (root_from == root_to) {
                continue;  // already merged via a shared cheapest edge
            }

            // Union by depth/rank to keep the tree roughly balanced
            if (uf[root_from].second < uf[root_to].second) {
                uf[root_to].first = root_from;
                uf[root_to].second++;
            } else {
                uf[root_from].first = root_to;
                uf[root_from].second++;
            }

            mst[from][to] = weights[from][to];
            mst[to][from] = weights[to][from];
            --components_left;
        }
    }

    return mst;
}

/**
 * @brief Sums the weight of every edge in the upper triangle of an
 * adjacency matrix, useful for validating an MST's total cost.
 */
int total_edge_weight(std::vector<std::vector<int>> adjacency) {
    const size_t vertex_count = adjacency.size();
    int running_total = 0;

    for (size_t u = 0; u < vertex_count; ++u) {
        for (size_t v = u + 1; v < vertex_count; ++v) {
            if (adjacency[u][v] < INT_MAX) {
                running_total += adjacency[u][v];
            }
        }
    }
    return running_total;
}

}  // namespace boruvka_mst
}  // namespace greedy_algorithms

/**
 * @brief Checks Boruvka's algorithm against two small hand-verified graphs.
 */
static void run_mst_checks() {
    std::cout << "Running Boruvka MST checks...\n\n";

    std::vector<std::vector<int>> graph_one = {
        {0, 5, INT_MAX, 3, INT_MAX},
        {5, 0, 2, INT_MAX, 5},
        {INT_MAX, 2, 0, INT_MAX, 3},
        {3, INT_MAX, INT_MAX, 0, INT_MAX},
        {INT_MAX, 5, 3, INT_MAX, 0},
    };
    auto mst_one = greedy_algorithms::boruvka_mst::build_mst(graph_one);
    assert(greedy_algorithms::boruvka_mst::total_edge_weight(mst_one) == 13);
    std::cout << "Graph 1: MST weight matches expectation (13)\n";

    std::vector<std::vector<int>> graph_two = {
        {0, 2, 0, 6, 0},
        {2, 0, 3, 8, 5},
        {0, 3, 0, 0, 7},
        {6, 8, 0, 0, 9},
        {0, 5, 7, 9, 0},
    };
    auto mst_two = greedy_algorithms::boruvka_mst::build_mst(graph_two);
    assert(greedy_algorithms::boruvka_mst::total_edge_weight(mst_two) == 16);
    std::cout << "Graph 2: MST weight matches expectation (16)\n";
}

int main() {
    run_mst_checks();
    return 0;
}

/**
 * @file
 * @brief [Kruskals Minimum Spanning
 * Tree](https://www.simplilearn.com/tutorials/data-structure-tutorial/kruskal-algorithm)
 * implementation
 *
 * @details
 * _Quoted from
 * [Simplilearn](https://www.simplilearn.com/tutorials/data-structure-tutorial/kruskal-algorithm)._
 *
 * Kruskal’s algorithm is the concept that is introduced in the graph theory of
 * discrete mathematics. It is used to discover the shortest path between two
 * points in a connected weighted graph. This algorithm converts a given graph
 * into the forest, considering each node as a separate tree. These trees can
 * only link to each other if the edge connecting them has a low value and
 * doesn’t generate a cycle in MST structure.
 *
 * @author [coleman2246](https://github.com/coleman2246)
 */

#include <array>     /// for array
#include <iostream>  /// for IO operations
#include <limits>    /// for numeric limits
#include <cstdint>   /// for uint32_t

/**
 * @namespace
 * @brief Greedy Algorithms
 */
namespace greedy_algorithms {
/**
 * @brief Finds the minimum edge of the given graph.
 * @param infinity Defines the infinity of the graph
 * @param graph The graph that will be used to find the edge
 * @returns void
 */
template <typename T, std::size_t N, std::size_t M>
void findMinimumEdge(const T &infinity,
                     const std::array<std::array<T, N>, M> &graph) {
    if (N != M) {
        std::cout << "\nWrong input passed. Provided array has dimensions " << N
                  << "x" << M << ". Please provide a square matrix.\n";
        return;
    }
    for (int i = 0; i < graph.size(); i++) {
        int min = infinity;
        int minIndex = 0;
        for (int j = 0; j < graph.size(); j++) {
            if (i != j && graph[i][j] != 0 && graph[i][j] < min) {
                min = graph[i][j];
                minIndex = j;
            }
        }
        std::cout << i << "  -  " << minIndex << "\t" << graph[i][minIndex]
                  << "\n";
    }
}
}  // namespace greedy_algorithms

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    /**
     * define a large value for int
     * define a large value for float
     * define a large value for double
     * define a large value for uint32_t
     */
    constexpr int INFINITY_INT = std::numeric_limits<int>::max();
    constexpr float INFINITY_FLOAT = std::numeric_limits<float>::max();
    constexpr double INFINITY_DOUBLE = std::numeric_limits<double>::max();
    constexpr uint32_t INFINITY_UINT32 = UINT32_MAX;

    // Test case with integer values
    std::cout << "\nTest Case 1 :\n";
    std::array<std::array<int, 6>, 6> graph1{
             0,            4,            1,             4,        INFINITY_INT,   INFINITY_INT,
             4,            0,            3,             8,             3,         INFINITY_INT,
             1,            3,            0,        INFINITY_INT,       1,         INFINITY_INT,
             4,            8,       INFINITY_INT,        0,            5,              7,
        INFINITY_INT,      3,            1,              5,            0,         INFINITY_INT,
        INFINITY_INT, INFINITY_INT, INFINITY_INT,        7,       INFINITY_INT,       0};
    greedy_algorithms::findMinimumEdge(INFINITY_INT, graph1);

    // Test case with floating values
    std::cout << "\nTest Case 2 :\n";
     std::array<std::array<float, 3>, 3> graph2{
             0.0f,           2.5f,  INFINITY_FLOAT,
             2.5f,           0.0f,       3.2f,
        INFINITY_FLOAT,      3.2f,       0.0f};
    greedy_algorithms::findMinimumEdge(INFINITY_FLOAT, graph2);

    // Test case with double values
    std::cout << "\nTest Case 3 :\n";
   std::array<std::array<double, 5>, 5> graph3{
               0.0,             10.5,       INFINITY_DOUBLE,        6.7,              3.3,
               10.5,            0.0,              8.1,              15.4,       INFINITY_DOUBLE,
        INFINITY_DOUBLE,        8.1,              0.0,        INFINITY_DOUBLE,         7.8,
               6.7,             15.4,       INFINITY_DOUBLE,        0.0,               9.9,
               3.3,       INFINITY_DOUBLE,        7.8,              9.9,               0.0};
    greedy_algorithms::findMinimumEdge(INFINITY_DOUBLE, graph3);

    // Test Case with negative weights
    std::cout << "\nTest Case 4 :\n";
    std::array<std::array<int, 3>, 3> graph_neg{
        0,   -2,   4,
       -2,    0,   3,
        4,    3,   0};
    greedy_algorithms::findMinimumEdge(INFINITY_INT, graph_neg);

    // Test Case with Self-Loops
    std::cout << "\nTest Case 5 :\n";
    std::array<std::array<int, 3>, 3> graph_self_loop{
               2,       1, INFINITY_INT,
        INFINITY_INT,   0,        4,
        INFINITY_INT,   4,        0};
    greedy_algorithms::findMinimumEdge(INFINITY_INT, graph_self_loop);

    // Test Case with no edges
    std::cout << "\nTest Case 6 :\n";
    std::array<std::array<int, 4>, 4> no_edges{
               0,       INFINITY_INT,   INFINITY_INT,   INFINITY_INT,
        INFINITY_INT,         0,        INFINITY_INT,   INFINITY_INT,
        INFINITY_INT,   INFINITY_INT,          0,       INFINITY_INT,
        INFINITY_INT,   INFINITY_INT,   INFINITY_INT,           0};
    greedy_algorithms::findMinimumEdge(INFINITY_INT, no_edges);

    // Test Case with a non-connected graph
    std::cout << "\nTest Case 7:\n";
    std::array<std::array<int, 4>, 4> partial_graph{
                0,             2,    INFINITY_INT,         6,
                2,             0,            3,     INFINITY_INT,
        INFINITY_INT,          3,            0,             4,
                6,     INFINITY_INT,         4,             0};
    greedy_algorithms::findMinimumEdge(INFINITY_INT, partial_graph);

    // Test Case with Directed weighted graph. The Krushkal algorithm does not give
    // optimal answer
    std::cout << "\nTest Case 8:\n";
    std::array<std::array<int, 4>, 4> directed_graph{
                0,            3,            7,   INFINITY_INT,  // Vertex 0 has edges to Vertex 1 and Vertex 2
        INFINITY_INT,         0,            2,           5,  // Vertex 1 has edges to Vertex 2 and Vertex 3
        INFINITY_INT, INFINITY_INT,         0,           1,  // Vertex 2 has an edge to Vertex 3
        INFINITY_INT, INFINITY_INT, INFINITY_INT,        0};  // Vertex 3 has no outgoing edges
    greedy_algorithms::findMinimumEdge(INFINITY_INT, directed_graph);

    // Test case with wrong input passed
    std::cout << "\nTest Case 9:\n";
   std::array<std::array<int, 4>, 3> graph9{
        0,        5,        5,        5,
        5,        0,        5,        5,        
        5,        5,        5,        5};
    greedy_algorithms::findMinimumEdge(INFINITY_INT, graph9);

    // Test case with all the same values between every edge
    std::cout << "\nTest Case 10:\n";
    std::array<std::array<int, 5>, 5> graph10{
        0,        5,        5,        5,        5,
        5,        0,        5,        5,        5,
        5,        5,        0,        5,        5,
        5,        5,        5,        0,        5,
        5,        5,        5,        5,        0};
    greedy_algorithms::findMinimumEdge(INFINITY_INT, graph10);

  // Test Case with uint32_t values
    std::cout << "\nTest Case 11 :\n";
    std::array<std::array<uint32_t, 4>, 4> graph_uint32{
                0,                      5,        INFINITY_UINT32,          9,
                5,                      0,                2,        INFINITY_UINT32,
        INFINITY_UINT32,                2,                0,                6,
                9,               INFINITY_UINT32,         6,                0};
    greedy_algorithms::findMinimumEdge(INFINITY_UINT32, graph_uint32);

    std::cout << "\nAll tests have successfully passed!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */

int main() {
    test();  // run Self-test implementation
    return 0;
}

/**
 * @file
 * @brief Alternate demonstration of the "cheapest incident edge per vertex"
 * step that underlies Kruskal's minimum-spanning-tree construction.
 *
 * @details
 * Kruskal's algorithm treats every vertex as its own tree initially and
 * repeatedly merges the two trees connected by the cheapest edge that does
 * not create a cycle. This file focuses on the per-vertex cheapest-edge
 * lookup used as a building block, tested against a variety of adjacency
 * matrices (square, non-square, negative weights, directed, etc).
 *
 * @author rewritten for the classroom dataset
 */

#include <array>     /// fixed-size array container
#include <iostream>  /// console IO
#include <limits>    /// numeric_limits
#include <cstdint>   /// uint32_t

/**
 * @namespace
 * @brief Greedy Algorithms
 */
namespace greedy_algorithms {

/**
 * @brief Prints, for every vertex, the cheapest outgoing edge in an
 * adjacency-matrix graph.
 * @param noEdgeMarker Sentinel value that represents "no edge"/infinity.
 * @param adjMatrix The square adjacency matrix describing edge weights.
 * @returns void
 */
template <typename Weight, std::size_t Rows, std::size_t Cols>
void reportCheapestEdges(const Weight &noEdgeMarker,
                          const std::array<std::array<Weight, Rows>, Cols> &adjMatrix) {
    if (Rows != Cols) {
        std::cout << "\nWrong input passed. Provided array has dimensions " << Rows
                  << "x" << Cols << ". Please provide a square matrix.\n";
        return;
    }
    for (int row = 0; row < adjMatrix.size(); row++) {
        int cheapest = noEdgeMarker;
        int cheapestCol = 0;
        for (int col = 0; col < adjMatrix.size(); col++) {
            if (row != col && adjMatrix[row][col] != 0 && adjMatrix[row][col] < cheapest) {
                cheapest = adjMatrix[row][col];
                cheapestCol = col;
            }
        }
        std::cout << row << "  -  " << cheapestCol << "\t" << adjMatrix[row][cheapestCol]
                  << "\n";
    }
}

}  // namespace greedy_algorithms

/**
 * @brief Runs a battery of scenario checks against reportCheapestEdges.
 * @returns void
 */
static void runScenarios() {
    constexpr int NO_EDGE_INT = std::numeric_limits<int>::max();
    constexpr float NO_EDGE_FLOAT = std::numeric_limits<float>::max();
    constexpr double NO_EDGE_DOUBLE = std::numeric_limits<double>::max();
    constexpr uint32_t NO_EDGE_UINT32 = UINT32_MAX;

    // Scenario 1: integer-weighted graph
    std::cout << "\nTest Case 1 :\n";
    std::array<std::array<int, 6>, 6> g1{
             0,            4,            1,             4,        NO_EDGE_INT,   NO_EDGE_INT,
             4,            0,            3,             8,             3,         NO_EDGE_INT,
             1,            3,            0,        NO_EDGE_INT,       1,         NO_EDGE_INT,
             4,            8,       NO_EDGE_INT,        0,            5,              7,
        NO_EDGE_INT,      3,            1,              5,            0,         NO_EDGE_INT,
        NO_EDGE_INT, NO_EDGE_INT, NO_EDGE_INT,        7,       NO_EDGE_INT,       0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, g1);

    // Scenario 2: floating-point weights
    std::cout << "\nTest Case 2 :\n";
    std::array<std::array<float, 3>, 3> g2{
             0.0f,           2.5f,  NO_EDGE_FLOAT,
             2.5f,           0.0f,       3.2f,
        NO_EDGE_FLOAT,      3.2f,       0.0f};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_FLOAT, g2);

    // Scenario 3: double-precision weights
    std::cout << "\nTest Case 3 :\n";
    std::array<std::array<double, 5>, 5> g3{
               0.0,             10.5,       NO_EDGE_DOUBLE,        6.7,              3.3,
               10.5,            0.0,              8.1,              15.4,       NO_EDGE_DOUBLE,
        NO_EDGE_DOUBLE,        8.1,              0.0,        NO_EDGE_DOUBLE,         7.8,
               6.7,             15.4,       NO_EDGE_DOUBLE,        0.0,               9.9,
               3.3,       NO_EDGE_DOUBLE,        7.8,              9.9,               0.0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_DOUBLE, g3);

    // Scenario 4: negative weights
    std::cout << "\nTest Case 4 :\n";
    std::array<std::array<int, 3>, 3> gNeg{
        0,   -2,   4,
       -2,    0,   3,
        4,    3,   0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gNeg);

    // Scenario 5: self-loops present
    std::cout << "\nTest Case 5 :\n";
    std::array<std::array<int, 3>, 3> gSelfLoop{
               2,       1, NO_EDGE_INT,
        NO_EDGE_INT,   0,        4,
        NO_EDGE_INT,   4,        0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gSelfLoop);

    // Scenario 6: no edges at all
    std::cout << "\nTest Case 6 :\n";
    std::array<std::array<int, 4>, 4> gNoEdges{
               0,       NO_EDGE_INT,   NO_EDGE_INT,   NO_EDGE_INT,
        NO_EDGE_INT,         0,        NO_EDGE_INT,   NO_EDGE_INT,
        NO_EDGE_INT,   NO_EDGE_INT,          0,       NO_EDGE_INT,
        NO_EDGE_INT,   NO_EDGE_INT,   NO_EDGE_INT,           0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gNoEdges);

    // Scenario 7: disconnected components
    std::cout << "\nTest Case 7:\n";
    std::array<std::array<int, 4>, 4> gPartial{
                0,             2,    NO_EDGE_INT,         6,
                2,             0,            3,     NO_EDGE_INT,
        NO_EDGE_INT,          3,            0,             4,
                6,     NO_EDGE_INT,         4,             0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gPartial);

    // Scenario 8: directed graph (result is not a true MST in this case)
    std::cout << "\nTest Case 8:\n";
    std::array<std::array<int, 4>, 4> gDirected{
                0,            3,            7,   NO_EDGE_INT,
        NO_EDGE_INT,         0,            2,           5,
        NO_EDGE_INT, NO_EDGE_INT,         0,           1,
        NO_EDGE_INT, NO_EDGE_INT, NO_EDGE_INT,        0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gDirected);

    // Scenario 9: malformed (non-square) input
    std::cout << "\nTest Case 9:\n";
    std::array<std::array<int, 4>, 3> gBadShape{
        0,        5,        5,        5,
        5,        0,        5,        5,
        5,        5,        5,        5};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gBadShape);

    // Scenario 10: uniform edge weights
    std::cout << "\nTest Case 10:\n";
    std::array<std::array<int, 5>, 5> gUniform{
        0,        5,        5,        5,        5,
        5,        0,        5,        5,        5,
        5,        5,        0,        5,        5,
        5,        5,        5,        0,        5,
        5,        5,        5,        5,        0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gUniform);

    // Scenario 11: unsigned 32-bit weights
    std::cout << "\nTest Case 11 :\n";
    std::array<std::array<uint32_t, 4>, 4> gUint32{
                0,                      5,        NO_EDGE_UINT32,          9,
                5,                      0,                2,        NO_EDGE_UINT32,
        NO_EDGE_UINT32,                2,                0,                6,
                9,               NO_EDGE_UINT32,         6,                0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_UINT32, gUint32);

    std::cout << "\nAll tests have successfully passed!\n";
}

/**
 * @brief Program entry point.
 * @returns 0 on exit
 */
int main() {
    runScenarios();
    return 0;
}

/**
 * @file
 * @author [achance6](https://github.com/achance6)
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Storage mechanism using [quadratic probing
 * hash](https://en.wikipedia.org/wiki/Quadratic_probing) keys.
 * @note The implementation can be optimized by using OOP style.
 */
#include <cmath>
#include <iostream>
#include <vector>

/**
 * @addtogroup open_addressing Open Addressing
 * @{
 * @namespace quadratic_probing
 * @brief An implementation of hash table using [quadratic
 * probing](https://en.wikipedia.org/wiki/Quadratic_probing) algorithm.
 */
namespace quadratic_probing {
// fwd declarations
using Entry = struct Entry;
bool putProber(const Entry& entry, int key);
bool searchingProber(const Entry& entry, int key);
void add(int key);

// globals
int notPresent;
std::vector<Entry> table;
int totalSize;
int tomb = -1;
int size;
bool rehashing;

/** Node that holds key
 */
struct Entry {
    explicit Entry(int key = notPresent) : key(key) {}  ///< constructor
    int key;                                            ///< key value
};

/** Hash a key
 * @param key key value to hash
 * @returns hash of the key
 */
size_t hashFxn(int key) {
    std::hash<int> hash;
    return hash(key);
}

/** Performs quadratic probing to resolve collisions
 * @param key key value to search/probe
 * @param searching `true` if only searching, `false1 if assigning
 * @returns value of `notPresent`.
 */
int quadraticProbe(int key, bool searching) {
    int hash = static_cast<int>(hashFxn(key));
    int i = 0;
    Entry entry;
    do {
        size_t index =
            (hash + static_cast<size_t>(std::round(std::pow(i, 2)))) %
            totalSize;
        entry = table[index];
        if (searching) {
            if (entry.key == notPresent) {
                return notPresent;
            }
            if (searchingProber(entry, key)) {
                std::cout << "Found key!" << std::endl;
                return index;
            }
            std::cout << "Found tombstone or equal hash, checking next"
                      << std::endl;
            i++;
        } else {
            if (putProber(entry, key)) {
                if (!rehashing) {
                    std::cout << "Spot found!" << std::endl;
                }
                return index;
            }
            if (!rehashing) {
                std::cout << "Spot taken, looking at next (next index = "
                          << (hash + static_cast<size_t>(
                                         std::round(std::pow(i + 1, 2)))) %
                                 totalSize
                          << std::endl;
            }
            i++;
        }
        if (i == totalSize * 100) {
            std::cout << "Quadratic probe failed (infinite loop)" << std::endl;
            return notPresent;
        }
    } while (entry.key != notPresent);
    return notPresent;
}

/** Finds empty spot
 * @param entry Instance of table entry
 * @param key key value to search/probe
 * @returns `true` if key is present
 * @returns `false` if key is absent
 */
bool putProber(const Entry& entry, int key) {
    if (entry.key == notPresent || entry.key == tomb) {
        return true;
    }
    return false;
}

/** Looks for a matching key
 * @param entry Instance of table entry
 * @param key key value to search/probe
 * @returns `true` if key matches the entry
 * @returns `false` if key does not match the entry
 */
bool searchingProber(const Entry& entry, int key) {
    if (entry.key == key) {
        return true;
    }
    return false;
}

/** Get the entry instance corresponding to a key
 * @param key key value to search/probe
 * @returns if present, the entry instance
 * @returns if not present, a new instance
 */
Entry find(int key) {
    int index = quadraticProbe(key, true);
    if (index == notPresent) {
        return Entry();
    }
    return table[index];
}

/** Displays the table
 * @returns None
 */
void display() {
    for (int i = 0; i < totalSize; i++) {
        if (table[i].key == notPresent) {
            std::cout << " Empty ";
        } else if (table[i].key == tomb) {
            std::cout << " Tomb ";
        } else {
            std::cout << " ";
            std::cout << table[i].key;
            std::cout << " ";
        }
    }
    std::cout << std::endl;
}

/** Rehashes the table into a bigger table
 * @returns none
 */
void rehash() {
    // Necessary so wall of add info isn't printed all at once
    rehashing = true;
    int oldSize = totalSize;
    std::vector<Entry> oldTable(table);
    // Really this should use the next prime number greater than totalSize * 2
    totalSize *= 2;
    table = std::vector<Entry>(totalSize);
    for (int i = 0; i < oldSize; i++) {
        if (oldTable[i].key != -1 && oldTable[i].key != notPresent) {
            size--;  // Size stays the same (add increments size)
            add(oldTable[i].key);
        }
    }
    // delete[] oldTable;
    rehashing = false;
    std::cout << "Table was rehashed, new size is: " << totalSize << std::endl;
}

/** Checks for load factor here
 * @param key  key value to hash and add to table
 */
void add(int key) {
    int index = quadraticProbe(key, false);
    table[index].key = key;
    // Load factor greater than 0.5 causes resizing
    if (++size / static_cast<double>(totalSize) >= 0.5) {
        rehash();
    }
}

/** Removes key. Leaves tombstone upon removal.
 * @param key  key value to hash and remove from table
 */
void remove(int key) {
    int index = quadraticProbe(key, true);
    if (index == notPresent) {
        std::cout << "key not found" << std::endl;
    }
    table[index].key = tomb;
    std::cout << "Removal successful, leaving tombstone" << std::endl;
    size--;
}

/** Information about the adding process
 * @param key  key value to hash and add to table
 */
void addInfo(int key) {
    std::cout << "Initial table: ";
    display();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << hashFxn(key) << " % "
              << totalSize << " == " << hashFxn(key) % totalSize;
    std::cout << std::endl;
    add(key);
    std::cout << "New table: ";
    display();
}

/** Information about removal process
 * @param key  key value to hash and remove from table
 */
void removalInfo(int key) {
    std::cout << "Initial table: ";
    display();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << hashFxn(key) << " % "
              << totalSize << " == " << hashFxn(key) % totalSize;
    std::cout << std::endl;
    remove(key);
    std::cout << "New table: ";
    display();
}

}  // namespace quadratic_probing
/**
 * @}
 */

using quadratic_probing::Entry;
using quadratic_probing::table;
using quadratic_probing::totalSize;

/** Main function
 * @returns None
 */
int main() {
    int cmd = 0, key = 0;
    std::cout << "Enter the initial size of Hash Table. = ";
    std::cin >> totalSize;
    table = std::vector<Entry>(totalSize);
    bool loop = true;
    while (loop) {
        std::cout << std::endl;
        std::cout << "PLEASE CHOOSE -" << std::endl;
        std::cout << "1. Add key. (Numeric only)" << std::endl;
        std::cout << "2. Remove key." << std::endl;
        std::cout << "3. Find key." << std::endl;
        std::cout << "4. Generate Hash. (Numeric only)" << std::endl;
        std::cout << "5. Display Hash table." << std::endl;
        std::cout << "6. Exit." << std::endl;
        std::cin >> cmd;
        switch (cmd) {
            case 1:
                std::cout << "Enter key to add = ";
                std::cin >> key;
                quadratic_probing::addInfo(key);
                break;
            case 2:
                std::cout << "Enter key to remove = ";
                std::cin >> key;
                quadratic_probing::removalInfo(key);
                break;
            case 3: {
                std::cout << "Enter key to search = ";
                std::cin >> key;
                quadratic_probing::Entry entry =
                    quadratic_probing::table[quadratic_probing::quadraticProbe(
                        key, true)];
                if (entry.key == quadratic_probing::notPresent) {
                    std::cout << "Key not present";
                }
                break;
            }
            case 4:
                std::cout << "Enter element to generate hash = ";
                std::cin >> key;
                std::cout << "Hash of " << key
                          << " is = " << quadratic_probing::hashFxn(key);
                break;
            case 5:
