/**
 * \addtogroup machine_learning Machine Learning Algorithms
 * @{
 * \file
 * \brief Alternate implementation of a Kohonen self-organizing map used to
 * trace the shape of a dataset with a 1D chain of nodes.
 *
 * \details
 * This variant trains a linear chain of weight vectors that snakes through
 * the input data, effectively tracing the shape (e.g. a circle or a
 * figure-eight) that the samples were drawn from.
 * \see kohonen_som_topology.cpp
 */
#define _USE_MATH_DEFINES
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <fstream>
#include <iostream>
#include <valarray>
#include <vector>
#ifdef _OPENMP
#include <omp.h>
#endif

/**
 * Draws a uniform random double from the interval [lo, hi).
 * \param[in] lo lower bound
 * \param[in] hi upper bound
 * \returns a pseudo-random value in [lo, hi)
 */
double drawUniform(double lo, double hi) {
    return ((hi - lo) * (std::rand() % 100) / 100.f) + lo;
}

/**
 * Writes an N-dimensional point matrix to a CSV file.
 * \param[in] path output filename (overwritten without confirmation)
 * \param[in] points row-major matrix of points to save
 * \returns 0 on success, -1 if the file could not be opened
 */
int writePointsCsv(const char *path, const std::vector<std::valarray<double>> &points) {
    size_t rowCount = points.size();
    size_t colCount = points[0].size();

    std::ofstream out;
    out.open(path);
    if (!out.is_open()) {
        std::cerr << "Error opening file " << path << "\n";
        return -1;
    }

    for (int i = 0; i < rowCount; i++) {
        for (int j = 0; j < colCount; j++) {
            out << points[i][j];
            if (j < colCount - 1) {
                out << ",";
            }
        }
        if (i < rowCount - 1) {
            out << "\n";
        }
    }

    out.close();
    return 0;
}

/** \namespace machine_learning
 * \brief Machine learning algorithms
 */
namespace machine_learning {

/**
 * Applies a single Kohonen weight-update step for one input sample against
 * a 1D chain of output nodes.
 * \param[in] sample the current training point
 * \param[in,out] chain the chain of weight vectors
 * \param[in,out] scratch reusable distance buffer, one entry per chain node
 * \param[in] learnRate current learning rate (0, 1]
 * \param[in] neighborhood current neighborhood radius along the chain
 */
void updateChain(const std::valarray<double> &sample,
                  std::vector<std::valarray<double>> *chain, std::valarray<double> *scratch,
                  double learnRate, int neighborhood) {
    int k = 0;
    int chainLen = chain->size();

#ifdef _OPENMP
#pragma omp for
#endif
    for (k = 0; k < chainLen; k++) {
        (*scratch)[k] = (((*chain)[k] - sample) * ((*chain)[k] - sample)).sum();
    }

    auto it = std::min_element(std::begin(*scratch), std::end(*scratch));
    int bmuIdx = std::distance(std::begin(*scratch), it);

    int start = std::max(0, bmuIdx - neighborhood);
    int end = std::min(chainLen, bmuIdx + neighborhood + 1);

#ifdef _OPENMP
#pragma omp for
#endif
    for (k = start; k < end; k++) {
        (*chain)[k] += learnRate * (sample - (*chain)[k]);
    }
}

/**
 * Trains the 1D chain over the full dataset, decaying the learning rate and
 * shrinking the neighborhood as training proceeds.
 * \param[in] dataset the training samples
 * \param[in,out] chain the chain of weight vectors to train
 * \param[in] learnRateFloor training stops once the learning rate drops to
 * or below this value
 */
void traceWithSom(const std::vector<std::valarray<double>> &dataset,
                   std::vector<std::valarray<double>> *chain, double learnRateFloor) {
    int sampleCount = dataset.size();
    int chainLen = chain->size();
    int neighborhood = chainLen >> 2, iteration = 0;
    double learnRate = 1.f;

    std::valarray<double> scratch(chainLen);

    do {
        for (int sample = 0; sample < sampleCount; sample++) {
            updateChain(dataset[sample], chain, &scratch, learnRate, neighborhood);
        }

        if (iteration % 10 == 0 && neighborhood > 1) {
            neighborhood--;
        }

        learnRate -= 0.01;
        iteration++;
    } while (learnRate > learnRateFloor);
}

}  // namespace machine_learning

/** @} */

using machine_learning::traceWithSom;

/** Generates points scattered near the circumference of a circle.
 * \param[out] data matrix to fill with generated points
 */
void makeCircleData(std::vector<std::valarray<double>> *data) {
    const int N = data->size();
    const double radius = 0.75, spread = 0.3;
    double thetaLo = 0., thetaHi = 2.f * M_PI;
    double radiusLo = radius - spread, radiusHi = radius + spread;
    int i = 0;

#ifdef _OPENMP
#pragma omp for
#endif
    for (i = 0; i < N; i++) {
        double r = drawUniform(radiusLo, radiusHi);
        double theta = drawUniform(thetaLo, thetaHi);
        data[0][i][0] = r * cos(theta);
        data[0][i][1] = r * sin(theta);
    }
}

/** Scenario 1: trace a circular dataset. Writes test1.csv, w11.csv, w12.csv. */
void scenarioCircle() {
    int j = 0, N = 500;
    int dims = 2;
    int chainLen = 50;
    std::vector<std::valarray<double>> X(N);
    std::vector<std::valarray<double>> W(chainLen);
    for (int i = 0; i < std::max(chainLen, N); i++) {
        if (i < N) {
            X[i] = std::valarray<double>(dims);
        }
        if (i < chainLen) {
            W[i] = std::valarray<double>(dims);
#ifdef _OPENMP
#pragma omp for
#endif
            for (j = 0; j < dims; j++) {
                W[i][j] = drawUniform(-1, 1);
            }
        }
    }

    makeCircleData(&X);
    writePointsCsv("test1.csv", X);
    writePointsCsv("w11.csv", W);
    traceWithSom(X, &W, 0.1);
    writePointsCsv("w12.csv", W);
}

/** Generates points scattered near the Lemniscate of Gerono curve.
 * \param[out] data matrix to fill with generated points
 */
void makeLemniscateData(std::vector<std::valarray<double>> *data) {
    const int N = data->size();
    const double spread = 0.2;
    int i = 0;

#ifdef _OPENMP
#pragma omp for
#endif
    for (i = 0; i < N; i++) {
        double dx = drawUniform(-spread, spread);
        double dy = drawUniform(-spread, spread);
        double theta = drawUniform(0, M_PI);
        data[0][i][0] = dx + cos(theta);
        data[0][i][1] = dy + sin(2. * theta) / 2.f;
    }
}

/** Scenario 2: trace a lemniscate dataset. Writes test2.csv, w21.csv, w22.csv. */
void scenarioLemniscate() {
    int j = 0, N = 500;
    int dims = 2;
    int chainLen = 20;
    std::vector<std::valarray<double>> X(N);
    std::vector<std::valarray<double>> W(chainLen);
    for (int i = 0; i < std::max(chainLen, N); i++) {
