            X[i] = std::valarray<double>(dims);
        }
        if (i < chainLen) {
            W[i] = std::valarray<double>(dims);
#ifdef _OPENMP
#pragma omp for
#endif
            for (j = 0; j < dims; j++) {
                W[i][j] = drawUniform(-1, 1);
            }
        }
    }

    makeLemniscateData(&X);
    writePointsCsv("test2.csv", X);
    writePointsCsv("w21.csv", W);
    traceWithSom(X, &W, 0.01);
    writePointsCsv("w22.csv", W);
}

/** Generates points scattered around eight cluster centers in 3D space.
 * \param[out] data matrix to fill with generated points
 */
void makeEightClusterData(std::vector<std::valarray<double>> *data) {
    const int N = data->size();
    const double R = 0.1;
    int i = 0;
    const int classCount = 8;
    const std::array<const std::array<double, 3>, classCount> centers = {
        std::array<double, 3>({.5, .5, .5}), std::array<double, 3>({.5, .5, -.5}),
        std::array<double, 3>({.5, -.5, .5}), std::array<double, 3>({.5, -.5, -.5}),
        std::array<double, 3>({-.5, .5, .5}), std::array<double, 3>({-.5, .5, -.5}),
        std::array<double, 3>({-.5, -.5, .5}), std::array<double, 3>({-.5, -.5, -.5})};

#ifdef _OPENMP
#pragma omp for
#endif
    for (i = 0; i < N; i++) {
        int cls = std::rand() % classCount;
        data[0][i][0] = drawUniform(centers[cls][0] - R, centers[cls][0] + R);
        data[0][i][1] = drawUniform(centers[cls][1] - R, centers[cls][1] + R);
        data[0][i][2] = drawUniform(centers[cls][2] - R, centers[cls][2] + R);
    }
}

/** Scenario 3: trace an eight-cluster 3D dataset. Writes test3.csv, w31.csv, w32.csv. */
void scenarioEightClusters() {
    int j = 0, N = 200;
    int dims = 3;
    int chainLen = 20;
    std::vector<std::valarray<double>> X(N);
    std::vector<std::valarray<double>> W(chainLen);
