            W[i] = std::valarray<double>(dims);
#ifdef _OPENMP
#pragma omp for
#endif
            for (j = 0; j < dims; j++) {
                W[i][j] = drawUniform(-1, 1);
            }
        }
    }

    makeEightClusterData(&X);
    writePointsCsv("test3.csv", X);
    writePointsCsv("w31.csv", W);
    traceWithSom(X, &W, 0.01);
    writePointsCsv("w32.csv", W);
}

/**
 * Converts a pair of clock readings into elapsed seconds.
 * \param[in] startTick start clock reading
 * \param[in] endTick end clock reading
 * \returns elapsed seconds
 */
double elapsedSeconds(clock_t startTick, clock_t endTick) {
    return static_cast<double>(endTick - startTick) / CLOCKS_PER_SEC;
}

