/**
 * @file
 * @brief Rewritten fast Fibonacci generator using simple iterative
 * accumulation of state between calls.
 *
 * @details
 * Instead of relying on matrix exponentiation (O(n log n)), this variant
 * keeps two running values across calls to produce successive Fibonacci
 * numbers in O(1) amortized time per call, similar in spirit to the
 * standard "keep the last two terms" technique. Because uint64_t overflows
 * beyond the 92nd term, we explicitly reject requests at or above that
 * ceiling.
 *
 * @see fibonacci_large.cpp, fibonacci.cpp, string_fibonacci.cpp
 */
#include <cinttypes>  /// fixed width integer types
#include <cstdio>     /// standard C IO
#include <iostream>   /// C++ IO
#include <cassert>    /// assertion checks
#include <string>     /// std::to_string
#include <stdexcept>  /// std::invalid_argument

/**
 * @brief One past the largest Fibonacci index representable in a
 * uint64_t.
 */
constexpr uint64_t FIB_LIMIT = 93;

/**
 * @brief Produces the n-th Fibonacci number, remembering prior state
 * between invocations.
 * @param n index to compute (must be less than FIB_LIMIT)
 * @return the requested Fibonacci number
 */
uint64_t running_fibonacci(uint64_t n) {
    // These persist across calls so we don't redo earlier work.
    static uint64_t prev = 1, curr = 1;

    if (n <= 2) {
        return curr;
    }
    if (n >= FIB_LIMIT) {
        throw std::invalid_argument(
            "Cannot compute for n>=" + std::to_string(FIB_LIMIT) +
            " due to limit of 64-bit integers");
    }

    uint64_t next_prev = curr;
    curr += prev;
    prev = next_prev;

    return curr;
}

