/**
 * @file
 * @brief C++ Program to find the modular inverse using [Fermat's Little
 * Theorem](https://en.wikipedia.org/wiki/Fermat%27s_little_theorem)
 *
 * Fermat's Little Theorem state that \f[ϕ(m) = m-1\f]
 * where \f$m\f$ is a prime number.
 * \f{eqnarray*}{
 *  a \cdot x &≡& 1 \;\text{mod}\; m\\
 *  x &≡& a^{-1} \;\text{mod}\; m
 * \f}
 * Using Euler's theorem we can modify the equation.
 *\f[
 * a^{ϕ(m)} ≡ 1 \;\text{mod}\; m
 * \f]
 * (Where '^' denotes the exponent operator)
 *
 * Here 'ϕ' is Euler's Totient Function. For modular inverse existence 'a' and
 * 'm' must be relatively primes numbers. To apply Fermat's Little Theorem is
 * necessary that 'm' must be a prime number. Generally in many competitive
 * programming competitions 'm' is either 1000000007 (1e9+7) or 998244353.
 *
 * We considered m as large prime (1e9+7).
 * \f$a^{ϕ(m)} ≡ 1 \;\text{mod}\; m\f$ (Using Euler's Theorem)
 * \f$ϕ(m) = m-1\f$ using Fermat's Little Theorem.
 * \f$a^{m-1} ≡ 1 \;\text{mod}\; m\f$
 * Now multiplying both side by \f$a^{-1}\f$.
 * \f{eqnarray*}{
 * a^{m-1} \cdot a^{-1} &≡& a^{-1} \;\text{mod}\; m\\
 * a^{m-2} &≡&  a^{-1} \;\text{mod}\; m
 * \f}
 *
 * We will find the exponent using binary exponentiation such that the
 * algorithm works in \f$O(\log n)\f$ time.
 *
 * Examples: -
 * * a = 3 and m = 7
 * * \f$a^{-1} \;\text{mod}\; m\f$ is equivalent to
 * \f$a^{m-2} \;\text{mod}\; m\f$
 * * \f$3^5 \;\text{mod}\; 7 = 243 \;\text{mod}\; 7 = 5\f$
 * <br/>Hence, \f$3^{-1} \;\text{mod}\; 7 = 5\f$
 * or \f$3 \times 5  \;\text{mod}\; 7 = 1 \;\text{mod}\; 7\f$
 * (as \f$a\times a^{-1} = 1\f$)
 */

#include <cassert>  /// for assert
#include <cstdint>  /// for std::int64_t
#include <iostream> /// for IO implementations

/**
 * @namespace math
 * @brief Maths algorithms.
 */
namespace math {
/**
 * @namespace modular_inverse_fermat
 * @brief Calculate modular inverse using Fermat's Little Theorem.
 */
namespace modular_inverse_fermat {
/**
 * @brief Calculate exponent with modulo using binary exponentiation in \f$O(\log b)\f$ time.
 * @param a The base
 * @param b The exponent
 * @param m The modulo
 * @return The result of \f$a^{b} % m\f$
 */
std::int64_t binExpo(std::int64_t a, std::int64_t b, std::int64_t m) {
  a %= m;
  std::int64_t res = 1;
  while (b > 0) {
    if (b % 2 != 0) {
      res = res * a % m;
    }
    a = a * a % m;
    // Dividing b by 2 is similar to right shift by 1 bit
    b >>= 1;
  }
  return res;
}
/**
 * @brief Check if an integer is a prime number in \f$O(\sqrt{m})\f$ time.
 * @param m An intger to check for primality
 * @return true if the number is prime
 * @return false if the number is not prime
 */
bool isPrime(std::int64_t m) {
  if (m <= 1) {
    return false;
  } 
  for (std::int64_t i = 2; i * i <= m; i++) {
    if (m % i == 0) {
      return false;
    }
  }
  return true;
}
/**
 * @brief calculates the modular inverse.
 * @param a Integer value for the base
 * @param m Integer value for modulo
 * @return The result that is the modular inverse of a modulo m
 */
std::int64_t modular_inverse(std::int64_t a, std::int64_t m) {
  while (a < 0) {
    a += m;
  }

  // Check for invalid cases
  if (!isPrime(m) || a == 0) {
    return -1; // Invalid input
  }

  return binExpo(a, m - 2, m);  // Fermat's Little Theorem
}
} // namespace modular_inverse_fermat
} // namespace math

/**
 * @brief Self-test implementation
 * @return void
 */
static void test() {
  assert(math::modular_inverse_fermat::modular_inverse(0, 97) == -1);
  assert(math::modular_inverse_fermat::modular_inverse(15, -2) == -1);
  assert(math::modular_inverse_fermat::modular_inverse(3, 10) == -1);
  assert(math::modular_inverse_fermat::modular_inverse(3, 7) == 5);
  assert(math::modular_inverse_fermat::modular_inverse(1, 101) == 1);
  assert(math::modular_inverse_fermat::modular_inverse(-1337, 285179) == 165519);
  assert(math::modular_inverse_fermat::modular_inverse(123456789, 998244353) == 25170271);
  assert(math::modular_inverse_fermat::modular_inverse(-9876543210, 1000000007) == 784794281);
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
  test();  // run self-test implementation
  return 0;
}

/**
 * @file
 * @brief Compute a modular multiplicative inverse via Fermat's little
 * theorem.
 * @details
 * For a prime modulus `m` and any `a` not divisible by `m`, Fermat's little
 * theorem tells us `a^(m-1) = 1 (mod m)`. Multiplying both sides by `a^-1`
 * gives `a^(m-2) = a^-1 (mod m)`. So the inverse of `a` modulo the prime `m`
 * is just `a` raised to the `(m-2)`-th power, modulo `m`, which we compute
 * efficiently with binary exponentiation in O(log m) time.
 *
 * This only works when `m` is prime (so that `a` and `m` are guaranteed
 * coprime whenever `a % m != 0`); the implementation checks primality first
 * and reports failure otherwise.
 *
 * Worked example: a = 3, m = 7.
 *   3^-1 mod 7 == 3^(7-2) mod 7 == 3^5 mod 7 == 243 mod 7 == 5.
 *   Check: 3 * 5 mod 7 == 15 mod 7 == 1, as expected.
 */

#include <cassert>
#include <cstdint>
#include <iostream>

namespace math {
namespace modular_inverse_fermat {

/**
 * Determines whether `candidate` is a prime number by trial division up to
 * its square root.
 */
bool is_prime_number(std::int64_t candidate) {
    if (candidate <= 1) {
        return false;
    }
    for (std::int64_t divisor = 2; divisor * divisor <= candidate;
         ++divisor) {
        if (candidate % divisor == 0) {
            return false;
        }
    }
    return true;
}

/**
 * Computes (base ^ exponent) mod modulus using iterative square-and-multiply.
 */
std::int64_t pow_mod(std::int64_t base, std::int64_t exponent,
                      std::int64_t modulus) {
    std::int64_t b = base % modulus;
    std::int64_t result = 1;

    while (exponent > 0) {
        if (exponent % 2 != 0) {
            result = result * b % modulus;
        }
        b = b * b % modulus;
        exponent >>= 1;  // same as dividing the exponent by two
    }
    return result;
}

/**
 * Finds the modular inverse of `value` modulo `modulus`, assuming `modulus`
 * is prime. Returns -1 if the request is invalid (non-prime modulus, or a
 * value that is a multiple of the modulus after normalization).
 */
std::int64_t modular_inverse(std::int64_t value, std::int64_t modulus) {
    std::int64_t normalized = value;
    while (normalized < 0) {
        normalized += modulus;
    }

    if (!is_prime_number(modulus) || normalized == 0) {
        return -1;
    }

    return pow_mod(normalized, modulus - 2, modulus);
}

}  // namespace modular_inverse_fermat
}  // namespace math

/**
 * Verifies modular_inverse against a collection of known input/output pairs.
 */
static void run_inverse_checks() {
    using math::modular_inverse_fermat::modular_inverse;

    assert(modular_inverse(0, 97) == -1);
    assert(modular_inverse(15, -2) == -1);
    assert(modular_inverse(3, 10) == -1);
    assert(modular_inverse(3, 7) == 5);
    assert(modular_inverse(1, 101) == 1);
    assert(modular_inverse(-1337, 285179) == 165519);
    assert(modular_inverse(123456789, 998244353) == 25170271);
    assert(modular_inverse(-9876543210, 1000000007) == 784794281);

    std::cout << "All modular inverse checks passed." << std::endl;
}

int main() {
    run_inverse_checks();
    return 0;
}

/**
 * @file
 * @brief Simple implementation of [modular multiplicative
 * inverse](https://en.wikipedia.org/wiki/Modular_multiplicative_inverse)
 *
 * @details
 * this algorithm calculates the modular inverse x^{-1} \mod y iteratively
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations

/**
 * @brief Function imod
 * Calculates the modular inverse of x with respect to y, x^{-1} \mod y
 * @param x number
 * @param y number
 * @returns the modular inverse
 */
uint64_t imod(uint64_t x, uint64_t y) {
    uint64_t aux = 0;  // auxiliary variable
    uint64_t itr = 0;  // iteration counter

    do {  // run the algorithm while not find the inverse
        aux = y * itr + 1;
        itr++;
    } while (aux % x);  // while module aux % x non-zero

    return aux / x;
}

/**
 * @brief  self-test implementations
 * @returns void
 */
static void test() {
    std::cout << "First case testing... \n";
    // for a = 3 and b = 11 return 4
    assert(imod(3, 11) == 4);
    std::cout << "\nPassed!\n";

    std::cout << "Second case testing... \n";
    // for a = 3 and b = 26 return 9
    assert(imod(3, 26) == 9);
    std::cout << "\nPassed!\n";

    std::cout << "Third case testing... \n";
    // for a = 7 and b = 26 return 15
    assert(imod(7, 26) == 15);
    std::cout << "\nPassed!\n";

    std::cout << "\nAll test cases have successfully passed!\n";
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
};

/**
 * @file
 * @brief Brute-force computation of the modular multiplicative inverse.
 *
 * @details
 * Given two coprime integers `value` and `modulus`, we search linearly
 * for an integer `k` such that (modulus * k + 1) is evenly divisible by
 * `value`. The quotient of that division is the modular inverse we want,
 * i.e. the number x satisfying (value * x) % modulus == 1.
 */

#include <cassert>   /// brings in assert()
#include <cstdint>   /// fixed width integer types
#include <iostream>  /// console output for the demo

/**
 * @brief Computes the modular inverse of `value` modulo `modulus`.
 * @param value the number whose inverse we are looking for
 * @param modulus the modulus with respect to which we invert
 * @return the modular inverse of value mod modulus
 */
uint64_t find_modular_inverse(uint64_t value, uint64_t modulus) {
    uint64_t candidate_numerator = 0;  // candidate = modulus * k + 1
    uint64_t k = 0;                    // search counter

    while (true) {
        candidate_numerator = modulus * k + 1;
        if (candidate_numerator % value == 0) {
            break;  // found a numerator divisible by value
        }
        k++;
    }

    return candidate_numerator / value;
}

/**
 * @brief Runs a handful of hand-checked cases against find_modular_inverse.
 */
static void run_examples() {
    std::cout << "Checking case 1 (3, 11)...\n";
    assert(find_modular_inverse(3, 11) == 4);
    std::cout << "ok\n";

    std::cout << "Checking case 2 (3, 26)...\n";
    assert(find_modular_inverse(3, 26) == 9);
    std::cout << "ok\n";

    std::cout << "Checking case 3 (7, 26)...\n";
    assert(find_modular_inverse(7, 26) == 15);
    std::cout << "ok\n";

    std::cout << "\nEverything checked out fine!\n";
}

/**
 * @brief Program entry point.
 * @return 0 always
 */
int main() {
    run_examples();
    return 0;
}

/**
 * @file
 * @brief Compute powers of large numbers
 */
#include <iostream>

/** Maximum number of digits in output
 *  \f$x^n\f$ where \f$1 <= x,\; n <= 10000\f$ and overflow may happen
 */
#define MAX 100000

/** This function multiplies x
 * with the number represented by res[].
 * res_size is size of res[] or
 * number of digits in the number
 * represented by res[]. This function
 * uses simple school mathematics
 * for multiplication.
 * This function may value of res_size
 * and returns the new value of res_size
 * @param x multiplicand
 * @param res large number representation using array
 * @param res_size number of digits in `res`
 */
int multiply(int x, int res[], int res_size) {
    // Initialize carry
    int carry = 0;

    // One by one multiply n with
    // individual digits of res[]
    for (int i = 0; i < res_size; i++) {
        int prod = res[i] * x + carry;

        // Store last digit of
        // 'prod' in res[]
        res[i] = prod % 10;

        // Put rest in carry
        carry = prod / 10;
    }

    // Put carry in res and
    // increase result size
    while (carry) {
        res[res_size] = carry % 10;
        carry = carry / 10;
        res_size++;
    }
    return res_size;
}

/** This function finds power of a number x and print \f$x^n\f$
 * @param x base
 * @param n exponent
 */
void power(int x, int n) {
    // printing value "1" for power = 0
    if (n == 0) {
        std::cout << "1";
        return;
    }

    int res[MAX];
    int res_size = 0;
    int temp = x;

    // Initialize result
    while (temp != 0) {
        res[res_size++] = temp % 10;
        temp = temp / 10;
    }

    // Multiply x n times
    // (x^n = x*x*x....n times)
    for (int i = 2; i <= n; i++) res_size = multiply(x, res, res_size);

    std::cout << x << "^" << n << " = ";
    for (int i = res_size - 1; i >= 0; i--) std::cout << res[i];
}

/** Main function */
int main() {
    int exponent, base;
    std::cout << "Enter base ";
    std::cin >> base;
    std::cout << "Enter exponent ";
    std::cin >> exponent;
    power(base, exponent);
    return 0;
}

/**
 * @file
 * @brief Raise an integer to a (possibly large) integer power using
 * arbitrary-precision arithmetic emulated with a digit array.
 *
 * Since native integer types overflow quickly for something like 9999^9999,
 * we keep the intermediate/result value as an array of base-10 digits and
 * perform manual long multiplication against it at every step.
 */
#include <iostream>

/// Upper bound on how many decimal digits the result can hold.
constexpr int kDigitCapacity = 100000;

/**
 * Multiplies the big number stored in `digits` (least-significant digit
 * first) by the scalar `factor`, writing the product back into `digits`.
 *
 * @param factor      the small integer to multiply by
 * @param digits      digit array representing the big number so far
 * @param digit_count  how many digits are currently populated in `digits`
 * @return updated digit count after the multiplication (may grow)
 */
int scaleBigNumber(int factor, int digits[], int digit_count) {
    int carry_over = 0;

    // Classic grade-school multiplication, one digit at a time.
    for (int idx = 0; idx < digit_count; ++idx) {
        int column_value = digits[idx] * factor + carry_over;
        digits[idx] = column_value % 10;
        carry_over = column_value / 10;
    }

    // Flush whatever carry remains into new higher-order digits.
    while (carry_over > 0) {
        digits[digit_count] = carry_over % 10;
        carry_over /= 10;
        ++digit_count;
    }

    return digit_count;
}

/**
 * Computes base^exponent for potentially huge results and prints it.
 *
 * @param base      the number being raised to a power
 * @param exponent  how many times to multiply base by itself
 */
void printHugePower(int base, int exponent) {
    if (exponent == 0) {
        std::cout << "1";
        return;
    }

    int digits[kDigitCapacity];
    int digit_count = 0;

    // Seed the digit array with the base value itself.
    int remaining = base;
    while (remaining != 0) {
        digits[digit_count] = remaining % 10;
        ++digit_count;
        remaining /= 10;
    }

    // Apply (exponent - 1) additional multiplications by base.
    for (int step = 2; step <= exponent; ++step) {
        digit_count = scaleBigNumber(base, digits, digit_count);
    }

    std::cout << base << "^" << exponent << " = ";
    for (int idx = digit_count - 1; idx >= 0; --idx) {
        std::cout << digits[idx];
    }
}

/** Entry point: reads base and exponent from stdin and prints base^exponent. */
int main() {
    int base_value = 0;
    int exponent_value = 0;

    std::cout << "Enter base ";
    std::cin >> base_value;
    std::cout << "Enter exponent ";
    std::cin >> exponent_value;

    printHugePower(base_value, exponent_value);
    return 0;
}

/**
 * @file
 *
 * @brief Calculates the [Cross
 *Product](https://en.wikipedia.org/wiki/Cross_product) and the magnitude of two
 *mathematical 3D vectors.
 *
 *
 * @details Cross Product of two vectors gives a vector.
 * Direction Ratios of a vector are the numeric parts of the given vector. They
 *are the tree parts of the vector which determine the magnitude (value) of the
 *vector. The method of finding a cross product is the same as finding the
 *determinant of an order 3 matrix consisting of the first row with unit vectors
 *of magnitude 1, the second row with the direction ratios of the first vector
 *and the third row with the direction ratios of the second vector. The
 *magnitude of a vector is it's value expressed as a number. Let the direction
 *ratios of the first vector, P be: a, b, c Let the direction ratios of the
 *second vector, Q be: x, y, z Therefore the calculation for the cross product
 *can be arranged as:
 *
 * ```
 * P x Q:
 *  	1	1	1
 *  	a	b	c
 *  	x	y	z
 * ```
 *
 * The direction ratios (DR) are calculated as follows:
 *  	1st DR, J:  (b * z) - (c * y)
 *  	2nd DR, A: -((a * z) - (c * x))
 *  	3rd DR, N:  (a * y) - (b * x)
 *
 * Therefore, the direction ratios of the cross product are: J, A, N
 * The following C++ Program calculates the direction ratios of the cross
 *products of two vector. The program uses a function, cross() for doing so. The
 *direction ratios for the first and the second vector has to be passed one by
 *one seperated by a space character.
 *
 * Magnitude of a vector is the square root of the sum of the squares of the
 *direction ratios.
 *
 * ### Example:
 * An example of a running instance of the executable program:
 *
 * 	Pass the first Vector: 1 2 3
 *	Pass the second Vector: 4 5 6
 *	The cross product is: -3 6 -3
 *	Magnitude: 7.34847
 *
 * @author [Shreyas Sable](https://github.com/Shreyas-OwO)
 */

#include <array>
#include <cassert>
#include <cmath>

/**
 * @namespace math
 * @brief Math algorithms
 */
namespace math {
/**
 * @namespace vector_cross
 * @brief Functions for Vector Cross Product algorithms
 */
namespace vector_cross {
/**
 * @brief Function to calculate the cross product of the passed arrays
 * containing the direction ratios of the two mathematical vectors.
 * @param A contains the direction ratios of the first mathematical vector.
 * @param B contains the direction ration of the second mathematical vector.
 * @returns the direction ratios of the cross product.
 */
std::array<double, 3> cross(const std::array<double, 3> &A,
                            const std::array<double, 3> &B) {
    std::array<double, 3> product;
    /// Performs the cross product as shown in @algorithm.
    product[0] = (A[1] * B[2]) - (A[2] * B[1]);
    product[1] = -((A[0] * B[2]) - (A[2] * B[0]));
    product[2] = (A[0] * B[1]) - (A[1] * B[0]);
    return product;
}

/**
 * @brief Calculates the magnitude of the mathematical vector from it's
 * direction ratios.
 * @param vec an array containing the direction ratios of a mathematical vector.
 * @returns type: double description: the magnitude of the mathematical vector
 * from the given direction ratios.
 */
double mag(const std::array<double, 3> &vec) {
    double magnitude =
        sqrt((vec[0] * vec[0]) + (vec[1] * vec[1]) + (vec[2] * vec[2]));
    return magnitude;
}
}  // namespace vector_cross
}  // namespace math

/**
 * @brief test function.
 * @details test the cross() and the mag() functions.
 */
static void test() {
    /// Tests the cross() function.
    std::array<double, 3> t_vec =
        math::vector_cross::cross({1, 2, 3}, {4, 5, 6});
    assert(t_vec[0] == -3 && t_vec[1] == 6 && t_vec[2] == -3);

    /// Tests the mag() function.
    double t_mag = math::vector_cross::mag({6, 8, 0});
    assert(t_mag == 10);

    /// Tests A ⨯ A = 0
    std::array<double, 3> t_vec2 =
        math::vector_cross::cross({1, 2, 3}, {1, 2, 3});
    assert(t_vec2[0] == 0 && t_vec2[1] == 0 &&
           t_vec2[2] == 0);  // checking each element
    assert(math::vector_cross::mag(t_vec2) ==
           0);  // checking the magnitude is also zero
}

/**
 * @brief Main Function
 * @details Asks the user to enter the direction ratios for each of the two
 * mathematical vectors using std::cin
 * @returns 0 on exit
 */
int main() {
    /// Tests the functions with sample input before asking for user input.
    test();
    return 0;
}

/**
 * @file
 *
 * @brief Reworked demo of computing the 3D cross product and vector norm.
 *
 * @details Given two vectors P = (a, b, c) and Q = (x, y, z), their cross
 * product P x Q yields a new vector whose components can be derived from
 * the determinant expansion of a 3x3 matrix built from the unit basis
 * vectors and the direction numbers of P and Q:
 *
 * ```
 * P x Q:
 *      1   1   1
 *      a   b   c
 *      x   y   z
 * ```
 *
 * Expanding that determinant gives the components:
 *      comp0 =  (b * z) - (c * y)
 *      comp1 = -((a * z) - (c * x))
 *      comp2 =  (a * y) - (b * x)
 *
 * The Euclidean norm (magnitude) of a vector is simply the square root of
 * the sum of the squares of its components.
 *
 * This file re-implements that idea with different naming/structure than
 * the reference version, purely for dataset/style-comparison purposes.
 */

#include <array>
#include <cassert>
#include <cmath>

/**
 * @namespace math
 * @brief Collection of math routines.
 */
namespace math {
/**
 * @namespace vector_ops
 * @brief Helpers for basic 3D vector arithmetic.
 */
namespace vector_ops {

using Vec3 = std::array<double, 3>;

/**
 * @brief Computes the cross product of two 3-component vectors.
 * @param lhs first operand vector
 * @param rhs second operand vector
 * @return resulting perpendicular vector
 */
Vec3 cross_product(const Vec3 &lhs, const Vec3 &rhs) {
    Vec3 result{};

    result[0] = lhs[1] * rhs[2] - lhs[2] * rhs[1];
    result[1] = lhs[2] * rhs[0] - lhs[0] * rhs[2];
    result[2] = lhs[0] * rhs[1] - lhs[1] * rhs[0];

    return result;
}

/**
 * @brief Computes the Euclidean length of a 3-component vector.
 * @param v vector whose length is requested
 * @return scalar magnitude of v
 */
double length_of(const Vec3 &v) {
    double sum_of_squares = 0.0;
    for (double component : v) {
        sum_of_squares += component * component;
    }
    return std::sqrt(sum_of_squares);
}

}  // namespace vector_ops
}  // namespace math

/**
 * @brief Runs a handful of sanity checks against known results.
 */
static void run_self_checks() {
    using math::vector_ops::Vec3;

    // Basic cross product check against a known pair.
    Vec3 first = {1, 2, 3};
    Vec3 second = {4, 5, 6};
    Vec3 crossed = math::vector_ops::cross_product(first, second);
    assert(crossed[0] == -3);
    assert(crossed[1] == 6);
    assert(crossed[2] == -3);

    // Magnitude check on a well known 3-4-5-like triple.
    Vec3 sample = {6, 8, 0};
    double norm_value = math::vector_ops::length_of(sample);
    assert(norm_value == 10);

    // A vector crossed with itself must be the zero vector, magnitude 0.
    Vec3 self_cross = math::vector_ops::cross_product(first, first);
    bool all_zero = true;
    for (double c : self_cross) {
        if (c != 0) {
            all_zero = false;
        }
    }
    assert(all_zero);
    assert(math::vector_ops::length_of(self_cross) == 0);
}

/**
 * @brief Entry point that triggers the self checks.
 * @return 0 on success
 */
int main() {
    run_self_checks();
    return 0;
}

/**
 * @file
 * @brief Implmentations for the [volume](https://en.wikipedia.org/wiki/Volume)
 * of various 3D shapes.
 * @details The volume of a 3D shape is the amount of 3D space that the shape
 * takes up. All shapes have a formula to get the volume of any given shape.
 * These implementations support multiple return types.
 *
 * @author [Focusucof](https://github.com/Focusucof)
 */

#include <cassert>   /// for assert
#include <cmath>     /// for std::pow
#include <cstdint>   /// for std::uint32_t
#include <iostream>  /// for IO operations

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @brief The volume of a [cube](https://en.wikipedia.org/wiki/Cube)
 * @param length The length of the cube
 * @returns The volume of the cube
 */
template <typename T>
T cube_volume(T length) {
    return std::pow(length, 3);
}

/**
 * @brief The volume of a
 * [rectangular](https://en.wikipedia.org/wiki/Cuboid) prism
 * @param length The length of the base rectangle
 * @param width The width of the base rectangle
 * @param height The height of the rectangular prism
 * @returns The volume of the rectangular prism
 */
template <typename T>
T rect_prism_volume(T length, T width, T height) {
    return length * width * height;
}

/**
 * @brief The volume of a [cone](https://en.wikipedia.org/wiki/Cone)
 * @param radius The radius of the base circle
 * @param height The height of the cone
 * @param PI The definition of the constant PI
 * @returns The volume of the cone
 */
template <typename T>
T cone_volume(T radius, T height, double PI = 3.14) {
    return std::pow(radius, 2) * PI * height / 3;
}

/**
 * @brief The volume of a
 * [triangular](https://en.wikipedia.org/wiki/Triangular_prism) prism
 * @param base The length of the base triangle
 * @param height The height of the base triangles
 * @param depth The depth of the triangular prism (the height of the whole
 * prism)
 * @returns The volume of the triangular prism
 */
template <typename T>
T triangle_prism_volume(T base, T height, T depth) {
    return base * height * depth / 2;
}

/**
 * @brief The volume of a
 * [pyramid](https://en.wikipedia.org/wiki/Pyramid_(geometry))
 * @param length The length of the base shape (or base for triangles)
 * @param width The width of the base shape (or height for triangles)
 * @param height The height of the pyramid
 * @returns The volume of the pyramid
 */
template <typename T>
T pyramid_volume(T length, T width, T height) {
    return length * width * height / 3;
}

/**
 * @brief The volume of a [sphere](https://en.wikipedia.org/wiki/Sphere)
 * @param radius The radius of the sphere
 * @param PI The definition of the constant PI
 * @returns The volume of the sphere
 */
template <typename T>
T sphere_volume(T radius, double PI = 3.14) {
    return PI * std::pow(radius, 3) * 4 / 3;
}

/**
 * @brief The volume of a [cylinder](https://en.wikipedia.org/wiki/Cylinder)
 * @param radius The radius of the base circle
 * @param height The height of the cylinder
 * @param PI The definition of the constant PI
 * @returns The volume of the cylinder
 */
template <typename T>
T cylinder_volume(T radius, T height, double PI = 3.14) {
    return PI * std::pow(radius, 2) * height;
}
}  // namespace math

/**
