// Rightward circular rotation of an array's contents.
// Builds a brand-new vector holding the rotated sequence instead of
// mutating the caller's data.

#include <cassert>
#include <iostream>
#include <vector>

namespace operations_on_datastructures {
namespace array_rotation_right {

// Dumps every element of the vector to stdout, space separated.
void display(const std::vector<int32_t> &values) {
    for (size_t idx = 0; idx < values.size(); ++idx) {
        std::cout << values[idx] << ' ';
    }
    std::cout << '\n';
}

// Produces a copy of `values` rotated `offset` positions to the right.
// The trailing `offset` elements are wrapped around to the front.
// If `offset` is not strictly smaller than the container size, the
// request is considered invalid and an empty vector is handed back.
std::vector<int32_t> rotate_right(const std::vector<int32_t> &values,
                                   size_t offset) {
    const size_t n = values.size();
    if (offset >= n) {
        return {};
    }

    std::vector<int32_t> rotated(n);

    size_t write_pos = 0;
    // Wrapped tail goes first.
    for (size_t src = n - offset; src < n; ++src) {
        rotated[write_pos++] = values[src];
    }
    // Then the untouched head portion follows.
    for (size_t src = 0; src < n - offset; ++src) {
        rotated[write_pos++] = values[src];
    }

    return rotated;
}

}  // namespace array_rotation_right
}  // namespace operations_on_datastructures

namespace self_checks {
using operations_on_datastructures::array_rotation_right::display;
using operations_on_datastructures::array_rotation_right::rotate_right;

// Basic rotation with a mid-range offset.
void check_basic_rotation() {
    std::cout << "[check_basic_rotation]\n";
    std::vector<int32_t> input = {10, 20, 30, 40, 50};
    std::vector<int32_t> want = {40, 50, 10, 20, 30};
    std::vector<int32_t> got = rotate_right(input, 2);
    assert(got == want);
    display(got);
    std::cout << "ok\n\n";
}

// Rotating an empty container should yield an empty container.
void check_empty_input() {
    std::cout << "[check_empty_input]\n";
    std::vector<int32_t> input;
    std::vector<int32_t> got = rotate_right(input, 3);
    assert(got.empty());
    display(got);
    std::cout << "ok\n\n";
}

// Offset larger than the vector length is treated as invalid.
void check_offset_out_of_range() {
    std::cout << "[check_offset_out_of_range]\n";
    std::vector<int32_t> input = {5, 6, 7};
    std::vector<int32_t> got = rotate_right(input, 9);
    assert(got.empty());
    display(got);
    std::cout << "ok\n\n";
}

// Larger scale sanity check on a generated sequence.
void check_large_sequence() {
    std::cout << "[check_large_sequence]\n";
    std::vector<int32_t> input;
    for (int i = 1; i <= 150; ++i) {
        input.push_back(i * 3);
    }
    std::vector<int32_t> got = rotate_right(input, 1);

    std::vector<int32_t> expected;
    expected.push_back(input.back());
    for (size_t i = 0; i + 1 < input.size(); ++i) {
        expected.push_back(input[i]);
    }

    assert(got == expected);
    std::cout << "ok (first few: " << got[0] << ' ' << got[1] << ' ' << got[2]
               << " ...)\n\n";
}

// Rotating by zero must leave the sequence unchanged.
void check_zero_offset() {
    std::cout << "[check_zero_offset]\n";
    std::vector<int32_t> input = {7, 8, 9, 10};
    std::vector<int32_t> got = rotate_right(input, 0);
    assert(got == input);
    display(got);
    std::cout << "ok\n\n";
}

void run_all() {
    check_basic_rotation();
    check_empty_input();
    check_offset_out_of_range();
    check_large_sequence();
    check_zero_offset();
}

}  // namespace self_checks

int main() {
    self_checks::run_all();
    return 0;
}

/**
 * @file
 * @brief Implementation for the [Intersection of two sorted
 * Arrays](https://en.wikipedia.org/wiki/Intersection_(set_theory))
 * algorithm.
 * @details The intersection of two arrays is the collection of all the elements
 * that are common in both the first and second arrays. This implementation uses
 * ordered arrays, and an algorithm to correctly order them and return the
 * result as a new array (vector).
 * @see union_of_two_arrays.cpp
 * @author [Alvin](https://github.com/polarvoid)
 */

#include <algorithm>  /// for std::sort
#include <cassert>    /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * @brief Prints the values of a vector sequentially, ending with a newline
 * character.
 * @param array Reference to the array to be printed
 * @returns void
 */
void print(const std::vector<int32_t> &array) {
    for (int32_t i : array) {
        std::cout << i << " ";  /// Print each value in the array
    }
    std::cout << "\n";  /// Print newline
}

/**
 * @brief Gets the intersection of two sorted arrays, and returns them in a
 * vector.
 * @details An algorithm is used that compares the elements of the two vectors,
 * incrementing the index of the smaller of the two. If the elements are the
 * same, the element is appended to the result array to be returned.
 * @param first A std::vector of sorted integer values
 * @param second A std::vector of sorted integer values
 * @returns A std::vector of the intersection of the two arrays, in ascending
 * order
 */
std::vector<int32_t> get_intersection(const std::vector<int32_t> &first,
                                      const std::vector<int32_t> &second) {
    std::vector<int32_t> res;         ///< Vector to hold the intersection
    size_t f_index = 0;               ///< Index for the first array
    size_t s_index = 0;               ///< Index for the second array
    size_t f_length = first.size();   ///< Length of first array
    size_t s_length = second.size();  ///< Length of second array

    while (f_index < f_length && s_index < s_length) {
        if (first[f_index] < second[s_index]) {
            f_index++;  ///< Increment index of second array
        } else if (first[f_index] > second[s_index]) {
            s_index++;  ///< Increment index of second array
        } else {
            if ((res.size() == 0) || (first[f_index] != res.back())) {
                res.push_back(
                    first[f_index]);  ///< Add the element if it is unique
            }
            f_index++;  ///< Increment index of first array
            s_index++;  ///< Increment index of second array too
        }
    }
    return res;
}

}  // namespace operations_on_datastructures

