/**
 * @file
 * @brief Finds the intersection of two already-sorted arrays.
 * @details The intersection is the set of values that appear in both
 * inputs. Because both arrays arrive pre-sorted, we can walk them with
 * two pointers in a single linear pass instead of using a hash set:
 * whichever pointer references the smaller value advances; when the
 * values match, that value is recorded (once) and both pointers move
 * forward together.
 * @see union_of_two_arrays.cpp
 */

#include <algorithm>  // std::sort
#include <cassert>    // assert
#include <iostream>   // console IO
#include <vector>     // std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * @brief Prints every element of a vector on one line, space separated,
 * followed by a trailing newline.
 * @param values the vector to print
 */
void dump(const std::vector<int32_t> &values) {
    for (int32_t value : values) {
        std::cout << value << " ";
    }
    std::cout << "\n";
}

/**
 * @brief Computes the intersection of two sorted integer vectors.
 * @param lhs first sorted vector
 * @param rhs second sorted vector
 * @return sorted vector containing values present in both inputs (no
 * duplicates)
 */
std::vector<int32_t> shared_elements(const std::vector<int32_t> &lhs,
                                      const std::vector<int32_t> &rhs) {
    std::vector<int32_t> common;
    size_t li = 0, ri = 0;
    const size_t lhs_len = lhs.size();
    const size_t rhs_len = rhs.size();

    while (li < lhs_len && ri < rhs_len) {
        if (lhs[li] < rhs[ri]) {
            ++li;
        } else if (lhs[li] > rhs[ri]) {
            ++ri;
        } else {
            if (common.empty() || lhs[li] != common.back()) {
                common.push_back(lhs[li]);
            }
            ++li;
            ++ri;
        }
    }
    return common;
}

}  // namespace operations_on_datastructures

/**
 * @namespace checks
 * @brief Verification routines for shared_elements
 */
namespace checks {
using operations_on_datastructures::dump;
using operations_on_datastructures::shared_elements;

/** @brief Both inputs empty. */
void check_both_empty() {
    std::cout << "CHECK 1\n";
    std::cout << "a = {} , b = {}\n";
    std::cout << "expect: {}\n";
    std::vector<int32_t> a = {};
    std::vector<int32_t> b = {};
    std::vector<int32_t> out = shared_elements(a, b);
    assert(out == a);
    dump(out);
    std::cout << "PASSED\n\n";
}

