void check_one_empty() {
    std::cout << "CHECK 2\n";
    std::cout << "a = {} , b = {2, 3}\n";
    std::cout << "expect: {}\n";
    std::vector<int32_t> a = {};
    std::vector<int32_t> b = {2, 3};
    std::vector<int32_t> out = shared_elements(a, b);
    assert(out == a);
    dump(out);
    std::cout << "PASSED\n\n";
}

