}

/** @brief Overlap involving repeated values. */
void check_with_duplicates() {
    std::cout << "CHECK 4\n";
    std::cout << "a = {4, 6, 6, 6} , b = {2, 4, 4, 6}\n";
    std::cout << "expect: {4, 6}\n";
    std::vector<int32_t> a = {4, 6, 6, 6};
    std::vector<int32_t> b = {2, 4, 4, 6};
    std::vector<int32_t> out = shared_elements(a, b);
    std::vector<int32_t> expect = {4, 6};
    assert(out == expect);
    dump(out);
