}

/** @brief Larger mixed case. */
void check_larger_case() {
    std::cout << "CHECK 5\n";
    std::cout << "a = {1, 2, 3, 4, 6, 7, 9} , b = {2, 3, 4, 5}\n";
    std::cout << "expect: {2, 3, 4}\n";
    std::vector<int32_t> a = {1, 2, 3, 4, 6, 7, 9};
    std::vector<int32_t> b = {2, 3, 4, 5};
    std::vector<int32_t> out = shared_elements(a, b);
    std::vector<int32_t> expect = {2, 3, 4};
    assert(out == expect);
    dump(out);
    std::cout << "PASSED\n\n";
}

/** @brief Case that requires pre-sorting the inputs first. */
void check_needs_presort() {
    std::cout << "CHECK 6\n";
    std::cout << "a = {1, 3, 3, 2, 5, 9, 4, 7, 3, 2} ";
    std::cout << "b = {11, 3, 7, 8, 6}\n";
    std::cout << "expect: {3, 7}\n";
    std::vector<int32_t> a = {1, 3, 3, 2, 5, 9, 4, 7, 3, 2};
    std::vector<int32_t> b = {11, 3, 7, 8, 6};
    std::sort(a.begin(), a.end());
    std::sort(b.begin(), b.end());
    std::vector<int32_t> out = shared_elements(a, b);
    std::vector<int32_t> expect = {3, 7};
    assert(out == expect);
    dump(out);
    std::cout << "PASSED\n\n";
}
}  // namespace checks

/**
