/**
 * @file
 * @brief Mirrors (reverses) a binary tree by swapping each node's left
 * and right children, recursively, starting from the root.
 * @details A tree is "reversed" (mirrored) when, at every node, the
 * left and right subtrees are swapped with each other and this swap
 * cascades all the way down to the leaves. This file implements a
 * small BST class and the recursive mirroring routine.
 */

#include <cassert>   // assert
#include <iostream>  // console IO
#include <queue>     // std::queue
#include <vector>    // std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * @namespace mirror_tree
 * @brief Binary tree mirroring implementation
 */
namespace mirror_tree {

/**
 * @brief A single binary tree node holding an integer payload and
 * pointers to its two children.
 */
struct TreeCell {
    int64_t value;      ///< payload stored at this node
    TreeCell* left_kid;  ///< left child (nullptr if absent)
    TreeCell* right_kid;  ///< right child (nullptr if absent)

    explicit TreeCell(int64_t v) {
        value = v;
        left_kid = nullptr;
        right_kid = nullptr;
    }
};

/**
 * @brief A binary search tree wrapper that supports insertion, level
 * order dumping, and mirroring (reversal).
 */
class SearchTree {
 private:
    TreeCell* root_node;

    /**
     * @brief Inserts `value` into the subtree rooted at `node`,
     * keeping BST ordering (smaller values go left).
     * @param value value to insert
     * @param node root of the (sub)tree being inserted into
     * @return the (possibly new) root of this subtree
     */
    TreeCell* insert_at(int64_t value, TreeCell* node) {
        if (node == nullptr) {
            return new TreeCell(value);
        }
        if (value <= node->value) {
            node->left_kid = insert_at(value, node->left_kid);
        } else {
            node->right_kid = insert_at(value, node->right_kid);
        }
        return node;
    }

    /**
     * @brief Recursively mirrors the subtree rooted at `node` by
     * swapping its children (and their children, and so on).
     * @param node root of the (sub)tree to mirror
     * @return the (unchanged pointer to the) root of the mirrored
     * subtree
     */
    TreeCell* mirror_at(TreeCell* node) {
        if (node == nullptr) {
            return node;
        }
        TreeCell* old_left = node->left_kid;
        node->left_kid = mirror_at(node->right_kid);
        node->right_kid = mirror_at(old_left);
        return node;
    }

    SearchTree(const SearchTree&) = delete;
    SearchTree& operator=(const SearchTree&) = delete;

 public:
    /** @brief Builds an empty tree. */
    SearchTree() { root_node = nullptr; }
    /** @brief Builds a tree whose root holds `value`. */
    explicit SearchTree(int64_t value) { root_node = new TreeCell(value); }

    ~SearchTree() {
        std::vector<TreeCell*> stack;
        stack.emplace_back(root_node);
        while (!stack.empty()) {
            TreeCell* current = stack.back();
            stack.pop_back();
            if (current) {
                stack.emplace_back(current->left_kid);
                stack.emplace_back(current->right_kid);
                delete current;
            }
        }
    }

    /** @brief Inserts a new value into the tree. */
    void insert(int64_t value) { root_node = insert_at(value, root_node); }

    /** @brief Mirrors the whole tree in place. */
    void mirror() { root_node = mirror_at(root_node); }

    /**
     * @brief Returns the tree's contents visited top-to-bottom,
     * left-to-right (level order / BFS), using a queue to track the
     * frontier of unvisited nodes.
     * @return vector of values in level order
     */
    std::vector<int64_t> level_order() {
        std::vector<int64_t> values;
        if (root_node == nullptr) {
            return values;
        }
        std::queue<TreeCell*> frontier;
        frontier.push(root_node);
        while (!frontier.empty()) {
            TreeCell* current = frontier.front();
            values.push_back(current->value);
            frontier.pop();
            if (current->left_kid != nullptr) {
                frontier.push(current->left_kid);
            }
            if (current->right_kid != nullptr) {
                frontier.push(current->right_kid);
            }
        }
        return values;
    }

    /** @brief Prints the tree's level-order contents on one line. */
    void show() {
        for (int64_t v : level_order()) {
            std::cout << v << " ";
        }
        std::cout << "\n";
    }
};

}  // namespace mirror_tree
}  // namespace operations_on_datastructures

/**
 * @namespace checks
 * @brief Verification routines for tree mirroring
 */
namespace checks {
using operations_on_datastructures::mirror_tree::SearchTree;

/** @brief Mirroring a single-node tree should be a no-op. */
void check_single_node() {
    SearchTree tree;
    std::vector<int64_t> before, after;
    std::cout << "CHECK 1\n";
    std::cout << "Single-node tree containing 5\n";
    tree.insert(5);
    before = tree.level_order();
    std::cout << "before: ";
    tree.show();
    std::cout << "after: ";
    tree.mirror();
    after = tree.level_order();
    assert(before.size() == after.size());
    assert(before.size() == 1);
    assert(before[0] == after[0]);
    tree.show();
    std::cout << "PASSED\n\n";
}

/** @brief Mirroring an empty tree should remain empty. */
void check_empty_tree() {
    SearchTree tree;
    std::vector<int64_t> before, after;
    std::cout << "CHECK 2\n";
    std::cout << "Empty tree (root is null)\n";
    before = tree.level_order();
    std::cout << "before: ";
    tree.show();
    std::cout << "after: ";
    tree.mirror();
    after = tree.level_order();
    assert(before.size() == after.size());
    assert(before.size() == 0);
    tree.show();
    std::cout << "PASSED\n\n";
}

/** @brief Mirroring a multi-node tree should swap subtrees correctly. */
void check_full_tree() {
    SearchTree tree;
    std::vector<int64_t> before, after;
    std::vector<int64_t> expect_before = {4, 3, 6, 2, 5, 7, 1};
    std::vector<int64_t> expect_after = {4, 6, 3, 7, 5, 2, 1};
    std::cout << "CHECK 3\n";
    std::cout << "Tree built from (4, 6, 3, 2, 5, 7, 1)\n";
    tree.insert(4);
    tree.insert(6);
    tree.insert(3);
    tree.insert(2);
    tree.insert(5);
    tree.insert(7);
    tree.insert(1);
    before = tree.level_order();
    assert(before == expect_before);
    std::cout << "before: ";
    tree.show();
    std::cout << "after: ";
    tree.mirror();
    after = tree.level_order();
    assert(after == expect_after);
    tree.show();
    std::cout << "PASSED\n\n";
}
}  // namespace checks

/**
 * @brief Runs every mirroring check.
 */
static void run_checks() {
    checks::check_single_node();
    checks::check_empty_tree();
    checks::check_full_tree();
}

/**
 * @brief Program entry point.
 */
int main() {
    run_checks();
    return 0;
}

/*
 * @file
 * @brief Determines the [Date of
 * Easter](https://en.wikipedia.org/wiki/Date_of_Easter) after 1582
 *
 * @details
 * The date of Easter is determined in each year through a calculation known as
 * "computus." Easter is celebrated on the first Sunday after the Paschal full
 * moon, which is the first full moon on or after 21 March. Determining this
 * date in advance requires a correlation between the lunar months and the solar
 * year, while also accounting for the month, date, and weekday of the Julian or
 * Gregorian calendar. The complexity of the algorithm arises because of the
 * desire to associate the date of Easter with the date of the Jewish feast of
 * Passover which, Christians believe, is when Jesus was crucified.
 *
 *
 * @author [AlternateWalls](https://github.com/AlternateWalls)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations

/*
 * @brief Contains information for Easter date
 */
class EasterYearMonthDay {
 public:
    uint64_t year;   ///< year Easter is on
    uint64_t month;  ///< month Easter is on
    uint64_t day;    ///< day Easter is on

    EasterYearMonthDay(uint64_t newYear, uint64_t newMonth, uint64_t newDay) {
        year = newYear;  // Assigns year to class
        month = newMonth;
        day = newDay;
    }
};

/*
 * @brief Function that finds the month and day of Easter
 * @params param1 An int "y" of the year you want to find Easter on after
 * 1582
 * @returns An instance of the easterYearMonthDay calss that contains the
 * information (Ex. 420 - 4/20 or April 20th)
 */
EasterYearMonthDay findEaster(uint64_t y) {
    if (y > 1582) {
        uint64_t a = y % 19;   // Year's location on Metonic Calendar
        uint64_t b = y / 100;  // Century index
        uint64_t c = y % 100;
        uint64_t d = b / 4;
        uint64_t e = b % 4;  // Takes into account leap years
        uint64_t f = (b + 8) / 25;
        uint64_t g = (b - f + 1) / 3;
        uint64_t h = (19 * a + b - d - g + 15) %
                     30;  // Days from Mar. 21st until the full moon
        uint64_t i = c / 4;
        uint64_t k = c % 4;
        uint64_t r =
            (32 + 2 * e + 2 * i - h - k) %
            7;  // The number of days from Paschal full moon to next Sunday
        uint64_t m = (a + 11 * h + 22 * r) / 451;
        uint64_t n = (h + r - 7 * m + 114) / 31;  // Month of Easter
        uint64_t p = (h + r - 7 * m + 114) % 31;  // p + 1 is the day of Easter

        // Assign values
        EasterYearMonthDay date(
            y, n, p + 1);  // Assign values to new instance of class

        // Return date
        return date;
    } else {
        EasterYearMonthDay date(0, 0, 0);

        // Return date
        return date;
    }
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 2003 | April 20th
    assert(findEaster(2003).month == 4);  // Should return true
    assert(findEaster(2003).day == 20);   // Should return true

    // 1910 | March 27th
    assert(findEaster(1910).month == 3);  // Should return true
    assert(findEaster(1910).day == 27);   // Should return true

    // 1877 | April 1st
    assert(findEaster(1877).month != 3);  // Should return true
    assert(findEaster(1877).day != 22);   // Should return true

    // 1400 | Invalid date
    assert(findEaster(1400).month == 0);  // Should return true
    assert(findEaster(1400).day == 0);    // Should return true
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/*
 * @file
 * @brief Works out the [Date of
 * Easter](https://en.wikipedia.org/wiki/Date_of_Easter) for years after 1582
 * using the "computus" calculation.
 *
 * @details
 * Easter falls on the first Sunday following the first full moon that
 * occurs on or after March 21st (the Paschal full moon). Because this ties
 * the solar calendar to the lunar cycle, computing it algorithmically
 * requires several intermediate correction terms, implemented below
 * following the classic Gregorian algorithm.
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations

/*
 * @brief Simple value holder describing a computed Easter date.
 */
class HolidayDate {
 public:
    uint64_t yearValue;
    uint64_t monthValue;
    uint64_t dayValue;

    HolidayDate(uint64_t y, uint64_t m, uint64_t d)
        : yearValue(y), monthValue(m), dayValue(d) {}
};

/*
 * @brief Computes the month/day of Easter for a given Gregorian year.
 * @param year target year, must be greater than 1582 to be meaningful
 * @returns a HolidayDate holding the resulting month and day (0/0 if the
 * year is out of the supported range)
 */
HolidayDate computeEasterDate(uint64_t year) {
    if (year <= 1582) {
        return HolidayDate(0, 0, 0);
    }

    uint64_t metonicPos = year % 19;
    uint64_t century = year / 100;
    uint64_t yearInCentury = year % 100;
    uint64_t leapCenturies = century / 4;
    uint64_t centuryRemainder = century % 4;
    uint64_t lunarCorrection = (century + 8) / 25;
    uint64_t lunarCorrection2 = (century - lunarCorrection + 1) / 3;
    uint64_t daysToFullMoon =
        (19 * metonicPos + century - leapCenturies - lunarCorrection2 + 15) % 30;
    uint64_t leapYearIdx = yearInCentury / 4;
    uint64_t leapYearRem = yearInCentury % 4;
    uint64_t daysToSunday =
        (32 + 2 * centuryRemainder + 2 * leapYearIdx - daysToFullMoon - leapYearRem) % 7;
    uint64_t monthCorrection =
        (metonicPos + 11 * daysToFullMoon + 22 * daysToSunday) / 451;
    uint64_t month =
        (daysToFullMoon + daysToSunday - 7 * monthCorrection + 114) / 31;
    uint64_t day =
        (daysToFullMoon + daysToSunday - 7 * monthCorrection + 114) % 31;

    return HolidayDate(year, month, day + 1);
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void runSelfTests() {
    // 2003 -> April 20th
    assert(computeEasterDate(2003).monthValue == 4);
    assert(computeEasterDate(2003).dayValue == 20);

    // 1910 -> March 27th
    assert(computeEasterDate(1910).monthValue == 3);
    assert(computeEasterDate(1910).dayValue == 27);

    // 1877 -> April 1st
    assert(computeEasterDate(1877).monthValue != 3);
    assert(computeEasterDate(1877).dayValue != 22);

    // 1400 -> unsupported, expect zeroed date
    assert(computeEasterDate(1400).monthValue == 0);
    assert(computeEasterDate(1400).dayValue == 0);
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    runSelfTests();
    return 0;
}

/**
 * @file
 * @brief A happy number is a number whose sum of digits is calculated until the
 * sum is a single digit, and this sum turns out to be 1
 */

#include <iostream>

/**
 * Checks if a decimal number is a happy number
 * \returns true if happy else false
 */
template <typename T>
bool is_happy(T n) {
    T s = 0;              // stores sum of digits
    while (n > 9) {       // while number is > 9, there are more than 1 digit
        while (n != 0) {  // get digit
            T d = n % 10;
            s += d;
            n /= 10;
        }
        n = s;
        s = 0;
    }
    return (n == 1) ? true : false;  // true if k == 1
}

/** Main function */
int main() {
    int n;
    std::cout << "Enter a number:";
    std::cin >> n;

    if (is_happy(n))
        std::cout << n << " is a happy number" << std::endl;
    else
        std::cout << n << " is not a happy number" << std::endl;
    return 0;
}

/**
 * @file
 * @brief A "happy" number eventually reaches 1 when you repeatedly replace it
 * with the sum of the squares... actually here, with the sum of its digits,
 * repeated until a single digit remains equal to 1.
 */

#include <iostream>

/**
 * Determines whether repeatedly summing the digits of n eventually
 * collapses to exactly 1.
 * \returns true when the digit-sum chain terminates at 1
 */
template <typename NumT>
bool checkHappy(NumT value) {
    NumT digitSum = 0;
    while (value > 9) {
        while (value != 0) {
            NumT lastDigit = value % 10;
            digitSum += lastDigit;
            value /= 10;
        }
        value = digitSum;
        digitSum = 0;
    }
    return value == 1;
}

/** Program entry point */
int main() {
    int userInput;
    std::cout << "Enter a number:";
    std::cin >> userInput;

    if (checkHappy(userInput)) {
        std::cout << userInput << " is a happy number" << std::endl;
    } else {
        std::cout << userInput << " is not a happy number" << std::endl;
    }
    return 0;
}

/**
 * @file
 * @brief Iterative version of Preorder, Postorder, and preorder [Traversal of
 * the Tree] (https://en.wikipedia.org/wiki/Tree_traversal)
 * @author [Motasim](https://github.com/motasimmakki)
 * @details
 *
 * ### Iterative Preorder Traversal of a tree
 * Create a Stack that will store the Node of Tree.
 * Push the root node into the stack.
 * Save the root into the variabe named as current, and pop and elemnt from the
 * stack. Store the data of current into the result array, and start traversing
 * from it. Push both the child node of the current node into the stack, first
 * right child then left child. Repeat the same set of steps untill the Stack
 * becomes empty. And return the result array as the preorder traversal of a
 * tree.
 *
 * ### Iterative Postorder Traversal of a tree
 * Create a Stack that will store the Node of Tree.
 * Push the root node into the stack.
 * Save the root into the variabe named as current, and pop and elemnt from the
 * stack. Store the data of current into the result array, and start traversing
 * from it. Push both the child node of the current node into the stack, first
 * left child then right child. Repeat the same set of steps untill the Stack
 * becomes empty. Now reverse the result array and then return it to the calling
 * function as a postorder traversal of a tree.
 *
 * ### Iterative Inorder Traversal of a tree
 * Create a Stack that will store the Node of Tree.
 * Push the root node into the stack.
 * Save the root into the variabe named as current.
 * Now iterate and take the current to the extreme left of the tree by
 * traversing only to its left. Pop the elemnt from the stack and assign it to
 * the current. Store the data of current into the result array. Repeat the same
 * set of steps until the Stack becomes empty or the current becomes NULL. And
 * return the result array as the inorder traversal of a tree.
 */
#include <algorithm>  /// for `reverse`
#include <cassert>    /// for `assert`
#include <iostream>   /// for I/O operations
#include <stack>      /// for `stack`
#include <vector>     /// for `vector`

/**
 * @namespace others
 * @brief Other algorithms
 */
namespace others {
/**
 * @namespace iterative_tree_traversals
 * @brief Functions for the [Traversal of the
 * Tree](https://en.wikipedia.org/wiki/Tree_traversal) algorithm
 */
namespace iterative_tree_traversals {
/**
 * @brief defines the structure of a node of the tree
 */
struct Node {
    int64_t data = 0;      ///< The value/key of the node.
    struct Node *left{};   ///< struct pointer to left subtree.
    struct Node *right{};  ///< struct pointer to right subtree.
};

/**
 * @brief defines the functions associated with the binary tree
 */
class BinaryTree {
 public:
    Node *createNewNode(
        int64_t);  ///< function that will create new node for insertion.
    std::vector<int64_t> preOrderIterative(
        Node *);  ///< function that takes root of the tree as an argument, and
                  ///< returns its preorder traversal.
    std::vector<int64_t> postOrderIterative(
        Node *);  ///< function that takes root of the tree as an argument, and
                  ///< returns its postorder traversal.
    std::vector<int64_t> inOrderIterative(
        Node *);  ///< function that takes root of the tree as an argument, and
                  ///< returns its inorder traversal.
};

/**
 * @brief will allocate the memory for a node and, along the data and return the
 * node.
 * @param data value that a particular node will contain.
 * @return pointer to the newly created node with assigned data.
 */
Node *BinaryTree::createNewNode(int64_t data) {
    Node *node = new Node();
    node->data = data;
    node->left = node->right = nullptr;
    return node;
}

/**
 * @brief preOrderIterative() function that will perform the preorder traversal
 * iteratively, and return the result array that contain the preorder traversal
 * of a tree.
 * @param root head/root node of a tree
 * @return result that is containing the preorder traversal of a tree
 */
std::vector<int64_t> BinaryTree::preOrderIterative(Node *root) {
    std::stack<Node *>
        stack;  ///< is used to find and traverse the child nodes.
    std::vector<int64_t> result;  ///< list of values, sorted in pre-order.

    stack.push(root);

    while (!stack.empty()) {
        result.push_back(stack.top()->data);
        Node *current = stack.top();
        stack.pop();

        if (current->right) {
            stack.push(current->right);
        }
        if (current->left) {
            stack.push(current->left);
        }
    }

    return result;
}

/**
 * @brief postOrderIterative() function that will perform the postorder
 * traversal iteratively, and return the result array that contain the postorder
 * traversal of a tree.
 * @param root head/root node of a tree
 * @return result that is containing the postorder traversal of a tree
 */
std::vector<int64_t> BinaryTree::postOrderIterative(Node *root) {
    std::stack<Node *>
        stack;  ///< is used to find and traverse the child nodes.
    std::vector<int64_t> result;  ///< List of values, sorted in post-order.

    stack.push(root);

    while (!stack.empty()) {
        result.push_back(stack.top()->data);
        Node *current = stack.top();
        stack.pop();

        if (current->left) {
            stack.push(current->left);
        }
        if (current->right) {
            stack.push(current->right);
        }
    }

    reverse(result.begin(), result.end());

    return result;
}

/**
 * @brief inOrderIterative() function that will perform the inorder traversal
 * iteratively, and return the result array that contain the inorder traversal
 * of a tree.
 * @param root head/root node of a tree
 * @return result that is containing the inorder traversal of a tree
 */
std::vector<int64_t> BinaryTree::inOrderIterative(Node *root) {
    std::stack<Node *>
        stack;  ///< is used to find and traverse the child nodes.
    std::vector<int64_t> result;  ///< List of values, sorted in in-order.

    Node *current = root;

    while (!stack.empty() || current) {
        while (current) {
            stack.push(current);
            current = current->left;
        }
        current = stack.top();
        stack.pop();
        result.push_back(current->data);
        current = current->right;
    }
    return result;
}
void deleteAll(Node *root) {
    if (root) {
        std::stack<Node *> stack;
        stack.push(root);

        while (!stack.empty()) {
            const Node *current = stack.top();
            stack.pop();

            if (current->right) {
                stack.push(current->right);
            }
            if (current->left) {
                stack.push(current->left);
            }
            delete current;
        }
    }
}
}  // namespace iterative_tree_traversals
}  // namespace others

