/**
 * @file
 * @brief Non-recursive (stack-based) Preorder, Postorder, and Inorder
 * [tree traversals](https://en.wikipedia.org/wiki/Tree_traversal).
 * @details
 *
 * ### Iterative Preorder
 * Push the root onto a stack. Repeatedly pop the top node, record its
 * value, then push its right child followed by its left child (so the left
 * child is processed first). Continue until the stack is empty.
 *
 * ### Iterative Postorder
 * Similar to preorder but push left before right, which yields a
 * root-right-left order; reversing that result gives left-right-root
 * (postorder).
 *
 * ### Iterative Inorder
 * Walk left as far as possible while pushing each node onto the stack.
 * When you can't go left anymore, pop a node, record it, then move to its
 * right child and repeat.
 */
#include <algorithm>  /// for `reverse`
#include <cassert>    /// for `assert`
#include <iostream>   /// for I/O operations
#include <stack>      /// for `stack`
#include <vector>     /// for `vector`

/**
 * @namespace others
 * @brief Other algorithms
 */
namespace others {
/**
 * @namespace iterative_tree_traversals
 * @brief Iterative tree traversal functions
 */
namespace iterative_tree_traversals {
/**
 * @brief A single binary tree node.
 */
struct TreeNode {
    int64_t value = 0;         ///< value stored at this node
    struct TreeNode *left{};   ///< left child, or nullptr
    struct TreeNode *right{};  ///< right child, or nullptr
};

/**
 * @brief Wraps node creation and the three iterative traversal routines.
 */
class TreeWalker {
 public:
    TreeNode *makeNode(int64_t value);
    std::vector<int64_t> preorder(TreeNode *root);
    std::vector<int64_t> postorder(TreeNode *root);
    std::vector<int64_t> inorder(TreeNode *root);
};

/**
 * @brief Allocates a new leaf node holding the given value.
 * @param value payload for the new node
 * @return pointer to the freshly allocated node
 */
TreeNode *TreeWalker::makeNode(int64_t value) {
    TreeNode *node = new TreeNode();
    node->value = value;
    node->left = node->right = nullptr;
    return node;
}

/**
 * @brief Iterative preorder traversal (root, left, right).
 * @param root root of the (sub)tree to traverse
 * @return values visited in preorder
 */
std::vector<int64_t> TreeWalker::preorder(TreeNode *root) {
    std::stack<TreeNode *> pending;
    std::vector<int64_t> visited;

    pending.push(root);

    while (!pending.empty()) {
        TreeNode *node = pending.top();
        visited.push_back(node->value);
        pending.pop();

        if (node->right) {
            pending.push(node->right);
        }
        if (node->left) {
            pending.push(node->left);
        }
    }

    return visited;
}

/**
 * @brief Iterative postorder traversal (left, right, root).
 * @param root root of the (sub)tree to traverse
 * @return values visited in postorder
 */
std::vector<int64_t> TreeWalker::postorder(TreeNode *root) {
    std::stack<TreeNode *> pending;
    std::vector<int64_t> visited;

    pending.push(root);

    while (!pending.empty()) {
        TreeNode *node = pending.top();
        visited.push_back(node->value);
        pending.pop();

        if (node->left) {
            pending.push(node->left);
        }
        if (node->right) {
            pending.push(node->right);
        }
    }

    std::reverse(visited.begin(), visited.end());

    return visited;
}

/**
 * @brief Iterative inorder traversal (left, root, right).
 * @param root root of the (sub)tree to traverse
 * @return values visited in inorder
 */
std::vector<int64_t> TreeWalker::inorder(TreeNode *root) {
    std::stack<TreeNode *> pending;
    std::vector<int64_t> visited;

    TreeNode *cursor = root;

    while (!pending.empty() || cursor) {
        while (cursor) {
            pending.push(cursor);
            cursor = cursor->left;
        }
        cursor = pending.top();
        pending.pop();
        visited.push_back(cursor->value);
        cursor = cursor->right;
    }
    return visited;
}

/**
 * @brief Frees every node reachable from root using an iterative traversal.
 */
void freeTree(TreeNode *root) {
    if (root) {
        std::stack<TreeNode *> pending;
        pending.push(root);

        while (!pending.empty()) {
            const TreeNode *node = pending.top();
            pending.pop();

            if (node->right) {
                pending.push(node->right);
            }
            if (node->left) {
                pending.push(node->left);
            }
            delete node;
        }
    }
}
}  // namespace iterative_tree_traversals
}  // namespace others

/**
 * @brief Verifies the preorder result against the expected sequence.
 */
static void checkPreorder(others::iterative_tree_traversals::TreeWalker walker,
                           others::iterative_tree_traversals::TreeNode *root) {
    std::vector<int64_t> expected{1, 2, 4, 5, 3};
    std::vector<int64_t> actual = walker.preorder(root);

    for (size_t idx = 0; idx < actual.size(); idx++) {
        assert(expected[idx] == actual[idx]);
    }

    std::cout << "\nPreOrder Traversal Is : " << std::endl;
    for (auto value : actual) {
        std::cout << value << "  ";
    }
}

