/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // Build the following tree:
    /*
              1
            /   \
           2     3
         /   \
        4     5
    */

    others::iterative_tree_traversals::TreeWalker walker;
    others::iterative_tree_traversals::TreeNode *root = walker.makeNode(1);
    root->left = walker.makeNode(2);
    root->right = walker.makeNode(3);
    root->left->left = walker.makeNode(4);
    root->left->right = walker.makeNode(5);

    std::cout << "\n| Tests for positive data value |" << std::endl;
    checkPreorder(walker, root);
    std::cout << "\nPre-order test Passed!" << std::endl;

    checkPostorder(walker, root);
    std::cout << "\nPost-order test Passed!" << std::endl;

    checkInorder(walker, root);
    std::cout << "\nIn-order test Passed!" << std::endl;

    // Flip the sign of every value to exercise the negative-value path.
    root->value = -1;
    root->left->value = -2;
    root->right->value = -3;
    root->left->left->value = -4;
    root->left->right->value = -5;

    std::cout << "\n| Tests for negative data values |" << std::endl;
    checkPreorderNegative(walker, root);
    std::cout << "\nPre-order test on-negative value Passed!" << std::endl;

    checkPostorderNegative(walker, root);
    std::cout << "\nPost-order test on-negative value Passed!" << std::endl;

    checkInorderNegative(walker, root);
    std::cout << "\nIn-order test on-negative value Passed!" << std::endl;

    others::iterative_tree_traversals::freeTree(root);

    return 0;
}

/**
 * @file
 * @brief Implementation for [LFU Cache]
 * (https://en.wikipedia.org/wiki/Least_frequently_used)
 *
 * @details
 * LFU discards the least frequently used value. if there are multiple items
 * with the same minimum frequency then, the least recently used among them is
 * discarded. Data structures used - doubly linked list and unordered_map(hash
 * map).
 *
 * Hashmap maps the key to the address of the node of the linked list and its
 * current usage frequency. If the element is accessed the element is removed
 * from the linked list of the current frequency and added to the linked list of
 * incremented frequency.
 *
 * When the cache is full, the last element in the minimum frequency linked list
 * is popped.
 *
 * @author [Karan Sharma](https://github.com/deDSeC00720)
 */

#include <cassert>        // for assert
#include <iostream>       // for std::cout
#include <unordered_map>  // for std::unordered_map

/**
 * @namespace
 * @brief Other algorithms
 */
namespace others {

/**
 * @namespace
 * @brief Cache algorithm
 */
namespace Cache {

/**
 * @class
 * @brief Node for a doubly linked list with data, prev and next pointers
 * @tparam T type of the data of the node
 */
template <typename T>
class D_Node {
 public:
    T data;           ///< data of the node
    D_Node<T> *prev;  ///< previous node in the doubly linked list
    D_Node<T> *next;  ///< next node in the doubly linked list

    explicit D_Node(T data) : data(data), prev(nullptr), next(nullptr) {}
};

template <typename K, typename V>
using CacheNode = D_Node<std::pair<K, V>>;

/**
 * @class
 * @brief LFUCache
 * @tparam K type of key in the LFU
 * @tparam V type of value in the LFU
 */
template <typename K, typename V>
class LFUCache {
    std::unordered_map<K, std::pair<CacheNode<K, V> *, int>>
        node_map;  ///< maps the key to the node address and frequency
    std::unordered_map<int, std::pair<CacheNode<K, V> *, CacheNode<K, V> *>>
        freq_map;  ///< maps the frequency to doubly linked list

    int minFreq;    ///< minimum frequency in the cache
    int _capacity;  ///< maximum capacity of the cache

 public:
    /**
     * @brief Constructor, Initialize with minFreq and _capacity.
     * @param _capacity Total capacity of the cache.
     */
    explicit LFUCache(int _capacity) : minFreq(0), _capacity(_capacity) {}

 private:
    /**
     * @brief push the node at first position in the linked list of given
     * frequency
     * @param freq the frequency mapping to the linked list where node should be
     * pushed.
     * @param node node to be pushed to the linked list.
     */
    void push(int freq, CacheNode<K, V> *node) {
        // if freq is not present, then make a new list with node as the head as
        // well as tail.
        if (!freq_map.count(freq)) {
            freq_map[freq] = {node, node};
            return;
        }

        std::pair<CacheNode<K, V> *, CacheNode<K, V> *> &p = freq_map[freq];

        // insert the node at the beginning of the linked list and update the
        // head.
        p.first->prev = node;
        node->next = p.first;
        p.first = node;
    }

    /**
     * @brief increase the frequency of node and push it in the respective list.
     * @param p_node the node to be updated
     */
    void increase_frequency(std::pair<CacheNode<K, V> *, int> &p_node) {
        CacheNode<K, V> *node = p_node.first;
        int freq = p_node.second;

        std::pair<CacheNode<K, V> *, CacheNode<K, V> *> &p = freq_map[freq];

        // if the given node is the only node in the list,
        // then erase the frequency from map
        // and increase minFreq by 1.
        if (p.first == node && p.second == node) {
            freq_map.erase(freq);
            if (minFreq == freq) {
                minFreq = freq + 1;
            }
        } else {
            // remove the given node from current freq linked list
            CacheNode<K, V> *prev = node->prev;
            CacheNode<K, V> *next = node->next;
            node->prev = nullptr;
            node->next = nullptr;

            if (prev) {
                prev->next = next;
            } else {
                p.first = next;
            }

            if (next) {
                next->prev = prev;
            } else {
                p.second = prev;
            }
        }
        push(freq + 1, node);
        ++p_node.second;
    }

    /**
     * @brief pop the last node in the least frequently used linked list
     */
    void pop() {
        std::pair<CacheNode<K, V> *, CacheNode<K, V> *> &p = freq_map[minFreq];

        // if there is only one node
        // remove the node and erase
        // the frequency from freq_map
        if (p.first == p.second) {
            delete p.first;
            freq_map.erase(minFreq);
            return;
        }

        // remove the last node in the linked list
        CacheNode<K, V> *temp = p.second;
        p.second = temp->prev;
        p.second->next = nullptr;
        delete temp;
    }

 public:
    /**
     * @brief upsert a key-value pair
     * @param key key of the key-value pair
     * @param value value of the key-value pair
     */
    void put(K key, V value) {
        // update the value if key already exists
        if (node_map.count(key)) {
            node_map[key].first->data.second = value;
            increase_frequency(node_map[key]);
            return;
        }

        // if the cache is full
        // remove the least frequently used item
        if (node_map.size() == _capacity) {
            node_map.erase(freq_map[minFreq].second->data.first);
            pop();
        }

        // insert the new node and set minFreq to 1
        CacheNode<K, V> *node = new CacheNode<K, V>({key, value});
        node_map[key] = {node, 1};
        minFreq = 1;
        push(1, node);
    }

    /**
     * @brief get the value of the key-value pair if exists
     * @param key key of the key-value pair
     * @return the value mapped to the given key
     * @exception exception is thrown if the key is not present in the cache
     */
    V get(K key) {
        if (!node_map.count(key)) {
            throw std::runtime_error("key is not present in the cache");
        }

        // increase the frequency and return the value
        V value = node_map[key].first->data.second;
        increase_frequency(node_map[key]);
        return value;
    }

    /**
     * @brief Returns the number of items present in the cache.
     * @return number of items in the cache
     */
    int size() const { return node_map.size(); }

    /**
     * @brief Returns the total capacity of the cache
     * @return Total capacity of the cache
     */
    int capacity() const { return _capacity; }

    /**
     * @brief returns true if the cache is empty, false otherwise.
     * @return true if the cache is empty, false otherwise.
     */
    bool empty() const { return node_map.empty(); }

    /**
     * @brief destructs the cache, iterates on the map and deletes every node
     * present in the cache.
     */
    ~LFUCache() {
        auto it = node_map.begin();
        while (it != node_map.end()) {
            delete it->second.first;
            ++it;
        }
    }
};
}  // namespace Cache
}  // namespace others

/**
 * @brief self test implementation
 * @return void
 */
static void test() {
    others::Cache::LFUCache<int, int> cache(5);

    // test the initial state of the cache
    assert(cache.size() == 0);
    assert(cache.capacity() == 5);
    assert(cache.empty());

    // test insertion in the cache
    cache.put(1, 10);
    cache.put(-2, 20);

    // test the state of cache after inserting some items
    assert(cache.size() == 2);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    // test getting items from the cache
    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    cache.put(-3, -30);
    cache.put(4, 40);
    cache.put(5, -50);
    cache.put(6, 60);

    // test the state after inserting more items than the capacity
    assert(cache.size() == 5);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    // test retrieval of all items in the cache
    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    // fetching -3 throws runtime_error
    // as -3 was evicted being the least frequently used
    // when 6 was added
    // assert(cache.get(-3) == -30);

    assert(cache.get(4) == 40);
    assert(cache.get(5) == -50);
    assert(cache.get(6) == 60);

    std::cout << "test - passed\n";
}

/**
 * @brief main function
 * @return 0 on exit
 */
int main() {
    test();  // run the self test implementation
    return 0;
}

/**
 * @file
 * @brief Implementation of an [LFU Cache]
 * (https://en.wikipedia.org/wiki/Least_frequently_used)
 *
 * @details
 * A Least-Frequently-Used cache evicts whichever entry has been accessed the
 * fewest times; ties are broken by evicting the least recently used entry
 * among those tied for lowest frequency. This is implemented using a hash
 * map from key to (node, frequency), plus a second hash map from frequency
 * to a small doubly linked list of nodes sharing that frequency.
 *
 * Whenever an entry is touched (via get or an updating put), it is unlinked
 * from its current frequency bucket and relinked at the head of the next
 * frequency bucket up.
 *
 * Eviction removes the tail node of the lowest-frequency bucket.
 */

#include <cassert>
#include <iostream>
#include <unordered_map>

/**
 * @namespace
 * @brief Other algorithms
 */
namespace others {

/**
 * @namespace
 * @brief Cache algorithm
 */
namespace Cache {

/**
 * @class
 * @brief Doubly linked list node.
 * @tparam T type stored in the node
 */
template <typename T>
class ListNode {
 public:
    T payload;
    ListNode<T> *prevNode;
    ListNode<T> *nextNode;

    explicit ListNode(T payload)
        : payload(payload), prevNode(nullptr), nextNode(nullptr) {}
};

template <typename K, typename V>
using EntryNode = ListNode<std::pair<K, V>>;

/**
 * @class
 * @brief Least-Frequently-Used cache.
 * @tparam K key type
 * @tparam V value type
 */
template <typename K, typename V>
class LFUCache {
    std::unordered_map<K, std::pair<EntryNode<K, V> *, int>>
        keyIndex;  ///< key -> (node pointer, current frequency)
    std::unordered_map<int, std::pair<EntryNode<K, V> *, EntryNode<K, V> *>>
        freqBuckets;  ///< frequency -> (head, tail) of that bucket's list

    int lowestFreq;
    int maxCapacity;

 public:
    /**
     * @brief Builds an empty cache with a fixed maximum capacity.
     * @param capacity how many entries the cache may hold at once
     */
    explicit LFUCache(int capacity) : lowestFreq(0), maxCapacity(capacity) {}

 private:
    /**
     * @brief Inserts a node at the head of the given frequency bucket.
     */
    void insertAtHead(int freq, EntryNode<K, V> *node) {
        if (!freqBuckets.count(freq)) {
            freqBuckets[freq] = {node, node};
            return;
        }

        auto &bucket = freqBuckets[freq];
        bucket.first->prevNode = node;
        node->nextNode = bucket.first;
        bucket.first = node;
    }

    /**
     * @brief Moves a node from its current frequency bucket to the next one
     * up, bumping its recorded frequency by one.
     */
    void bumpFrequency(std::pair<EntryNode<K, V> *, int> &entry) {
        EntryNode<K, V> *node = entry.first;
        int freq = entry.second;

        auto &bucket = freqBuckets[freq];

        if (bucket.first == node && bucket.second == node) {
            freqBuckets.erase(freq);
            if (lowestFreq == freq) {
                lowestFreq = freq + 1;
            }
        } else {
            EntryNode<K, V> *before = node->prevNode;
            EntryNode<K, V> *after = node->nextNode;
            node->prevNode = nullptr;
            node->nextNode = nullptr;

            if (before) {
                before->nextNode = after;
            } else {
                bucket.first = after;
            }

            if (after) {
                after->prevNode = before;
            } else {
                bucket.second = before;
            }
        }
        insertAtHead(freq + 1, node);
        ++entry.second;
    }

    /**
     * @brief Removes the least recently used node from the lowest-frequency
     * bucket.
     */
    void evictOldest() {
        auto &bucket = freqBuckets[lowestFreq];

        if (bucket.first == bucket.second) {
            delete bucket.first;
            freqBuckets.erase(lowestFreq);
            return;
        }

        EntryNode<K, V> *victim = bucket.second;
        bucket.second = victim->prevNode;
        bucket.second->nextNode = nullptr;
        delete victim;
    }

 public:
    /**
     * @brief Inserts or updates a key-value pair.
     * @param key key to insert/update
     * @param value value to associate with the key
     */
    void put(K key, V value) {
        if (keyIndex.count(key)) {
            keyIndex[key].first->payload.second = value;
            bumpFrequency(keyIndex[key]);
            return;
        }

        if (static_cast<int>(keyIndex.size()) == maxCapacity) {
            keyIndex.erase(freqBuckets[lowestFreq].second->payload.first);
            evictOldest();
        }

        EntryNode<K, V> *node = new EntryNode<K, V>({key, value});
        keyIndex[key] = {node, 1};
        lowestFreq = 1;
        insertAtHead(1, node);
    }

    /**
     * @brief Retrieves the value for a key, bumping its usage frequency.
     * @param key key to look up
     * @return the stored value
     * @exception std::runtime_error if the key is absent
     */
    V get(K key) {
        if (!keyIndex.count(key)) {
            throw std::runtime_error("key is not present in the cache");
        }

        V value = keyIndex[key].first->payload.second;
        bumpFrequency(keyIndex[key]);
        return value;
    }

    /** @brief Number of entries currently stored. */
    int size() const { return static_cast<int>(keyIndex.size()); }

    /** @brief Maximum number of entries the cache can hold. */
    int capacity() const { return maxCapacity; }

    /** @brief True when the cache holds no entries. */
    bool empty() const { return keyIndex.empty(); }

    /** @brief Frees every node still owned by the cache. */
    ~LFUCache() {
        for (auto &entry : keyIndex) {
            delete entry.second.first;
        }
    }
};
}  // namespace Cache
}  // namespace others

/**
 * @brief self test implementation
 * @return void
 */
static void runSelfTest() {
    others::Cache::LFUCache<int, int> cache(5);

    assert(cache.size() == 0);
    assert(cache.capacity() == 5);
    assert(cache.empty());

    cache.put(1, 10);
    cache.put(-2, 20);

    assert(cache.size() == 2);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    cache.put(-3, -30);
    cache.put(4, 40);
    cache.put(5, -50);
    cache.put(6, 60);

    assert(cache.size() == 5);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    // -3 was the least frequently used entry when 6 was inserted, so it was
    // evicted; fetching it now would throw.
    // assert(cache.get(-3) == -30);

    assert(cache.get(4) == 40);
    assert(cache.get(5) == -50);
    assert(cache.get(6) == 60);

    std::cout << "test - passed\n";
}

/**
 * @brief main function
 * @return 0 on exit
 */
int main() {
    runSelfTest();
    return 0;
}

/**
 * @file
 * @brief Implementation for [LRU Cache]
 * (https://en.wikipedia.org/wiki/Cache_replacement_policies#:~:text=Least%20Recently%20Used%20(LRU))
 *
 * @details
 * LRU discards the least recently used value.
 * Data structures used - doubly linked list and unordered_map
 *
 * unordered_map maps the key to the address of the node of the linked list.
 * If the element is accessed, the element is moved to the beginning of the
 * linked list.
 *
 * When the cache is full, the last element in the linked list is popped.
 *
 * @author [Karan Sharma](https://github.com/deDSeC00720)
 */

#include <cassert>        // for assert
#include <cstdint>        // for std::uint32_t
#include <iostream>       // for std::cout
#include <unordered_map>  // for std::unordered_map

/**
 * @namespace
 * @brief Other algorithms
 */
namespace others {

/**
 * @namespace
 * @brief Cache algorithm
 */
namespace Cache {

/**
 * @class
 * @brief Node for a doubly linked list with data, prev and next pointers
 * @tparam T type of the data of the node
 */
template <typename T>
class D_Node {
 public:
    T data;           ///< data of the node
    D_Node<T> *prev;  ///< previous node in the doubly linked list
    D_Node<T> *next;  ///< next node in the doubly linked list

    explicit D_Node(T data) : data(data), prev(nullptr), next(nullptr) {}
};

template <typename K, typename V>
using CacheNode = D_Node<std::pair<K, V>>;

/**
 * @class
 * @brief LRUCache
 * @tparam K type of key in the LRU
 * @tparam V type of value in the LRU
 */
template <typename K, typename V>
class LRUCache {
    CacheNode<K, V> *head;    ///< head of the doubly linked list
    CacheNode<K, V> *tail;    ///< tail of the doubly linked list
    std::uint32_t _capacity;  ///< maximum capacity of the cache

    std::unordered_map<K, CacheNode<K, V> *>
        node_map;  ///< maps the key to the node address

 public:
    /**
     * @brief Constructor, Initialize the head and tail pointers to nullptr and
     * initialize the _capacity of the cache
     * @param _capacity Total capacity of the cache
     */
    explicit LRUCache(int _capacity)
        : head(nullptr), tail(nullptr), _capacity(_capacity) {}

 private:
    /**
     * @brief push the node to the front of the linked list.
     * @param node_ptr the node to be pushed
     */
    void push_front(CacheNode<K, V> *node_ptr) {
        if (!head) {
            head = node_ptr;
            tail = node_ptr;
            return;
        }

        node_ptr->next = head;
        head->prev = node_ptr;
        head = node_ptr;
    }

    /**
     * @brief move the existing node in the list to the beginning of the list.
     * @param node_ptr node to be moved to the beginning.
     */
    void make_recent(CacheNode<K, V> *node_ptr) {
        if (head == node_ptr) {
            return;
        }

        CacheNode<K, V> *prev = node_ptr->prev;
        CacheNode<K, V> *next = node_ptr->next;

        prev->next = next;
        if (next) {
            next->prev = prev;
        } else {
            tail = prev;
        }

        node_ptr->prev = nullptr;
        node_ptr->next = nullptr;
        push_front(node_ptr);
    }

    /**
     * @brief pop the last node in the linked list.
     */
    void pop_back() {
        if (!head) {
            return;
        }
        if (head == tail) {
            delete head;
            head = nullptr;
            tail = nullptr;
            return;
        }

        CacheNode<K, V> *temp = tail;
        tail = tail->prev;
        tail->next = nullptr;
        delete temp;
    }

 public:
    /**
     * @brief upsert a key-value pair
     * @param key key of the key-value pair
     * @param value value of the key-value pair
     */
    void put(K key, V value) {
        // update the value if key already exists
        if (node_map.count(key)) {
            node_map[key]->data.second = value;
            make_recent(node_map[key]);
            return;
        }

        // if the cache is full
        // remove the least recently used item
        if (node_map.size() == _capacity) {
            node_map.erase(tail->data.first);
            pop_back();
        }

        CacheNode<K, V> *newNode = new CacheNode<K, V>({key, value});

        node_map[key] = newNode;
        push_front(newNode);
    }

    /**
     * @brief get the value of the key-value pair if exists
     * @param key key of the key-value pair
     * @return the value mapped to the given key
     * @exception exception is thrown if the key is not present in the cache
     */
    V get(K key) {
        if (!node_map.count(key)) {
            throw std::runtime_error("key is not present in the cache");
        }

        // move node to the beginning of the list
        V value = node_map[key]->data.second;
        make_recent(node_map[key]);
        return value;
    }

    /**
     * @brief Returns the number of items present in the cache.
     * @return number of items in the cache
     */
    int size() const { return node_map.size(); }

    /**
     * @brief Returns the total capacity of the cache
     * @return Total capacity of the cache
     */
    int capacity() const { return _capacity; }

    /**
     * @brief returns whether the cache is empty or not
     * @return true if the cache is empty, false otherwise.
     */
    bool empty() const { return node_map.empty(); }

    /**
     * @brief destructs the cache, iterates on the map and deletes every node
     * present in the cache.
     */
    ~LRUCache() {
        auto it = node_map.begin();
        while (it != node_map.end()) {
            delete it->second;
            ++it;
        }
    }
};
}  // namespace Cache
}  // namespace others

/**
 * @brief self test implementations
 * @return void
 */
static void test() {
    others::Cache::LRUCache<int, int> cache(5);

    // test the initial state of the cache
    assert(cache.size() == 0);
    assert(cache.capacity() == 5);
    assert(cache.empty());

    // test insertion in the cache
    cache.put(1, 10);
    cache.put(-2, 20);

    // test the state of cache after inserting some items
    assert(cache.size() == 2);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    // test getting items from the cache
    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    cache.put(-3, -30);
    cache.put(4, 40);
    cache.put(5, -50);
    cache.put(6, 60);

    // test the state after inserting more items than the capacity
    assert(cache.size() == 5);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    // fetching 1 throws runtime_error
    // as 1 was evicted being the least recently used
    // when 6 was added
    try {
        cache.get(1);
    } catch (const std::runtime_error &e) {
        assert(std::string(e.what()) == "key is not present in the cache");
    }

    // test retrieval of all items in the cache
    assert(cache.get(-2) == 20);
    assert(cache.get(-3) == -30);
    assert(cache.get(4) == 40);
    assert(cache.get(5) == -50);
    assert(cache.get(6) == 60);

    std::cout << "test - passed\n";
}

/**
 * @brief main function
 * @return 0 on exit
 */
int main() {
    test();  // run the self test implementation
    return 0;
}

/**
 * @file
 * @brief Alternate implementation of an [LRU Cache]
 * (https://en.wikipedia.org/wiki/Cache_replacement_policies#:~:text=Least%20Recently%20Used%20(LRU))
 *
 * @details
 * This variant keeps the most recently touched entries near the "front"
 * of an intrusive doubly linked list, while a hash map gives O(1) lookup
 * from key straight to the list node holding that key's value.
 *
 * Whenever an entry is read or overwritten it is unlinked from wherever it
 * currently sits and relinked at the front. Once the map grows past the
 * configured capacity, whatever sits at the back (the least recently
 * touched entry) is evicted first.
 *
 * @author rewritten for dataset generation
 */

#include <cassert>        // assert() for the demo checks
#include <cstdint>        // fixed width integer capacity field
#include <iostream>       // console output for the demo
#include <stdexcept>      // std::runtime_error
#include <unordered_map>  // key -> node lookup table

namespace others {

/**
 * @namespace
 * @brief Cache eviction strategies live here
 */
namespace Cache {

/**
 * @brief A single link in an intrusive doubly linked list.
 * @tparam Payload the value type stored at each link
 */
template <typename Payload>
struct ChainLink {
    Payload payload;        ///< stored payload (key/value pair in practice)
    ChainLink *before;      ///< link closer to the front
    ChainLink *after;       ///< link closer to the back

    explicit ChainLink(Payload payload_in)
        : payload(std::move(payload_in)), before(nullptr), after(nullptr) {}
};

template <typename Key, typename Val>
using EntryLink = ChainLink<std::pair<Key, Val>>;

/**
 * @brief Least-recently-used cache keyed on arbitrary hashable keys.
 * @tparam Key key type
 * @tparam Val value type
 */
template <typename Key, typename Val>
class LRUCache {
 public:
    /**
     * @brief Build an empty cache bounded to hold at most `max_entries`
     * key/value pairs.
     */
    explicit LRUCache(int max_entries)
        : front_(nullptr), back_(nullptr), max_entries_(max_entries) {}

    /**
     * @brief destructor frees every remaining link owned by the lookup table
     */
    ~LRUCache() {
        for (auto &entry : lookup_) {
            delete entry.second;
        }
    }

    /**
     * @brief Insert a new key or overwrite an existing one, refreshing its
     * recency either way.
     */
    void put(Key key, Val value) {
        auto found = lookup_.find(key);
        if (found != lookup_.end()) {
            found->second->payload.second = value;
            bump_to_front(found->second);
            return;
        }

        if (static_cast<int>(lookup_.size()) == max_entries_) {
            evict_oldest();
        }

        auto *fresh_link = new EntryLink<Key, Val>({key, value});
        lookup_[key] = fresh_link;
        attach_at_front(fresh_link);
    }

    /**
     * @brief Fetch the value for `key`, marking it as recently used.
     * @throws std::runtime_error when the key is absent from the cache
     */
    Val get(Key key) {
        auto found = lookup_.find(key);
        if (found == lookup_.end()) {
            throw std::runtime_error("key is not present in the cache");
        }

        Val value = found->second->payload.second;
        bump_to_front(found->second);
        return value;
    }

    /// @brief number of key/value pairs currently stored
    int size() const { return static_cast<int>(lookup_.size()); }

    /// @brief maximum number of pairs this cache will hold
    int capacity() const { return max_entries_; }

    /// @brief true when no pairs are stored
    bool empty() const { return lookup_.empty(); }

 private:
    /**
     * @brief Splice `link` in as the new front of the chain.
     */
    void attach_at_front(EntryLink<Key, Val> *link) {
        if (front_ == nullptr) {
            front_ = link;
            back_ = link;
            return;
        }

        link->after = front_;
        front_->before = link;
        front_ = link;
    }

    /**
     * @brief Detach `link` from its current position and reattach it at
     * the front, unless it is already there.
     */
    void bump_to_front(EntryLink<Key, Val> *link) {
        if (link == front_) {
            return;
        }

        EntryLink<Key, Val> *prior = link->before;
        EntryLink<Key, Val> *later = link->after;

        prior->after = later;
        if (later != nullptr) {
            later->before = prior;
        } else {
            back_ = prior;
        }

        link->before = nullptr;
        link->after = nullptr;
        attach_at_front(link);
    }

    /**
     * @brief Remove the least recently used entry (the back of the chain)
     * from both the chain and the lookup table.
     */
    void evict_oldest() {
        if (back_ == nullptr) {
            return;
        }

        lookup_.erase(back_->payload.first);

        if (front_ == back_) {
            delete back_;
            front_ = nullptr;
            back_ = nullptr;
            return;
        }

        EntryLink<Key, Val> *doomed = back_;
        back_ = back_->before;
        back_->after = nullptr;
        delete doomed;
    }

    EntryLink<Key, Val> *front_;  ///< most recently touched link
    EntryLink<Key, Val> *back_;   ///< least recently touched link
    std::uint32_t max_entries_;   ///< capacity bound for the cache

    std::unordered_map<Key, EntryLink<Key, Val> *> lookup_;  ///< key -> link
};

}  // namespace Cache
}  // namespace others

/**
 * @brief exercises the cache through a scripted sequence of operations
 */
static void run_lru_checks() {
    others::Cache::LRUCache<int, int> box(5);

    // freshly constructed cache should report empty
    assert(box.size() == 0);
    assert(box.capacity() == 5);
    assert(box.empty());

    // add a couple of entries
    box.put(100, 1);
    box.put(-200, 2);

    assert(box.size() == 2);
    assert(box.capacity() == 5);
    assert(!box.empty());

    // reading back the values should work and mark them recent
    assert(box.get(100) == 1);
    assert(box.get(-200) == 2);

    box.put(-300, -3);
    box.put(400, 4);
    box.put(500, -5);
    box.put(600, 6);

    // cache is now saturated at its configured capacity
    assert(box.size() == 5);
    assert(box.capacity() == 5);
    assert(!box.empty());

    // entry 100 should have been evicted since it was least recently
    // touched by the time 600 pushed the cache over capacity
    try {
        box.get(100);
        assert(false && "expected eviction of key 100");
    } catch (const std::runtime_error &err) {
        assert(std::string(err.what()) == "key is not present in the cache");
    }

    // remaining entries should still be retrievable
    assert(box.get(-200) == 2);
    assert(box.get(-300) == -3);
    assert(box.get(400) == 4);
    assert(box.get(500) == -5);
    assert(box.get(600) == 6);

    std::cout << "lru cache checks passed\n";
}

/**
 * @brief program entry point
 */
int main() {
    run_lru_checks();
    return 0;
}

/**
 * @file
 * @brief Recursive version of Inorder, Preorder, and Postorder [Traversal of
 * the Tree] (https://en.wikipedia.org/wiki/Tree_traversal)
 *
 * @details
 *
 * ### Iterative Inorder Traversal of a tree
 * For traversing a (non-empty) binary tree in an inorder fashion, we must do
 * these three things for every node n starting from the tree’s root:
 *
 * (L) Recursively traverse its left subtree. When this step is finished,
 * we are back at n again.
 * (N) Process n itself.
 * (R) Recursively traverse its right subtree. When this step is finished,
 * we are back at n again.
 *
 * In normal inorder traversal, we visit the left subtree before the right
 * subtree. If we visit the right subtree before visiting the left subtree, it
 * is referred to as reverse inorder traversal.
 *
 * ### Iterative Preorder Traversal of a tree
 * For traversing a (non-empty) binary tree in a preorder fashion, we must do
 * these three things for every node n starting from the tree’s root:
 *
 * (N) Process n itself.
 * (L) Recursively traverse its left subtree. When this step is finished,
 * we are back at n again.
 * (R) Recursively traverse its right subtree. When this step is finished,
 * we are back at n again.
 *
 * In normal preorder traversal, visit the left subtree before the right
 * subtree. If we visit the right subtree before visiting the left subtree, it
 * is referred to as reverse preorder traversal.
 *
 * ### Iterative Postorder Traversal of a tree
 * For traversing a (non-empty) binary tree in a postorder fashion, we must do
 * these three things for every node n starting from the tree’s root:
 *
 * (L) Recursively traverse its left subtree. When this step is finished,
 * we are back at n again.
 * (R) Recursively traverse its right subtree. When this step is finished,
 * we are back at n again.
 * (N) Process n itself.
 *
 * In normal postorder traversal, visit the left subtree before the right
 * subtree. If we visit the right subtree before visiting the left subtree, it
 * is referred to as reverse postorder traversal.
 *
 * @author [Lajat Manekar](https://github.com/Lazeeez)
 *
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for I/O operations
#include <vector>    /// for vector

/**
 * @namespace others
 * @brief Other algorithms
 */
namespace others {

/**
 * @namespace interpolation_search
 * @brief Functions for the Recursive version of Inorder, Preorder, and
 * Postorder [Traversal of the
 * Tree](https://en.wikipedia.org/wiki/Tree_traversal) algorithm implementation
 */
namespace recursive_tree_traversals {

/**
 * @brief The structure to hold Nodes of the tree.
 * @param data Value that will be stored in the node.
 * @param left follow up left subtree.
 * @param right follow up right subtree.
 */
struct Node {
    std::uint64_t data = 0;  ///< The value/key of the node.
    struct Node *left{};     ///< struct pointer to left subtree.
    struct Node *right{};    ///< struct pointer to right subtree.
};
/**
 * @brief BT used to make the entire structure of the binary tree and the
 * functions associated with the binary tree
 */
class BT {
 public:
    std::vector<std::uint64_t>
        inorder_result;  // vector to store the inorder traversal of the tree.
    std::vector<std::uint64_t>
        preorder_result;  // vector to store the preorder traversal of the tree.
    std::vector<std::uint64_t>
        postorder_result;  // vector to store the preorder
                           // traversal of the tree.

    Node *createNewNode(
        std::uint64_t);  // function that will create new node for insertion.

    std::vector<std::uint64_t> inorder(
        Node *);  // function that takes root of the tree as an argument and
                  // returns its inorder traversal.
    std::vector<std::uint64_t> preorder(
        Node *);  // function that takes root of the tree as an argument and
                  // returns its preorder traversal.
    std::vector<std::uint64_t> postorder(
        Node *);  // function that takes root of the tree as an argument and
                  // returns its postorder traversal.
};

/**
 * @brief will allocate the memory for a node and, along the data and return the
 * node.
 * @param data value that a particular node will contain.
 * @return pointer to the newly created node with assigned data.
 */
Node *BT::createNewNode(std::uint64_t data) {
    Node *node = new Node();
    node->data = data;
    node->left = node->right = nullptr;
    return node;
}

/*
 * @brief inorder() function that will perform the inorder traversal
 * recursively, and return the resultant vector that contain the inorder
 * traversal of a tree.
 * @param root head/root node of a tree
 * @return result that is containing the inorder traversal of a tree
 **/
std::vector<std::uint64_t> BT::inorder(Node *root) {
    if (root == nullptr) {  // return if the current node is empty
        return {};
    }

    inorder(root->left);  // Traverse the left subtree
    BT::inorder_result.push_back(
        root->data);  // Display the data part of the root (or current node)
    inorder(root->right);  // Traverse the right subtree

    return inorder_result;
}

/**
 * @brief preorder function that will perform the preorder traversal
 * recursively, and return the resultant vector that contain the preorder
 * traversal of a tree.
 * @param root head/root node of a tree
 * @return result that is containing the preorder traversal of a tree
 */
std::vector<std::uint64_t> BT::preorder(Node *root) {
    if (root == nullptr) {  // if the current node is empty
        return {};
    }

    BT::preorder_result.push_back(
        root->data);  // Display the data part of the root (or current node)
    preorder(root->left);   // Traverse the left subtree
    preorder(root->right);  // Traverse the right subtree

    return preorder_result;
}

/**
 * @brief postorder function that will perform the postorder traversal
 * recursively, and return the result vector that contain the postorder
 * traversal of a tree.
 * @param root head/root node of a tree
 * @return result that is containing the postorder traversal of a tree
 */
std::vector<std::uint64_t> BT::postorder(Node *root) {
    if (root == nullptr) {  // if the current node is empty
        return {};
    }

    postorder(root->left);   // Traverse the left subtree
    postorder(root->right);  // Traverse the right subtree
    BT::postorder_result.push_back(
        root->data);  // Display the data part of the root (or current node)

    return postorder_result;
}

void deleteAll(const Node *const root) {
    if (root) {
        deleteAll(root->left);
        deleteAll(root->right);
        delete root;
    }
}

}  // namespace recursive_tree_traversals

}  // namespace others

