/**
 * @file
 * @brief Recursive Inorder, Preorder, and Postorder [tree
 * traversal](https://en.wikipedia.org/wiki/Tree_traversal) implementations.
 *
 * @details
 *
 * ### Inorder traversal
 * Starting from the root, for each node n we:
 * (L) recursively walk the left subtree,
 * (N) visit n itself,
 * (R) recursively walk the right subtree.
 * Visiting the right side before the left would instead be called a
 * reverse-inorder walk.
 *
 * ### Preorder traversal
 * Starting from the root, for each node n we:
 * (N) visit n itself,
 * (L) recursively walk the left subtree,
 * (R) recursively walk the right subtree.
 * Again, swapping the left/right order yields a reverse-preorder walk.
 *
 * ### Postorder traversal
 * Starting from the root, for each node n we:
 * (L) recursively walk the left subtree,
 * (R) recursively walk the right subtree,
 * (N) visit n itself.
 * Swapping left/right here yields a reverse-postorder walk.
 *
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for I/O operations
#include <vector>    /// for std::vector

/**
 * @namespace others
 * @brief Miscellaneous algorithms that don't fit a bigger category
 */
namespace others {

/**
 * @namespace recursive_tree_traversals
 * @brief Recursive inorder/preorder/postorder walks over a binary tree
 */
namespace recursive_tree_traversals {

/**
 * @brief A single binary-tree node.
 */
struct TreeNode {
    std::uint64_t value = 0;      ///< payload stored at this node
    TreeNode *leftChild{};        ///< pointer to the left subtree (or null)
    TreeNode *rightChild{};       ///< pointer to the right subtree (or null)
};

/**
 * @brief Wraps a binary tree along with the traversal orders that have
 * been collected so far.
 */
class BinaryTree {
 public:
    std::vector<std::uint64_t> inorderTrace;    ///< accumulated inorder walk
    std::vector<std::uint64_t> preorderTrace;   ///< accumulated preorder walk
    std::vector<std::uint64_t> postorderTrace;  ///< accumulated postorder walk

    TreeNode *makeNode(std::uint64_t value);

    std::vector<std::uint64_t> walkInorder(TreeNode *node);
    std::vector<std::uint64_t> walkPreorder(TreeNode *node);
    std::vector<std::uint64_t> walkPostorder(TreeNode *node);
};

/**
 * @brief Allocates a fresh, childless node carrying the given value.
 * @param value payload for the new node
 * @return pointer to the freshly allocated node
 */
TreeNode *BinaryTree::makeNode(std::uint64_t value) {
    auto *node = new TreeNode();
    node->value = value;
    node->leftChild = nullptr;
    node->rightChild = nullptr;
    return node;
}

/**
 * @brief Recursively records an inorder (left, node, right) traversal.
 * @param node subtree root to walk
 * @return the accumulated inorder trace so far
 */
std::vector<std::uint64_t> BinaryTree::walkInorder(TreeNode *node) {
    if (node == nullptr) {
        return {};
    }

    walkInorder(node->leftChild);
    inorderTrace.push_back(node->value);
    walkInorder(node->rightChild);

    return inorderTrace;
}

/**
 * @brief Recursively records a preorder (node, left, right) traversal.
 * @param node subtree root to walk
 * @return the accumulated preorder trace so far
 */
std::vector<std::uint64_t> BinaryTree::walkPreorder(TreeNode *node) {
    if (node == nullptr) {
        return {};
    }

    preorderTrace.push_back(node->value);
    walkPreorder(node->leftChild);
    walkPreorder(node->rightChild);

    return preorderTrace;
}

/**
 * @brief Recursively records a postorder (left, right, node) traversal.
 * @param node subtree root to walk
 * @return the accumulated postorder trace so far
 */
std::vector<std::uint64_t> BinaryTree::walkPostorder(TreeNode *node) {
    if (node == nullptr) {
        return {};
    }

    walkPostorder(node->leftChild);
    walkPostorder(node->rightChild);
    postorderTrace.push_back(node->value);

    return postorderTrace;
}

/**
 * @brief Recursively frees every node reachable from the given root.
 * @param node subtree root to tear down
 */
void freeSubtree(const TreeNode *const node) {
    if (node != nullptr) {
        freeSubtree(node->leftChild);
        freeSubtree(node->rightChild);
        delete node;
    }
}

}  // namespace recursive_tree_traversals

}  // namespace others

namespace {

/**
 * @brief Compares an expected sequence against a produced sequence
 * element by element.
 */
void expectSequenceEqual(const std::vector<std::uint64_t> &expected,
                          const std::vector<std::uint64_t> &actual) {
    for (std::size_t i = 0; i < expected.size(); ++i) {
        assert(expected[i] == actual[i]);
    }
}

}  // namespace

/**
 * @brief First traversal scenario: a nine-node, three-level-deep tree.
 */
void scenarioNineNodes() {
    others::recursive_tree_traversals::BinaryTree tree;
    auto *root = tree.makeNode(2);
    root->leftChild = tree.makeNode(7);
    root->rightChild = tree.makeNode(5);
    root->leftChild->leftChild = tree.makeNode(2);
    root->leftChild->rightChild = tree.makeNode(6);
    root->rightChild->rightChild = tree.makeNode(9);
    root->leftChild->rightChild->leftChild = tree.makeNode(5);
    root->leftChild->rightChild->rightChild = tree.makeNode(11);
    root->rightChild->rightChild->leftChild = tree.makeNode(4);

    std::vector<std::uint64_t> expectedInorder{2, 7, 5, 6, 11, 2, 5, 4, 9};
    std::vector<std::uint64_t> expectedPreorder{2, 7, 2, 6, 5, 11, 5, 9, 4};
    std::vector<std::uint64_t> expectedPostorder{2, 5, 11, 6, 7, 4, 9, 5, 2};

    std::cout << "Scenario #1: Inorder Traversal...";
    expectSequenceEqual(expectedInorder, tree.walkInorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << "Scenario #1: Preorder Traversal...";
    expectSequenceEqual(expectedPreorder, tree.walkPreorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << "Scenario #1: Postorder Traversal...";
    expectSequenceEqual(expectedPostorder, tree.walkPostorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << std::endl;
    others::recursive_tree_traversals::freeSubtree(root);
}

/**
 * @brief Second traversal scenario: an eight-node tree, unbalanced to
 * the right.
 */
void scenarioEightNodes() {
    others::recursive_tree_traversals::BinaryTree tree;
    auto *root = tree.makeNode(1);
    root->leftChild = tree.makeNode(2);
    root->rightChild = tree.makeNode(3);
    root->leftChild->leftChild = tree.makeNode(4);
    root->rightChild->leftChild = tree.makeNode(5);
    root->rightChild->rightChild = tree.makeNode(6);
    root->rightChild->leftChild->leftChild = tree.makeNode(7);
    root->rightChild->leftChild->rightChild = tree.makeNode(8);

    std::vector<std::uint64_t> expectedInorder{4, 2, 1, 7, 5, 8, 3, 6};
    std::vector<std::uint64_t> expectedPreorder{1, 2, 4, 3, 5, 7, 8, 6};
    std::vector<std::uint64_t> expectedPostorder{4, 2, 7, 8, 5, 6, 3, 1};

    std::cout << "Scenario #2: Inorder Traversal...";
    expectSequenceEqual(expectedInorder, tree.walkInorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << "Scenario #2: Preorder Traversal...";
    expectSequenceEqual(expectedPreorder, tree.walkPreorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << "Scenario #2: Postorder Traversal...";
    expectSequenceEqual(expectedPostorder, tree.walkPostorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << std::endl;
    others::recursive_tree_traversals::freeSubtree(root);
}

/**
 * @brief Third traversal scenario: a compact five-node tree.
 */
void scenarioFiveNodes() {
    others::recursive_tree_traversals::BinaryTree tree;
    auto *root = tree.makeNode(1);
    root->leftChild = tree.makeNode(2);
    root->rightChild = tree.makeNode(3);
    root->leftChild->leftChild = tree.makeNode(4);
    root->leftChild->rightChild = tree.makeNode(5);

    std::vector<std::uint64_t> expectedInorder{4, 2, 5, 1, 3};
    std::vector<std::uint64_t> expectedPreorder{1, 2, 4, 5, 3};
    std::vector<std::uint64_t> expectedPostorder{4, 5, 2, 3, 1};

    std::cout << "Scenario #3: Inorder Traversal...";
    expectSequenceEqual(expectedInorder, tree.walkInorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << "Scenario #3: Preorder Traversal...";
    expectSequenceEqual(expectedPreorder, tree.walkPreorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << "Scenario #3: Postorder Traversal...";
    expectSequenceEqual(expectedPostorder, tree.walkPostorder(root));
    std::cout << "Passed!" << std::endl;

    std::cout << std::endl;
    others::recursive_tree_traversals::freeSubtree(root);
}

/**
 * @brief Runs every traversal scenario in sequence.
 */
static void runAllScenarios() {
    std::cout << "Scenario 1" << std::endl;
    scenarioNineNodes();
    std::cout << "Scenario 2" << std::endl;
    scenarioEightNodes();
    std::cout << "Scenario 3" << std::endl;
    scenarioFiveNodes();
}

/**
 * @brief Program entry point.
 * @returns 0 on success
 */
int main() {
    runAllScenarios();
    return 0;
}

/**
 * @file
@brief This program is use to print the following pattern<pre>
   \*\*
   \*\*
  \*\*\*\*
  \*\*\*\*
 \*\*\*\*\*\*
 \*\*\*\*\*\*
\*\*\*\*\*\*\*\*
********</pre>
where number of pairs line is given by user
*/
#include <iostream>

/** main function */
int main() {
    int l, st = 2, x, r, z, n, sp;
    std::cout << "Enter number of pair - ";
    std::cin >> x;
    z = x;
    for (r = 1; r <= x; r++) {
        z = z - 1;
        for (n = 1; n <= 2; n++) {
            for (sp = 1; sp <= z; sp++) {
                std::cout << " ";
            }
            for (l = 1; l <= st; l++) {
                std::cout << "\\*";
            }
            std::cout << std::endl;
        }
        st = st + 2;
    }
}

/**
 * @file
 * @brief Draws a symmetric "double staircase" pattern made of pairs of rows,
 * each pair using two asterisks (escaped) per step, e.g. for 4 pairs:<pre>
 *    \*\*
 *    \*\*
 *   \*\*\*\*
 *   \*\*\*\*
 *  \*\*\*\*\*\*
 *  \*\*\*\*\*\*
 * \*\*\*\*\*\*\*\*
 * ********</pre>
 * The number of row-pairs is supplied by the user.
 */
#include <iostream>

/** Print one line of leading spaces followed by a run of escaped stars.
 * \param [in] leadingSpaces how many blank columns to print before the stars
 * \param [in] starPairs how many "\*" tokens to print on this line
 */
void printStepLine(int leadingSpaces, int starPairs) {
    for (int gap = 0; gap < leadingSpaces; ++gap) {
        std::cout << " ";
    }
    for (int star = 0; star < starPairs; ++star) {
        std::cout << "\\*";
    }
    std::cout << std::endl;
}

/** Entry point: reads the number of step-pairs and draws each step twice,
 * widening the star count and shrinking the indentation as it descends. */
int main() {
    int stepCount = 0;
    std::cout << "Enter number of pair - ";
    std::cin >> stepCount;

    int starsThisStep = 2;
    int indent = stepCount;

    for (int step = 1; step <= stepCount; ++step) {
        --indent;
        for (int repeat = 0; repeat < 2; ++repeat) {
            printStepLine(indent, starsThisStep);
        }
        starsThisStep += 2;
    }

    return 0;
}

/**
 * @file
 * @brief [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 *
 * The exponential distribution is used to model
 * events occuring between a Poisson process like radioactive decay.
 *
 * \f[P(x, \lambda) = \lambda e^{-\lambda x}\f]
 *
 * Summary of variables used:
 * \f$\lambda\f$ : rate parameter
 */

#include <cassert>    // For assert
#include <cmath>      // For std::pow
#include <iostream>   // For I/O operation
#include <stdexcept>  // For std::invalid_argument
#include <string>     // For std::string

/**
 * @namespace probability
 * @brief Probability algorithms
 */
namespace probability {
/**
 * @namespace exponential_dist
 * @brief Functions for the [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 * algorithm implementation
 */
namespace geometric_dist {
/**
 * @brief the expected value of the exponential distribution
 * @returns \f[\mu = \frac{1}{\lambda}\f]
 */
double exponential_expected(double lambda) {
    if (lambda <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
    return 1 / lambda;
}

/**
 * @brief the variance of the exponential distribution
 * @returns \f[\sigma^2 = \frac{1}{\lambda^2}\f]
 */
double exponential_var(double lambda) {
    if (lambda <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
    return 1 / pow(lambda, 2);
}

/**
 * @brief the standard deviation of the exponential distribution
 * @returns \f[\sigma = \frac{1}{\lambda}\f]
 */
double exponential_std(double lambda) {
    if (lambda <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
    return 1 / lambda;
}
}  // namespace geometric_dist
}  // namespace probability

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    double lambda_1 = 1;
    double expected_1 = 1;
    double var_1 = 1;
    double std_1 = 1;

    double lambda_2 = 2;
    double expected_2 = 0.5;
    double var_2 = 0.25;
    double std_2 = 0.5;

    double lambda_3 = 3;
    double expected_3 = 0.333333;
    double var_3 = 0.111111;
    double std_3 = 0.333333;

    double lambda_4 = 0;     // Test 0
    double lambda_5 = -2.3;  // Test negative value

    const float threshold = 1e-3f;

    std::cout << "Test for lambda = 1 \n";
    assert(
        std::abs(expected_1 - probability::geometric_dist::exponential_expected(
                                  lambda_1)) < threshold);
    assert(std::abs(var_1 - probability::geometric_dist::exponential_var(
                                lambda_1)) < threshold);
    assert(std::abs(std_1 - probability::geometric_dist::exponential_std(
                                lambda_1)) < threshold);
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = 2 \n";
    assert(
        std::abs(expected_2 - probability::geometric_dist::exponential_expected(
                                  lambda_2)) < threshold);
    assert(std::abs(var_2 - probability::geometric_dist::exponential_var(
                                lambda_2)) < threshold);
    assert(std::abs(std_2 - probability::geometric_dist::exponential_std(
                                lambda_2)) < threshold);
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = 3 \n";
    assert(
        std::abs(expected_3 - probability::geometric_dist::exponential_expected(
                                  lambda_3)) < threshold);
    assert(std::abs(var_3 - probability::geometric_dist::exponential_var(
                                lambda_3)) < threshold);
    assert(std::abs(std_3 - probability::geometric_dist::exponential_std(
                                lambda_3)) < threshold);
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = 0 \n";
    try {
        probability::geometric_dist::exponential_expected(lambda_4);
        probability::geometric_dist::exponential_var(lambda_4);
        probability::geometric_dist::exponential_std(lambda_4);
    } catch (std::invalid_argument& err) {
        assert(std::string(err.what()) == "lambda must be greater than 0");
    }
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = -2.3 \n";
    try {
        probability::geometric_dist::exponential_expected(lambda_5);
        probability::geometric_dist::exponential_var(lambda_5);
        probability::geometric_dist::exponential_std(lambda_5);
    } catch (std::invalid_argument& err) {
        assert(std::string(err.what()) == "lambda must be greater than 0");
    }
    std::cout << "ALL TEST PASSED\n\n";
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    test();  // Self test implementation
    return 0;
}

/**
 * @file
 * @brief [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 * routines
 *
 * The exponential distribution models the waiting time between successive
 * events of a Poisson process, such as radioactive decay.
 *
 * \f[f(x, \lambda) = \lambda e^{-\lambda x}\f]
 *
 * Naming used below:
 * \f$\lambda\f$ (rate) : the rate parameter of the process
 */

#include <cassert>    // For assert
#include <cmath>      // For std::pow
#include <iostream>   // For I/O operation
#include <stdexcept>  // For std::invalid_argument
#include <string>     // For std::string

/**
 * @namespace probability
 * @brief Probability algorithms
 */
namespace probability {
/**
 * @namespace exponential_dist
 * @brief Functions for the [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 * algorithm implementation
 */
namespace exponential_dist {
/**
 * @brief Validates that a rate parameter is usable, throwing otherwise.
 * @param rate the rate parameter to validate
 */
void ensurePositiveRate(double rate) {
    if (rate <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
}

/**
 * @brief the mean of the exponential distribution
 * @returns \f[\mu = \frac{1}{\lambda}\f]
 */
double distributionMean(double rate) {
    ensurePositiveRate(rate);
    return 1 / rate;
}

/**
 * @brief the variance of the exponential distribution
 * @returns \f[\sigma^2 = \frac{1}{\lambda^2}\f]
 */
double distributionVariance(double rate) {
    ensurePositiveRate(rate);
    return 1 / pow(rate, 2);
}

/**
 * @brief the standard deviation of the exponential distribution
 * @returns \f[\sigma = \frac{1}{\lambda}\f]
 */
double distributionStdDev(double rate) {
    ensurePositiveRate(rate);
    return 1 / rate;
}
}  // namespace exponential_dist
}  // namespace probability

/**
 * @brief Runs a battery of checks for a single rate value, comparing the
 * computed mean/variance/std-dev against expected constants.
 * @returns void
 */
static void checkRate(double rate, double expectedMean, double expectedVar,
                       double expectedStd, float tolerance) {
    std::cout << "Checking lambda = " << rate << "\n";
    assert(std::abs(expectedMean -
                     probability::exponential_dist::distributionMean(rate)) <
           tolerance);
    assert(std::abs(expectedVar - probability::exponential_dist::
                                       distributionVariance(rate)) <
           tolerance);
    assert(std::abs(expectedStd -
                     probability::exponential_dist::distributionStdDev(
                         rate)) < tolerance);
    std::cout << "ALL TEST PASSED\n\n";
}

/**
 * @brief Confirms that invalid rate values raise the expected exception.
 * @returns void
 */
static void checkInvalidRate(double rate) {
    std::cout << "Checking lambda = " << rate << "\n";
    try {
        probability::exponential_dist::distributionMean(rate);
        probability::exponential_dist::distributionVariance(rate);
        probability::exponential_dist::distributionStdDev(rate);
    } catch (std::invalid_argument& err) {
        assert(std::string(err.what()) == "lambda must be greater than 0");
    }
    std::cout << "ALL TEST PASSED\n\n";
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    const float tolerance = 1e-3f;

    checkRate(1, 1, 1, 1, tolerance);
    checkRate(2, 0.5, 0.25, 0.5, tolerance);
    checkRate(3, 0.333333, 0.111111, 0.333333, tolerance);

    checkInvalidRate(0);      // boundary case
    checkInvalidRate(-2.3);   // negative rate
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    test();  // Self test implementation
    return 0;
}

#include <algorithm>
#include <cmath>
#include <iostream>

using namespace std;
const int N = 1e6 + 5;
int a[N], bucket[N], cnt[N];
int bucket_size;
struct query {
    int l, r, i;
} q[N];
int ans = 0;

void add(int index) {
    cnt[a[index]]++;
    if (cnt[a[index]] == 1)
        ans++;
}
void remove(int index) {
    cnt[a[index]]--;
    if (cnt[a[index]] == 0)
        ans--;
}

bool mycmp(query x, query y) {
    if (x.l / bucket_size != y.l / bucket_size)
        return x.l / bucket_size < y.l / bucket_size;
    return x.r < y.r;
}

int main() {
    int n, t, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    bucket_size = ceil(sqrt(n));
    scanf("%d", &t);
    for (i = 0; i < t; i++) {
        scanf("%d %d", &q[i].l, &q[i].r);
        q[i].l--;
        q[i].r--;
        q[i].i = i;
    }
    sort(q, q + t, mycmp);
    int left = 0, right = 0;
    for (i = 0; i < t; i++) {
        int L = q[i].l, R = q[i].r;
        while (left < L) {
            remove(left);
            left++;
        }
        while (left > L) {
            add(left - 1);
            left--;
        }
        while (right <= R) {
            add(right);
            right++;
        }
        while (right > R + 1) {
            remove(right - 1);
            right--;
        }
        bucket[q[i].i] = ans;
    }
    for (i = 0; i < t; i++) printf("%d\n", bucket[i]);
    return 0;
}

// Offline range-query answering using Mo's square-root decomposition trick.
// Instead of answering each [l, r] query independently, we reorder the
// queries so that consecutive ones share most of their range, then slide
// a two-pointer window across the array, paying only for the incremental
// difference between queries.
#include <algorithm>
#include <cmath>
#include <iostream>

using namespace std;

const int MAXN = 1e6 + 5;

int values[MAXN];         // the input sequence
int distinctCountAt[MAXN]; // frequency table over value domain
int resultFor[MAXN];       // answer per original query index
int blockWidth;

struct Range {
    int from, to, originalIndex;
};

Range ranges[MAXN];
int distinctInWindow = 0;

// Including position p into the active window.
void includePos(int p) {
    distinctCountAt[values[p]]++;
    if (distinctCountAt[values[p]] == 1) {
        distinctInWindow++;
    }
}

// Excluding position p from the active window.
void excludePos(int p) {
    distinctCountAt[values[p]]--;
    if (distinctCountAt[values[p]] == 0) {
        distinctInWindow--;
    }
}

// Comparator implementing Mo's ordering: bucket by block, then by right end.
bool moOrder(const Range &a, const Range &b) {
    int blockA = a.from / blockWidth;
    int blockB = b.from / blockWidth;
    if (blockA != blockB) {
        return blockA < blockB;
    }
    return a.to < b.to;
}

int main() {
    int n, queryCount;
    scanf("%d", &n);
    for (int idx = 0; idx < n; idx++) {
        scanf("%d", &values[idx]);
    }

    blockWidth = static_cast<int>(ceil(sqrt(static_cast<double>(n))));

    scanf("%d", &queryCount);
    for (int idx = 0; idx < queryCount; idx++) {
        scanf("%d %d", &ranges[idx].from, &ranges[idx].to);
        ranges[idx].from--;
        ranges[idx].to--;
        ranges[idx].originalIndex = idx;
    }

    sort(ranges, ranges + queryCount, moOrder);

    int windowLeft = 0, windowRight = 0;
    for (int idx = 0; idx < queryCount; idx++) {
        int targetLeft = ranges[idx].from;
        int targetRight = ranges[idx].to;

        while (windowLeft < targetLeft) {
            excludePos(windowLeft);
            windowLeft++;
        }
        while (windowLeft > targetLeft) {
            includePos(windowLeft - 1);
            windowLeft--;
        }
        while (windowRight <= targetRight) {
            includePos(windowRight);
            windowRight++;
        }
        while (windowRight > targetRight + 1) {
            excludePos(windowRight - 1);
            windowRight--;
        }

        resultFor[ranges[idx].originalIndex] = distinctInWindow;
    }

    for (int idx = 0; idx < queryCount; idx++) {
        printf("%d\n", resultFor[idx]);
    }
    return 0;
}

/**
 * @file
 * @brief
 * [Prefix Sum
 * Array](https://en.wikipedia.org/wiki/Prefix_sum) data structure
 * implementation.
 *
 * @details
 * Prefix Sum Array is a data structure, that allows answering sum in some range
 * queries. It can answer most sum range queries in O(1), with a build time
 * complexity of O(N). But it hasn't an update querie.
 *
 * * Running Time Complexity \n
 * * Build : O(N) \n
 * * Range Query : O(1) \n
 * @author [Paulo Vitor Lima Borges](https://github.com/PauloVLB)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace range_queries
 * @brief Range Queries algorithms
 */
namespace range_queries {
/**
 * @namespace prefix_sum_array
 * @brief Range sum queries using prefix-sum-array
 */
namespace prefix_sum_array {

std::vector<int64_t> PSA{};

/**
 * @brief function that builds the PSA
 * @param original_array original array of values
 * @returns void
 */
void build(const std::vector<int64_t>& original_array) {
    PSA.clear();
    PSA.push_back(0);
    for (std::size_t i = 1; i < original_array.size(); ++i) {
        PSA.push_back(PSA.back() + original_array[i]);
    }
}
/**
 * @brief query function
 * @param beg begin of the interval to sum
 * @param end end of the interval to sum
 * @returns sum of the range [beg, end]
 */
int64_t query(int64_t beg, int64_t end) { return PSA[end] - PSA[beg - 1]; }

}  // namespace prefix_sum_array
}  // namespace range_queries

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    std::vector<int64_t> values{0,  123, 0,  2,  -2, 5,
                                24, 0,   23, -1, -1};  // original array

    range_queries::prefix_sum_array::build(values);
    // queries are of the type: sum of the range [a, b] = psa[b] - psa[a-1]

    assert(range_queries::prefix_sum_array::query(1, 10) ==
           173);  // sum of the entire array
    assert(range_queries::prefix_sum_array::query(4, 6) ==
           27);  // the sum of the interval [4, 6]
    assert(range_queries::prefix_sum_array::query(5, 9) ==
           51);  // the sum of the interval [5, 9]
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Cumulative-sum array (a.k.a. prefix sums) letting range-sum
 * queries run in constant time after a linear-time precomputation pass.
 *
 * @details
 * By precomputing running totals of the input sequence we can answer
 * "what is the sum between index a and b" queries in O(1) each, at the
 * cost of O(n) preprocessing and O(n) extra storage. The tradeoff is that
 * there is no efficient way to update individual elements afterward
 * without rebuilding (or using a Fenwick/segment tree instead).
 *
 * * Preprocessing: O(n)
 * * Each range query: O(1)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace range_queries
 * @brief Range query algorithms
 */
namespace range_queries {
/**
 * @namespace prefix_sum_array
 * @brief Constant-time range sums via a running-total array
 */
namespace prefix_sum_array {

std::vector<int64_t> runningTotals{};

/**
 * @brief Builds the running-total table from the raw input sequence.
 * @param sourceData the sequence to precompute sums over
 */
void buildTable(const std::vector<int64_t>& sourceData) {
    runningTotals.clear();
    runningTotals.push_back(0);
    for (std::size_t pos = 1; pos < sourceData.size(); ++pos) {
        runningTotals.push_back(runningTotals.back() + sourceData[pos]);
    }
}

/**
 * @brief Returns the sum of elements over the inclusive range [from, to].
 * @param from start of the range (1-indexed style, matching original array)
 * @param to end of the range
 * @returns sum across [from, to]
 */
int64_t rangeSum(int64_t from, int64_t to) {
    return runningTotals[to] - runningTotals[from - 1];
}

}  // namespace prefix_sum_array
}  // namespace range_queries

/**
 * @brief Sanity checks exercising a handful of ranges
 */
static void runChecks() {
    std::vector<int64_t> sample{0,  123, 0,  2,  -2, 5,
                                24, 0,   23, -1, -1};

    range_queries::prefix_sum_array::buildTable(sample);

    assert(range_queries::prefix_sum_array::rangeSum(1, 10) == 173);
    assert(range_queries::prefix_sum_array::rangeSum(4, 6) == 27);
    assert(range_queries::prefix_sum_array::rangeSum(5, 9) == 51);
}

int main() {
    runChecks();
    return 0;
}

/**
 * @file sparse_table.cpp
 * @brief Implementation of [Sparse
 * Table](https://en.wikipedia.org/wiki/Range_minimum_query) data structure
 *
 * @details
 * Sparse Table is a data structure, that allows answering range queries.
 * It can answer most range queries in O(logn), but its true power is answering
 * range minimum queries or equivalent range maximum queries). For those queries
 * it can compute the answer in O(1) time.
 *
 * * Running Time Complexity \n
 * * Build : O(NlogN) \n
 * * Range Query : O(1) \n
 */

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

/**
 * @namespace range_queries
 * @brief Range Queries algorithms
 */
namespace range_queries {
/**
 * @namespace sparse_table
 * @brief Range queries using sparse-tables
 */
namespace sparse_table {
/**
 * This function precomputes intial log table for further use.
 * @param n value of the size of the input array
 * @return corresponding vector of the log table
 */
template <typename T>
std::vector<T> computeLogs(const std::vector<T>& A) {
    int n = A.size();
    std::vector<T> logs(n);
    logs[1] = 0;
    for (int i = 2; i < n; i++) {
        logs[i] = logs[i / 2] + 1;
    }
    return logs;
}

/**
 * This functions builds the primary data structure sparse table
 * @param n value of the size of the input array
 * @param A array of the input integers
 * @param logs array of the log table
 * @return created sparse table data structure
 */
template <typename T>
std::vector<std::vector<T> > buildTable(const std::vector<T>& A,
                                        const std::vector<T>& logs) {
    int n = A.size();
    std::vector<std::vector<T> > table(20, std::vector<T>(n + 5, 0));
    int curLen = 0;
    for (int i = 0; i <= logs[n]; i++) {
        curLen = 1 << i;
        for (int j = 0; j + curLen < n; j++) {
            if (curLen == 1) {
                table[i][j] = A[j];
            } else {
                table[i][j] =
                    std::min(table[i - 1][j], table[i - 1][j + curLen / 2]);
            }
        }
    }
    return table;
}

/**
 * This function is the query function to get the range minimum value
 * @param beg beginning index of the query range
 * @param end ending index of the query range
 * @param logs array of the log table
 * @param table sparse table data structure for the input array
 * @return minimum value for the [beg, end] range for the input array
 */
template <typename T>
int getMinimum(int beg, int end, const std::vector<T>& logs,
               const std::vector<std::vector<T> >& table) {
    int p = logs[end - beg + 1];
    int pLen = 1 << p;
    return std::min(table[p][beg], table[p][end - pLen + 1]);
}
}  // namespace sparse_table
}  // namespace range_queries

/**
 * Main function
 */
int main() {
    std::vector<int> A{1, 2, 0, 3, 9};
    std::vector<int> logs = range_queries::sparse_table::computeLogs(A);
    std::vector<std::vector<int> > table =
        range_queries::sparse_table::buildTable(A, logs);
    assert(range_queries::sparse_table::getMinimum(0, 0, logs, table) == 1);
    assert(range_queries::sparse_table::getMinimum(0, 4, logs, table) == 0);
    assert(range_queries::sparse_table::getMinimum(2, 4, logs, table) == 0);
    return 0;
}

/**
 * @file sparse_table_range_queries.cpp
 * @brief Sparse table structure for O(1) range-minimum queries
 *
 * @details
 * A sparse table precomputes, for every power-of-two length, the minimum
 * over every window of that length. Because "minimum" is idempotent, two
 * overlapping precomputed windows can be combined to answer any range query
 * without recomputation.
 *
 * Complexity:
 *   Build:        O(n log n)
 *   Query:        O(1)
 */

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

/**
 * @namespace range_queries
 * @brief Range Queries algorithms
 */
namespace range_queries {

/**
 * @namespace sparse_table
 * @brief Range queries using sparse tables
 */
namespace sparse_table {

/**
 * @brief Builds a lookup table where entry i holds floor(log2(i)).
 * @param data the array we plan on querying (only its size matters here)
 * @return a vector such that result[i] == floor(log2(i))
 */
template <typename T>
std::vector<T> buildLogLookup(const std::vector<T>& data) {
    int count = data.size();
    std::vector<T> logLookup(count);
    logLookup[1] = 0;
    for (int i = 2; i < count; i++) {
        logLookup[i] = logLookup[i / 2] + 1;
    }
    return logLookup;
}

/**
 * @brief Constructs the sparse table itself.
 * @param data the source array
 * @param logLookup precomputed floor(log2(i)) values
 * @return a 2D table where table[k][i] holds the min over data[i..i+2^k-1]
 */
template <typename T>
std::vector<std::vector<T> > constructSparseTable(const std::vector<T>& data,
                                                    const std::vector<T>& logLookup) {
    int count = data.size();
    std::vector<std::vector<T> > table(20, std::vector<T>(count + 5, 0));
    int windowLen = 0;
    for (int level = 0; level <= logLookup[count]; level++) {
        windowLen = 1 << level;
        for (int start = 0; start + windowLen < count; start++) {
            if (windowLen == 1) {
                table[level][start] = data[start];
            } else {
                table[level][start] = std::min(table[level - 1][start],
                                                table[level - 1][start + windowLen / 2]);
            }
        }
    }
    return table;
}

/**
 * @brief Answers a range-minimum query using the prebuilt sparse table.
 * @param left inclusive left bound of the query
 * @param right inclusive right bound of the query
 * @param logLookup precomputed floor(log2(i)) values
 * @param table sparse table built by constructSparseTable
 * @return minimum element within data[left..right]
 */
template <typename T>
int queryMinimum(int left, int right, const std::vector<T>& logLookup,
                  const std::vector<std::vector<T> >& table) {
    int level = logLookup[right - left + 1];
    int windowLen = 1 << level;
    return std::min(table[level][left], table[level][right - windowLen + 1]);
}

}  // namespace sparse_table
}  // namespace range_queries

/**
 * Program entry point exercising the sparse table on a small example.
 */
int main() {
    std::vector<int> values{1, 2, 0, 3, 9};
    std::vector<int> logLookup = range_queries::sparse_table::buildLogLookup(values);
    std::vector<std::vector<int> > table =
        range_queries::sparse_table::constructSparseTable(values, logLookup);

    assert(range_queries::sparse_table::queryMinimum(0, 0, logLookup, table) == 1);
    assert(range_queries::sparse_table::queryMinimum(0, 4, logLookup, table) == 0);
    assert(range_queries::sparse_table::queryMinimum(2, 4, logLookup, table) == 0);
    return 0;
}

/**
 * @author sprintyaf
 * @file fibonacci_search.cpp
 * @brief [Fibonacci search
 * algorithm](https://en.wikipedia.org/wiki/Fibonacci_search_technique)
 */

#include <iostream>
#include <vector> // for std::vector class
#include <cassert> // for assert
#include <cstdlib> // for random numbers
#include <algorithm> // for sorting



/**
 * @brief using fibonacci search algorithm finds an index of a given element in a sorted array
 * 
 * @param arr sorted array
 * @param value value that we're looking for
 * @returns if the array contains the value, returns an index of the element. otherwise -1.
 */
int fibonacci_search(const std::vector<int> &arr, int value){
    // initialize last and current members of Fibonacci sequence 
    int last = 0, current = 1;
    int length = arr.size(); // array size
    // next member of Fibonacci sequence which is "last" + "current"
    int next = last + current; 

    // "next" will store the smallest Fibonacci number greater or equal to "length"
    while(next < length){
        last = current;
        current = next;
        next = last + current;
    }

    // "offset" is the end of eliminated range from front
    int offset = -1, index;
    // while loop until there are elements left to consider.
    // when "next" becomes 1, last is equal to 0, so search is done,
    // because arr[offset] will already be eliminated
    while(next > 1){
        // check if "last" is valid location
        index = std::min(offset + last, length-1);
        // if value is greater than the value at "index", eliminate the subarray from offset to index
        if(arr[index] < value){
            next = current;
            current = last;
            last = next - current;
            offset = index;
        // if value is less than the value at "index", eliminate the subarray after index+1
        } else if(arr[index] > value){
            next = last;
            current = current - last;
            last = next - current;
        // element is found
        } else {
            return index;
        }
    }
    // comparing the last element
    if(current && !arr.empty() && arr[offset+1] == value){
        return offset+1;
    }
    // value was not found, return -1
    return -1;
}

/**
 * @brief random tests for checking performance when an array doesn't contain an element
*/
bool no_occurence_tests(){
    bool passed = true;
    int rand_num, rand_value, index, num_tests = 1000;
    std::vector<int> arr;
    while(num_tests--){
        arr.clear();
        for(int i = 0; i < 100; i++){
            rand_num = std::rand() % 1000;
            arr.push_back(rand_num);
        }
        rand_value = std::rand() % 1000;
        while(std::find(arr.begin(), arr.end(), rand_value) != arr.end()){
            std::remove(arr.begin(), arr.end(), rand_value);
        }
        sort(arr.begin(), arr.end());
        index = fibonacci_search(arr, rand_value);
        passed = passed && (index == -1);
    }
    return passed;
}

/**
 * @brief random tests which cover cases when we have one, multiple or zero occurences of the value we're looking for
*/
bool random_tests(){
    bool passed = true;
    int rand_num, rand_value, index, real_value, num_tests = 10000;
    std::vector<int> arr;
    while(num_tests--){
        arr.clear();
        for(int i = 0; i < 100; i++){
            rand_num = std::rand() % 1000;
            arr.push_back(rand_num);
        }
        rand_value = std::rand() % 1000;
        std::sort(arr.begin(), arr.end());
        index = fibonacci_search(arr, rand_value);
        if(index != -1){
            real_value = arr[index];
            passed = passed && (real_value == rand_value);
        } else {
            passed = passed && (std::find(arr.begin(), arr.end(), rand_value) == arr.end());
        }
    }
    return passed;
}

/**
 * Main Function
 * testing the algorithm
 */
int main() {
    assert(no_occurence_tests());
    assert(random_tests());
    return 0;
}

/**
 * @file fibonacci_search.cpp
 * @brief Fibonacci search over a sorted array
 * @details
 * Instead of splitting the search interval in half like binary search,
 * Fibonacci search splits it according to consecutive Fibonacci numbers.
 * This can be handy on architectures where division is expensive since the
 * algorithm only needs addition and subtraction to advance.
 *
 * Rewritten variant for educational dataset generation.
 */

#include <iostream>
#include <vector>    // for std::vector
#include <cassert>   // for assert
#include <cstdlib>   // for random number generation
#include <algorithm> // for std::sort / std::find

/**
 * @brief Finds `target` in a sorted array using Fibonacci search.
 *
 * @param sortedArr array assumed to be sorted ascending
 * @param target value being searched for
 * @return index of target if present, otherwise -1
 */
int fibonacciLookup(const std::vector<int> &sortedArr, int target) {
    // fibPrev2/fibPrev1 track the two previous Fibonacci numbers,
    // fibCurrent is their sum (the smallest Fibonacci >= array length)
    int fibPrev2 = 0, fibPrev1 = 1;
    int n = sortedArr.size();
    int fibCurrent = fibPrev2 + fibPrev1;

    while (fibCurrent < n) {
        fibPrev2 = fibPrev1;
        fibPrev1 = fibCurrent;
        fibCurrent = fibPrev2 + fibPrev1;
    }

    // marks the boundary of the portion of the array already ruled out
    int excludedUpTo = -1;
    int probe;

    while (fibCurrent > 1) {
        probe = std::min(excludedUpTo + fibPrev2, n - 1);

        if (sortedArr[probe] < target) {
            // discard everything up to and including probe
            fibCurrent = fibPrev1;
            fibPrev1 = fibPrev2;
            fibPrev2 = fibCurrent - fibPrev1;
            excludedUpTo = probe;
        } else if (sortedArr[probe] > target) {
            // discard everything after probe
            fibCurrent = fibPrev2;
            fibPrev1 = fibPrev1 - fibPrev2;
            fibPrev2 = fibCurrent - fibPrev1;
        } else {
            return probe;
        }
    }

    // only one element may remain uncompared; check it explicitly
    if (fibPrev1 && !sortedArr.empty() && sortedArr[excludedUpTo + 1] == target) {
        return excludedUpTo + 1;
    }
    return -1;
}

/**
 * @brief Randomized regression: confirms -1 is returned for absent values.
 */
bool checkAbsentValues() {
    bool ok = true;
    int sample, missingValue, foundIdx, trials = 1000;
    std::vector<int> data;
    while (trials--) {
        data.clear();
        for (int i = 0; i < 100; i++) {
            sample = std::rand() % 1000;
            data.push_back(sample);
        }
        missingValue = std::rand() % 1000;
        while (std::find(data.begin(), data.end(), missingValue) != data.end()) {
            std::remove(data.begin(), data.end(), missingValue);
        }
        sort(data.begin(), data.end());
        foundIdx = fibonacciLookup(data, missingValue);
        ok = ok && (foundIdx == -1);
    }
    return ok;
}

/**
 * @brief Randomized regression covering present/absent/duplicate cases.
 */
bool checkGeneralCases() {
    bool ok = true;
    int sample, target, foundIdx, foundValue, trials = 10000;
    std::vector<int> data;
    while (trials--) {
        data.clear();
        for (int i = 0; i < 100; i++) {
            sample = std::rand() % 1000;
            data.push_back(sample);
        }
        target = std::rand() % 1000;
        std::sort(data.begin(), data.end());
        foundIdx = fibonacciLookup(data, target);
        if (foundIdx != -1) {
            foundValue = data[foundIdx];
            ok = ok && (foundValue == target);
        } else {
            ok = ok && (std::find(data.begin(), data.end(), target) == data.end());
        }
    }
    return ok;
}

/**
 * Program entry point running the reworded regression checks.
 */
int main() {
    assert(checkAbsentValues());
    assert(checkGeneralCases());
    return 0;
}

/******************************************************************************
 * @file
 * @brief [Interpolation search
 * algorithm](https://en.wikipedia.org/wiki/interpolation_search)
 *
 * @details
 * interpolation search resembles the method by which people search a telephone
 * directory for a name (the key value by which the book's entries are ordered):
 * in each step the algorithm calculates where in the remaining search space
 * the sought item might be, based on the key values at the bounds of the search
 * space and the value of the sought key, usually via a linear interpolation.
 * The key value actually found at this estimated position is then compared to
 * the key value being sought. If it is not equal, then depending on the
 * comparison, the remaining search space is reduced to the part before or
 * after the estimated position. This method will only work if calculations
 * on the size of differences between key values are sensible.

 * ### Complexities
 *
 * //n is the number of element in the array.
 *
 * Worst-case time complexity	O(n)                (when items are distributed
 exponentially)
 * Average time complexity	    O(log2(log2 n))
 * space complexity  0(1)
 *
 * @author [Lajat Manekar](https://github.com/Lazeeez)
 * @author Unknown author
 *******************************************************************************/

#include <algorithm>  /// for std::sort function
#include <cassert>    /// for std::assert
#include <cstdint>
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/******************************************************************************
 * @namespace search
 * @brief Searching algorithms
 *******************************************************************************/
namespace search {

/******************************************************************************
 * @namespace interpolation_search
 * @brief Functions for the [Interpolation
 *Search](https://en.wikipedia.org/wiki/interpolation_search) algorithm
 *implementation
 *******************************************************************************/
namespace interpolation_search {

/******************************************************************************
 * @brief The main function which implements interpolation search
 * @param arr vector to be searched in
 * @param number value to be searched
 * @returns integer index of `number` in vector `arr`
 *******************************************************************************/
uint64_t interpolationSearch(const std::vector<uint64_t> &arr,
                             uint64_t number) {
    uint64_t size = arr.size();
    uint64_t low = 0, high = (size - 1);

    // Since vector is sorted, an element present in array must be in range
    // defined by corner
    while (low <= high && number >= arr[low] && number <= arr[high]) {
        if (low == high) {
            if (arr[low] == number) {
                return low;
            }
            return -1;
        }
        // Probing the position with keeping uniform distribution in mind.
        uint64_t pos =
            low +
            ((static_cast<uint64_t>(high - low) / (arr[high] - arr[low])) *
             (number - arr[low]));

        if (arr[pos] == number) {
            return pos;  // Condition of target found
        }

        if (arr[pos] < number) {
            low = pos + 1;  // If x is larger, x is in upper part
        }

        else {
            high = pos - 1;  // If x is smaller, x is in the lower part
        }
    }
    return -1;
}

}  // namespace interpolation_search

}  // namespace search

/*******************************************************************************
 * @brief Self-test implementation
 * @returns void
 *******************************************************************************/
static void tests() {
    // testcase
    // array = [10, 12, 13, 16, 18, 19, 20, 21, 1, 2, 3, 4, 22, 23, 24, 33, 35,
    // 42, 47] , Value = 33 should return 15
    std::vector<uint64_t> arr = {{10, 12, 13, 16, 18, 19, 20, 21, 1, 2, 3, 4,
                                  22, 23, 24, 33, 35, 42, 47}};
    sort(arr.begin(), arr.end());
    uint64_t number = 33;  // Element to be searched
    uint64_t expected_answer = 15;
    uint64_t derived_answer =
        search::interpolation_search::interpolationSearch(arr, number);
    std::cout << "Testcase: ";
    assert(derived_answer == expected_answer);
    std::cout << "Passed!\n";
}

/*******************************************************************************
 * @brief Main function
 * @returns 0 on exit
 *******************************************************************************/
int main() {
    tests();  // run self-test implementations
    return 0;
}

/******************************************************************************
 * @file
 * @brief Interpolation search over a sorted vector
 *
 * @details
 * Interpolation search behaves like flipping to an estimated page in a
 * phone book rather than always checking the middle: given the values at
 * both ends of the current search window, it linearly estimates where the
 * target ought to live and probes there directly. If the probed value
 * doesn't match, the window shrinks to the side implied by the comparison.
 * This only helps when the data is roughly uniformly distributed; on
 * pathological (e.g. exponential) distributions it degrades to O(n).
 *
 * Complexity: worst case O(n), average case O(log log n), O(1) space.
 ******************************************************************************/

#include <algorithm>  /// for std::sort
#include <cassert>    /// for assert
#include <cstdint>
#include <iostream>   /// for std::cout
#include <vector>     /// for std::vector

/******************************************************************************
 * @namespace search
 * @brief Searching algorithms
 ******************************************************************************/
namespace search {

/******************************************************************************
 * @namespace interpolation_search
 * @brief Interpolation search implementation
 ******************************************************************************/
namespace interpolation_search {

/******************************************************************************
 * @brief Estimates the target's position and narrows the search window.
 * @param sortedArr sorted array to search within
 * @param target value being searched for
 * @returns index of target, or -1 (as unsigned wraparound) if absent
 ******************************************************************************/
uint64_t estimateAndSearch(const std::vector<uint64_t> &sortedArr, uint64_t target) {
    uint64_t total = sortedArr.size();
    uint64_t lo = 0, hi = total - 1;

    // target, if present, must lie within [arr[lo], arr[hi]]
    while (lo <= hi && target >= sortedArr[lo] && target <= sortedArr[hi]) {
        if (lo == hi) {
            if (sortedArr[lo] == target) {
                return lo;
            }
            return -1;
        }
        // linear interpolation assuming a roughly uniform distribution
        uint64_t probe =
            lo + ((static_cast<uint64_t>(hi - lo) / (sortedArr[hi] - sortedArr[lo])) *
                  (target - sortedArr[lo]));

        if (sortedArr[probe] == target) {
            return probe;  // found it
        }

        if (sortedArr[probe] < target) {
            lo = probe + 1;  // target is further right
        } else {
            hi = probe - 1;  // target is further left
        }
    }
    return -1;
}

}  // namespace interpolation_search

}  // namespace search

/*******************************************************************************
 * @brief Reworded self-test.
 *******************************************************************************/
static void runCheck() {
    // sorted version of {10,12,13,16,18,19,20,21,1,2,3,4,22,23,24,33,35,42,47}
    // searching for 33 should yield index 15
    std::vector<uint64_t> data = {{10, 12, 13, 16, 18, 19, 20, 21, 1, 2, 3, 4,
                                   22, 23, 24, 33, 35, 42, 47}};
    sort(data.begin(), data.end());
    uint64_t target = 33;
    uint64_t expected = 15;
    uint64_t got = search::interpolation_search::estimateAndSearch(data, target);
    std::cout << "Testcase: ";
    assert(got == expected);
    std::cout << "Passed!\n";
}

/*******************************************************************************
 * @brief Program entry point.
 * @returns 0 on exit
 *******************************************************************************/
int main() {
    runCheck();
    return 0;
}

/**
 * @file
 * @brief find the length of the Longest Increasing Subsequence (LIS)
 * using [Binary Search](https://en.wikipedia.org/wiki/Longest_increasing_subsequence)
 * @details
 * Given an integer array nums, return the length of the longest strictly
 * increasing subsequence.
 * The longest increasing subsequence is described as a subsequence of an array
 * where: All elements of the subsequence are in increasing order. This subsequence
 * itself is of the longest length possible.

 * For solving this problem we have Three Approaches :-

 * Approach 1 :- Using Brute Force
 * The first approach that came to your mind is the Brute Force approach where we
 * generate all subsequences and then manually filter the subsequences whose
 * elements come in increasing order and then return the longest such subsequence.
 * Time Complexity :- O(2^n)
 * It's time complexity is exponential. Therefore we will try some other
 * approaches.

 * Approach 2 :- Using Dynamic Programming
 * To generate all subsequences we will use recursion and in the recursive logic we
 * will figure out a way to solve this problem. Recursive Logic to solve this
 * problem:-
 * 1. We only consider the element in the subsequence if the element is grater then
 * the last element present in the subsequence
 * 2. When we consider the element we will increase the length of subsequence by 1
 * Time Complexity: O(N*N)
 * Space Complexity: O(N*N) + O(N)

 * This approach is better then the previous Brute Force approach so, we can
 * consider this approach.

 * But when the Constraints for the problem is very larger then this approach fails

 * Approach 3 :- Using Binary Search
 * Other approaches use additional space to create a new subsequence Array.
 * Instead, this solution uses the existing nums Array to build the subsequence
 * array. We can do this because the length of the subsequence array will never be
 * longer than the current index.

 * Time complexity: O(n∗log(n))
 * Space complexity: O(1)

 * This approach consider Most optimal Approach for solving this problem

 * @author [Naman Jain](https://github.com/namanmodi65)
 */

#include <cassert>   /// for std::assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector
#include <algorithm> /// for std::lower_bound
#include <cstdint>   /// for std::uint32_t

/**
 * @brief Function to find the length of the Longest Increasing Subsequence (LIS)
 * using Binary Search
 * @tparam T The type of the elements in the input vector
 * @param nums The input vector of elements of type T
 * @return The length of the longest increasing subsequence
 */
template <typename T>
std::uint32_t longest_increasing_subsequence_using_binary_search(std::vector<T>& nums) {
    if (nums.empty()) return 0;

    std::vector<T> ans;
    ans.push_back(nums[0]);
    for (std::size_t i = 1; i < nums.size(); i++) {
        if (nums[i] > ans.back()) {
            ans.push_back(nums[i]);
        } else {
            auto idx = std::lower_bound(ans.begin(), ans.end(), nums[i]) - ans.begin();
            ans[idx] = nums[i];
        }
    }
    return static_cast<std::uint32_t>(ans.size());
}

/**
 * @brief Test cases for Longest Increasing Subsequence function
 * @returns void
 */
static void tests() {
    std::vector<int> arr = {10, 9, 2, 5, 3, 7, 101, 18};
    assert(longest_increasing_subsequence_using_binary_search(arr) == 4);

    std::vector<int> arr2 = {0, 1, 0, 3, 2, 3};
    assert(longest_increasing_subsequence_using_binary_search(arr2) == 4);

    std::vector<int> arr3 = {7, 7, 7, 7, 7, 7, 7};
    assert(longest_increasing_subsequence_using_binary_search(arr3) == 1);

    std::vector<int> arr4 = {-10, -1, -5, 0, 5, 1, 2};
    assert(longest_increasing_subsequence_using_binary_search(arr4) == 5);

    std::vector<double> arr5 = {3.5, 1.2, 2.8, 3.1, 4.0};
    assert(longest_increasing_subsequence_using_binary_search(arr5) == 4);

    std::vector<char> arr6 = {'a', 'b', 'c', 'a', 'd'};
    assert(longest_increasing_subsequence_using_binary_search(arr6) == 4);

    std::vector<int> arr7 = {};
    assert(longest_increasing_subsequence_using_binary_search(arr7) == 0);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function to run tests
 * @returns 0 on exit
 */
int main() {
    tests();  // run self test implementation
    return 0;
}

/**
 * @file
 * @brief Length of the Longest Increasing Subsequence (LIS) via patience
 * sorting / binary search
 * @details
 * Given a sequence, the LIS is the longest subsequence (not necessarily
 * contiguous) whose elements are strictly increasing.
 *
 * Three well-known strategies exist:
 *   1. Brute force: enumerate every subsequence - O(2^n), impractical.
 *   2. Dynamic programming: O(n^2) time, tracking the best subsequence
 *      ending at each index.
 *   3. Patience-sorting with binary search: maintain a "tails" array where
 *      tails[k] is the smallest possible tail value of an increasing
 *      subsequence of length k+1. Each new element either extends the tails
 *      array or replaces the first tail that is >= it (found via binary
 *      search). The final size of tails is the LIS length.
 *      Time: O(n log n), Space: O(n) for the tails array.
 *
 * This file implements approach 3.
 */

#include <cassert>   /// for assert
#include <iostream>  /// for std::cout
#include <vector>    /// for std::vector
#include <algorithm> /// for std::lower_bound
#include <cstdint>   /// for std::uint32_t

/**
 * @brief Computes the length of the longest strictly increasing subsequence.
 * @tparam T element type stored in the sequence
 * @param sequence input values (unmodified logically, only scanned)
 * @return length of the longest increasing subsequence
 */
template <typename T>
std::uint32_t lisLengthViaBisection(std::vector<T>& sequence) {
    if (sequence.empty()) return 0;

    std::vector<T> tails;
    tails.push_back(sequence[0]);
    for (std::size_t i = 1; i < sequence.size(); i++) {
        if (sequence[i] > tails.back()) {
            tails.push_back(sequence[i]);
        } else {
            auto pos = std::lower_bound(tails.begin(), tails.end(), sequence[i]) - tails.begin();
            tails[pos] = sequence[i];
        }
    }
    return static_cast<std::uint32_t>(tails.size());
}

/**
 * @brief Reworded regression suite covering several data types/edge cases.
 * @returns void
 */
static void runChecks() {
    std::vector<int> caseA = {10, 9, 2, 5, 3, 7, 101, 18};
    assert(lisLengthViaBisection(caseA) == 4);

    std::vector<int> caseB = {0, 1, 0, 3, 2, 3};
    assert(lisLengthViaBisection(caseB) == 4);

    std::vector<int> caseC = {7, 7, 7, 7, 7, 7, 7};
    assert(lisLengthViaBisection(caseC) == 1);

    std::vector<int> caseD = {-10, -1, -5, 0, 5, 1, 2};
    assert(lisLengthViaBisection(caseD) == 5);

    std::vector<double> caseE = {3.5, 1.2, 2.8, 3.1, 4.0};
    assert(lisLengthViaBisection(caseE) == 4);

    std::vector<char> caseF = {'a', 'b', 'c', 'a', 'd'};
    assert(lisLengthViaBisection(caseF) == 4);

    std::vector<int> caseG = {};
    assert(lisLengthViaBisection(caseG) == 0);

    std::cout << "All checks completed successfully!\n";
}

/**
 * @brief Program entry point.
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [Bogosort algorithm](https://en.wikipedia.org/wiki/Bogosort)
 *
 * @details
 *      In computer science, bogosort (also known as permutation sort, stupid sort, slowsort, 
 *      shotgun sort, random sort, monkey sort, bobosort or shuffle sort) is a highly inefficient 
 *      sorting algorithm based on the generate and test paradigm. Two versions of this algorithm 
 *      exist: a deterministic version that enumerates all permutations until it hits a sorted one,
 *      and a randomized version that randomly permutes its input.Randomized version is implemented here. 
 *
 * ### Algorithm
 * Shuffle the array untill array is sorted.
 *
 * @author [Deep Raval](https://github.com/imdeep2905)
 */
#include <iostream>
#include <algorithm>
#include <array>
#include <cassert>
#include <random>


/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * Function to shuffle the elements of an array. (for reference)
 * @tparam T typename of the array
 * @tparam N length of array
 * @param arr array to shuffle
 * @returns new array with elements shuffled from a given array
 */
template <typename T, size_t N>
std::array <T, N> shuffle (std::array <T, N> arr) {
    for (int i = 0; i < N; i++) {
        // Swaps i'th  index with random index (less than array size)
        std::swap(arr[i], arr[std::rand() % N]);
    }
    return arr;
}
/**
 * Implement randomized Bogosort algorithm and sort the elements of a given array.
 * @tparam T typename of the array
 * @tparam N length of array
 * @param arr array to sort
 * @returns new array with elements sorted from a given array
 */
template <typename T, size_t N>
std::array <T, N> randomized_bogosort (std::array <T, N> arr) {
    // Untill array is not sorted
    std::random_device random_device;
    std::mt19937 generator(random_device());
    while (!std::is_sorted(arr.begin(), arr.end())) {
        std::shuffle(arr.begin(), arr.end(), generator);// Shuffle the array
    }
    return arr;
}

}  // namespace sorting

/**
 * Function to display array on screen 
 * @tparam T typename of the array
 * @tparam N length of array
 * @param arr array to display
 */
template <typename T, size_t N>
void show_array (const std::array <T, N> &arr) {
    for (int x : arr) {
        std::cout << x << ' ';
    }
    std::cout << '\n';
}

/**
 * Function to test above algorithm
 */
void test() {
    // Test 1
    std::array <int, 5> arr1;
    for (int &x : arr1) {
        x = std::rand() % 100;
    }
    std::cout << "Original Array : ";
    show_array(arr1);
    arr1 = sorting::randomized_bogosort(arr1);
    std::cout << "Sorted Array : ";
    show_array(arr1);
    assert(std::is_sorted(arr1.begin(), arr1.end()));
    // Test 2
    std::array <int, 5> arr2;
    for (int &x : arr2) {
        x = std::rand() % 100;
    }
    std::cout << "Original Array : ";
    show_array(arr2);
    arr2 = sorting::randomized_bogosort(arr2);
    std::cout << "Sorted Array : ";
    show_array(arr2);
    assert(std::is_sorted(arr2.begin(), arr2.end()));
}

/** Driver Code */
int main() {
    // Testing
    test();
    // Example Usage
    std::array <int, 5> arr = {3, 7, 10, 4, 1}; // Defining array which we want to sort
    std::cout << "Original Array : ";
    show_array(arr);
    arr = sorting::randomized_bogosort(arr); // Callling bogo sort on it
    std::cout << "Sorted Array : ";
    show_array(arr); // Printing sorted array
    return 0;
}

/**
 * @file
 * @brief A reworked take on the [Bogosort](https://en.wikipedia.org/wiki/Bogosort) algorithm.
 *
 * @details
 *      Bogosort (aka permutation sort / slowsort / shotgun sort) is a joke of a
 *      sorting algorithm: it repeatedly shuffles the data and checks whether it
 *      happens to be sorted. There's a deterministic variant that walks every
 *      permutation, and a randomized one that just keeps rolling the dice. This
 *      file implements the randomized flavor.
 *
 * ### Approach
 * Keep reshuffling the container until, by pure luck, it ends up in order.
 */
#include <iostream>
#include <algorithm>
#include <array>
#include <cassert>
#include <random>

/**
 * @namespace sorting
 * @brief Collection of sorting routines
 */
namespace sorting {

/**
 * @namespace bogosort_variant
 * @brief Helpers backing the randomized bogosort implementation
 */
namespace bogosort_variant {

/**
 * Randomly permutes the contents of a fixed-size array using a supplied
 * random engine. Present mostly as a reference/manual shuffle routine.
 * @tparam Elem element type stored in the array
 * @tparam Count number of elements
 * @param data array whose elements will be permuted
 * @returns a new array containing the same elements in randomized order
 */
template <typename Elem, size_t Count>
std::array<Elem, Count> scramble(std::array<Elem, Count> data) {
    size_t idx = 0;
    while (idx < Count) {
        std::swap(data[idx], data[static_cast<size_t>(std::rand()) % Count]);
        ++idx;
    }
    return data;
}

/**
 * Checks whether the container is already ordered, ascending.
 */
template <typename Elem, size_t Count>
bool already_ordered(const std::array<Elem, Count> &data) {
    return std::is_sorted(data.begin(), data.end());
}

}  // namespace bogosort_variant

/**
 * Sorts a fixed-size array via randomized bogosort: shuffle repeatedly until
 * the array happens to land in sorted order.
 * @tparam Elem element type stored in the array
 * @tparam Count number of elements
 * @param data array to sort
 * @returns sorted copy of the input array
 */
template <typename Elem, size_t Count>
std::array<Elem, Count> randomized_bogosort(std::array<Elem, Count> data) {
    std::random_device seed_source;
    std::mt19937 rng(seed_source());
    while (!bogosort_variant::already_ordered(data)) {
        std::shuffle(data.begin(), data.end(), rng);
    }
    return data;
}

}  // namespace sorting

/**
 * Prints the contents of an array to stdout, space separated.
 */
template <typename Elem, size_t Count>
void dump_array(const std::array<Elem, Count> &data) {
    for (const auto &value : data) {
        std::cout << value << ' ';
    }
    std::cout << '\n';
}

/**
 * Builds a small array of random values for exercising the sorter.
 */
std::array<int, 5> make_random_batch() {
    std::array<int, 5> batch{};
    for (auto &value : batch) {
        value = std::rand() % 100;
    }
    return batch;
}

/**
 * Self-check routine exercising the randomized bogosort on a couple of
 * randomly generated batches, asserting the result is actually sorted.
 */
void run_self_checks() {
    // Case A
    auto batch_a = make_random_batch();
    std::cout << "Before: ";
    dump_array(batch_a);
    batch_a = sorting::randomized_bogosort(batch_a);
    std::cout << "After:  ";
    dump_array(batch_a);
    assert(std::is_sorted(batch_a.begin(), batch_a.end()));

    // Case B
    auto batch_b = make_random_batch();
    std::cout << "Before: ";
    dump_array(batch_b);
    batch_b = sorting::randomized_bogosort(batch_b);
    std::cout << "After:  ";
    dump_array(batch_b);
    assert(std::is_sorted(batch_b.begin(), batch_b.end()));
}

/** Program entry point */
int main() {
    run_self_checks();

    std::array<int, 5> sample = {3, 7, 10, 4, 1};
    std::cout << "Before: ";
    dump_array(sample);
    sample = sorting::randomized_bogosort(sample);
    std::cout << "After:  ";
    dump_array(sample);

    return 0;
}

#include <iostream>
using namespace std;

int Max(int Arr[], int N) {
    int max = Arr[0];
    for (int i = 1; i < N; i++)
        if (Arr[i] > max)
            max = Arr[i];
    return max;
}

int Min(int Arr[], int N) {
    int min = Arr[0];
    for (int i = 1; i < N; i++)
        if (Arr[i] < min)
            min = Arr[i];
    return min;
}

void Print(int Arr[], int N) {
    for (int i = 0; i < N; i++) cout << Arr[i] << ", ";
}

int *Counting_Sort(int Arr[], int N) {
    int max = Max(Arr, N);
    int min = Min(Arr, N);
    int *Sorted_Arr = new int[N];

    int *Count = new int[max - min + 1];
    for (int i = 0; i < max - min + 1; ++i) {
        Count[i] = 0;
    }

    for (int i = 0; i < N; i++) Count[Arr[i] - min]++;

    for (int i = 1; i < (max - min + 1); i++) Count[i] += Count[i - 1];

    for (int i = N - 1; i >= 0; i--) {
        Sorted_Arr[Count[Arr[i] - min] - 1] = Arr[i];
        Count[Arr[i] - min]--;
    }

    delete[] Count;
    return Sorted_Arr;
}

int main() {
    int Arr[] = {47, 65, 20, 66, 25, 53, 64, 69, 72, 22,
                 74, 25, 53, 15, 42, 36, 4,  69, 86, 19},
        N = 20;
    int *Sorted_Arr;

    cout << "\n\tOrignal Array = ";
    Print(Arr, N);
    Sorted_Arr = Counting_Sort(Arr, N);
    cout << "\n\t Sorted Array = ";
    Print(Sorted_Arr, N);
    delete[] Sorted_Arr;
    cout << endl;

    return 0;
}

#include <iostream>
using namespace std;

// Scans the buffer and reports the largest value found.
int findLargest(int data[], int length) {
    int best = data[0];
    for (int idx = 1; idx < length; idx++) {
        if (data[idx] > best) {
            best = data[idx];
        }
    }
    return best;
}

// Scans the buffer and reports the smallest value found.
int findSmallest(int data[], int length) {
    int best = data[0];
    for (int idx = 1; idx < length; idx++) {
        if (data[idx] < best) {
            best = data[idx];
        }
    }
    return best;
}

// Dumps the contents of a buffer to stdout, comma separated.
void dumpBuffer(int data[], int length) {
    for (int idx = 0; idx < length; idx++) {
        cout << data[idx] << ", ";
    }
}

// Classic counting sort: builds a frequency table shifted by the
// minimum value, turns it into a prefix-sum table, then places
// each element into its final position by walking the input in reverse
// (reverse traversal keeps the sort stable).
int *countingSortBuffer(int data[], int length) {
    int hi = findLargest(data, length);
    int lo = findSmallest(data, length);
    int range = hi - lo + 1;

    int *result = new int[length];
    int *freq = new int[range];

    for (int idx = 0; idx < range; idx++) {
        freq[idx] = 0;
    }

    for (int idx = 0; idx < length; idx++) {
        freq[data[idx] - lo]++;
    }

    for (int idx = 1; idx < range; idx++) {
        freq[idx] += freq[idx - 1];
    }

    for (int idx = length - 1; idx >= 0; idx--) {
        int bucket = data[idx] - lo;
        result[freq[bucket] - 1] = data[idx];
        freq[bucket]--;
    }

    delete[] freq;
    return result;
}

int main() {
    int values[] = {47, 65, 20, 66, 25, 53, 64, 69, 72, 22,
                     74, 25, 53, 15, 42, 36, 4,  69, 86, 19};
    int total = 20;

    cout << "\n\tBefore sorting = ";
    dumpBuffer(values, total);

    int *sortedValues = countingSortBuffer(values, total);

    cout << "\n\tAfter sorting  = ";
    dumpBuffer(sortedValues, total);

    delete[] sortedValues;
    cout << endl;

    return 0;
}

/**
 * @file
 * @brief Implementation of [Cycle
 * sort](https://en.wikipedia.org/wiki/Cycle_sort) algorithm
 * @details
 * Cycle Sort is a sorting algorithm that works in \f$O(n^2)\f$ time in the best
 * case and works in \f$O(n^2)\f$ in worst case. If a element is already at its
 * correct  position, do nothing. If a element is not at its correct position,
 * we then need to move it to its correct position by computing the correct
 * positions.Therefore, we should make sure the duplicate elements.
 * @author [TsungHan Ho](https://github.com/dalaoqi)
 */

#include <algorithm>  /// for std::is_sorted, std::swap
#include <cassert>    /// for assert
#include <cstdint>
#include <iostream>   /// for io operations
#include <vector>     /// for std::vector

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace cycle_sort
 * @brief Functions for [Cycle sort](https://en.wikipedia.org/wiki/Cycle_sort)
 * algorithm
 */
namespace cycle_sort {
/**
 * @brief The main function implements cycleSort
 * @tparam T type of array
 * @param in_arr array to be sorted
 * @returns void
 */
template <typename T>
std::vector<T> cycleSort(const std::vector<T> &in_arr) {
    std::vector<T> arr(in_arr);
    for (int cycle_start = 0; cycle_start <= arr.size() - 1; cycle_start++) {
        // initialize item
        T item = arr[cycle_start];

        // Count the number of elements smaller than item, this  number is the
        // correct index of item.
        int pos = cycle_start;
        for (int i = cycle_start + 1; i < arr.size(); i++) {
            if (arr[i] < item) {
                pos++;
            }
        }

        // item is already in correct position
        if (pos == cycle_start) {
            continue;
        }

        // duplicate  elements
        while (item == arr[pos]) pos += 1;
        if (pos == cycle_start) {
            continue;
        } else {
            std::swap(item, arr[pos]);
        }
        // Rest of the  elements
        while (pos != cycle_start) {
            pos = cycle_start;
            // Find position where we put the element
            for (size_t i = cycle_start + 1; i < arr.size(); i++) {
                if (arr[i] < item) {
                    pos += 1;
                }
            }
            // duplicate  elements
            while (item == arr[pos]) pos += 1;
            if (item == arr[pos]) {
                continue;
            } else {
                std::swap(item, arr[pos]);
            }
        }
    }
    return arr;
}
}  // namespace cycle_sort
}  // namespace sorting

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    // Test 1
    // [4, 3, 2, 1] return [1, 2, 3, 4]
    std::vector<uint32_t> array1 = {4, 3, 2, 1};
    std::cout << "Test 1... ";
    std::vector<uint32_t> arr1 = sorting::cycle_sort::cycleSort(array1);
    assert(std::is_sorted(std::begin(arr1), std::end(arr1)));
    std::cout << "passed" << std::endl;

    // [4.3, -6.5, -7.4, 0, 2.7, 1.8] return [-7.4, -6.5, 0, 1.8, 2.7, 4.3]
    std::vector<double> array2 = {4.3, -6.5, -7.4, 0, 2.7, 1.8};
    std::cout << "Test 2... ";
    std::vector<double> arr2 = sorting::cycle_sort::cycleSort(array2);
