/**
 * @file
 * @brief Reimplementation of the [Cycle
 * sort](https://en.wikipedia.org/wiki/Cycle_sort) algorithm.
 * @details
 * Cycle sort minimizes the number of writes to the underlying array: every
 * element is moved directly to its final resting place, computed by counting
 * how many other elements are smaller than it. Its runtime is quadratic in
 * both the average and worst case, but it guarantees each value is written
 * at most once (aside from duplicates), which matters when writes are
 * expensive.
 */

#include <algorithm>  /// for std::is_sorted, std::swap
#include <cassert>    /// for assert
#include <cstdint>
#include <iostream>  /// for io operations
#include <vector>    /// for std::vector

namespace sorting {
namespace cyclic_placement {

/**
 * @brief Sorts a copy of the input vector using the cycle-sort strategy.
 * @tparam ValueT element type stored in the vector
 * @param source vector to be sorted (left untouched)
 * @returns a newly built, sorted vector
 */
template <typename ValueT>
std::vector<ValueT> sortByCycles(const std::vector<ValueT> &source) {
    std::vector<ValueT> data(source);
    const size_t total = data.size();

    for (size_t start = 0; start + 1 <= total && start < total; start++) {
        ValueT candidate = data[start];

        // Determine how many entries to the right are strictly smaller;
        // that count tells us candidate's correct slot.
        size_t target = start;
        for (size_t scan = start + 1; scan < total; scan++) {
            if (data[scan] < candidate) {
                target++;
            }
        }

        if (target == start) {
            // Already resting in the right spot.
            continue;
        }

        // Skip past any equal values to keep duplicates untouched.
        while (candidate == data[target]) {
            target++;
        }
        if (target == start) {
            continue;
        }
        std::swap(candidate, data[target]);

        // Keep cycling the displaced value into its own correct slot
        // until we loop back around to the starting index.
        while (target != start) {
            target = start;
            for (size_t scan = start + 1; scan < total; scan++) {
                if (data[scan] < candidate) {
                    target++;
                }
            }
            while (candidate == data[target]) {
                target++;
            }
            if (candidate == data[target]) {
                continue;
            }
            std::swap(candidate, data[target]);
        }
    }
    return data;
}

}  // namespace cyclic_placement
}  // namespace sorting

/**
 * @brief Runs a handful of sanity checks against sortByCycles.
 * @returns void
 */
static void runChecks() {
    std::cout << "Check A... ";
    std::vector<uint32_t> descending = {4, 3, 2, 1};
    auto resultA = sorting::cyclic_placement::sortByCycles(descending);
    assert(std::is_sorted(std::begin(resultA), std::end(resultA)));
    std::cout << "ok" << std::endl;

    std::cout << "Check B... ";
    std::vector<double> mixedDoubles = {4.3, -6.5, -7.4, 0, 2.7, 1.8};
    auto resultB = sorting::cyclic_placement::sortByCycles(mixedDoubles);
    assert(std::is_sorted(std::begin(resultB), std::end(resultB)));
    std::cout << "ok" << std::endl;

    std::cout << "Check C... ";
    std::vector<uint32_t> allSame = {3, 3, 3, 3};
    auto resultC = sorting::cyclic_placement::sortByCycles(allSame);
    assert(std::is_sorted(std::begin(resultC), std::end(resultC)));
    std::cout << "ok" << std::endl;

    std::cout << "Check D... ";
    std::vector<uint32_t> alreadySorted = {3, 4, 6, 8, 9, 14};
    auto resultD = sorting::cyclic_placement::sortByCycles(alreadySorted);
    assert(std::is_sorted(std::begin(resultD), std::end(resultD)));
    std::cout << "ok" << std::endl;
}

