 * Our main function with example of sort method.
 */
int main() {
    test();
    return 0;
}

/**
 * @file
 * @brief Reimplementation of [gnome
 * sort](https://en.wikipedia.org/wiki/Gnome_sort).
 * @details
 * Gnome sort behaves like a garden gnome sorting flower pots: it looks at
 * the pot next to it and the one before it. If they are in the right
 * order, it steps forward one pot. If not, it swaps them and steps
 * backward one pot. It keeps doing this until it reaches the end of the
 * row. It is simple to implement but not particularly fast, sitting at
 * O(n^2) in general with O(n) behavior on nearly-sorted input.
 */

#include <algorithm>  // for std::swap
#include <array>      // for std::array
#include <cassert>    // for assertions
#include <iostream>   // for io operations

namespace sorting {

/**
 * @brief In-place gnome sort over a raw pointer / C-style array.
 * @tparam ValueT element type
 * @param items pointer to first element of the array
 * @param count number of elements in the array
 */
template <typename ValueT>
void gnomeSortInPlace(ValueT *items, int count) {
    if (count <= 1) {
        return;
    }

    int cursor = 0;
    while (cursor < count) {
        bool atStartOrOrdered =
            (cursor == 0) || (items[cursor] >= items[cursor - 1]);
        if (atStartOrOrdered) {
            cursor++;
        } else {
            std::swap(items[cursor], items[cursor - 1]);
            cursor--;
        }
    }
}

/**
 * @brief Value-semantics gnome sort over a std::array; returns a sorted copy.
 * @tparam ValueT element type
 * @tparam count number of elements
 * @param items array to sort (received by value)
 * @return sorted array
 */
template <typename ValueT, size_t count>
std::array<ValueT, count> gnomeSortCopy(std::array<ValueT, count> items) {
    if (count <= 1) {
        return items;
    }

    int cursor = 0;
    while (cursor < static_cast<int>(count)) {
        bool atStartOrOrdered =
            (cursor == 0) || (items[cursor] >= items[cursor - 1]);
        if (atStartOrOrdered) {
            cursor++;
        } else {
            std::swap(items[cursor], items[cursor - 1]);
            cursor--;
        }
    }
    return items;
}

}  // namespace sorting

/**
 * @brief Runs demonstration/verification cases for both overloads.
 */
static void runChecks() {
    std::cout << "Scenario 1 - raw C-array of ints... ";
    const int width = 6;
    std::array<int, width> ints = {-22, 100, 150, 35, -10, 99};
    sorting::gnomeSortInPlace(ints.data(), width);
    assert(std::is_sorted(std::begin(ints), std::end(ints)));
    std::cout << "passed\n";
    for (int i = 0; i < width; i++) {
        std::cout << ints[i] << ", ";
    }
    std::cout << std::endl;

    std::cout << "\nScenario 2 - std::array of doubles... ";
    std::array<double, width> doubles = {-100.2, 10.2, 20.0, 9.0, 7.5, 7.2};
    std::array<double, width> sortedDoubles = sorting::gnomeSortCopy(doubles);
    assert(std::is_sorted(std::begin(sortedDoubles), std::end(sortedDoubles)));
    std::cout << "passed\n";
    for (int i = 0; i < width; i++) {
        std::cout << doubles[i] << ", ";
    }
    std::cout << std::endl;

    std::cout << "\nScenario 3 - 200 random floats... ";
    const int bigWidth = 200;
    std::array<float, bigWidth> randomFloats{};

    for (auto &value : randomFloats) {
        value = float(std::rand() % 1000 - 500) / 100.f;
    }

    std::array<float, bigWidth> sortedFloats =
        sorting::gnomeSortCopy(randomFloats);
    assert(std::is_sorted(std::begin(sortedFloats), std::end(sortedFloats)));
    std::cout << "passed\n";
    std::cout << std::endl;
}

/**
 * @brief Program entry point.
 */
int main() {
    runChecks();
    return 0;
}

/**
 * Copyright 2020 @author Albirair
 * @file
 *
 * A generic implementation of non-recursive merge sort.
 */
#include <cstddef>  // for size_t
#include <iostream>
#include <utility>  // for std::move & std::remove_reference_t

namespace sorting {
template <class Iterator>
void merge(Iterator, Iterator, const Iterator, char[]);
/// bottom-up merge sort which sorts elements in a non-decreasing order
/**
 * sorts elements non-recursively by breaking them into small segments,
 * merging adjacent segments into larger sorted segments, then increasing
 * the sizes of segments by factors of 2 and repeating the same process.
 * best-case = worst-case = O(n log(n))
 * @param first points to the first element
 * @param last points to 1-step past the last element
 * @param n the number of elements
 */
template <class Iterator>
void non_recursive_merge_sort(const Iterator first, const Iterator last,
                              const size_t n) {
    // create a buffer large enough to store all elements
    // dynamically allocated to comply with cpplint
    char* buffer = new char[n * sizeof(*first)];
    // buffer size can be optimized to largest power of 2 less than n
    // elements divide the container into equally-sized segments whose
    // length start at 1 and keeps increasing by factors of 2
    for (size_t length(1); length < n; length <<= 1) {
        // merge adjacent segments whose number is n / (length * 2)
        Iterator left(first);
        for (size_t counter(n / (length << 1)); counter; --counter) {
            Iterator right(left + length), end(right + length);
            merge(left, right, end, buffer);
            left = end;
        }
        // if the number of remaining elements (n * 2 % length) is longer
        // than a segment, merge the remaining elements
        if ((n & ((length << 1) - 1)) > length)
            merge(left, left + length, last, buffer);
    }
    delete[] buffer;
}
/// merges 2 sorted adjacent segments into a larger sorted segment
/**
 * best-case = worst-case = O(n)
 * @param l points to the left part
 * @param r points to the right part, end of left part
 * @param e points to end of right part
 * @param b points at the buffer
 */
template <class Iterator>
void merge(Iterator l, Iterator r, const Iterator e, char b[]) {
    // create 2 pointers to point at the buffer
    auto p(reinterpret_cast<std::remove_reference_t<decltype(*l)>*>(b)), c(p);
    // move the left part of the segment
    for (Iterator t(l); r != t; ++t) *p++ = std::move(*t);
    // while neither the buffer nor the right part has been exhausted
    // move the smallest element of the two back to the container
    while (e != r && c != p) *l++ = std::move(*r < *c ? *r++ : *c++);
    // notice only one of the two following loops will be executed
    // while the right part hasn't bee exhausted, move it back
    while (e != r) *l++ = std::move(*r++);
    // while the buffer hasn't bee exhausted, move it back
    while (c != p) *l++ = std::move(*c++);
}
/// bottom-up merge sort which sorts elements in a non-decreasing order
/**
 * @param first points to the first element
 * @param n the number of elements
 */
template <class Iterator>
void non_recursive_merge_sort(const Iterator first, const size_t n) {
    non_recursive_merge_sort(first, first + n, n);
}
/// bottom-up merge sort which sorts elements in a non-decreasing order
/**
 * @param first points to the first element
 * @param last points to 1-step past the last element
 */
template <class Iterator>
void non_recursive_merge_sort(const Iterator first, const Iterator last) {
    non_recursive_merge_sort(first, last, last - first);
}

}  // namespace sorting

using sorting::non_recursive_merge_sort;

int main() {
    int size;
    std::cout << "Enter the number of elements : ";
    std::cin >> size;
    int* arr = new int[size];
    for (int i = 0; i < size; ++i) {
        std::cout << "arr[" << i << "] = ";
        std::cin >> arr[i];
    }
    non_recursive_merge_sort(arr, size);
    std::cout << "Sorted array\n";
    for (int i = 0; i < size; ++i)
        std::cout << "arr[" << i << "] = " << arr[i] << '\n';
    delete[] arr;
    return 0;
}

/**
 * Bottom-up (iterative) merge sort.
 *
 * Instead of recursively splitting the input, this variant starts by
 * treating every single element as a sorted run of length 1, then
 * repeatedly merges adjacent runs into runs twice as long, doubling the
 * run length each pass until the whole range is one sorted run.
 * Best-case and worst-case complexity are both O(n log n).
 */
#include <cstddef>
#include <iostream>
#include <utility>

namespace sorting {

template <class Iterator>
void mergeRuns(Iterator, Iterator, const Iterator, char[]);

/**
 * Sorts elements in [first, last) into non-decreasing order using the
 * iterative bottom-up merge strategy.
 * @param first  points to the first element
 * @param last   points one past the last element
 * @param count  number of elements in the range
 */
template <class Iterator>
void bottomUpMergeSort(const Iterator first, const Iterator last,
                       const size_t count) {
    char *scratch = new char[count * sizeof(*first)];

    for (size_t runLen(1); runLen < count; runLen <<= 1) {
        Iterator windowStart(first);
        for (size_t pairsRemaining(count / (runLen << 1)); pairsRemaining;
             --pairsRemaining) {
            Iterator windowMid(windowStart + runLen), windowEnd(windowMid + runLen);
            mergeRuns(windowStart, windowMid, windowEnd, scratch);
            windowStart = windowEnd;
        }
        if ((count & ((runLen << 1) - 1)) > runLen) {
            mergeRuns(windowStart, windowStart + runLen, last, scratch);
        }
    }
    delete[] scratch;
}

/**
 * Merges two adjacent sorted runs [l, r) and [r, e) into one sorted run,
 * using `buffer` as scratch space for the left run.
 */
template <class Iterator>
void mergeRuns(Iterator l, Iterator r, const Iterator e, char buffer[]) {
    auto bufStart(reinterpret_cast<std::remove_reference_t<decltype(*l)> *>(buffer));
    auto bufCursor(bufStart);

    for (Iterator t(l); r != t; ++t) *bufCursor++ = std::move(*t);

    while (e != r && bufStart != bufCursor) {
        *l++ = std::move(*r < *bufStart ? *r++ : *bufStart++);
    }
    while (e != r) *l++ = std::move(*r++);
    while (bufStart != bufCursor) *l++ = std::move(*bufStart++);
}

/**
 * Convenience overload taking just a start iterator and element count.
 */
template <class Iterator>
void bottomUpMergeSort(const Iterator first, const size_t count) {
    bottomUpMergeSort(first, first + count, count);
}

/**
 * Convenience overload taking a [first, last) range with no explicit count.
 */
template <class Iterator>
void bottomUpMergeSort(const Iterator first, const Iterator last) {
    bottomUpMergeSort(first, last, last - first);
}

}  // namespace sorting

using sorting::bottomUpMergeSort;

int main() {
    int count;
    std::cout << "Enter the number of elements : ";
    std::cin >> count;
    int *values = new int[count];
    for (int i = 0; i < count; ++i) {
        std::cout << "values[" << i << "] = ";
        std::cin >> values[i];
    }
    bottomUpMergeSort(values, static_cast<size_t>(count));
    std::cout << "Sorted array\n";
    for (int i = 0; i < count; ++i) {
        std::cout << "values[" << i << "] = " << values[i] << '\n';
    }
    delete[] values;
    return 0;
}

/* C++ implementation Odd Even Sort */
#include <iostream>
#include <vector>

using namespace std;

void oddEven(vector<int> &arr, int size) {
    bool sorted = false;
    while (!sorted) {
        sorted = true;
        for (int i = 1; i < size - 1; i += 2)  // Odd
        {
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                sorted = false;
            }
        }

        for (int i = 0; i < size - 1; i += 2)  // Even
        {
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                sorted = false;
            }
        }
    }
}

void show(vector<int> A, int size) {
    int i;
    for (i = 0; i < size; i++) cout << A[i] << "\n";
}

int main() {
    int size, temp;
    cout << "\nEnter the number of elements : ";
    cin >> size;

    vector<int> arr;

    cout << "\nEnter the unsorted elements : \n";

    for (int i = 0; i < size; ++i) {
        cin >> temp;
        arr.push_back(temp);
    }

    oddEven(arr, size);

    cout << "Sorted array\n";
    show(arr, size);
    return 0;
}

/* Brick sort (a.k.a. odd-even transposition sort), reimplemented with a
 * do-while driver loop and index-based helper functions instead of the
 * classic while(!sorted) shape. */
#include <iostream>
#include <vector>

namespace brick_sort_demo {

void swapEntries(std::vector<int> &data, std::size_t left, std::size_t right) {
    int tmp = data[left];
    data[left] = data[right];
    data[right] = tmp;
}

// Runs a single pass over odd-indexed neighbor pairs (1,2), (3,4), ...
// Returns true if any swap occurred during this pass.
bool oddPhase(std::vector<int> &data) {
    bool changed = false;
    for (std::size_t i = 1; i + 1 < data.size(); i += 2) {
        if (data[i] > data[i + 1]) {
            swapEntries(data, i, i + 1);
            changed = true;
        }
    }
    return changed;
}

// Runs a single pass over even-indexed neighbor pairs (0,1), (2,3), ...
// Returns true if any swap occurred during this pass.
bool evenPhase(std::vector<int> &data) {
    bool changed = false;
    for (std::size_t i = 0; i + 1 < data.size(); i += 2) {
        if (data[i] > data[i + 1]) {
            swapEntries(data, i, i + 1);
            changed = true;
        }
    }
    return changed;
}

void brickSort(std::vector<int> &data) {
    bool didSwap;
    do {
        bool a = oddPhase(data);
        bool b = evenPhase(data);
        didSwap = a || b;
    } while (didSwap);
}

void printAll(const std::vector<int> &data) {
    for (int value : data) {
        std::cout << value << "\n";
    }
}

}  // namespace brick_sort_demo

int main() {
    std::size_t count = 0;
    std::cout << "\nHow many values will you enter? ";
    std::cin >> count;

    std::vector<int> values;
    values.reserve(count);

    std::cout << "\nEnter the values, unsorted:\n";
    for (std::size_t i = 0; i < count; ++i) {
        int v;
        std::cin >> v;
        values.push_back(v);
    }

    brick_sort_demo::brickSort(values);

    std::cout << "Result after brick sort:\n";
    brick_sort_demo::printAll(values);
    return 0;
}

/**
 * @file
 * @brief pancake sort sorts a disordered stack of pancakes by flipping any
 * number of pancakes using a spatula using minimum number of flips.
 *
 * @details
 * Unlike a traditional sorting algorithm, which attempts to sort with the
 * fewest comparisons possible, the goal is to sort the sequence in as few
 * reversals as possible. Overall time complexity of pancake sort is O(n^2) For
 * example: example 1:- Disordered pancake sizes: {2,5,3,7,8} Sorted:
 * {2,3,5,7,8} For example: example 2:- Disordered pancake sizes:
 * {22,51,37,73,81} Sorted: {22,37,51,73,81}
 * @author [Divyansh Gupta](https://github.com/divyansh12323)
 * @see more on [Pancake sort](https://en.wikipedia.org/wiki/Pancake_sorting)
 * @see related problem at
 * [Leetcode](https://leetcode.com/problems/pancake-sorting/)
 */

#include <algorithm>  // for std::is_sorted
#include <cassert>    // for std::assert
#include <iostream>   // for io operations
#include <vector>     // for std::vector

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace pancake_sort
 * @brief Functions for [Pancake
 * sort](https://en.wikipedia.org/wiki/Pancake_sorting) algorithm
 */
namespace pancake_sort {
/**
 * @brief This implementation is for reversing elements in a a C-style array .
 * @param [start,end] arr our vector of elements.
 * @param start starting index of array
 * @param end ending index of array
 * @returns void
 */
template <typename T>
void reverse(std::vector<T> &arr, int start, int end) {
    T temp;  // Temporary variable
    while (start <= end) {
        temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}
/**
 * @brief This implementation is for a C-style array input that gets modified in
 * place.
 * @param [start,end] arr our vector of elements.
 * @param size size of given array
 * @returns 0 on exit
 */
template <typename T>
int pancakeSort(std::vector<T> &arr, int size) {
    for (int i = size; i > 1; --i) {
        int max_index = 0, j = 0;  // intialize some variables.
        T max_value = 0;
        for (j = 0; j < i; j++) {
            if (arr[j] >= max_value) {
                max_value = arr[j];
                max_index = j;
            }
        }
        if (max_index != i - 1)  // check for reversing
        {
            reverse(arr, 0, max_index);
            reverse(arr, 0, i - 1);
        }
    }
    return 0;
}
}  // namespace pancake_sort
}  // namespace sorting

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    // example 1: vector of int
    const int size1 = 7;
    std::cout << "\nTest 1- as std::vector<int>...";
    std::vector<int> arr1 = {23, 10, 20, 11, 12, 6, 7};
    sorting::pancake_sort::pancakeSort(arr1, size1);
    assert(std::is_sorted(arr1.begin(), arr1.end()));
    std::cout << "Passed\n";
    for (int i = 0; i < size1; i++) {
