/**
 * @file
 * @brief Alternate implementation of pancake sort: repeatedly find the
 * largest unplaced "pancake" and flip it to the top of the stack, then flip
 * the whole unsorted prefix so it lands at the end of its final region.
 *
 * @details
 * Pancake sort measures cost in flips (prefix reversals) rather than
 * comparisons or swaps. Each outer step performs at most two reversals, so
 * overall complexity stays O(n^2). This version renames the moving pieces
 * to "stack" terminology and drives the outer loop with decreasing stack
 * height via a while loop instead of a for loop.
 */

#include <algorithm>  // for std::is_sorted
#include <cassert>    // for assert
#include <iostream>   // for std::cout
#include <vector>     // for std::vector

namespace sorting {
namespace flip_stack_sort {

// Reverses the sub-range [lo, hi] of the stack in place -- this is the
// "spatula flip" operation.
template <typename T>
void flipRange(std::vector<T> &stack, int lo, int hi) {
    while (lo < hi) {
        T swapTmp = stack[lo];
        stack[lo] = stack[hi];
        stack[hi] = swapTmp;
        ++lo;
        --hi;
    }
}

// Finds the index of the biggest pancake within stack[0..limit].
template <typename T>
int indexOfLargest(const std::vector<T> &stack, int limit) {
    int best = 0;
    for (int k = 1; k <= limit; ++k) {
        if (stack[k] > stack[best]) {
            best = k;
        }
    }
    return best;
}

// Sorts `stack` (of the given `count` elements) using flip operations only.
template <typename T>
int stackSort(std::vector<T> &stack, int count) {
    int unsortedTop = count - 1;
    while (unsortedTop > 0) {
        int biggest = indexOfLargest(stack, unsortedTop);
        if (biggest != unsortedTop) {
            // Bring the largest remaining pancake to the front, then flip
            // it down to its resting place at unsortedTop.
            flipRange(stack, 0, biggest);
            flipRange(stack, 0, unsortedTop);
        }
        --unsortedTop;
    }
    return 0;
}

}  // namespace flip_stack_sort
}  // namespace sorting

// Reworded self-checks exercising int, double, and float stacks.
static void runChecks() {
    std::cout << "\nCheck 1 - std::vector<int> stack...";
    std::vector<int> intStack = {23, 10, 20, 11, 12, 6, 7};
    sorting::flip_stack_sort::stackSort(intStack, static_cast<int>(intStack.size()));
    assert(std::is_sorted(intStack.begin(), intStack.end()));
    std::cout << "OK\n";
    for (int v : intStack) std::cout << v << " ,";
    std::cout << std::endl;

    std::cout << "\nCheck 2 - std::vector<double> stack...";
    std::vector<double> dblStack = {23.56, 10.62, 200.78, 111.484,
                                     3.9,   1.2,   61.77,  79.6};
    sorting::flip_stack_sort::stackSort(dblStack, static_cast<int>(dblStack.size()));
    assert(std::is_sorted(dblStack.begin(), dblStack.end()));
    std::cout << "OK\n";
    for (double v : dblStack) std::cout << v << ", ";
    std::cout << std::endl;

    std::cout << "\nCheck 3 - std::vector<float> stack...";
    std::vector<float> fltStack = {6.56f, 12.62f, 200.78f, 768.484f,
                                    19.27f, 68.87f, 9.6f};
    sorting::flip_stack_sort::stackSort(fltStack, static_cast<int>(fltStack.size()));
    assert(std::is_sorted(fltStack.begin(), fltStack.end()));
    std::cout << "OK\n";
    for (float v : fltStack) std::cout << v << ", ";
    std::cout << std::endl;
}

