/**
 * @file
 * @brief Alternate implementation of Pigeonhole Sort
 * (https://en.wikipedia.org/wiki/Pigeonhole_sort)
 * @details
 * Pigeonhole sort works well when the number of distinct key values is
 * close to the number of elements: it builds one "hole" (bucket) per
 * possible value in the input's range, drops each element into its own
 * bucket, then reads the buckets back out in order. Runs in O(n + range)
 * time using a std::vector of counts instead of a raw new[] buffer.
 */

#include <algorithm>  // for std::is_sorted, std::min_element, std::max_element
#include <array>      // for std::array
#include <cassert>    // for assert
#include <iostream>   // for std::cout
#include <vector>     // for std::vector

namespace sorting {

/**
 * Sorts a fixed-size array of ints using the pigeonhole technique.
 * Returns a new, sorted array; the input is left untouched.
 */
template <std::size_t N>
std::array<int, N> pigeonholeSort(std::array<int, N> data) {
    if (N == 0) {
        return data;
    }

    int lowest = *std::min_element(data.begin(), data.end());
    int highest = *std::max_element(data.begin(), data.end());

    std::size_t bucketCount = static_cast<std::size_t>(highest - lowest + 1);
    std::vector<int> buckets(bucketCount, 0);
    std::vector<bool> occupied(bucketCount, false);

    // Drop each value straight into its bucket, keyed by offset from the
    // minimum value seen.
    for (std::size_t idx = 0; idx < N; ++idx) {
        std::size_t bucketIdx = static_cast<std::size_t>(data[idx] - lowest);
        buckets[bucketIdx] = data[idx];
        occupied[bucketIdx] = true;
    }

    // Walk the buckets in order, writing occupied ones back into the
    // result array.
    std::size_t writePos = 0;
    for (std::size_t b = 0; b < bucketCount; ++b) {
        if (occupied[b]) {
            data[writePos++] = buckets[b];
        }
    }

    return data;
}

}  // namespace sorting

/** Verifies sorting of {8, 3, 2, 7, 4, 6, 8}. */
static void check_small_with_duplicate() {
    constexpr std::size_t n = 7;
    std::array<int, n> sample = {8, 3, 2, 7, 4, 6, 8};

    sample = sorting::pigeonholeSort<n>(sample);

    assert(std::is_sorted(sample.begin(), sample.end()));
    for (int v : sample) std::cout << v << " ";
    std::cout << "\nOK\n";
}

