 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * Selection sort (recursive form).
 *
 * Conceptually identical to plain selection sort: keep a sorted prefix and
 * an unsorted suffix, repeatedly move the minimum of the suffix to the
 * boundary. Both the "find the minimum" step and the "advance the
 * boundary" step are expressed recursively here rather than with loops.
 */

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

namespace sorting {
namespace selection_sort_recursive {

/**
 * Recursively finds the index of the smallest element within
 * data[from..end).
 */
template <typename T>
uint64_t indexOfSmallest(const std::vector<T> &data, uint64_t from = 0) {
    if (from + 1 == data.size()) {
        return from;
    }
    uint64_t bestRest = indexOfSmallest(data, from + 1);
    return (data[from] < data[bestRest]) ? from : bestRest;
}

/**
 * Recursively sorts data[from..end) by placing the smallest remaining
 * element at position `from` and recursing on the rest.
 */
template <typename T>
void sortFrom(std::vector<T> &data, uint64_t from = 0) {
    if (from == data.size()) {
        return;
    }
    uint64_t chosen = indexOfSmallest(data, from);
    if (chosen != from) {
        std::swap(data[chosen], data[from]);
    }
    sortFrom(data, from + 1);
}

}  // namespace selection_sort_recursive
}  // namespace sorting

/**
 * Exercises sortFrom against a handful of small vectors.
 */
static void runChecks() {
    std::vector<uint64_t> setA = {0, 1, 1, 2};
    std::cout << "check A... ";
    sorting::selection_sort_recursive::sortFrom(setA);
    assert(std::is_sorted(setA.begin(), setA.end()));
    std::cout << "ok" << std::endl;

    std::vector<uint64_t> setB = {1, 0, 0, 1, 1, 0, 2, 1};
    std::cout << "check B... ";
    sorting::selection_sort_recursive::sortFrom(setB);
    assert(std::is_sorted(setB.begin(), setB.end()));
    std::cout << "ok" << std::endl;

    std::vector<uint64_t> setC = {1, 1, 0, 0, 1, 2, 2, 0, 2, 1};
    std::cout << "check C... ";
    sorting::selection_sort_recursive::sortFrom(setC);
    assert(std::is_sorted(setC.begin(), setC.end()));
    std::cout << "ok" << std::endl;

    std::vector<uint64_t> setD = {2, 2, 2, 0, 0, 1, 1};
    std::cout << "check D... ";
    sorting::selection_sort_recursive::sortFrom(setD);
    assert(std::is_sorted(setD.begin(), setD.end()));
    std::cout << "ok" << std::endl;
}

int main() {
    runChecks();
    return 0;
}

// C++ program to find minimum number of swaps required to sort an array
#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

// Function returns the minimum number of swaps
// required to sort the array
int minSwaps(int arr[], int n) {
    // Create an array of pairs where first
    // element is array element and second element
    // is position of first element
    std::pair<int, int> *arrPos = new std::pair<int, int>[n];
    for (int i = 0; i < n; i++) {
        arrPos[i].first = arr[i];
        arrPos[i].second = i;
    }

    // Sort the array by array element values to
    // get right position of every element as second
    // element of pair.
    std::sort(arrPos, arrPos + n);

    // To keep track of visited elements. Initialize
    // all elements as not visited or false.
    std::vector<bool> vis(n, false);

    // Initialize result
    int ans = 0;

    // Traverse array elements
    for (int i = 0; i < n; i++) {
        // already swapped and corrected or
        // already present at correct pos
        if (vis[i] || arrPos[i].second == i)
            continue;

        // find out the number of node in
        // this cycle and add in ans
        int cycle_size = 0;
        int j = i;
        while (!vis[j]) {
            vis[j] = 1;

            // move to next node
            j = arrPos[j].second;
            cycle_size++;
        }

        // Update answer by adding current cycle.
        if (cycle_size > 0) {
            ans += (cycle_size - 1);
        }
    }

    delete[] arrPos;

    // Return result
    return ans;
}

// program to test
int main() {
    int arr[] = {6, 7, 8, 1, 2, 3, 9, 12};
    int n = (sizeof(arr) / sizeof(int));
    std::cout << minSwaps(arr, n);
    return 0;
}

// Computes the minimum number of element swaps needed to fully sort an
// array. Rather than actually sorting, this treats the array as a
// permutation graph: each element points to the slot it should occupy, and
// following those pointers traces out disjoint cycles. A cycle of length k
// needs exactly (k - 1) swaps to resolve, so summing that over all cycles
// gives the answer.

#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

int minimumSwapsToSort(const std::vector<int>& values) {
    const int count = static_cast<int>(values.size());

    // Pair each value with its original slot, then sort by value so that
    // `second` tells us where each element belongs once ordered.
    std::vector<std::pair<int, int>> withOrigin(count);
    for (int idx = 0; idx < count; ++idx) {
        withOrigin[idx] = {values[idx], idx};
    }
    std::sort(withOrigin.begin(), withOrigin.end());

    std::vector<bool> settled(count, false);
    int totalSwaps = 0;

    for (int start = 0; start < count; ++start) {
        if (settled[start] || withOrigin[start].second == start) {
            continue;
        }

        int cycleLength = 0;
        int cursor = start;
        while (!settled[cursor]) {
            settled[cursor] = true;
            cursor = withOrigin[cursor].second;
            ++cycleLength;
        }

        if (cycleLength > 0) {
            totalSwaps += cycleLength - 1;
        }
    }

    return totalSwaps;
}

int main() {
    std::vector<int> sample{6, 7, 8, 1, 2, 3, 9, 12};
    std::cout << minimumSwapsToSort(sample);
    return 0;
}

// C++ program to perform TimSort.
#include <algorithm>
#include <cassert>
#include <iostream>
#include <numeric>

const int RUN = 32;

// this function sorts array from left index to to right index which is of size
// atmost RUN
void insertionSort(int arr[], int left, int right) {
    for (int i = left + 1; i <= right; i++) {
        const int temp = arr[i];
        int j = i - 1;
        while (j >= left && arr[j] > temp) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = temp;
    }
}

// merge function merges the sorted runs
void merge(int arr[], int l, int m, int r) {
    // original array is broken in two parts, left and right array
    const int len1 = m - l + 1, len2 = r - m;
    int *left = new int[len1], *right = new int[len2];
    for (int i = 0; i < len1; i++) left[i] = arr[l + i];
    for (int i = 0; i < len2; i++) right[i] = arr[m + 1 + i];

    int i = 0;
    int j = 0;
    int k = l;

    // after comparing, we merge those two array in larger sub array
    while (i < len1 && j < len2) {
        if (left[i] <= right[j]) {
            arr[k] = left[i];
            i++;
        } else {
            arr[k] = right[j];
            j++;
        }
        k++;
    }

    // copy remaining elements of left, if any
    while (i < len1) {
        arr[k] = left[i];
        k++;
        i++;
    }

    // copy remaining element of right, if any
    while (j < len2) {
        arr[k] = right[j];
        k++;
        j++;
    }
    delete[] left;
    delete[] right;
}

// iterative Timsort function to sort the array[0...n-1] (similar to merge sort)
void timSort(int arr[], int n) {
    // Sort individual subarrays of size RUN
    for (int i = 0; i < n; i += RUN)
        insertionSort(arr, i, std::min((i + 31), (n - 1)));

    // start merging from size RUN (or 32). It will merge to form size 64, then
    // 128, 256 and so on ....
    for (int size = RUN; size < n; size = 2 * size) {
        // pick starting point of left sub array. We are going to merge
        // arr[left..left+size-1] and arr[left+size, left+2*size-1] After every
        // merge, we increase left by 2*size
        for (int left = 0; left < n; left += 2 * size) {
            // find ending point of left sub array
            // mid+1 is starting point of right sub array
            const int mid = std::min((left + size - 1), (n - 1));
            const int right = std::min((left + 2 * size - 1), (n - 1));

            // merge sub array arr[left.....mid] & arr[mid+1....right]
            merge(arr, left, mid, right);
        }
    }
}

// utility function to print the Array
void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++) printf("%d  ", arr[i]);
    std::cout << std::endl;
}

/**
 * @brief self-test implementation
 * @returns void
 */
void tests() {
    // Case: array of length 65
    constexpr int N = 65;
    int arr[N];

    std::iota(arr, arr + N, 0);
    std::reverse(arr, arr + N);
    assert(!std::is_sorted(arr, arr + N));

    timSort(arr, N);
    assert(std::is_sorted(arr, arr + N));
}

// Driver program to test above function
int main() {
    tests();  // run self test implementations

    int arr[] = {5, 21, 7, 23, 19};
    const int n = sizeof(arr) / sizeof(arr[0]);
    printf("Given Array is\n");
    printArray(arr, n);

    timSort(arr, n);

    printf("After Sorting Array is\n");
    printArray(arr, n);
    return 0;
}

// A from-scratch TimSort walkthrough: break the array into fixed-size runs,
// sort each run with insertion sort (cheap for small slices), then
// repeatedly merge neighboring runs — doubling the merge width each pass —
// until the whole array is one sorted run.

#include <algorithm>
#include <cassert>
#include <cstdio>
#include <iostream>
#include <numeric>

constexpr int RUN_WIDTH = 32;

// Sorts arr[from..to] in place using plain insertion sort.
void insertionSortRange(int arr[], int from, int to) {
    for (int cur = from + 1; cur <= to; ++cur) {
        const int key = arr[cur];
        int back = cur - 1;
        while (back >= from && arr[back] > key) {
            arr[back + 1] = arr[back];
            --back;
        }
        arr[back + 1] = key;
    }
}

// Merges two adjacent sorted slices arr[lo..mid] and arr[mid+1..hi] into a
// single sorted slice using temporary buffers.
void mergeRuns(int arr[], int lo, int mid, int hi) {
    const int leftLen = mid - lo + 1;
    const int rightLen = hi - mid;

    int* leftBuf = new int[leftLen];
    int* rightBuf = new int[rightLen];
    for (int i = 0; i < leftLen; ++i) leftBuf[i] = arr[lo + i];
    for (int i = 0; i < rightLen; ++i) rightBuf[i] = arr[mid + 1 + i];

    int li = 0, ri = 0, out = lo;
    while (li < leftLen && ri < rightLen) {
        if (leftBuf[li] <= rightBuf[ri]) {
            arr[out++] = leftBuf[li++];
        } else {
            arr[out++] = rightBuf[ri++];
        }
    }
    while (li < leftLen) arr[out++] = leftBuf[li++];
    while (ri < rightLen) arr[out++] = rightBuf[ri++];

    delete[] leftBuf;
    delete[] rightBuf;
}

// Full TimSort-style pass: sort fixed runs, then merge them bottom-up.
void timSort(int arr[], int length) {
    for (int start = 0; start < length; start += RUN_WIDTH) {
        insertionSortRange(arr, start, std::min(start + RUN_WIDTH - 1, length - 1));
    }

    for (int width = RUN_WIDTH; width < length; width *= 2) {
        for (int lo = 0; lo < length; lo += 2 * width) {
            const int mid = std::min(lo + width - 1, length - 1);
            const int hi = std::min(lo + 2 * width - 1, length - 1);
            mergeRuns(arr, lo, mid, hi);
        }
    }
}

void showArray(const int arr[], int length) {
    for (int i = 0; i < length; ++i) {
        printf("%d  ", arr[i]);
    }
    std::cout << std::endl;
}

void selfCheck() {
    constexpr int SIZE = 65;
    int data[SIZE];

    std::iota(data, data + SIZE, 0);
    std::reverse(data, data + SIZE);
    assert(!std::is_sorted(data, data + SIZE));

    timSort(data, SIZE);
    assert(std::is_sorted(data, data + SIZE));
}

int main() {
    selfCheck();

    int sample[] = {5, 21, 7, 23, 19};
    const int sampleLen = sizeof(sample) / sizeof(sample[0]);

    printf("Before sorting:\n");
    showArray(sample, sampleLen);

    timSort(sample, sampleLen);

    printf("After sorting:\n");
    showArray(sample, sampleLen);
    return 0;
}

/**
 * \addtogroup sorting Sorting Algorithms
 * @{
 * \file
 * \brief [Wiggle Sort Algorithm]
 * (https://leetcode.com/problems/wiggle-sort-ii/) Implementation
 *
 * \author [Roshan Kanwar](http://github.com/roshan0708)
 *
 * \details
 * Wiggle Sort sorts the array into a wave like array.
 * An array ‘arr[0..n-1]’ is sorted in wave form,
 * if arr[0] >= arr[1] <= arr[2] >= arr[3] <= arr[4] >= …..
 *
 * \example
 * arr = [1,1,5,6,1,4], after wiggle sort arr will become equal to [1,1,6,1,5,4]
 * arr = [2,8,9,1,7], after wiggle sort arr will become equal to [8,2,9,1,7]
 */

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <ctime>
#include <iostream>  /// for io operations
#include <vector>

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace wiggle_sort
 * @brief Functions for [Wiggle
 * Sort](https://leetcode.com/problems/wiggle-sort-ii/) algorithm
 */
namespace wiggle_sort {

/**
 *
 * @brief Function used for sorting the elements in wave form.
 * @details
 * Checking whether the even indexed elements are greater than
 * their adjacent odd elements.
 * Traversing all even indexed elements of the input arr.
 * If current element is smaller than the previous odd element, swap them.
 * If current element is smaller than the next odd element, swap them.
 *
 * @param arr input array (unsorted elements)
 *
 */
template <typename T>  // this allows to have vectors of ints, double, float,
                       // etc
std::vector<T> wiggleSort(const std::vector<T> &arr) {
    uint32_t size = arr.size();

    std::vector<T> out(
        arr);  // create a copy of input vector. this way, the original input
               // vector does not get modified. a sorted array is is returned.

    for (int i = 0; i < size; i += 2) {
        if (i > 0 && out[i - 1] > out[i]) {
            std::swap(out[i], out[i - 1]);  // swapping the two values
        }

        if (i < size - 1 && out[i] < out[i + 1]) {
            std::swap(out[i], out[i + 1]);  // swapping the two values
        }
    }

    return out;  // returns the sorted vector
}
}  // namespace wiggle_sort
}  // namespace sorting

/**
 *
 * @brief Utility function used for printing the elements.
 * Prints elements of the array after they're sorted using wiggle sort
 * algorithm.
 *
 * @param arr array containing the sorted elements
 *
 */
template <typename T>
static void displayElements(const std::vector<T> &arr) {
    uint32_t size = arr.size();

    std::cout << "Sorted elements are as follows: ";

    std::cout << "[";

    for (int i = 0; i < size; i++) {
        std::cout << arr[i];
        if (i != size - 1) {
            std::cout << ", ";
        }
    }

    std::cout << "]" << std::endl;
}

/**
 * Test function
 * @returns void
 */
static void test() {
    std::srand(std::time(nullptr));  // initialize random number generator

    std::vector<float> data1(100);
    for (auto &d : data1) {  // generate random numbers between -5.0 and 4.99
        d = float(std::rand() % 1000 - 500) / 100.f;
    }

    std::vector<float> sorted = sorting::wiggle_sort::wiggleSort<float>(data1);

    displayElements(sorted);

    for (uint32_t j = 0; j < data1.size(); j += 2) {
        assert(data1[j] <= data1[j + 1] &&
               data1[j + 1] >= data1[j + 2]);  // check the validation condition
    }

    std::cout << "Test 1 passed\n";
}

/** Driver Code */
int main() {
    test();
    return 0;
}

/** @} */

// Wiggle sort variant: rearranges elements so the pattern alternates
// peak/valley — arr[0] >= arr[1] <= arr[2] >= arr[3] <= ... This
// implementation walks the array two steps at a time, fixing local
// violations against both neighbors of each even position without doing a
// full sort first.

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <ctime>
#include <iostream>
#include <vector>

namespace ordering {
namespace zigzag {

// Produces a wiggle-ordered copy of `input`; the source is left untouched.
template <typename T>
std::vector<T> makeWiggle(const std::vector<T>& input) {
    std::vector<T> result(input);
    const size_t total = result.size();

    for (size_t pos = 0; pos < total; pos += 2) {
        if (pos > 0 && result[pos - 1] > result[pos]) {
            std::swap(result[pos], result[pos - 1]);
        }
        if (pos + 1 < total && result[pos] < result[pos + 1]) {
            std::swap(result[pos], result[pos + 1]);
        }
    }

    return result;
}

}  // namespace zigzag
}  // namespace ordering

template <typename T>
static void printSequence(const std::vector<T>& seq) {
    std::cout << "Wiggle-ordered output: [";
    for (size_t i = 0; i < seq.size(); ++i) {
        std::cout << seq[i];
        if (i + 1 != seq.size()) {
            std::cout << ", ";
        }
    }
    std::cout << "]" << std::endl;
}

static void runDemo() {
    std::srand(static_cast<unsigned>(std::time(nullptr)));

    std::vector<float> raw(100);
    for (auto& value : raw) {
        value = static_cast<float>(std::rand() % 1000 - 500) / 100.f;
    }

    std::vector<float> wiggled = ordering::zigzag::makeWiggle<float>(raw);
    printSequence(wiggled);

    for (size_t i = 0; i + 2 < raw.size(); i += 2) {
        assert(raw[i] <= raw[i + 1] && raw[i + 1] >= raw[i + 2]);
    }

    std::cout << "Demo check passed\n";
}

int main() {
    runDemo();
    return 0;
}

/**
 * @file duval.cpp
 * @brief Implementation of [Duval's algorithm](https://en.wikipedia.org/wiki/Lyndon_word).
 *
 * @details
 * Duval's algorithm is an algorithm to find the lexicographically smallest
 * rotation of a string. It is based on the concept of Lyndon words.
 * Lyndon words are defined as the lexicographically smallest string in a
 * rotation equivalence class. A rotation equivalence class is a set of strings
 * that can be obtained by rotating a string. For example, the rotation
 * equivalence class of "abc" is {"abc", "bca", "cab"}. The lexicographically
 * smallest string in this class is "abc".
 *
 * Duval's algorithm works by iterating over the string and finding the
 * smallest rotation of the string that is a Lyndon word. This is done by
 * comparing the string with its suffixes and finding the smallest suffix that
 * is lexicographically smaller than the string. This suffix is then added to
 * the result and the process is repeated with the remaining string.
 * The algorithm has a time complexity of O(n) where n is the length of the
 * string.
 *
 * @note While Lyndon words are described in the context of strings,
 * Duval's algorithm can be used to find the lexicographically smallest cyclic
 * shift of any sequence of comparable elements.
 *
 * @author [Amine Ghoussaini](https://github.com/aminegh20)
*/

#include <array>    /// for std::array
#include <cassert>  /// for assert
#include <cstddef>  /// for std::size_t
#include <deque>    /// for std::deque
#include <iostream> /// for std::cout and std::endl
#include <string>   /// for std::string
#include <vector>   /// for std::vector

/**
 * @brief string manipulation algorithms
 * @namespace
 */
namespace string {
/**
 * @brief Find the lexicographically smallest cyclic shift of a sequence.
 * @tparam T type of the sequence
 * @param s the sequence
 * @returns the 0-indexed position of the least cyclic shift of the sequence
 */
template <typename T>
size_t duval(const T& s) {
    size_t n = s.size();
    size_t i = 0, ans = 0;
    while (i < n) {
        ans = i;
        size_t j = i + 1, k = i;
        while (j < (n + n) && s[j % n] >= s[k % n]) {
            if (s[k % n] < s[j % n]) {
                k = i;
            } else {
                k++;
            }
            j++;
        }
        while (i <= k) {
            i += j - k;
        }
    }
    return ans;
    // returns 0-indexed position of the least cyclic shift
}

}  // namespace string

/**
 * @brief self test implementation
 * returns void
 */
static void test() {
    using namespace string;

    // Test 1
    std::string s1 = "abcab";
    assert(duval(s1) == 3);

    // Test 2
    std::string s2 = "011100";
    assert(duval(s2) == 4);

    // Test 3
    std::vector<int> v = {5, 2, 1, 3, 4};
    assert(duval(v) == 2);

    // Test 4
    std::array<int, 5> a = {1, 2, 3, 4, 5};
    assert(duval(a) == 0);

    // Test 5
    std::deque<char> d = {'a', 'z', 'c', 'a', 'b'};
    assert(duval(d) == 3);

    // Test 6
    std::string s3;
    assert(duval(s3) == 0);

    // Test 7
    std::vector<int> v2 = {5, 2, 1, 3, -4};
    assert(duval(v2) == 4);

    std::cout << "All tests passed!" << std::endl;
}

/**
 * @brief main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self test implementations
    return 0;
}

// Duval's algorithm locates the starting index of the lexicographically
// smallest rotation of a sequence, leaning on the theory of Lyndon words.
// It scans the (conceptually doubled) sequence once, tracking a candidate
// start, a comparison cursor, and a "last known smaller" marker, and runs
// in linear time regardless of the element type as long as it's orderable.

#include <array>
#include <cassert>
#include <cstddef>
#include <deque>
#include <iostream>
#include <string>
#include <vector>

namespace text_rotation {

// Finds the 0-indexed offset of the smallest cyclic rotation of `seq`.
template <typename Sequence>
size_t smallestRotationOffset(const Sequence& seq) {
    const size_t length = seq.size();
    size_t bestStart = 0;
    size_t scan = 0;

    while (scan < length) {
        bestStart = scan;
        size_t ahead = scan + 1;
        size_t matched = scan;

        while (ahead < 2 * length && seq[ahead % length] >= seq[matched % length]) {
            if (seq[matched % length] < seq[ahead % length]) {
                matched = scan;
            } else {
                ++matched;
            }
            ++ahead;
        }

        while (scan <= matched) {
            scan += ahead - matched;
        }
    }

    return bestStart;
}

}  // namespace text_rotation

static void runAllChecks() {
    using text_rotation::smallestRotationOffset;

    std::string caseA = "abcab";
    assert(smallestRotationOffset(caseA) == 3);

    std::string caseB = "011100";
    assert(smallestRotationOffset(caseB) == 4);

    std::vector<int> caseC = {5, 2, 1, 3, 4};
    assert(smallestRotationOffset(caseC) == 2);

    std::array<int, 5> caseD = {1, 2, 3, 4, 5};
    assert(smallestRotationOffset(caseD) == 0);

    std::deque<char> caseE = {'a', 'z', 'c', 'a', 'b'};
    assert(smallestRotationOffset(caseE) == 3);

    std::string caseF;
    assert(smallestRotationOffset(caseF) == 0);

    std::vector<int> caseG = {5, 2, 1, 3, -4};
    assert(smallestRotationOffset(caseG) == 4);

    std::cout << "All Duval checks passed!" << std::endl;
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [Manacher's
 * Algorithm](https://en.wikipedia.org/wiki/Longest_palindromic_substring)
 * @details
 * Manacher's Algorithm is used to find the longest palindromic substring within
 * a string in O(n) time. It exploits the property of a palindrome that its
 * first half is symmetric to the last half, and thus if the first half is a
 * palindrome, then last half is also a palindrome.
 * @author [Riti Kumari](https://github.com/riti2409)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector STL
#ifdef _MSC_VER
#include <string>  /// for string (required for MS Visual C++)
#else
#include <cstring>  /// for string
#endif

/**
 * @namespace strings
 * @brief Algorithms with strings
 */
namespace strings {
/**
 * @namespace manacher
 * @brief Functions for [Manacher's
 * Algorithm](https://en.wikipedia.org/wiki/Longest_palindromic_substring)
 * implementation
 */
namespace manacher {
/**
 * @brief A function that implements Manacher's algorithm
 * @param prototype is the string where algorithm finds a palindromic substring.
 * This string can contain any character except `@` `#` `&`
 * @returns the largest palindromic substring
 */
std::string manacher(const std::string &prototype) {
    if (prototype.size() > 0) {
        // stuffing characters between the input string to handle cases with
        // even length palindrome
        std::string stuffed_string = "";
        for (auto str : prototype) {
            stuffed_string += str;
            stuffed_string += "#";
        }
        stuffed_string = "@#" + stuffed_string + "&";

        std::vector<uint64_t> palindrome_max_half_length(
            stuffed_string.size(),
            0);  // this array will consist of largest possible half length of
                 // palindrome centered at index (say i with respect to the
                 // stuffed string). This value will be lower bound of half
                 // length since single character is a palindrome in itself.

        uint64_t bigger_center =
            0;  // this is the index of the center of palindromic
                // substring which would be considered as the larger
                // palindrome, having symmetric halves

        uint64_t right = 0;  // this is the maximum length of the palindrome
                             // from 'bigger_center' to the rightmost end

        // i is considered as center lying within one half of the palindrone
        // which is centered at 'bigger_center'
        for (uint64_t i = 1; i < stuffed_string.size() - 1; i++) {
            if (i < right) {  // when i is before right end, considering
                              // 'bigger_center' as center of palindrome
                uint64_t opposite_to_i =
                    2 * bigger_center -
                    i;  // this is the opposite end of string, if
                        // centered at center, and having one end as i

                // finding the minimum possible half length among
                // the palindrome on having center at opposite end,
                // and the string between i and right end,
                // considering 'bigger_center' as center of palindrome
                palindrome_max_half_length[i] = std::min(
                    palindrome_max_half_length[opposite_to_i], right - i);
            }

            // expanding the palindrome across the maximum stored length in the
            // array, centered at i
            while (stuffed_string[i + (palindrome_max_half_length[i] + 1)] ==
                   stuffed_string[i - (palindrome_max_half_length[i] + 1)]) {
                palindrome_max_half_length[i]++;
            }

            // if palindrome centered at i exceeds the rightmost end of
            // palindrome centered at 'bigger_center', then i will be made the
            // 'bigger_center' and right value will also be updated with respect
            // to center i
            if (i + palindrome_max_half_length[i] > right) {
                bigger_center = i;
                right = i + palindrome_max_half_length[i];
            }
        }

        // now extracting the first largest palindrome
        uint64_t half_length = 0;   // half length of the largest palindrome
        uint64_t center_index = 0;  // index of center of the largest palindrome

        for (uint64_t i = 1; i < stuffed_string.size() - 1; i++) {
            if (palindrome_max_half_length[i] > half_length) {
                half_length = palindrome_max_half_length[i];
                center_index = i;
            }
        }

        std::string palindromic_substring =
            "";  // contains the resulting largest palindrome

        if (half_length > 0) {
            // extra information: when '#' is the center, then palindromic
            // substring will have even length, else palindromic substring will
            // have odd length

            uint64_t start =
                center_index - half_length +
                1;  // index of first character of palindromic substring
            uint64_t end =
                center_index + half_length -
                1;  // index of last character of palindromic substring
            for (uint64_t index = start; index <= end; index += 2) {
                palindromic_substring += stuffed_string[index];
            }
        } else {
            // if length = 0, then there does not exist any palindrome of length
            // > 1 so we can assign any character of length 1 from string as the
            // palindromic substring
            palindromic_substring = prototype[0];
        }
        return palindromic_substring;

    } else {
        // handling case when string is empty
        return "";
    }
}

}  // namespace manacher
}  // namespace strings

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    assert(strings::manacher::manacher("") == "");
    assert(strings::manacher::manacher("abababc") == "ababa");
    assert(strings::manacher::manacher("cbaabd") == "baab");
    assert(strings::manacher::manacher("DedzefDeD") == "DeD");
    assert(strings::manacher::manacher("XZYYXXYZXX") == "YXXY");
    assert(strings::manacher::manacher("1sm222m10abc") == "m222m");
    assert(strings::manacher::manacher("798989591") == "98989");
    assert(strings::manacher::manacher("xacdedcax") == "xacdedcax");
    assert(strings::manacher::manacher("xaccax") == "xaccax");
    assert(strings::manacher::manacher("a") == "a");
    assert(strings::manacher::manacher("xy") == "x");
    assert(strings::manacher::manacher("abced") == "a");

    std::cout << "All tests have passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

// Manacher's algorithm finds the longest palindromic substring in linear
// time. The trick: insert separator characters between (and around) every
// original character so odd/even-length palindromes are handled uniformly,
// then expand palindrome radii while reusing previously computed radii via
// mirroring around the current rightmost-reaching palindrome's center.

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>
#ifdef _MSC_VER
#include <string>
#else
#include <cstring>
#endif

namespace strings {
namespace manacher {

// Returns the longest palindromic substring of `source`.
std::string longestPalindrome(const std::string& source) {
    if (source.empty()) {
        return "";
    }

    // Build a transformed string with separators so every palindrome,
    // odd or even length, has a well-defined single center.
    std::string transformed = "";
    for (char c : source) {
        transformed += c;
        transformed += '#';
    }
    transformed = "@#" + transformed + "&";

    std::vector<uint64_t> radius(transformed.size(), 0);
    uint64_t axis = 0;
    uint64_t frontier = 0;

    for (uint64_t i = 1; i < transformed.size() - 1; ++i) {
        if (i < frontier) {
            uint64_t mirrored = 2 * axis - i;
            radius[i] = std::min(radius[mirrored], frontier - i);
        }

        while (transformed[i + (radius[i] + 1)] == transformed[i - (radius[i] + 1)]) {
            ++radius[i];
        }

        if (i + radius[i] > frontier) {
            axis = i;
            frontier = i + radius[i];
        }
    }

    uint64_t bestRadius = 0;
    uint64_t bestCenter = 0;
    for (uint64_t i = 1; i < transformed.size() - 1; ++i) {
        if (radius[i] > bestRadius) {
            bestRadius = radius[i];
            bestCenter = i;
        }
    }

    if (bestRadius == 0) {
        return std::string(1, source[0]);
    }

    std::string best = "";
    uint64_t from = bestCenter - bestRadius + 1;
    uint64_t to = bestCenter + bestRadius - 1;
    for (uint64_t idx = from; idx <= to; idx += 2) {
        best += transformed[idx];
    }
    return best;
}

}  // namespace manacher
}  // namespace strings

static void runAllChecks() {
    assert(strings::manacher::longestPalindrome("") == "");
    assert(strings::manacher::longestPalindrome("abababc") == "ababa");
    assert(strings::manacher::longestPalindrome("cbaabd") == "baab");
    assert(strings::manacher::longestPalindrome("DedzefDeD") == "DeD");
    assert(strings::manacher::longestPalindrome("XZYYXXYZXX") == "YXXY");
    assert(strings::manacher::longestPalindrome("1sm222m10abc") == "m222m");
    assert(strings::manacher::longestPalindrome("798989591") == "98989");
    assert(strings::manacher::longestPalindrome("xacdedcax") == "xacdedcax");
    assert(strings::manacher::longestPalindrome("xaccax") == "xaccax");
    assert(strings::manacher::longestPalindrome("a") == "a");
    assert(strings::manacher::longestPalindrome("xy") == "x");
    assert(strings::manacher::longestPalindrome("abced") == "a");

    std::cout << "All Manacher checks passed!" << std::endl;
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * @file
 * @brief The [Z function](https://cp-algorithms.com/string/z-function.html) for
 * finding occurences of a pattern within a piece of text with time and space
 * complexity O(n + m)
 * @details
 * 1. The Z-function for a string is an array of length n where the
 * i-th element is equal to the greatest number of characters starting
 * from the position i that coincide with the first characters of s.
 * 2. E.g.: string: ababb then z[2]=2 as s[2]=s[0] and s[3]=s[1] and s[4]!=s[2]
 * @author [Ritika Gupta](https://github.com/RitikaGupta8734)
 */

#include <cstdint>
#include <iostream>  /// for IO operations
#ifdef _MSC_VER
#include <string>  /// for string (use this for MS Visual C++)
#else
#include <cstring>  /// for string
#endif
#include <cassert>  /// for assert
#include <vector>   /// for std::vector

/**
 * @brief Generate the Z-function for the inputted string.
 * \param[in] pattern text on which to apply the Z-function
 * \returns the Z-function output as a vector array
 */
std::vector<uint64_t> Z_function(const std::string &pattern) {
    uint64_t pattern_length = pattern.size();
    std::vector<uint64_t> z(pattern_length, 0);

    for (uint64_t i = 1, l = 0, r = 0; i < pattern_length; i++) {
        if (i <= r) {
            z[i] = std::min(r - i + 1, z[i - l]);
        }
        while (i + z[i] < pattern_length &&
               pattern[z[i]] == pattern[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] - 1 > r) {
            r = i + z[i] - 1;
        }
    }
    return z;
}

/**
 * @brief Using Z_function to find a pattern in a text
 * \param[in] pattern string pattern to search
 * \param[in] text text in which to search
 * \returns a vector of starting indexes where pattern is found in the text
 */
std::vector<uint64_t> find_pat_in_text(const std::string &pattern,
                                       const std::string &text) {
    uint64_t text_length = text.size(), pattern_length = pattern.size();
    std::vector<uint64_t> z = Z_function(pattern + '#' + text);
    std::vector<uint64_t> matching_indexes;

    for (uint64_t i = 0; i < text_length; i++) {
        if (z[i + pattern_length + 1] == pattern_length) {
            matching_indexes.push_back(i);
        }
    }
    return matching_indexes;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // usual case
    std::string text1 = "alskfjaldsabc1abc1abcbksbcdnsdabcabc";
    std::string pattern1 = "abc";

    // matching_indexes1 gets the indexes where pattern1 exists in text1
    std::vector<uint64_t> matching_indexes1 = find_pat_in_text(pattern1, text1);
    assert((matching_indexes1 == std::vector<uint64_t>{10, 14, 18, 30, 33}));

    // corner case
    std::string text2 = "greengrass";
    std::string pattern2 = "abc";

    // matching_indexes2 gets the indexes where pattern2 exists in text2
    std::vector<uint64_t> matching_indexes2 = find_pat_in_text(pattern2, text2);
    assert((matching_indexes2 == std::vector<uint64_t>{}));

    // corner case - empty text
    std::string text3 = "";
    std::string pattern3 = "abc";

    // matching_indexes3 gets the indexes where pattern3 exists in text3
    std::vector<uint64_t> matching_indexes3 = find_pat_in_text(pattern3, text3);
    assert((matching_indexes3 == std::vector<uint64_t>{}));

    // corner case - empty pattern
    std::string text4 = "redsand";
    std::string pattern4 = "";

    // matching_indexes4 gets the indexes where pattern4 exists in text4
    std::vector<uint64_t> matching_indexes4 = find_pat_in_text(pattern4, text4);
    assert((matching_indexes4 == std::vector<uint64_t>{0, 1, 2, 3, 4, 5, 6}));
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

// Z-function based pattern search. z[i] is defined as the length of the
// longest common prefix between the whole string and the suffix starting
// at i. Computing it in O(n) lets us find every occurrence of a pattern in
// a text by evaluating the Z-function of pattern + separator + text and
// looking for positions where z equals the pattern's length.

#include <cstdint>
#include <iostream>
#ifdef _MSC_VER
#include <string>
#else
#include <cstring>
#endif
#include <cassert>
#include <vector>

namespace zfunc {

// Builds the Z-array for `s`: zArr[i] = length of the longest prefix of s
// that also matches the substring starting at index i.
std::vector<uint64_t> compute(const std::string& s) {
    const uint64_t n = s.size();
    std::vector<uint64_t> zArr(n, 0);

    uint64_t segStart = 0, segEnd = 0;
    for (uint64_t i = 1; i < n; ++i) {
        if (i <= segEnd) {
            zArr[i] = std::min(segEnd - i + 1, zArr[i - segStart]);
        }
        while (i + zArr[i] < n && s[zArr[i]] == s[i + zArr[i]]) {
            ++zArr[i];
        }
        if (i + zArr[i] - 1 > segEnd) {
            segStart = i;
            segEnd = i + zArr[i] - 1;
        }
    }
    return zArr;
}

// Locates every starting index in `text` where `needle` occurs, using the
// Z-function of the concatenation needle + '#' + text.
std::vector<uint64_t> locateAll(const std::string& needle, const std::string& text) {
    const uint64_t textLen = text.size();
    const uint64_t needleLen = needle.size();
    std::vector<uint64_t> combinedZ = compute(needle + '#' + text);

    std::vector<uint64_t> hits;
    for (uint64_t i = 0; i < textLen; ++i) {
        if (combinedZ[i + needleLen + 1] == needleLen) {
            hits.push_back(i);
        }
    }
    return hits;
}

}  // namespace zfunc

static void runAllChecks() {
    // typical scenario with several matches
    std::string textA = "alskfjaldsabc1abc1abcbksbcdnsdabcabc";
    std::string needleA = "abc";
    std::vector<uint64_t> hitsA = zfunc::locateAll(needleA, textA);
    assert((hitsA == std::vector<uint64_t>{10, 14, 18, 30, 33}));

    // no matches at all
    std::string textB = "greengrass";
    std::string needleB = "abc";
    std::vector<uint64_t> hitsB = zfunc::locateAll(needleB, textB);
    assert((hitsB == std::vector<uint64_t>{}));

    // empty text
    std::string textC = "";
    std::string needleC = "abc";
    std::vector<uint64_t> hitsC = zfunc::locateAll(needleC, textC);
    assert((hitsC == std::vector<uint64_t>{}));

    // empty pattern matches everywhere
    std::string textD = "redsand";
    std::string needleD = "";
    std::vector<uint64_t> hitsD = zfunc::locateAll(needleD, textD);
    assert((hitsD == std::vector<uint64_t>{0, 1, 2, 3, 4, 5, 6}));
}

int main() {
    runAllChecks();
    return 0;
}
